-- william-shakespeare_richard-iii (776 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_richard-iii', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","londonastreet~londonastreet~13":"Londres. Uma rua.","enterricharddukeofgloucestersolus~arddukeofgloucestersolus~33":"Entra Ricardo, Duque de Gloucester, sozinho.","gloucesternowisthewinterofourdiscontentm~omysoulhereclarencecomes~1373":"GLOUCESTER — Eis que o inverno de nosso descontentamento\nSe fez glorioso verão por este sol de York;\nE todas as nuvens que pesavam sobre nossa casa\nSepultaram-se no fundo seio do oceano.\nAgora nossas frontes cingem-se de louros vitoriosos;\nNossas armas amolgadas pendem como troféus;\nNossos severos alarmes mudaram-se em alegres festas,\nNossas marchas terríveis em danças deleitosas.\nA guerra de rosto severo alisou a fronte enrugada;\nE agora, em vez de montar corcéis encouraçados\nPara aterrar a alma de adversários medrosos,\nSalta ágil no quarto de uma dama\nAo som lascivo de um alaúde.\nMas eu, que não fui feito para jogos de recreio,\nNem talhado para cortejar um espelho amoroso;\nEu, rudemente cunhado, sem a majestade do amor\nPara pavonear-me diante de uma ninfa lasciva e saltitante;\nEu, a quem falta esta bela proporção,\nTrapaceado em feições pela natureza enganadora,\nDeformado, inacabado, enviado antes do tempo\nA este mundo que respira, mal feito pela metade,\nE tão coxo e fora de moda\nQue os cães me ladram quando manquejo por perto;\nEu, nesta fraca e flautada época de paz,\nNão tenho prazer algum com que passar o tempo,\nSenão espiar minha sombra ao sol\nE discantar sobre minha própria deformidade:\nE portanto, uma vez que não posso ser amante\nPara entreter estes belos dias de fala fácil,\nResolvi ser um vilão\nE odiar os ociosos prazeres destes dias.\nTramas tenho urdido, perigosas induções,\nPor profecias de bêbados, libelos e sonhos,\nPara pôr meu irmão Clarence e o rei\nEm mortal ódio um contra o outro:\nE se o rei Eduardo for tão leal e justo\nQuanto eu sou sutil, falso e traiçoeiro,\nHoje mesmo Clarence será encerrado em segredo,\nPor causa de uma profecia, que diz que G\nDos herdeiros de Eduardo será o assassino.\nMergulhai, pensamentos, até o fundo de minha alma: eis que vem Clarence.","enterclarenceguardedandbrakenbury~enceguardedandbrakenbury~33":"Entram Clarence, sob guarda, e Brakenbury.","brothergooddaywhatmeansthisarmedguardtha~rdthatwaitsuponyourgrace~59":"Irmão, bom dia: que significa esta guarda armada\nQue acompanha vossa graça?","clarencehismajestytenderingmypersonssafe~ducttoconveymetothetower~86":"CLARENCE — Sua majestade,\nZelando pela segurança de minha pessoa, designou\nEsta escolta para conduzir-me à Torre.","gloucesteruponwhatcause~gloucesteruponwhatcause~23":"GLOUCESTER — Por que motivo?","clarencebecausemynameisgeorge~ncebecausemynameisgeorge~29":"CLARENCE — Porque meu nome é George.","gloucesteralackmylordthatfaultisnoneofyo~hematterclarencemayiknow~178":"GLOUCESTER — Ai, meu senhor, essa falta não é vossa;\nPor isso ele devia prender vossos padrinhos:\nÓ, quiçá sua majestade pretenda\nQue sejais rebatizado na Torre.\nMas qual é o caso, Clarence? Posso saber?","clarenceyearichardwheniknowforiprotestas~hishighnesstocommitmenow~316":"CLARENCE — Sim, Ricardo, quando eu souber; pois protesto\nQue ainda não sei: mas, até onde posso apurar,\nEle dá ouvidos a profecias e sonhos;\nE do alfabeto arranca a letra G,\nE diz que um mago lhe disse que por G\nSua descendência seria deserdada;\nE, como meu nome George começa com G,\nSegue-se em seu pensamento que sou eu o homem.\nEssas, pelo que apuro, e outras frivolidades como essas\nMoveram sua alteza a prender-me agora.","gloucesterwhythisitiswhenmenareruledbywo~safeclarencewearenotsafe~308":"GLOUCESTER — Ora, eis o que dá quando os homens são governados por mulheres:\nNão é o rei que vos manda à Torre;\nMinha Lady Grey, sua esposa, Clarence, é ela\nQue o tempera a essa extremidade.\nNão foram ela e aquele bom homem de respeito,\nAnthony Woodville, seu irmão ali,\nQue o fizeram mandar lorde Hastings à Torre,\nDe onde hoje mesmo foi libertado?\nNão estamos seguros, Clarence; não estamos seguros.","clarencebyheavenithinktheresnomanissecur~gswastoherforhisdelivery~187":"CLARENCE — Pelos céus, creio que não há homem seguro\nSenão os parentes da rainha e os arautos noctâmbulos\nQue labutam entre o rei e a senhora Shore.\nNão ouvistes que humilde suplicante\nFoi lorde Hastings junto a ela por sua libertação?","gloucesterhumblycomplainingtoherdeitygot~htygossipsinthismonarchy~255":"GLOUCESTER — Queixando-se humildemente à divindade dela\nConseguiu meu lorde camareiro a liberdade.\nDir-vos-ei o que penso: este é o nosso caminho,\nSe quisermos manter o favor do rei:\nSer homens dela e vestir-lhe a libré:\nA viúva ciumenta e gasta e ela mesma,\nDesde que nosso irmão as armou damas,\nSão poderosas comadres nesta monarquia.","brakenburyibeseechyourgracesbothtopardon~greesoeverwithhisbrother~144":"Brakenbury — Suplico a ambas as Vossas Graças que me perdoem;\nSua Majestade ordenou estritamente\nque ninguém, de qualquer condição,\nconverse em particular com seu irmão.","gloucesterevensoantpleaseyourworshipbrak~yyousircanyoudenyallthis~317":"Gloucester — Pois bem; se vos apraz, Brakenbury,\npodeis tomar parte em tudo o que dissermos:\nnão falamos traição, homem: dizemos que o rei\né sábio e virtuoso, e sua nobre rainha\nbem avançada em anos, bela, e sem ciúmes;\ndizemos que a mulher de Shore tem um pé bonito,\num lábio de cereja, um olho lindo, uma língua muito agradável;\ne que os parentes da rainha foram feitos fidalgos:\nque dizeis, senhor? Podeis negar tudo isso?","brakenburywiththismylordmyselfhavenought~lordmyselfhavenoughttodo~44":"Brakenbury — Com isso, meu senhor, nada tenho a ver.","gloucesternaughttodowithmistressshoreite~ebesthedoitsecretlyalone~114":"Gloucester — Nada a ver com a senhora Shore! Digo-te, camarada,\naquele que nada faz com ela, salvo um só,\nmelhor fora que o fizesse em segredo, a sós.","brakenburywhatonemylord~brakenburywhatonemylord~23":"Brakenbury — Que um só, meu senhor?","gloucesterherhusbandknavewouldstthoubetr~knavewouldstthoubetrayme~44":"Gloucester — O marido dela, patife: querias me trair?","brakenburyibeseechyourgracetopardonmeand~nferencewiththenobleduke~83":"Brakenbury — Suplico a Vossa Graça que me perdoe e, além disso,\nque cesse a conversa com o nobre duque.","clarenceweknowthychargebrakenburyandwill~rgebrakenburyandwillobey~44":"Clarence — Conhecemos tua ordem, Brakenbury, e obedeceremos.","gloucesterwearethequeensabjectsandmustob~edeeperthanyoucanimagine~236":"Gloucester — Somos os vassalos da rainha e devemos obedecer.\nIrmão, adeus: irei ao rei;\ne em tudo o que quiseres empregar-me,\nainda que fosse chamar de irmã a viúva do rei Eduardo,\ncumprirei para te libertar. Entretanto,\neste profundo opróbrio entre irmãos\ntoca-me mais fundo do que podes imaginar.","clarenceiknowitpleasethneitherofuswell~tpleasethneitherofuswell~38":"Clarence — Sei que a nenhum de nós agrada.","gloucesterwellyourimprisonmentshallnotbe~ryoumeantimehavepatience~94":"Gloucester — Bem, tua prisão não será longa;\nlibertar-te-ei, ou então ficarei preso em teu lugar:\nentretanto, tem paciência.","clarenceimustperforcefarewellexeuntclare~arencebrakenburyandguard~61":"Clarence — Por força devo. Adeus. Saem Clarence, Brakenbury e a Guarda.","gloucestergotreadthepaththatthoushaltnee~rethenewdeliverdhastings~187":"Gloucester — Vai, trilha o caminho de que nunca voltarás,\nsimples e franco Clarence! Amo-te tanto\nque em breve enviarei tua alma ao céu,\nse o céu aceitar o presente de nossas mãos.\nMas quem vem aí? o recém-libertado Hastings?","enterlordhastings~enterlordhastings~17":"Entra Lorde Hastings.","hastingsgoodtimeofdayuntomygraciouslord~eofdayuntomygraciouslord~39":"Hastings — Bom dia ao meu gracioso senhor!","gloucesterasmuchuntomygoodlordchamberlai~rdshipbrookdimprisonment~107":"Gloucester — O mesmo ao meu bom lorde camareiro!\nSede bem-vindo ao ar livre.\nComo Vossa Senhoria suportou a prisão?","hastingswithpatiencenoblelordasprisoners~thecauseofmyimprisonment~111":"Hastings — Com paciência, nobre senhor, como devem os prisioneiros:\nmas viverei, meu senhor, para agradecer\naos que foram a causa de minha prisão.","gloucesternodoubtnodoubtandsoshallclaren~prevaildasmuchonhimasyou~108":"Gloucester — Sem dúvida, sem dúvida; e assim fará Clarence também;\npois os que foram vossos inimigos são os dele,\ne prevaleceram sobre ele tanto quanto sobre vós.","hastingsmorepitythattheeagleshouldbemewd~andbuzzardspreyatliberty~74":"Hastings — Maior pena que a águia esteja engaiolada\nenquanto milhafres e abutres caçam em liberdade.","gloucesterwhatnewsabroad~gloucesterwhatnewsabroad~24":"Gloucester — Que novas há por fora?","hastingsnonewssobadabroadasthisathomethe~hysiciansfearhimmightily~100":"Hastings — Nenhuma tão ruim lá fora quanto esta aqui em casa:\no rei está doente, fraco e melancólico,\ne seus médicos o temem enormemente.","gloucesternowbysaintpaulthisnewsisbadind~ughtuponwhatisheinhisbed~147":"Gloucester — Ora, por São Paulo, esta notícia é deveras ruim.\nOh, ele manteve por muito tempo uma dieta maligna\ne consumiu em excesso a própria pessoa real:\né muito penoso pensar nisso.\nEntão, está de cama?","hastingsheis~hastingsheis~12":"Hastings — Está.","gloucestergoyoubeforeandiwillfollowyouex~henmusticountmygainsexit~670":"Gloucester — Ide na frente, e eu vos seguirei. Sai Hastings.\nEle não pode viver, espero; e não deve morrer\naté que George seja despachado em cavalos de posta ao céu.\nEntrarei, para atiçar mais o ódio do rei contra Clarence,\ncom mentiras bem temperadas de argumentos pesados;\ne, se não falhar meu profundo intento,\nClarence não terá outro dia de vida:\nfeito isso, que Deus leve o rei Eduardo à sua misericórdia\ne deixe o mundo para eu me agitar nele!\nPois então casarei com a filha mais nova de Warwick.\nQue importa que eu tenha matado o marido e o pai dela?\nO modo mais pronto de compensar a moça\né tornar-me seu marido e seu pai:\no que farei; não tanto por amor\nquanto por outro secreto e íntimo intento,\nque devo alcançar casando com ela.\nMas ainda corro na frente do cavalo ao mercado:\nClarence ainda respira; Eduardo ainda vive e reina:\nquando se forem, então devo contar meus ganhos. Sai.","sceneii~sceneii~7":"Cena II","thesameanotherstreet~thesameanotherstreet~20":"O mesmo lugar. Outra rua.","enterthecorpseofkinghenrythesixthgentlem~tladyannebeingthemourner~86":"Entra o cadáver do rei Henrique VI, com Cavalheiros de alabarda a guardá-lo; Lady Anne como pranteadora.","annesetdownsetdownyourhonourableloadifho~esilamentkinghenryscorse~1050":"Anne — Pousai, pousai vossa honrada carga,\nse a honra pode ser amortalhada num esquife,\nenquanto, por algum tempo, em exéquias lamento\na queda prematura do virtuoso Lancaster.\nPobre figura gélida como chave de um rei santo!\nPálidas cinzas da casa de Lancaster!\nTu, resto sem sangue desse sangue real!\nSeja-me lícito invocar teu espectro\npara ouvir os lamentos da pobre Anne,\nesposa de teu Eduardo, de teu filho trucidado,\napunhalado pela mesma mão que fez estas feridas!\nVede, nestas janelas que deixaram escapar tua vida,\nderramo o bálsamo inútil de meus pobres olhos.\nMaldita seja a mão que fez estes buracos fatais!\nMaldito o coração que teve coração para fazê-lo!\nMaldito o sangue que daqui fez jorrar este sangue!\nMais terrível desgraça caia sobre aquele odiado miserável\nque nos faz miseráveis com tua morte\ndo que eu possa desejar a víboras, aranhas, sapos\nou a qualquer coisa peçonhenta que rasteja e vive!\nSe ele tiver algum dia um filho, que seja abortivo,\nprodigioso, e trazido à luz antes do tempo,\ncujo aspecto feio e antinatural\npossa assustar à vista a esperançosa mãe;\ne seja esse o herdeiro de sua infelicidade!\nSe tiver esposa, que ela se torne\ntão infeliz com a morte dele\nquanto eu me tornei com a de meu pobre senhor e a tua!\nVamos, agora para Chertsey com vossa santa carga,\ntirada de São Paulo para ser enterrada ali;\ne, sempre que vos cansardes do peso,\ndescansai, enquanto lamento o corpo do rei Henrique.","entergloucester~entergloucester~15":"Entra Gloucester.","gloucesterstayyouthatbearthecorseandseti~bearthecorseandsetitdown~45":"Gloucester — Parai, vós que levais o cadáver, e pousai-o.","annewhatblackmagicianconjuresupthisfiend~opdevotedcharitabledeeds~68":"Anne — Que mago negro evoca este demônio\npara impedir atos devotos e caridosos?","gloucestervillainssetdownthecorseorbysai~eacorseofhimthatdisobeys~76":"Gloucester — Miseráveis, pousai o cadáver; ou, por São Paulo,\nfarei cadáver de quem desobedecer.","gentlemanmylordstandbackandletthecoffinp~dbackandletthecoffinpass~43":"Cavalheiro — Meu senhor, afastai-vos e deixai o caixão passar.","gloucesterunmannerddogstandthouwhenicomm~theebeggarforthyboldness~148":"Gloucester — Cão sem educação! para quando eu mandar:\nlevanta tua alabarda acima do meu peito,\nou, por São Paulo, derrubo-te a meus pés\ne piso-te, mendigo, pela tua ousadia.","annewhatdoyoutrembleareyouallafraidalasi~stnothavethereforebegone~203":"Anne — Como, tremeis? estais todos com medo?\nAi, não vos censuro; pois sois mortais,\ne olhos mortais não suportam o diabo.\nAfasta-te, tu terrível ministro do inferno!\nTiveste poder apenas sobre seu corpo mortal;\nsua alma não podes ter; portanto, vai-te.","gloucestersweetsaintforcharitybenotsocur~ntforcharitybenotsocurst~42":"Gloucester — Doce santa, por caridade, não sejas tão feroz.","annefouldevilforgodssakehenceandtroubleu~lgoverndarmhathbutchered~650":"Anne — Diabo imundo, por Deus, fora, e não nos perturbes;\npois fizeste da terra feliz o teu inferno,\nencheste-a de gritos de maldição e profundos clamores.\nSe te deleitas em ver teus atos hediondos,\ncontempla este exemplo de tuas carnificinas.\nOh, senhores, vede, vede! as feridas do morto Henrique\nabrem suas bocas coaguladas e sangram de novo!\nEnrubesce, enrubesce, massa de deformidade imunda;\npois é a tua presença que exala este sangue\nde veias frias e vazias, onde não mora sangue;\ntua ação, desumana e antinatural,\nprovoca este dilúvio antinatural.\nÓ Deus, que fizeste este sangue, vinga sua morte!\nÓ terra, que bebes este sangue, vinga sua morte!\nOu o céu fulmine o assassino com um raio,\nou a terra se abra e o devore vivo,\ncomo engoles o sangue deste bom rei,\nque seu braço governado pelo inferno trucidou!","gloucesterladyyouknownorulesofcharitywhi~forbadblessingsforcurses~77":"Gloucester — Senhora, não conheceis as regras da caridade,\nque retribui o mal com o bem, as maldições com bênçãos.","annevillainthouknowstnolawofgodnormannob~ebutknowssometouchofpity~75":"Anne — Miserável, não conheces lei de Deus nem dos homens:\nnenhuma fera é tão feroz que não conheça algum toque de piedade.","gloucesterbutiknownoneandthereforeamnobe~oneandthereforeamnobeast~43":"Gloucester — Mas eu não conheço nenhum, e portanto não sou fera.","anneowonderfulwhendevilstellthetruth~ulwhendevilstellthetruth~36":"Anne — Oh, maravilha, quando os diabos dizem a verdade!","gloucestermorewonderfulwhenangelsaresoan~mstancebuttoacquitmyself~140":"Gloucester — Maior maravilha, quando os anjos se zangam tanto.\nDignai-vos, divina perfeição de mulher,\nquanto a estes supostos males, permitir-me\npor circunstâncias ao menos justificar-me.","annevouchsafedefusedinfectionofamanforth~ancetocursethycursedself~103":"Anne — Dignai-vos, infecção disforme de homem,\nquanto a estes males conhecidos, apenas permitir-me\npor circunstâncias amaldiçoar tua maldita pessoa.","gloucesterfairerthantonguecannametheelet~entleisuretoexcusemyself~78":"Gloucester — Mais bela do que língua pode nomear, concede-me\nalgum paciente vagar para me desculpar.","annefoulerthanheartcanthinktheethoucanst~ecurrentbuttohangthyself~75":"Anne — Mais imundo do que o coração pode pensar, não podes dar\ndesculpa que valha, a não ser enforcar-te.","gloucesterbysuchdespairishouldaccusemyse~spairishouldaccusemyself~42":"Gloucester — Por tal desespero, eu me acusaria.","anneandbydespairingshouldstthoustandexcu~orthyslaughteruponothers~112":"Anne — E, desesperando, ficarias desculpado,\npor fazeres digna vingança em ti mesmo,\ntu que fizeste indigna matança nos outros.","gloucestersaythatislewthemnot~estersaythatislewthemnot~29":"Gloucester — E se eu disser que não os matei?","annewhythentheyarenotdeadbutdeadtheyarea~reanddevilishslavebythee~61":"Anne — Ora, então não estão mortos:\nmas mortos estão, e, escravo do demônio, por ti.","gloucesterididnotkillyourhusband~erididnotkillyourhusband~32":"Gloucester — Eu não matei vosso marido.","annewhythenheisalive~annewhythenheisalive~20":"Anne — Ora, então ele está vivo.","gloucesternayheisdeadandslainbyedwardsha~eadandslainbyedwardshand~42":"Gloucester — Não, está morto; e morto pela mão de Eduardo.","anneinthyfoulthroatthouliestqueenmargare~rothersbeatasidethepoint~157":"Anne — Na tua garganta imunda mentes: a rainha Margarida viu\ntua espada assassina fumegando em seu sangue;\na mesma que uma vez apontaste contra o peito dela,\nmas teus irmãos desviaram a ponta.","gloucesteriwasprovokedbyherslanderouston~uponmyguiltlessshoulders~86":"Gloucester — Fui provocado por sua língua caluniosa,\nque lançou a culpa deles sobre meus ombros inocentes.","annethouwastprovokedbythybloodymindwhich~didstthounotkillthisking~95":"Anne — Foste provocado por tua mente sanguinária,\nque nunca sonhou com outra coisa que carnificinas:\nnão mataste este rei?","gloucesterigrantye~gloucesterigrantye~18":"Gloucester — Concedo-vos.","annedostgrantmehedgehogthengodgrantmetoo~wasgentlemildandvirtuous~101":"Anne — Concedes-me, porco-espinho? então Deus me conceda também\nque sejas danado por esse ato perverso!\nOh, ele era gentil, brando e virtuoso!","gloucesterthefitterforthekingofheaventha~ekingofheaventhathathhim~48":"Gloucester — Tanto mais apto para o Rei do céu, que o tem.","anneheisinheavenwherethoushaltnevercome~nwherethoushaltnevercome~39":"Anne — Ele está no céu, aonde tu nunca chegarás.","gloucesterlethimthankmethatholptosendhim~terforthatplacethanearth~82":"Gloucester — Que ele me agradeça, que ajudei a enviá-lo para lá;\npois estava mais apto àquele lugar do que à terra.","anneandthouunfitforanyplacebuthell~uunfitforanyplacebuthell~34":"Anne — E tu inapto para qualquer lugar senão o inferno.","gloucesteryesoneplaceelseifyouwillhearme~lseifyouwillhearmenameit~46":"Gloucester — Sim, para outro lugar ainda, se quiserdes ouvir-me nomeá-lo.","annesomedungeon~annesomedungeon~15":"Anne — Alguma masmorra.","gloucesteryourbedchamber~gloucesteryourbedchamber~24":"Gloucester — Vossa alcova.","anneillrestbetidethechamberwherethoulies~thechamberwherethouliest~41":"Anne — Mau repouso caiba à alcova onde te deitares!","gloucestersowillitmadamtilliliewithyou~llitmadamtilliliewithyou~38":"Gloucester — Assim será, senhora, até que me deite convosco.","anneihopeso~anneihopeso~11":"Anne — Assim espero.","gloucesteriknowsobutgentleladyannetoleav~blamefulastheexecutioner~191":"Gloucester — Assim sei. Mas, gentil Lady Anne,\npara deixar este agudo duelo de nossos espíritos\ne passar a um método um tanto mais lento,\nnão é o causador das mortes prematuras\ndestes Plantagenetas, Henrique e Eduardo,\ntão culpado quanto o executor?","annethouartthecauseandmostaccursedeffect~useandmostaccursedeffect~40":"Anne — Tu és a causa, e o mais maldito efeito.","gloucesteryourbeautywasthecauseofthateff~eonehourinyoursweetbosom~144":"Gloucester — Vossa beleza foi a causa desse efeito;\nvossa beleza, que me assombrou no sono\npara empreender a morte do mundo inteiro,\ndesde que eu pudesse viver uma hora em vosso doce seio.","anneifithoughtthatitelltheehomicidethese~ndthatbeautyfrommycheeks~77":"Anne — Se eu pensasse isso, digo-te, homicida,\nestas unhas arrancariam essa beleza de minhas faces.","gloucestertheseeyescouldneverenduresweet~soibythatitismydaymylife~137":"Gloucester — Estes olhos nunca suportariam a ruína da doce beleza;\nnão a mancharíeis, se eu estivesse presente:\ncomo o mundo todo se alegra com o sol,\nassim eu com ela; é meu dia, minha vida.","anneblacknightoershadethydayanddeaththyl~adethydayanddeaththylife~43":"Anne — Negra noite ensombreça teu dia, e a morte tua vida!","gloucestercursenotthyselffaircreaturetho~ffaircreaturethouartboth~48":"Gloucester — Não te amaldiçoes, bela criatura; tu és ambos.","anneiwouldiweretoberevengedonthee~diweretoberevengedonthee~33":"Anne — Quisera ser, para me vingar de ti.","gloucesteritisaquarrelmostunnaturaltober~vengedonhimthatlovethyou~65":"Gloucester — É querela muito antinatural\nvingar-se de quem vos ama.","anneitisaquarreljustandreasonabletoberev~edonhimthatslewmyhusband~67":"Anne — É querela justa e razoável\nvingar-se de quem matou meu marido.","gloucesterhethatberefttheeladyofthyhusba~helptheetoabetterhusband~73":"Gloucester — Aquele que privou-vos, senhora, de vosso marido,\nfê-lo para vos ajudar a ter melhor marido.","annehisbetterdothnotbreatheupontheearth~thnotbreatheupontheearth~39":"Anne — O melhor dele não respira sobre a terra.","gloucesterhelivesthatlovestheebetterthan~vestheebetterthanhecould~47":"Gloucester — Vive quem vos ama mais do que ele podia.","annenamehim~annenamehim~11":"Anne — Nomeia-o.","gloucesterplantagenet~gloucesterplantagenet~21":"Gloucester — Plantageneta.","annewhythatwashe~annewhythatwashe~16":"Anne — Ora, esse era ele.","gloucestertheselfsamenamebutoneofbettern~namebutoneofbetternature~45":"Gloucester — O mesmo nome, mas de melhor natureza.","annewhereishe~annewhereishe~13":"Anne — Onde está ele?","gloucesterhereshespittethathimwhydosttho~athimwhydostthouspitatme~49":"Gloucester — Aqui. Ela cospe nele. Por que cuspis em mim?","annewoulditweremortalpoisonforthysake~remortalpoisonforthysake~37":"Anne — Quisera que fosse veneno mortal, por tua causa!","gloucesternevercamepoisonfromsosweetapla~epoisonfromsosweetaplace~42":"Gloucester — Nunca veio veneno de lugar tão doce.","anneneverhungpoisononafoulertoadoutofmys~ightthoudostinfectmyeyes~64":"Anne — Nunca pendeu veneno de sapo mais imundo.\nFora de minha vista! infeccionas meus olhos.","gloucesterthineeyessweetladyhaveinfected~weetladyhaveinfectedmine~44":"Gloucester — Vossos olhos, doce senhora, infeccionaram os meus.","annewouldtheywerebasiliskstostriketheede~asiliskstostriketheedead~42":"Anne — Quisera que fossem basiliscos, para te fulminar!","gloucesteriwouldtheywerethatimightdieato~ptheswordagainortakeupme~1247":"Gloucester — Quisera eu que fossem, para que eu morresse de uma vez;\npois agora me matam com uma morte viva.\nEsses vossos olhos tiraram dos meus lágrimas salgadas,\nenvergonharam-lhes o aspecto com abundância de gotas infantis:\nestes olhos, que nunca verteram lágrima de remorso,\nnão, quando meu pai York e Eduardo choraram\nao ouvir o lamento lastimoso que Rutland fez\nquando o Clifford de rosto negro brandiu a espada contra ele;\nnem quando vosso pai guerreiro, como criança,\ncontou a triste história da morte de meu pai\ne vinte vezes parou para soluçar e chorar,\ntanto que todos os presentes tinham as faces molhadas,\ncomo árvores salpicadas de chuva: naquele triste tempo\nmeus olhos viris desdenharam uma humilde lágrima;\ne o que aqueles pesares não puderam daí exalar,\nvossa beleza o fez, e os cegou de tanto chorar.\nNunca supliquei a amigo nem a inimigo;\nminha língua nunca aprendeu doces palavras lisonjeiras;\nmas agora, sendo vossa beleza proposta como meu prêmio,\nmeu orgulhoso coração suplica e impele minha língua a falar. Ela o olha com desdém.\nNão ensines teus lábios a tal desdém, pois foram feitos\npara beijar, senhora, não para tal desprezo.\nSe teu coração vingativo não pode perdoar,\nvê, aqui te empresto esta espada de ponta aguda;\nse te aprouver escondê-la neste peito leal\ne deixar sair a alma que te adora,\nofereço-o nu ao golpe mortal\ne humildemente peço a morte de joelhos. Abre o peito: ela investe contra ele com a espada.\nNão, não pares; pois eu matei o rei Henrique,\nmas foi tua beleza que me provocou.\nVamos, despacha; fui eu que apunhalei o jovem Eduardo,\nmas foi teu rosto celestial que me instigou. Aqui ela deixa cair a espada.\nApanha de novo a espada, ou apanha-me a mim.","annearisedissemblerthoughiwishthydeathiw~iwillnotbetheexecutioner~62":"Anne — Levanta-te, dissimulado: embora eu deseje tua morte,\nnão serei a executora.","gloucesterthenbidmekillmyselfandiwilldoi~mekillmyselfandiwilldoit~41":"Gloucester — Então manda-me matar a mim mesmo, e o farei.","anneihavealready~anneihavealready~16":"Anne — Já mandei.","gloucestertushthatwasinthyragespeakitaga~athsthoushaltbeaccessary~166":"Gloucester — Bah, isso foi na tua fúria:\ndize-o de novo e, com a própria palavra,\nesta mão, que, por teu amor, matou teu amor,\npor teu amor matará um amor muito mais verdadeiro;\nde ambas as mortes serás cúmplice.","anneiwouldiknewthyheart~anneiwouldiknewthyheart~23":"Anne — Quisera conhecer teu coração.","gloucestertisfiguredinmytongue~stertisfiguredinmytongue~30":"Gloucester — Está figurado em minha língua.","anneifearmebotharefalse~anneifearmebotharefalse~23":"Anne — Receio que ambos sejam falsos.","gloucesterthennevermanwastrue~esterthennevermanwastrue~29":"Gloucester — Então nunca homem foi verdadeiro.","annewellwellputupyoursword~newellwellputupyoursword~26":"Anne — Bem, bem, guarda a espada.","gloucestersaythenmypeaceismade~stersaythenmypeaceismade~30":"Gloucester — Dizei, então, que fiz as pazes.","annethatshallyouknowhereafter~hatshallyouknowhereafter~29":"Anne — Isso sabereis depois.","gloucesterbutshalliliveinhope~esterbutshalliliveinhope~29":"Gloucester — Mas viverei na esperança?","anneallmenihopeliveso~anneallmenihopeliveso~21":"Anne — Todos os homens, espero, vivem assim.","gloucestervouchsafetowearthisring~rvouchsafetowearthisring~33":"Gloucester — Dignai-vos usar este anel.","annetotakeisnottogive~annetotakeisnottogive~21":"Anne — Aceitar não é dar.","gloucesterlookhowthisringencompasseththy~nfirmhishappinessforever~213":"Gloucester — Vede como este anel envolve vosso dedo,\nassim vosso peito encerra meu pobre coração;\nusai ambos, pois ambos são vossos.\nE se vosso pobre e devoto suplicante puder\nsó pedir um favor à vossa graciosa mão,\nconfirmareis sua felicidade para sempre.","annewhatisit~annewhatisit~12":"Anne — Qual é?","gloucesterthatitwouldpleasetheeleavethes~eseechyougrantmethisboon~292":"Gloucester — Que vos aprouvesse deixar estes tristes ofícios\naquele que tem mais motivo de ser pranteador,\ne logo vos recolher a Crosby Place;\nonde, depois de eu ter solenemente sepultado\nno mosteiro de Chertsey este nobre rei\ne molhado sua sepultura com minhas lágrimas de arrependimento,\nirei ver-vos com todo o dever conveniente:\npor várias razões desconhecidas, suplico-vos,\nconcedei-me esta graça.","annewithallmyheartandmuchitjoysmetootose~andberkeleygoalongwithme~94":"Anne — De todo o coração; e muito me alegra também\nver que vos tornastes tão penitente.\nTressel e Berkeley, vinde comigo.","gloucesterbidmefarewell~gloucesterbidmefarewell~23":"Gloucester — Dizei-me adeus.","annetismorethanyoudeservebutsinceyouteac~dyannetresselandberkeley~121":"Anne — É mais do que mereceis;\nmas já que me ensinais a adular-vos,\nimaginai que já disse adeus. Saem Lady Anne, Tressel e Berkeley.","gloucestersirstakeupthecorse~cestersirstakeupthecorse~28":"Gloucester — Senhores, levantai o cadáver.","gentlemantowardschertseynoblelord~towardschertseynoblelord~33":"Cavalheiro — Para Chertsey, nobre senhor?","gloucesternotowhitefriarsthereattendmyco~ayseemyshadowasipassexit~1227":"Gloucester — Não, para White-Friars; ali aguardai minha chegada. Saem todos, menos Gloucester.\nJá se viu mulher cortejada neste humor?\nJá se viu mulher conquistada neste humor?\nTê-la-ei; mas não a manterei por muito tempo.\nComo! eu, que matei seu marido e o pai dele,\npegá-la no extremo ódio de seu coração,\ncom maldições na boca, lágrimas nos olhos,\na sangrenta testemunha de seu ódio ao lado;\ntendo Deus, sua consciência e estes obstáculos contra mim,\ne eu sem nada para apoiar meu pedido,\nsenão o puro diabo e olhares dissimulados,\ne ainda assim vencê-la, contra o mundo todo a nada!\nHa!\nEsqueceu já aquele valente príncipe,\nEduardo, seu senhor, que eu, há uns três meses,\napunhalei em meu humor colérico em Tewkesbury?\nUm cavalheiro mais doce e mais amável,\nformado na prodigalidade da natureza,\njovem, valente, sábio e, sem dúvida, muito real,\no vasto mundo não pode oferecer de novo:\ne ainda assim ela rebaixará seus olhos a mim,\nque ceifei a dourada flor deste doce príncipe\ne a fiz viúva de um leito de dor?\nA mim, cujo tudo não iguala a metade de Eduardo?\nA mim, que manco e sou assim disforme?\nMeu ducado contra um miserável denário,\neu me engano em minha pessoa todo este tempo:\npela minha vida, ela acha, embora eu não ache,\nque sou um homem maravilhosamente bem-feito.\nGastarei com um espelho,\ne contratarei umas vinte ou duas dúzias de alfaiates\npara estudar modas que adornem meu corpo:\njá que me insinuei na minha própria estima,\nmanterei isso com algum pequeno custo.\nMas primeiro farei virar aquele sujeito em sua cova;\ne depois voltarei lamentando a meu amor.\nBrilha, belo sol, até que eu compre um espelho,\npara que eu veja minha sombra ao passar. Sai.","sceneiii~sceneiii~8":"Cena III","thepalace~thepalace~9":"O palácio.","enterqueenelizabethlordriversandlordgrey~ethlordriversandlordgrey~40":"Entram a Rainha Elizabeth, Lord Rivers e Lord Grey.","rivershavepatiencemadamtheresnodoubthism~ecoverhisaccustomdhealth~79":"Rivers — Tende paciência, senhora: não há dúvida de que Sua Majestade\nlogo recuperará a saúde habitual.","greyinthatyoubrookitillitmakeshimworseth~cewithquickandmerrywords~116":"Grey — Se a suportais mal, isso o piora:\nportanto, por Deus, acolhei bom consolo\ne animai Sua Graça com palavras vivas e alegres.","queenelizabethifheweredeadwhatwouldbetid~edeadwhatwouldbetideofme~45":"Rainha Elizabeth — Se ele morresse, que seria de mim?","riversnootherharmbutlossofsuchalord~erharmbutlossofsuchalord~35":"Rivers — Nenhum outro mal além da perda de tal senhor.","queenelizabeththelossofsuchalordincludes~suchalordincludesallharm~47":"Rainha Elizabeth — A perda de tal senhor inclui todo mal.","greytheheavenshaveblessdyouwithagoodlyso~ourcomforterwhenheisgone~70":"Grey — Os céus vos abençoaram com um belo filho,\npara ser vosso consolador quando ele se for.","queenelizabethohheisyoungandhisminorityi~atlovesnotmenornoneofyou~105":"Rainha Elizabeth — Oh, ele é jovem, e sua menoridade\nfoi confiada a Ricardo de Gloucester,\num homem que não me ama, nem a nenhum de vós.","riversisitconcludedthatheshallbeprotecto~edthatheshallbeprotector~41":"Rivers — Está decidido que ele será protetor?","queenelizabethitisdeterminednotconcluded~tmustbeifthekingmiscarry~73":"Rainha Elizabeth — Está determinado, não concluído ainda:\nmas assim será, se o rei se for.","enterbuckinghamandderby~enterbuckinghamandderby~23":"Entram Buckingham e Derby.","greyherecomethelordsofbuckinghamandderby~ordsofbuckinghamandderby~40":"Grey — Aí vêm os lordes de Buckingham e Derby.","buckinghamgoodtimeofdayuntoyourroyalgrac~eofdayuntoyourroyalgrace~41":"Buckingham — Bom dia à vossa real graça!","derbygodmakeyourmajestyjoyfulasyouhavebe~jestyjoyfulasyouhavebeen~42":"Derby — Deus faça Vossa Majestade tão alegre quanto já foi!","queenelizabeththecountessrichmondgoodmyl~tyouforherproudarrogance~185":"Rainha Elizabeth — A condessa de Richmond, meu bom lorde de Derby,\nmal dirá amém às vossas boas preces.\nContudo, Derby, apesar de ser vossa esposa\ne não me amar, ficai, bom senhor, certo\nde que não vos odeio por sua orgulhosa arrogância.","derbyidobeseechyoueithernotbelievetheenv~knessandnogroundedmalice~174":"Derby — Suplico-vos, ou não creiais\nnas invejosas calúnias de seus falsos acusadores;\nou, se ela for acusada em relato verdadeiro,\nsuportai sua fraqueza, que, penso, procede\nde doença caprichosa, e não de malícia fundada.","riverssawyouthekingtodaymylordofderby~hekingtodaymylordofderby~37":"Rivers — Vistes o rei hoje, meu lorde de Derby?","derbybutnowthedukeofbuckinghamandiarecom~mefromvisitinghismajesty~63":"Derby — Agora mesmo o duque de Buckingham e eu\nviemos de visitar Sua Majestade.","queenelizabethwhatlikelihoodofhisamendme~ihoodofhisamendmentlords~47":"Rainha Elizabeth — Que probabilidade há de sua melhora, senhores?","buckinghammadamgoodhopehisgracespeaksche~hisgracespeakscheerfully~47":"Buckingham — Senhora, boa esperança; Sua Graça fala alegremente.","queenelizabethgodgranthimhealthdidyoucon~ealthdidyouconferwithhim~50":"Rainha Elizabeth — Deus lhe conceda saúde! Conversastes com ele?","buckinghammadamwedidhedesirestomakeatone~rnthemtohisroyalpresence~154":"Buckingham — Senhora, sim: deseja fazer reconciliação\nentre o duque de Gloucester e vossos irmãos,\ne entre eles e meu lorde camareiro;\ne mandou avisá-los para comparecerem à sua real presença.","queenelizabethwouldallwerewellbutthatwil~rhappinessisatthehighest~79":"Rainha Elizabeth — Quisera que tudo estivesse bem! mas isso nunca será:\ntemo que nossa felicidade esteja no auge.","entergloucesterhastingsanddorset~ucesterhastingsanddorset~32":"Entram Gloucester, Hastings e Dorset.","gloucestertheydomewrongandiwillnotendure~ilkenslyinsinuatingjacks~407":"Gloucester — Fazem-me injustiça, e não a suportarei:\nquem são os que se queixam ao rei\nde que eu, ora essa, sou áspero e não os amo?\nPor São Paulo, amam pouco Sua Graça\nos que lhe enchem os ouvidos de tais rumores de discórdia.\nPorque não sei adular e falar belo,\nsorrir nas caras dos homens, afagar, enganar e trapacear,\nfazer mesuras com acenos franceses e cortesia de macaco,\ndevo ser tido por inimigo rancoroso.\nNão pode um homem simples viver e não pensar mal,\nsem que sua simples verdade seja assim ultrajada\npor Joões de seda, ladinos e insinuantes?","riverstowhominallthispresencespeaksyourg~spresencespeaksyourgrace~44":"Rivers — A quem, em toda esta assembleia, fala Vossa Graça?","gloucestertotheethathastnorhonestynorgra~blehimwithlewdcomplaints~249":"Gloucester — A ti, que não tens honestidade nem graça.\nQuando te feri? quando te fiz mal?\nOu a ti? ou a ti? ou a qualquer da vossa facção?\nUma praga sobre todos vós! Sua real pessoa—\nque Deus preserve melhor do que desejaríeis!—\nmal pode ter o sossego de um fôlego,\nsem que o importuneis com queixas vis.","queenelizabethbrotherofgloucesteryoumist~yourillwillandsoremoveit~284":"Rainha Elizabeth — Irmão de Gloucester, enganais-vos no assunto.\nO rei, por sua própria real disposição,\ne não provocado por nenhum outro suplicante;\nmirando, talvez, vosso ódio interior,\nque em vossas ações externas se mostra\ncontra meus parentes, irmãos e contra mim,\nfá-lo mandar chamar; para daí colher\no motivo de vossa má vontade, e assim removê-lo.","gloucestericannottelltheworldisgrownsoba~nyagentlepersonmadeajack~143":"Gloucester — Não sei dizer: o mundo está tão ruim\nque os carriças caçam onde as águias não ousam pousar:\ndesde que todo João virou cavalheiro,\nmuito cavalheiro foi feito João.","queenelizabethcomecomeweknowyourmeaningb~twenevermayhaveneedofyou~119":"Rainha Elizabeth — Vamos, vamos, conhecemos vosso sentido, irmão de Gloucester;\ninvejais minha ascensão e a de meus amigos:\nDeus conceda que nunca precisemos de vós!","gloucestermeantimegodgrantsthatwehavenee~dayssincewereworthanoble~214":"Gloucester — Entretanto, Deus concede que precisemos de vós:\nvosso irmão está preso por vossa causa,\neu mesmo desonrado, e a nobreza\ntida em desprezo; enquanto muitas belas promoções\nsão dadas diariamente para enobrecer os que\nmal, há uns dois dias, valiam um nobre.","queenelizabethbyhimthatraisedmetothiscar~rawmeinthesevilesuspects~234":"Rainha Elizabeth — Por Aquele que me elevou a esta altura cheia de cuidados\ndaquela sorte contente que eu desfrutava,\nnunca incitei Sua Majestade\ncontra o duque de Clarence, mas fui\nardente advogada a interceder por ele.\nMeu senhor, fazeis-me vergonhosa injúria\nem me envolver falsamente nestas vis suspeitas.","gloucesteryoumaydenythatyouwerenotthecau~hastingslateimprisonment~74":"Gloucester — Podeis negar que não fostes a causa\nda recente prisão de meu lorde Hastings.","riversshemaymylordfor~riversshemaymylordfor~21":"Rivers — Pode, meu senhor, pois—","gloucestershemaylordriverswhywhoknowsnot~enotshemayyeamarrymayshe~205":"Gloucester — Pode, lorde Rivers! ora, quem não o sabe?\nPode mais, senhor, do que negar isso:\npode ajudar-vos a muitas belas preferências,\ne depois negar a mão que ajudou nisso,\ne atribuir aquelas honras aos vossos altos méritos.\nO que ela não pode? Pode, sim, em verdade, pode—","riverswhatmarrymayshe~riverswhatmarrymayshe~21":"Rivers — O quê, em verdade, pode?","gloucesterwhatmarrymayshemarrywithakinga~urgrandamhadaworsermatch~99":"Gloucester — O quê, em verdade, pode! casar com um rei,\num solteiro, e também belo rapaz:\nsei que vossa avó teve pior partido.","queenelizabethmylordofgloucesterihavetoo~tauntedscorndandbaitedat~251":"Rainha Elizabeth — Meu lorde de Gloucester, suportei por demais tempo\nvossas rudes censuras e vossos amargos escárnios:\npelo céu, informarei Sua Majestade\ndesses grosseiros insultos que tantas vezes aturei.\nPrefiro ser criada de aldeia\nque grande rainha, com a condição\nde ser assim insultada, desprezada e acossada:","enterqueenmargaretbehind~enterqueenmargaretbehind~24":"Entra a Rainha Margarida, atrás.","smalljoyhaveiinbeingenglandsqueen~aveiinbeingenglandsqueen~33":"Pouca alegria tenho em ser rainha da Inglaterra.","queenmargaretandlessendbethatsmallgodibe~ourstateandseatisduetome~79":"Rainha Margarida — E diminua-se esse pouco, Deus, suplico-te!\nTua honra, estado e trono são devidos a mim.","gloucesterwhatthreatyoumewithtellingofth~eakmypainsarequiteforgot~177":"Gloucester — Quê! ameaçais-me de contar ao rei?\nContai-lhe, e não poupeis: vede, o que eu disse\nconfirmarei na presença do rei:\nousarei aventurar-me a ser enviado à Torre.\nÉ tempo de falar; minhas penas estão de todo esquecidas.","queenmargaretoutdevilirememberthemtoowel~wardmypoorsonattewksbury~105":"Rainha Margarida — Fora, demônio! lembro-me delas bem demais:\nmataste meu marido Henrique na Torre,\ne Eduardo, meu pobre filho, em Tewkesbury.","gloucesterereyouwerequeenyeaoryourhusban~isehisbloodispiltmineown~166":"Gloucester — Antes que fôsseis rainha, ou vosso marido rei,\neu era besta de carga em seus grandes negócios;\ncapinador de seus orgulhosos adversários,\nliberal recompensador de seus amigos:\npara tornar real seu sangue, derramei o meu.","queenmargaretyeaandmuchbetterbloodthanhi~etterbloodthanhisorthine~48":"Rainha Margarida — Sim, e sangue muito melhor que o dele ou o teu.","gloucesterinallwhichtimeyouandyourhusban~lwhatihavebeenandwhatiam~242":"Gloucester — Em todo esse tempo, vós e vosso marido Grey\nfostes facciosos pela casa de Lancaster;\ne, Rivers, assim fostes vós. Não foi vosso marido\nmorto na batalha de Margarida em Saint Albans?\nDeixai-me lembrar-vos, se esqueceis,\no que fostes até agora e o que sois;\ne também o que fui e o que sou.","queenmargaretamurderousvillainandsostill~villainandsostillthouart~47":"Rainha Margarida — Um miserável assassino, e assim ainda és.","gloucesterpoorclarencedidforsakehisfathe~rehimselfwhichjesupardon~84":"Gloucester — O pobre Clarence abandonou seu pai, Warwick;\nsim, e perjurou-se—que Jesus perdoe!—","queenmargaretwhichgodrevenge~nmargaretwhichgodrevenge~28":"Rainha Margarida — Que Deus vingue!","gloucestertofightonedwardspartyforthecro~ldishfoolishforthisworld~175":"Gloucester — Para lutar do lado de Eduardo pela coroa;\ne, por sua recompensa, pobre senhor, está engaiolado.\nQuisera a Deus que meu coração fosse de pedra, como o de Eduardo;\nou o de Eduardo brando e piedoso, como o meu:\nsou infantil e tolo demais para este mundo.","queenmargarethietheetohellforshameandlea~codemontherethykingdomis~80":"Rainha Margarida — Vai para o inferno, por vergonha, e deixa o mundo,\ntu, cacodemônio! ali está teu reino.","riversmylordofgloucesterinthosebusydaysw~eyouifyoushouldbeourking~137":"Rivers — Meu lorde de Gloucester, naqueles dias agitados\nque aqui apontais para provar que somos inimigos,\nseguíamos então nosso senhor, nosso rei legítimo:\nassim seguiríamos a vós, se fôsseis nosso rei.","gloucesterifishouldbeihadratherbeapedlar~rommyheartthethoughtofit~72":"Gloucester — Se eu fosse! antes eu fosse mascate:\nlonge esteja de meu coração o pensamento disso!","queenelizabethaslittlejoymylordasyousupp~njoybeingthequeenthereof~138":"Rainha Elizabeth — Tão pouca alegria, meu senhor, quanto supondes\nque teríeis, se fôsseis rei deste país,\ntão pouca alegria podeis supor em mim,\nque a tenho, sendo rainha dele.","queenmargaretalittlejoyenjoysthequeenthe~ntlevillaindonotturnaway~315":"Rainha Margarida — Pouca alegria tem a rainha dele;\npois eu sou ela, e inteiramente sem alegria.\nNão posso mais manter a paciência. Avançando.\nOuvi-me, piratas briguentos, que vos desentendeis\nao dividir o que me saqueastes!\nQual de vós não treme ao me olhar?\nSe não porque, sendo eu rainha, vos curvais como súditos,\nao menos porque, por vós deposta, tremeis como rebeldes?\nOh, gentil vilão, não te afastes!","gloucesterfoulwrinkledwitchwhatmakesttho~hwhatmakestthouinmysight~50":"Gloucester — Bruxa imunda e enrugada, que fazes à minha vista?","queenmargaretbutrepetitionofwhatthouhast~illimakebeforeilettheego~74":"Rainha Margarida — Apenas repetir o que arruinaste;\nisso farei antes de te deixar ir.","gloucesterwertthounotbanishedonpainofdea~notbanishedonpainofdeath~42":"Gloucester — Não foste banida sob pena de morte?","queenmargaretiwasbutidofindmorepaininban~pleasuresyouusurparemine~205":"Rainha Margarida — Fui; mas acho mais pena no banimento\ndo que a morte me poderia dar aqui ficando.\nUm marido e um filho me deves;\ne tu, um reino; e todos vós, lealdade:\no pesar que tenho é por direito vosso,\ne todos os prazeres que usurpais são meus.","gloucesterthecursemynoblefatherlaidonthe~hathplaguedthybloodydeed~304":"Gloucester — A maldição que meu nobre pai lançou sobre ti,\nquando coroaste suas guerreiras frontes com papel\ne com teus escárnios lhe tiraste rios dos olhos,\ne depois, para enxugá-los, deste ao duque um pano\nembebido no sangue inocente do belo Rutland—\nsuas maldições, então proferidas por amargura de alma\ncontra ti, caíram todas sobre ti;\ne Deus, não nós, puniu teu ato sangrento.","queenelizabethsojustisgodtorighttheinnoc~tisgodtorighttheinnocent~43":"Rainha Elizabeth — Tão justo é Deus, em desagravar o inocente.","hastingsotwasthefoulestdeedtoslaythatbab~rcilessthateerwasheardof~77":"Hastings — Oh, foi o ato mais imundo matar aquela criança,\ne o mais impiedoso de que jamais se ouviu!","riverstyrantsthemselvesweptwhenitwasrepo~vesweptwhenitwasreported~44":"Rivers — Os próprios tiranos choraram quando se relatou.","dorsetnomanbutprophesiedrevengeforit~utprophesiedrevengeforit~36":"Dorset — Não houve homem que não profetizasse vingança por isso.","buckinghamnorthumberlandthenpresentweptt~ndthenpresentwepttoseeit~46":"Buckingham — Northumberland, então presente, chorou ao ver.","queenmargaretwhatwereyousnarlingallbefor~omeunlookdaccidentcutoff~929":"Rainha Margarida — Quê! estáveis todos rosnando antes que eu chegasse,\nprontos a agarrar-vos pelo pescoço uns aos outros,\ne voltais agora todo o vosso ódio contra mim?\nTanto prevaleceu no céu a terrível maldição de York\nque a morte de Henrique, a morte de meu querido Eduardo,\na perda de seu reino, meu doloroso banimento,\ntudo isso só serviu de resposta por aquele pirralho birrento?\nPodem maldições furar as nuvens e entrar no céu?\nEntão, cedei, nuvens pesadas, às minhas vivas maldições!\nSe não pela guerra, de excesso morra vosso rei,\ncomo o nosso de assassinato, para fazê-lo rei!\nEduardo, teu filho, que agora é Príncipe de Gales,\npor Eduardo, meu filho, que era Príncipe de Gales,\nmorra na juventude por igual violência prematura!\nTu mesma, rainha, por mim que fui rainha,\nsobrevive à tua glória, como eu, miserável!\nVivas longo tempo para chorar a perda dos filhos;\ne vejas outra, como te vejo agora,\nadornada de teus direitos, como estás instalada nos meus!\nLongamente morram teus dias felizes antes de tua morte;\ne, depois de muitas horas alongadas de pesar,\nmorras nem mãe, nem esposa, nem rainha da Inglaterra!\nRivers e Dorset, estáveis presentes,\ne assim estáveis vós, lorde Hastings, quando meu filho\nfoi apunhalado com punhais sangrentos: a Deus peço\nque nenhum de vós viva sua idade natural,\nmas seja ceifado por algum acidente inesperado!","gloucesterhavedonethycharmthouhatefulwit~armthouhatefulwitherdhag~47":"Gloucester — Acaba teu encantamento, odiosa bruxa mirrada!","queenmargaretandleaveouttheestaydogforth~uragofhonourthoudetested~630":"Rainha Margarida — E deixar-te de fora? fica, cão, pois me ouvirás.\nSe o céu tem em reserva alguma praga grave\nque exceda as que posso desejar-te,\noh, guardem-na até que teus pecados amadureçam,\ne então lancem sua indignação\nsobre ti, o perturbador da paz do pobre mundo!\nO verme da consciência roa sempre tua alma!\nSuspeites de traidores teus amigos enquanto viveres,\ne tomes profundos traidores por teus amigos mais caros!\nNenhum sono feche esse teu olho mortífero,\nsalvo enquanto algum sonho atormentador\nte aterre com um inferno de feios demônios!\nTu, marcado por duendes, abortivo, porco fuçador!\nTu que foste selado em teu nascimento\nescravo da natureza e filho do inferno!\nTu, calúnia do ventre pesado de tua mãe!\nTu, odiada prole dos lombos de teu pai!\nTu, trapo de honra! tu, detestado—","gloucestermargaret~gloucestermargaret~18":"Gloucester — Margarida.","queenmargaretrichard~queenmargaretrichard~20":"Rainha Margarida — Ricardo!","gloucesterha~gloucesterha~12":"Gloucester — Ah!","queenmargareticalltheenot~ueenmargareticalltheenot~25":"Rainha Margarida — Não te chamo.","gloucestericrytheemercythenforihadthough~lldmeallthesebitternames~80":"Gloucester — Peço-te perdão então, pois pensei\nque me chamavas todos esses nomes amargos.","queenmargaretwhysoididbutlookdfornoreply~memaketheperiodtomycurse~68":"Rainha Margarida — Ora, assim fiz; mas não esperava resposta.\nOh, deixa-me pôr o ponto final em minha maldição!","gloucestertisdonebymeandendsinmargaret~onebymeandendsinmargaret~38":"Gloucester — Está feito por mim, e termina em “Margarida”.","queenelizabeththushaveyoubreathedyourcur~yourcurseagainstyourself~57":"Rainha Elizabeth — Assim lançastes vossa maldição contra vós mesma.","queenmargaretpoorpaintedqueenvainflouris~tpoisonousbunchbackdtoad~238":"Rainha Margarida — Pobre rainha pintada, vã floreio de minha fortuna!\nPor que espalhas açúcar sobre aquela aranha de garrafa,\ncuja teia mortal te enreda em redor?\nTola, tola! afias uma faca para te matar.\nVirá o tempo em que desejarás que eu esteja\npara te ajudar a amaldiçoar aquele sapo peçonhento de corcunda.","hastingsfalsebodingwomanendthyfranticcur~yharmthoumoveourpatience~74":"Hastings — Mulher de falsos presságios, acaba tua maldição frenética,\nque a teu dano não movas nossa paciência.","queenmargaretfoulshameuponyouyouhaveallm~onyouyouhaveallmovedmine~48":"Rainha Margarida — Vergonha imunda sobre vós! todos moveis a minha.","riverswereyouwellservedyouwouldbetaughty~youwouldbetaughtyourduty~47":"Rivers — Se fôsseis bem servida, seríeis ensinada a vosso dever.","queenmargarettoservemewellyouallshoulddo~dteachyourselvesthatduty~120":"Rainha Margarida — Para me servir bem, todos devíeis prestar-me dever,\nensinar-me a ser vossa rainha, e vós meus súditos:\noh, servi-me bem, e ensinai-vos esse dever!","dorsetdisputenotwithhersheislunatic~tenotwithhersheislunatic~35":"Dorset — Não discuta com ela; é lunática.","queenmargaretpeacemastermarquessyouarema~eydashthemselvestopieces~229":"Rainha Margarida — Paz, senhor marquês, sois atrevido:\nvosso brasão de honra novo em folha mal tem curso.\nOh, se vossa jovem nobreza pudesse julgar\no que seria perdê-la e ser miserável!\nOs que estão no alto têm muitas rajadas que os sacodem;\ne se caem, despedaçam-se.","gloucestergoodcounselmarrylearnitlearnit~rylearnitlearnitmarquess~48":"Gloucester — Bom conselho, em verdade: aprendei-o, aprendei-o, marquês.","dorsetittouchethyoumylordasmuchasme~chethyoumylordasmuchasme~35":"Dorset — Toca-vos, meu senhor, tanto quanto a mim.","gloucesteryeaandmuchmorebutiwasbornsohig~ththewindandscornsthesun~106":"Gloucester — Sim, e muito mais: mas nasci tão alto,\nque nosso ninho se faz no topo do cedro,\nbrinca com o vento e despreza o sol.","queenmargaretandturnsthesuntoshadealasal~aswonwithbloodlostbeitso~230":"Rainha Margarida — E faz do sol sombra; ai! ai!\nTestemunha meu filho, agora na sombra da morte;\ncujos raios brilhantes e resplandecentes tua ira nublada\nenvolveu em escuridão eterna.\nVosso ninho se faz no ninho de nosso ninho.\nÓ Deus, que o vês, não o permitas;\ncomo foi ganho com sangue, assim seja perdido!","buckinghamhavedoneforshameifnotforcharit~eforshameifnotforcharity~41":"Buckingham — Chega! por vergonha, se não por caridade.","queenmargareturgeneithercharitynorshamet~mestilllivemysorrowsrage~174":"Rainha Margarida — Não me invoques caridade nem vergonha:\nsem caridade comigo agistes,\ne vergonhosamente por vós minhas esperanças foram trucidadas.\nMinha caridade é ultraje, a vida minha vergonha;\ne nessa vergonha viva sempre a fúria de meu pesar!","buckinghamhavedonehavedone~ckinghamhavedonehavedone~26":"Buckingham — Chega, chega.","queenmargaretoprincelybuckinghamillkisst~ithinthecompassofmycurse~177":"Rainha Margarida — Oh, principesco Buckingham, beijarei tua mão,\nem sinal de liga e amizade contigo:\nbem te suceda a ti e à tua nobre casa!\nTuas vestes não estão manchadas de nosso sangue,\nnem tu dentro do alcance de minha maldição.","buckinghamnornoonehereforcursesneverpass~ethatbreathethemintheair~77":"Buckingham — Nem ninguém aqui; pois maldições nunca passam\ndos lábios daqueles que as exalam no ar.","queenmargaretillnotbelievebuttheyascendt~heirministersattendonhim~277":"Rainha Margarida — Não creio senão que sobem ao céu,\ne ali despertam a paz suavemente adormecida de Deus.\nOh, Buckingham, guarda-te daquele cão!\nVê, quando afaga, morde; e quando morde,\nseu dente peçonhento supurará até a morte:\nnão tenhas trato com ele, cuida-te dele;\nPecado, Morte e Inferno marcaram-no com seus sinais,\ne todos os seus ministros o servem.","gloucesterwhatdothshesaymylordofbuckingh~shesaymylordofbuckingham~42":"Gloucester — Que diz ela, meu lorde de Buckingham?","buckinghamnothingthatirespectmygraciousl~atirespectmygraciouslord~43":"Buckingham — Nada que eu respeite, meu gracioso senhor.","queenmargaretwhatdostthouscornmeformygen~ursandallofyoutogodsexit~246":"Rainha Margarida — Quê, desprezas-me por meu gentil conselho?\nE acalentas o diabo de quem te aviso?\nOh, mas lembra-te disto outro dia,\nquando ele te partir o próprio coração de pesar,\ne dirás que a pobre Margarida era profetisa!\nVivei cada um súdito do ódio dele,\ne ele do vosso, e todos vós de Deus! Sai.","hastingsmyhairdothstandonendtohearhercur~tandonendtohearhercurses~43":"Hastings — Meus cabelos se arrepiam ao ouvir suas maldições.","riversandsodothmineimusewhyshesatliberty~ineimusewhyshesatliberty~40":"Rivers — E os meus também: admiro que ela esteja em liberdade.","gloucestericannotblameherbygodsholymothe~hereofthatihavedonetoher~104":"Gloucester — Não a posso culpar: pela santa mãe de Deus,\nela sofreu injustiça demais; e arrependo-me\nda parte que tive nisso, do que lhe fiz.","queenelizabethineverdidheranytomyknowled~erdidheranytomyknowledge~42":"Rainha Elizabeth — Eu nunca lhe fiz nenhuma, que eu saiba.","gloucesterbutyouhaveallthevantageofherwr~nthemthatarethecauseofit~195":"Gloucester — Mas tendes toda a vantagem da injustiça a ela.\nFui quente demais em fazer bem a alguém\nque é frio demais ao pensar nisso agora.\nEm verdade, quanto a Clarence, está bem pago;\nestá engaiolado para engordar, por suas penas:\nDeus perdoe os que são causa disso!","riversavirtuousandachristianlikeconclusi~emthathavedonescathetous~77":"Rivers — Uma conclusão virtuosa e cristã,\norar por aqueles que nos fizeram dano.","gloucestersodoieverasidebeingwelladvised~ursednowihadcursedmyself~72":"Gloucester — Assim faço sempre: bem avisado, à parte.\nPois se agora amaldiçoasse, teria amaldiçoado a mim mesmo.","entercatesby~entercatesby~12":"Entra Catesby.","catesbymadamhismajestydothcallforyouandf~rgraceandyoumynoblelords~69":"Catesby — Senhora, Sua Majestade vos chama;\ne a Vossa Graça; e a vós, meus nobres lordes.","queenelizabethcatesbywecomelordswillyoug~comelordswillyougowithus~47":"Rainha Elizabeth — Catesby, vamos. Senhores, ireis conosco?","riversmadamwewillattendyourgraceexeuntal~ceexeuntallbutgloucester~54":"Rivers — Senhora, acompanharemos Vossa Graça. Saem todos, menos Gloucester.","gloucesteridothewrongandfirstbegintobraw~intwhenmostiplaythedevil~496":"Gloucester — Eu faço o mal, e começo primeiro a brigar.\nAs maldades secretas que pus em marcha\nlanço sobre o grave encargo de outros.\nClarence, a quem eu, de fato, lancei nas trevas,\nlamento diante de muitos simples tolos;\nnomeadamente, Hastings, Derby, Buckingham;\ne digo que é a rainha e seus aliados\nque instigam o rei contra o duque meu irmão.\nAgora acreditam; e além disso me aguilhoam\na vingar-me de Rivers, Vaughan, Grey:\nmas então suspiro; e, com um trecho de escritura,\ndigo-lhes que Deus nos manda fazer o bem pelo mal:\ne assim visto minha nua vilania\ncom velhos retalhos roubados da Sagrada Escritura;\ne pareço santo quando mais faço o diabo.","entertwomurderers~entertwomurderers~17":"Entram dois Assassinos.","butsoftherecomemyexecutionershownowmyhar~wgoingtodispatchthisdeed~92":"Mas, calma! aí vêm meus executores.\nOra, meus ousados e firmes camaradas!\nIdes agora despachar este feito?","firstmurdererwearemylordandcometohavethe~wemaybeadmittedwhereheis~75":"Primeiro Assassino — Vamos, meu senhor; e viemos buscar o mandado,\npara sermos admitidos onde ele está.","gloucesterwellthoughtuponihaveithereabou~heartstopityifyoumarkhim~220":"Gloucester — Bem lembrado; tenho-o aqui comigo. Entrega o mandado.\nQuando terminardes, apresentai-vos em Crosby Place.\nMas, senhores, sede rápidos na execução,\ne também duros: não o ouçais suplicar;\npois Clarence fala bem e talvez\nmova vossos corações à piedade, se o escutardes.","firstmurderertushfearnotmylordwewillnots~ourhandsandnotourtongues~116":"Primeiro Assassino — Bah!\nNão temais, meu senhor, não ficaremos a tagarelar;\nfalantes não são bons fazedores: ficai certo\nde que viemos para usar as mãos e não a língua.","gloucesteryoureyesdropmillstoneswhenfool~nessstraightgogodispatch~103":"Gloucester — Vossos olhos soltam mós quando os olhos dos tolos soltam lágrimas:\ngosto de vós, rapazes; ao vosso serviço já;\nide, ide, despachai.","firstmurdererwewillmynoblelordexeunt~rwewillmynoblelordexeunt~36":"Primeiro Assassino — Assim faremos, meu nobre senhor. Saem.","sceneiv~sceneiv~7":"Cena IV","londonthetower~londonthetower~14":"Londres. A Torre.","enterclarenceandbrakenbury~terclarenceandbrakenbury~26":"Entram Clarence e Brakenbury.","brakenburywhylooksyourgracesoheavilytoda~syourgracesoheavilytoday~41":"Brakenbury — Por que parece Vossa Graça tão abatido hoje?","clarenceoihavepassdamiserablenightsofull~ofdismalterrorwasthetime~191":"Clarence — Oh, passei uma noite miserável,\ntão cheia de visões horrendas, de sonhos pavorosos,\nque, como sou cristão fiel,\nnão passaria outra noite assim,\nainda que fosse para comprar um mundo de dias felizes,\ntão cheio de sombrio terror foi o tempo!","brakenburywhatwasyourdreamilongtohearyou~reamilongtohearyoutellit~46":"Brakenbury — Qual foi vosso sonho? Anseio por ouvi-lo contar.","clarencemethoughtsthatihadbrokenfromthet~adbonesthatlayscatterdby~860":"Clarence — Pareceu-me que tinha escapado da Torre\ne embarcado para cruzar a Borgonha;\ne, em minha companhia, meu irmão Gloucester,\nque me tentou a sair da cabine e passear\nno convés: dali olhamos para a Inglaterra\ne recordamos mil tempos de pavor\nque nos haviam sobrevindo durante as guerras de York e Lancaster.\nEnquanto caminhávamos\nsobre o chão vertiginoso do convés,\npareceu-me que Gloucester tropeçou; e, ao cair,\nderrubou-me, a mim que pensei segurá-lo, pela borda,\nnas ondas revoltas do oceano.\nSenhor, Senhor! pensei, que dor era afogar-se!\nQue ruído terrível de águas em meus ouvidos!\nQue visões horrendas de morte diante dos olhos!\nPareceu-me ver mil naufrágios assustadores;\ndez mil homens que os peixes roíam;\ncunhas de ouro, grandes âncoras, montes de pérolas,\npedras inestimáveis, joias sem preço,\ntodas espalhadas no fundo do mar:\nalgumas jaziam em crânios de mortos; e, naqueles buracos\nonde olhos haviam habitado, rastejavam,\ncomo em escárnio dos olhos, gemas refletoras,\nque cortejavam o fundo lodoso do abismo\ne zombavam dos ossos mortos espalhados ao lado.","brakenburyhadyousuchleisureinthetimeofde~euponthesecretsofthedeep~72":"Brakenbury — Tínheis tal vagar no momento da morte\npara contemplar os segredos do abismo?","clarencemethoughtihadandoftendidistrivet~stbursttobelchitinthesea~208":"Clarence — Pareceu-me que sim; e muitas vezes tentei\nentregar o espírito: mas a onda invejosa\nmantinha minha alma dentro e não a deixava sair\npara buscar o ar vazio, vasto e errante;\nmas a sufocava em meu corpo ofegante,\nque quase estourava para a expelir ao mar.","brakenburyawakedyounotwiththissoreagony~dyounotwiththissoreagony~39":"Brakenbury — Não despertastes com esta agonia dolorosa?","clarenceonomydreamwaslengthendafterlifeo~leimpressionmadethedream~734":"Clarence — Oh, não, meu sonho prolongou-se além da vida;\noh, então começou a tempestade para minha alma,\nque passou, pareceu-me, a melancólica corrente,\ncom aquele sinistro barqueiro de que falam os poetas,\npara o reino da noite perpétua.\nO primeiro que ali saudou minha alma estrangeira\nfoi meu grande sogro, o renomado Warwick,\nque gritou alto: “Que flagelo para o perjúrio\npode esta escura monarquia oferecer ao falso Clarence?”\nE assim desapareceu: então veio errando\numa sombra como um anjo, de cabelos brilhantes\nsalpicados de sangue; e guinchou em voz alta:\n“Clarence chegou; falso, inconstante, perjuro Clarence,\nque me apunhalou no campo em Tewkesbury;\nagarrai-o, Fúrias, levai-o aos vossos tormentos!”\nCom isso, pareceu-me, uma legião de demônios imundos\nme cercou e uivou em meus ouvidos\ngritos tão hediondos que, com o mero ruído,\ndespertei trêmulo, e por algum tempo depois\nnão podia crer senão que estava no inferno,\ntão terrível impressão fez o sonho.","brakenburynomarvelmylordthoughitaffright~iamafraidtohearyoutellit~80":"Brakenbury — Não admira, meu senhor, que vos tenha assustado;\nprometo-vos, tenho medo de ouvir-vos contá-lo.","clarenceobrakenburyihavedonethosethingsw~sheavyandifainwouldsleep~300":"Clarence — Oh, Brakenbury, fiz aquelas coisas\nque agora testemunham contra minha alma,\npor amor de Eduardo; e vê como ele me retribui!\nÓ Deus! se minhas profundas preces não te aplacam,\nmas queres ser vingado de minhas más ações,\nexecuta tua ira em mim somente,\noh, poupa minha esposa inocente e meus pobres filhos!\nPeço-te, gentil guarda, fica comigo;\nmeu espírito está pesado, e de bom grado dormiria.","brakenburyiwillmylordgodgiveyourgracegoo~differsbuttheoutwardfame~331":"Brakenbury — Ficarei, meu senhor: Deus dê a Vossa Graça bom repouso! Clarence dorme.\nO pesar quebra as estações e as horas de repouso,\nfaz da noite manhã e do meio-dia noite.\nOs príncipes têm só os títulos por glória,\numa honra externa por um labor interno;\ne, por imaginações que não sentem,\nsentem muitas vezes um mundo de cuidados sem repouso:\nde modo que, entre seus títulos e os nomes humildes,\nnada difere senão a fama exterior.","enterthetwomurderers~enterthetwomurderers~20":"Entram os dois Assassinos.","firstmurdererhowhoshere~firstmurdererhowhoshere~23":"Primeiro Assassino — Ei! quem está aí?","brakenburyingodsnamewhatareyouandhowcame~reyouandhowcameyouhither~49":"Brakenbury — Em nome de Deus, quem sois e como viestes aqui?","firstmurdereriwouldspeakwithclarenceandi~ceandicamehitheronmylegs~58":"Primeiro Assassino — Quero falar com Clarence, e vim aqui com minhas pernas.","brakenburyyeaareyousobrief~akenburyyeaareyousobrief~26":"Brakenbury — Sim, sois assim tão breve?","secondmurdererosiritisbettertobebrieftha~knomorebrakenburyreadsit~95":"Segundo Assassino — Oh, senhor, é melhor ser breve que enfadonho. Mostrai-lhe nossa comissão; não faleis mais. Brakenbury a lê.","brakenburyiaminthiscommandedtodeliverthe~haveresigndmychargetoyou~232":"Brakenbury — Sou, por isto, mandado entregar\no nobre duque de Clarence em vossas mãos:\nnão discutirei o que isto significa,\npois quero ficar inocente do sentido.\nAqui estão as chaves, ali está o duque, adormecido:\nirei ao rei e lhe darei notícia\nde que assim passei meu encargo a vós.","firstmurdererdosoitisapointofwisdomfarey~areyouwellexitbrakenbury~60":"Primeiro Assassino — Fazei-o, é ponto de sabedoria: passai bem. Sai Brakenbury.","secondmurdererwhatshallwestabhimasheslee~shallwestabhimashesleeps~42":"Segundo Assassino — Quê, vamos apunhalá-lo enquanto dorme?","firstmurderernothenhewillsaytwasdonecowa~sdonecowardlywhenhewakes~55":"Primeiro Assassino — Não; então dirá, quando acordar, que foi feito covardemente.","secondmurdererwhenhewakeswhyfoolheshalln~erwaketillthejudgmentday~66":"Segundo Assassino — Quando acordar! ora, tolo, ele não acordará até o dia do juízo.","firstmurdererwhythenhewillsaywestabbedhi~lsaywestabbedhimsleeping~49":"Primeiro Assassino — Ora, então dirá que o apunhalamos dormindo.","secondmurderertheurgingofthatwordjudgmen~thbredakindofremorseinme~67":"Segundo Assassino — A menção dessa palavra “juízo” gerou em mim uma espécie de remorso.","firstmurdererwhatartthouafraid~urdererwhatartthouafraid~30":"Primeiro Assassino — Quê, tens medo?","secondmurderernottokillhimhavingawarrant~hichnowarrantcandefendus~100":"Segundo Assassino — Não de matá-lo, tendo mandado para isso; mas de ser danado por matá-lo, contra o que nenhum mandado nos pode defender.","firstmurdererithoughtthouhadstbeenresolu~ghtthouhadstbeenresolute~42":"Primeiro Assassino — Pensei que fosses resoluto.","secondmurderersoiamtolethimlive~urderersoiamtolethimlive~31":"Segundo Assassino — E sou, em deixá-lo viver.","firstmurdererbacktothedukeofgloucesterte~ukeofgloucestertellhimso~47":"Primeiro Assassino — Volta ao duque de Gloucester, dize-lhe isso.","secondmurdereripraytheestayawhileihopemy~twhileonewouldtelltwenty~102":"Segundo Assassino — Peço-te, espera um pouco: espero que meu humor santo mude; costumava durar só o tempo de contar vinte.","firstmurdererhowdostthoufeelthyselfnow~owdostthoufeelthyselfnow~38":"Primeiro Assassino — Como te sentes agora?","secondmurdererfaithsomecertaindregsofcon~conscienceareyetwithinme~61":"Segundo Assassino — Por minha fé, algumas certas borras de consciência ainda estão em mim.","firstmurdererrememberourrewardwhenthedee~rrewardwhenthedeedisdone~47":"Primeiro Assassino — Lembra-te da nossa recompensa, quando o feito estiver cumprido.","secondmurdererzoundshediesihadforgotther~ediesihadforgotthereward~45":"Segundo Assassino — Raios, ele morre: tinha esquecido a recompensa.","firstmurdererwhereisthyconsciencenow~rwhereisthyconsciencenow~36":"Primeiro Assassino — Onde está tua consciência agora?","secondmurdererinthedukeofgloucesterspurs~hedukeofgloucesterspurse~41":"Segundo Assassino — Na bolsa do duque de Gloucester.","firstmurderersowhenheopenshispursetogive~ardthyconsciencefliesout~72":"Primeiro Assassino — Assim, quando ele abrir a bolsa para nos dar a recompensa, tua consciência voa para fora.","secondmurdererletitgotheresfewornonewill~fewornonewillentertainit~51":"Segundo Assassino — Que vá; poucos ou nenhum a acolherão.","firstmurdererhowifitcometotheeagain~erhowifitcometotheeagain~35":"Primeiro Assassino — E se ela voltar a ti?","secondmurdererillnotmeddlewithititisadan~imselfandtolivewithoutit~441":"Segundo Assassino — Não me meterei com ela: é coisa perigosa: faz de um homem um covarde: um homem não pode roubar sem que ela o acuse; não pode jurar sem que ela o repreenda; não pode deitar com a mulher do vizinho sem que ela o denuncie: é um espírito ruborizado e pudico que se amotina no peito de um homem; enche-o de obstáculos: fez-me uma vez devolver uma bolsa de ouro que achei; empobrece qualquer homem que a guarda: é expulsa de todas as vilas e cidades como coisa perigosa; e todo homem que pretende viver bem procura confiar em si mesmo e viver sem ela.","firstmurdererzoundsitisevennowatmyelbowp~uadingmenottokilltheduke~67":"Primeiro Assassino — Raios, está agora mesmo ao meu cotovelo, persuadindo-me a não matar o duque.","secondmurderertakethedevilinthymindandbe~iththeebuttomaketheesigh~92":"Segundo Assassino — Mete o diabo na cabeça e não acredites nele: ele só se insinuaria contigo para te fazer suspirar.","firstmurderertutiamstrongframedhecannotp~revailwithmeiwarrantthee~64":"Primeiro Assassino — Bah, sou de constituição forte, ele não pode prevalecer comigo, garanto-te.","secondmurdererspokelikeatallfellowthatre~ioncomeshallwetothisgear~80":"Segundo Assassino — Falaste como um sujeito valente que respeita a reputação. Vamos, ao trabalho?","firstmurderertakehimoverthecostardwithth~malmseybuttinthenextroom~105":"Primeiro Assassino — Acerta-lhe a moleira com o punho da espada, e depois o jogaremos no tonel de malvasia na sala ao lado.","secondmurdereroexcellentdevicemakeasopof~llentdevicemakeasopofhim~43":"Segundo Assassino — Oh, excelente ideia! fazer dele um pão molhado.","firstmurdererharkhestirsshallistrike~rharkhestirsshallistrike~36":"Primeiro Assassino — Escuta! ele se mexe: golpeio?","secondmurderernofirstletsreasonwithhim~nofirstletsreasonwithhim~38":"Segundo Assassino — Não, primeiro raciocinemos com ele.","clarencewhereartthoukeepergivemeacupofwi~oukeepergivemeacupofwine~42":"Clarence — Onde estás, guarda? dá-me um copo de vinho.","secondmurdereryoushallhavewineenoughmylo~havewineenoughmylordanon~46":"Segundo Assassino — Tereis vinho bastante, meu senhor, logo.","clarenceingodsnamewhatartthou~nceingodsnamewhatartthou~29":"Clarence — Em nome de Deus, quem és tu?","secondmurdereramanasyouare~condmurdereramanasyouare~26":"Segundo Assassino — Um homem, como vós.","clarencebutnotasiamroyal~clarencebutnotasiamroyal~24":"Clarence — Mas não, como eu, real.","secondmurderernoryouasweareloyal~rderernoryouasweareloyal~32":"Segundo Assassino — Nem vós, como nós, leal.","clarencethyvoiceisthunderbutthylooksareh~nderbutthylooksarehumble~45":"Clarence — Tua voz é trovão, mas teus olhares são humildes.","secondmurderermyvoiceisnowthekingsmylook~owthekingsmylooksmineown~48":"Segundo Assassino — Minha voz agora é a do rei, meus olhares são meus.","clarencehowdarklyandhowdeadlydostthouspe~hitherwhereforedoyoucome~108":"Clarence — Quão obscuramente e quão mortalmente falas!\nVossos olhos me ameaçam: por que estais pálidos?\nQuem vos enviou aqui? Por que viestes?","bothtototo~bothtototo~10":"Ambos — Para, para, para—","clarencetomurderme~clarencetomurderme~18":"Clarence — Para me assassinar?","bothayay~bothayay~8":"Ambos — Sim, sim.","clarenceyouscarcelyhavetheheartstotellme~yfriendshaveioffendedyou~111":"Clarence — Mal tendes coração para me dizer isso,\ne portanto não podeis ter coração para fazê-lo.\nEm que, meus amigos, vos ofendi?","firstmurdereroffendedusyouhavenotbutthek~edusyouhavenotbuttheking~43":"Primeiro Assassino — A nós não ofendestes, mas ao rei.","clarenceishallbereconciledtohimagain~llbereconciledtohimagain~36":"Clarence — Serei reconciliado com ele de novo.","secondmurderernevermylordthereforeprepar~ordthereforepreparetodie~46":"Segundo Assassino — Nunca, meu senhor; portanto preparai-vos para morrer.","clarenceareyoucalldforthfromoutaworldofm~edyouundertakeisdamnable~414":"Clarence — Fostes chamados do meio de um mundo de homens\npara matar o inocente? Qual é minha ofensa?\nOnde estão as provas que me acusam?\nQue júri legítimo entregou seu veredicto\nao juiz carrancudo? ou quem pronunciou\na amarga sentença da morte do pobre Clarence?\nAntes que eu seja condenado por curso de lei,\nameaçar-me com a morte é ilegalíssimo.\nIntimo-vos, como esperais ter redenção\npelo precioso sangue de Cristo derramado por nossos graves pecados,\nque vos retireis e não ponhais as mãos em mim:\no ato que empreendeis é condenável.","firstmurdererwhatwewilldowedouponcommand~twewilldowedouponcommand~40":"Primeiro Assassino — O que faremos, fazemos por ordem.","secondmurdererandhethathathcommandedisth~athathcommandedistheking~45":"Segundo Assassino — E quem ordenou é o rei.","clarenceerroneousvassalthegreatkingofkin~heirheadsthatbreakhislaw~213":"Clarence — Vassalo errado! o grande Rei dos reis\nnas tábuas de sua lei mandou\nque não matarás: e queres, então,\ndesprezar o edito dele e cumprir o de um homem?\nCuida; pois ele tem a vingança em suas mãos,\npara lançar sobre as cabeças dos que quebram sua lei.","secondmurdererandthatsamevengeancedothhe~relofthehouseoflancaster~153":"Segundo Assassino — E essa mesma vingança ele lança sobre ti,\npor falso perjúrio e por assassinato também:\nrecebeste o santo sacramento\npara lutar na causa da casa de Lancaster.","firstmurdererandlikeatraitortothenameofg~bowelsofthysovereignsson~120":"Primeiro Assassino — E, como traidor ao nome de Deus,\nquebraste aquele voto; e com tua lâmina traiçoeira\nrasgaste as entranhas do filho de teu soberano.","secondmurdererwhomthouwertsworntocherish~tsworntocherishanddefend~49":"Segundo Assassino — A quem juraste estimar e defender.","firstmurdererhowcanstthouurgegodsdreadfu~astbrokeitinsodeardegree~81":"Primeiro Assassino — Como podes invocar a terrível lei de Deus contra nós,\nquando a quebraste em tão alto grau?","clarencealasforwhosesakedidithatilldeedf~thosethathaveoffendedhim~288":"Clarence — Ai! por amor de quem fiz esse mau ato?\nPor Eduardo, por meu irmão, por amor dele:\nOra, senhores,\nele não vos envia para me assassinar por isso;\npois neste pecado ele está tão fundo quanto eu.\nSe Deus quiser ser vingado deste ato,\noh, sabei ainda que o faz publicamente:\nnão tireis a querela de seu braço poderoso;\nele não precisa de curso indireto nem sem lei\npara cortar os que o ofenderam.","firstmurdererwhomadetheethenabloodyminis~ovicewasstruckdeadbythee~116":"Primeiro Assassino — Quem te fez, então, ministro sanguinário,\nquando o galhardo e valente Plantageneta,\naquele príncipe noviço, foi morto por ti?","clarencemybrotherslovethedevilandmyrage~erslovethedevilandmyrage~39":"Clarence — O amor de meu irmão, o diabo e minha fúria.","firstmurdererthybrothersloveourdutyandth~hithernowtoslaughterthee~79":"Primeiro Assassino — O amor de teu irmão, nosso dever e tua culpa\nnos provocam aqui agora a te matar.","clarenceohifyoulovemybrotherhatenotmeiam~dwillfortidingsofmydeath~196":"Clarence — Oh, se amais meu irmão, não me odieis;\nsou seu irmão, e o amo bem.\nSe fostes contratados por recompensa, voltai,\ne enviar-vos-ei a meu irmão Gloucester,\nque vos recompensará melhor por minha vida\ndo que Eduardo por notícias de minha morte.","secondmurdereryouaredeceivedyourbrotherg~rothergloucesterhatesyou~57":"Segundo Assassino — Estais enganado, vosso irmão Gloucester vos odeia.","clarenceonohelovesmeandheholdsmedeargoyo~dsmedeargoyoutohimfromme~52":"Clarence — Oh, não, ele me ama e me tem em estima:\nide a ele da minha parte.","bothaysowewill~bothaysowewill~14":"Ambos — Sim, assim faremos.","clarencetellhimwhenthatourprincelyfather~thinkofthisandhewillweep~195":"Clarence — Dizei-lhe que, quando nosso pai principesco York\nabençoou seus três filhos com seu braço vitorioso\ne nos mandou de toda a alma amar-nos uns aos outros,\npouco pensava nesta amizade dividida:\nmandai Gloucester pensar nisto, e ele chorará.","firstmurdereraymillstonesashelessondusto~tonesashelessondustoweep~44":"Primeiro Assassino — Sim, mós; como nos ensinou a chorar.","clarenceodonotslanderhimforheiskind~notslanderhimforheiskind~35":"Clarence — Oh, não o calunieis, pois ele é bondoso.","firstmurdererrightassnowinharvestthoudec~hithernowtoslaughterthee~92":"Primeiro Assassino — Certo,\ncomo neve na colheita. Enganais-vos:\né ele que nos enviou aqui agora para vos matar.","clarenceitcannotbeforwhenipartedwithhimh~thewouldlabourmydelivery~100":"Clarence — Não pode ser; pois quando me despedi dele,\nabraçou-me nos braços e jurou, com soluços,\nque trabalharia por minha libertação.","secondmurdererwhysohedothnowhedeliversth~hraldomtothejoysofheaven~81":"Segundo Assassino — Ora, assim faz, agora que vos liberta\ndo cativeiro deste mundo para as alegrias do céu.","firstmurderermakepeacewithgodforyoumustd~thgodforyoumustdiemylord~48":"Primeiro Assassino — Fazei as pazes com Deus, pois deveis morrer, meu senhor.","clarencehastthouthatholyfeelinginthysoul~eedwillhateyouforthedeed~199":"Clarence — Tens aquele santo sentimento na alma,\npara me aconselhar a fazer as pazes com Deus,\ne és ainda tão cego para tua própria alma\nque queres guerrear com Deus assassinando-me?\nAh, senhores, considerai, aquele que vos instigou\na fazer este ato vos odiará pelo ato.","secondmurdererwhatshallwedo~ondmurdererwhatshallwedo~27":"Segundo Assassino — Que faremos?","clarencerelentandsaveyoursouls~cerelentandsaveyoursouls~30":"Clarence — Cedei, e salvai vossas almas.","firstmurdererrelenttiscowardlyandwomanis~nttiscowardlyandwomanish~41":"Primeiro Assassino — Ceder! é covarde e mulheril.","clarencenottorelentisbeastlysavagedevili~rincewhatbeggarpitiesnot~313":"Clarence — Não ceder é bestial, selvagem, diabólico.\nQual de vós, se fôsseis filho de um príncipe,\nencerrado longe da liberdade, como estou agora,\nse dois tais assassinos como vós viessem a vós,\nnão imploraria pela vida?\nMeu amigo, vejo alguma piedade em teus olhares;\noh, se teu olho não é adulador,\nvem para o meu lado e intercede por mim,\ncomo mendigarias se estivesses em minha aflição:\num príncipe que mendiga, que mendigo não compadece?","secondmurdererlookbehindyoumylord~dererlookbehindyoumylord~33":"Segundo Assassino — Olhai atrás de vós, meu senhor.","firstmurderertakethatandthatifallthiswil~uttwithinexitwiththebody~102":"Primeiro Assassino — Toma isto, e isto: se tudo isto não bastar, apunhala-o\nafogar-te-ei no tonel de malvasia lá dentro. Sai, com o corpo.","secondmurdererabloodydeedanddesperatelyd~grievousguiltymurderdone~116":"Segundo Assassino — Ato sangrento, e desesperadamente despachado!\nComo de bom grado, como Pilatos, lavaria as mãos\ndeste gravíssimo e culpado assassinato cometido!","reenterfirstmurderer~reenterfirstmurderer~20":"Entra de novo o Primeiro Assassino.","firstmurdererhownowwhatmeanstthouthattho~shallknowhowslackthouart~92":"Primeiro Assassino — Ora! que queres dizer, que não me ajudas?\nPelos céus, o duque saberá quão frouxo és!","secondmurdereriwouldheknewthatihadsavedh~methatthedukeisslainexit~115":"Segundo Assassino — Quisera que ele soubesse que salvei seu irmão!\nToma tu a paga e dize-lhe o que digo;\npois arrependo-me de que o duque esteja morto. Sai.","firstmurderersodonotigocowardasthouartno~lloutandhereimustnotstay~160":"Primeiro Assassino — Eu não: vai, covarde como és.\nAgora devo esconder o corpo em algum buraco,\naté que o duque tome ordem para seu enterro:\ne quando tiver minha paga, devo partir;\npois isto virá à tona, e aqui não devo ficar.","londonthepalace~londonthepalace~15":"Londres. O palácio.","flourishenterkingedwardsickqueenelizabet~sbuckinghamgreyandothers~84":"Fanfarra. Entram o Rei Eduardo, doente, a Rainha Elizabeth, Dorset, Rivers, Hastings, Buckingham, Grey e outros.","kingedwardwhysonowhaveidoneagooddayswork~tyourhatredswearyourlove~269":"Rei Eduardo — Ora, assim: agora fiz um bom dia de trabalho:\nvós, pares, continuai esta liga unida:\ncada dia espero uma embaixada\nde meu Redentor para me redimir daqui;\ne agora em paz minha alma partirá para o céu,\nvisto que pus meus amigos em paz na terra.\nRivers e Hastings, dai-vos as mãos;\nnão disfarceis o ódio, jurai amor.","riversbyheavenmyheartispurgedfromgrudgin~andisealmytrueheartslove~79":"Rivers — Pelo céu, meu coração está purgado do ódio rancoroso;\ne com minha mão selo o amor de meu verdadeiro coração.","hastingssothriveiasitrulyswearthelike~iveiasitrulyswearthelike~37":"Hastings — Assim prospere eu, como juro verdadeiramente o mesmo!","kingedwardtakeheedyoudallynotbeforeyourk~herofyoutobetheothersend~138":"Rei Eduardo — Cuidado para não brincardes diante de vosso rei;\nque Aquele que é o supremo Rei dos reis\nnão confunda vossa falsidade oculta e determine\nque um seja o fim do outro.","hastingssoprosperiasiswearperfectlove~speriasiswearperfectlove~37":"Hastings — Assim prospere eu, como juro perfeito amor!","riversandiasilovehastingswithmyheart~ilovehastingswithmyheart~36":"Rivers — E eu, como amo Hastings de coração!","kingedwardmadamyourselfarenotexemptinthi~whatyoudodoitunfeignedly~175":"Rei Eduardo — Senhora, vós mesma não estais isenta disto,\nnem vosso filho Dorset, Buckingham, nem vós;\nfostes facciosos uns contra os outros.\nEsposa, amai lorde Hastings, deixai que beije vossa mão;\ne o que fizerdes, fazei-o sem fingimento.","queenelizabethherehastingsiwillnevermore~erhatredsothriveiandmine~79":"Rainha Elizabeth — Aqui, Hastings; nunca mais me lembrarei\nde nosso ódio passado, assim prospere eu e os meus!","kingedwarddorsetembracehimhastingslovelo~hastingslovelordmarquess~50":"Rei Eduardo — Dorset, abraça-o; Hastings, ama o lorde marquês.","dorsetthisinterchangeofloveihereprotestu~nmypartshallbeunviolable~66":"Dorset — Esta troca de amor, aqui protesto,\nde minha parte será inviolável.","hastingsandsoswearimylordtheyembrace~oswearimylordtheyembrace~36":"Hastings — E assim juro eu, meu senhor. Abraçam-se.","kingedwardnowprincelybuckinghamsealthout~ndmakemehappyinyourunity~108":"Rei Eduardo — Agora, principesco Buckingham, sela esta liga\ncom teus abraços aos aliados de minha esposa,\ne faze-me feliz em vossa união.","buckinghamwheneverbuckinghamdothturnhish~inzealtoyourstheyembrace~310":"Buckingham — Sempre que Buckingham voltar seu ódio\ncontra Vossa Majestade ou os vossos, ou aos vossos, e não vos estime, a vós e aos vossos, com todo o devotado amor, Deus me castigue\ncom ódio naqueles de quem espero mais amor!\nQuando eu mais precisar de empregar um amigo,\ne mais certo estiver de que é um amigo,\nprofundo, oco, traiçoeiro e cheio de ardil\nseja ele para comigo! isto peço a Deus,\nquando eu for frio em zelo pelos vossos. Abraçam-se.","kingedwardapleasingcordialprincelybuckin~perfectperiodofthispeace~145":"Rei Eduardo — Um cordial agradável, principesco Buckingham,\né este teu voto ao meu coração enfermo.\nFalta agora aqui nosso irmão Gloucester,\npara pôr o ponto final perfeito nesta paz.","buckinghamandingoodtimeherecomesthenoble~imeherecomesthenobleduke~44":"Buckingham — E, em boa hora, aqui vem o nobre duque.","gloucestergoodmorrowtomysovereignkingand~celypeersahappytimeofday~76":"Gloucester — Bom dia a meu soberano rei e rainha;\ne, principescos pares, feliz hora do dia!","kingedwardhappyindeedaswehavespenttheday~ellingwrongincensedpeers~140":"Rei Eduardo — Feliz, de fato, como passamos o dia.\nIrmão, fizemos obras de caridade;\nfizemos paz da inimizade, belo amor do ódio,\nentre estes pares inchados e incendiados de agravos.","gloucesterablessedlabourmymostsovereignl~ithankmygodformyhumility~637":"Gloucester — Bendito labor, meu soberano senhor:\nentre este principesco grupo, se alguém aqui,\npor falsa informação ou suposição errada,\ntem-me por inimigo;\nse eu, sem saber, ou em minha ira,\ncometi algo que seja mal suportado\npor alguém nesta presença, desejo\nreconciliar-me com sua amistosa paz:\né morte para mim estar em inimizade;\nodeio-a e desejo o amor de todos os bons homens.\nPrimeiro, senhora, peço-vos paz verdadeira,\nque comprarei com meu devotado serviço;\nde vós, meu nobre primo Buckingham,\nse alguma vez houve rancor entre nós;\nde vós, lorde Rivers, e, lorde Grey, de vós,\nque sem mérito me olhastes com cenho;\nduques, condes, lordes, cavalheiros; de fato, de todos.\nNão sei de inglês vivo\ncom quem minha alma esteja um tantinho em desavença\nmais do que a criança que nasce esta noite:\nagradeço a meu Deus minha humildade.","queenelizabethaholydayshallthisbekepther~otherclarencetoyourgrace~157":"Rainha Elizabeth — Um dia santo será este guardado de agora em diante:\nquisera a Deus que todas as contendas fossem bem compostas.\nMeu soberano senhor, suplico a Vossa Majestade\nque acolhais nosso irmão Clarence à vossa graça.","gloucesterwhymadamhaveiofferdloveforthis~himinjurytoscornhiscorse~146":"Gloucester — Ora, senhora, ofereci amor por isto,\npara ser assim escarnecido nesta real presença?\nQuem não sabe que o nobre duque está morto? Todos estremecem.\nFazeis-lhe injúria em desprezar seu cadáver.","riverswhoknowsnotheisdeadwhoknowsheis~snotheisdeadwhoknowsheis~37":"Rivers — Quem não sabe que está morto! quem sabe que está?","queenelizabethallseeingheavenwhataworldi~ngheavenwhataworldisthis~45":"Rainha Elizabeth — Céu que tudo vê, que mundo é este!","buckinghamlookisopalelorddorsetastherest~opalelorddorsetastherest~40":"Buckingham — Pareço tão pálido, lorde Dorset, como os demais?","dorsetaymygoodlordandnooneinthispresence~lourhathforsookhischeeks~75":"Dorset — Sim, meu bom senhor; e ninguém nesta presença\nque não tenha perdido a cor rubra das faces.","kingedwardisclarencedeadtheorderwasrever~edeadtheorderwasreversed~43":"Rei Eduardo — Clarence está morto? a ordem foi revogada.","gloucesterbuthepoorsoulbyyourfirstorderd~etgocurrentfromsuspicion~271":"Gloucester — Mas ele, pobre alma, morreu por vossa primeira ordem,\ne essa levou-a um Mercúrio alado;\nalgum aleijado tardio levou a contraordem,\nque chegou tarde demais para vê-lo enterrado.\nDeus conceda que alguns, menos nobres e menos leais,\nmais próximos em pensamentos sanguinários, mas não em sangue,\nnão mereçam pior que o miserável Clarence,\ne contudo passem livres de suspeita!","enterderby~enterderby~10":"Entra Derby.","derbyaboonmysovereignformyservicedone~overeignformyservicedone~37":"Derby — Uma graça, meu soberano, pelo serviço que prestei!","kingedwardipraytheepeacemysoulisfullofso~eacemysoulisfullofsorrow~44":"Rei Eduardo — Peço-te, paz: minha alma está cheia de dor.","derbyiwillnotriseunlessyourhighnessgrant~eunlessyourhighnessgrant~40":"Derby — Não me levantarei, a menos que Vossa Alteza conceda.","kingedwardthenspeakatoncewhatisitthoudem~oncewhatisitthoudemandst~45":"Rei Eduardo — Então fala logo o que pedes.","derbytheforfeitsovereignofmyservantslife~endantonthedukeofnorfolk~104":"Derby — O perdão, soberano, da vida de meu criado,\nque matou hoje um cavalheiro honrado\nrecentemente ao serviço do duque de Norfolk.","kingedwardhaveiatonguetodoommybrothersde~euntsomewithkingandqueen~1088":"Rei Eduardo — Tive eu língua para decretar a morte de meu irmão,\ne a mesma dará perdão a um escravo?\nMeu irmão não matou homem algum; sua falta foi pensamento,\ne contudo seu castigo foi cruel morte.\nQuem me suplicou por ele? quem, em minha ira,\najoelhou-se a meus pés e me mandou ponderar?\nQuem falou de fraternidade? quem falou de amor?\nQuem me contou como a pobre alma abandonou\no poderoso Warwick e lutou por mim?\nQuem me contou que, no campo de Tewkesbury,\nquando Oxford me derrubou, ele me salvou,\ne disse: “Caro irmão, vive, e sê rei”?\nQuem me contou que, quando jazíamos ambos no campo,\nquase gelados até a morte, como me envolveu\nnas suas próprias vestes e se entregou,\ntodo magro e nu, à noite de frio entorpecente?\nTudo isso de minha lembrança a ira brutal\narrancou pecaminosamente, e nenhum de vós\nteve a graça de me recordar.\nMas quando vossos carroceiros ou vassalos de serviço\ncometeram uma matança bêbada e desfiguraram\na preciosa imagem de nosso caro Redentor,\nlogo estais de joelhos por perdão, perdão;\ne eu, injustamente também, devo concedê-lo:\nmas por meu irmão ninguém quis falar,\nnem eu, sem graça, falei a mim mesmo\npor ele, pobre alma. O mais orgulhoso de vós todos\nlhe ficou em dívida em sua vida;\ncontudo nenhum de vós quis uma vez pleitear por sua vida.\nÓ Deus, temo que tua justiça caia\nsobre mim, e vós, e os meus, e os vossos por isto!\nVem, Hastings, ajuda-me ao meu gabinete. Oh, pobre Clarence! Saem alguns com o Rei e a Rainha.","gloucesterthisisthefruitofrashnessmarkdy~fortedwardwithourcompany~206":"Gloucester — Este é o fruto da precipitação! Não notastes\ncomo os parentes culpados da rainha\nficaram pálidos ao ouvir da morte de Clarence?\nOh, eles sempre o instigaram ao rei!\nDeus vingará. Mas vinde, entremos,\npara confortar Eduardo com nossa companhia.","buckinghamwewaituponyourgraceexeunt~ewaituponyourgraceexeunt~35":"Buckingham — Acompanhamos Vossa Graça. Saem.","entertheduchessofyorkwiththetwochildreno~thetwochildrenofclarence~49":"Entra a Duquesa de York, com os dois filhos de Clarence.","boytellmegoodgrandamisourfatherdead~odgrandamisourfatherdead~35":"Menino — Diz-me, boa avó, nosso pai está morto?","duchessnoboy~duchessnoboy~12":"Duquesa — Não, menino.","boywhydoyouwringyourhandsandbeatyourbrea~cryoclarencemyunhappyson~69":"Menino — Por que torceis as mãos e batéis no peito\ne gritais: “Oh, Clarence, meu filho infeliz!”","girlwhydoyoulookonusandshakeyourheadandc~hatournoblefatherbealive~96":"Menina — Por que nos olhais e abanais a cabeça\ne nos chamais de coitados, órfãos, náufragos,\nse nosso nobre pai está vivo?","duchessmyprettycousinsyoumistakememuchid~sorrowtowailonethatslost~136":"Duquesa — Meus queridos netinhos, enganais-vos muito;\nlamento a doença do rei,\nrelutante em perdê-lo, não a morte de vosso pai;\nseria pesar perdido chorar por quem está perdido.","boythengrandamyouconcludethatheisdeadthe~lyprayersalltothateffect~132":"Menino — Então, avó, concluís que ele está morto.\nO rei meu tio é culpado disto:\nDeus vingará; a quem importunarei\ncom preces diárias todas para esse fim.","girlandsowilli~girlandsowilli~14":"Menina — E assim farei eu.","duchesspeacechildrenpeacethekingdothlove~hocausedyourfathersdeath~114":"Duquesa — Paz, crianças, paz! o rei vos ama bem:\ninocentes incapazes e rasos,\nnão podeis adivinhar quem causou a morte de vosso pai.","boygrandamwecanformygoodunclegloucestert~ldlovemedearlyashischild~228":"Menino — Avó, podemos; pois meu bom tio Gloucester\ndisse-me que o rei, provocado pela rainha,\ndeu invenção a acusações para prendê-lo:\ne quando meu tio me disse isso, chorou,\ne abraçou-me nos braços, e beijou-me bondosamente a face;\nmandou-me confiar nele como em meu pai,\ne que me amaria muito como a seu filho.","duchessohthatdeceitshouldstealsuchgentle~ydugshedrewnotthisdeceit~142":"Duquesa — Oh, que o engano furte formas tão gentis\ne com máscara virtuosa esconda o ardil imundo!\nEle é meu filho; sim, e nisso minha vergonha;\ncontudo de meus peitos não sugou este engano.","boythinkyoumyunclediddissemblegrandam~unclediddissemblegrandam~37":"Menino — Pensais que meu tio dissimulou, avó?","duchessayboy~duchessayboy~12":"Duquesa — Sim, menino.","boyicannotthinkitharkwhatnoiseisthis~inkitharkwhatnoiseisthis~36":"Menino — Não posso crer. Escutai! que ruído é este?","enterqueenelizabethwithherhairaboutherea~sriversanddorsetafterher~65":"Entram a Rainha Elizabeth, com os cabelos soltos sobre as orelhas; Rivers e Dorset atrás dela.","queenelizabethohwhoshallhindermetowailan~andtomyselfbecomeanenemy~137":"Rainha Elizabeth — Oh, quem me impedirá de gemer e chorar,\nde repreender minha sorte e atormentar-me?\nUnir-me-ei ao negro desespero contra minha alma,\ne tornar-me-ei inimiga de mim mesma.","duchesswhatmeansthissceneofrudeimpatienc~hissceneofrudeimpatience~41":"Duquesa — Que significa esta cena de rude impaciência?","queenelizabethtomakeanactoftragicviolenc~ewkingdomofperpetualrest~277":"Rainha Elizabeth — Fazer um ato de violência trágica:\nEduardo, meu senhor, vosso filho, nosso rei, está morto.\nPor que crescem os ramos agora que a raiz secou?\nPor que não murcham as folhas, ida a seiva?\nSe quereis viver, lamentai; se morrer, sede breve,\npara que nossas almas de asas velozes alcancem a do rei;\nou, como súditos obedientes, sigam-no\nao seu novo reino de repouso perpétuo.","duchessahsomuchinteresthaveiinthysorrowa~yplaintsanddrownthycries~505":"Duquesa — Ah, tanto interesse tenho em tua dor\nquanto tive título em teu nobre marido!\nChorei a morte de um digno esposo\ne vivi olhando suas imagens:\nmas agora dois espelhos de seu semblante principesco\nforam rachados em pedaços pela morte maligna,\ne eu, por consolo, tenho só um espelho falso,\nque me aflige quando vejo minha vergonha nele.\nTu és viúva; contudo és mãe,\ne tens o consolo de teus filhos que te restam:\nmas a morte arrebatou meu marido de meus braços\ne arrancou duas muletas de meus membros débeis,\nEduardo e Clarence. Oh, que motivo tenho,\nsendo o teu apenas metade de minha dor,\npara superar teus queixumes e afogar teus gritos!","boygoodauntyouweptnotforourfathersdeathh~idyouwithourkindredtears~72":"Menino — Boa tia, não chorastes pela morte de nosso pai;\ncomo podemos ajudar-vos com nossas lágrimas de parentesco?","girlourfatherlessdistresswasleftunmoandy~owdolourlikewisebeunwept~70":"Menina — Nossa aflição de órfãos ficou sem lamento;\nque vossa dor de viúva também fique sem pranto!","queenelizabethgivemenohelpinlamentationi~sbandformydearlordedward~218":"Rainha Elizabeth — Não me deis ajuda no lamento;\nnão sou estéril para produzir queixumes:\ntodas as fontes reduzam suas correntes a meus olhos,\npara que eu, governada pela lua aquosa,\npossa mandar copiosas lágrimas para afogar o mundo!\nOh, por meu marido, por meu caro senhor Eduardo!","childrenohforourfatherforourdearlordclar~erforourdearlordclarence~44":"Crianças — Oh, por nosso pai, por nosso caro senhor Clarence!","duchessalasforbothbothmineedwardandclare~othmineedwardandclarence~43":"Duquesa — Ai de ambos, ambos meus, Eduardo e Clarence!","queenelizabethwhatstayhadibutedwardandhe~yhadibutedwardandhesgone~45":"Rainha Elizabeth — Que arrimo tive eu senão Eduardo? e ele se foi.","childrenwhatstayhadwebutclarenceandhesgo~dwebutclarenceandhesgone~42":"Crianças — Que arrimo tivemos nós senão Clarence? e ele se foi.","duchesswhatstayshadibuttheyandtheyaregon~adibuttheyandtheyaregone~41":"Duquesa — Que arrimos tive eu senão eles? e eles se foram.","queenelizabethwasneverwidowhadsodearalos~neverwidowhadsodearaloss~41":"Rainha Elizabeth — Nunca viúva teve perda tão cara!","childrenwereneverorphanshadsodearaloss~verorphanshadsodearaloss~38":"Crianças — Nunca órfãos tiveram perda tão cara!","duchesswasnevermotherhadsodearalossalasi~pamperitwithlamentations~314":"Duquesa — Nunca mãe teve perda tão cara!\nAi, sou a mãe destes lamentos!\nOs males deles são parciais, os meus são gerais.\nEla chora por um Eduardo, e eu também;\neu choro por um Clarence, ela não;\nestas crianças choram por Clarence, e eu também;\neu choro por um Eduardo, elas não:\nAi, vós três, sobre mim, três vezes aflita,\nderramai todas as vossas lágrimas! Sou a ama de vosso pesar,\ne o mimarei com lamentações.","dorsetcomfortdearmothergodismuchdispleas~restheroyaldebtitlentyou~254":"Dorset — Consolo, cara mãe: Deus está muito desagradado\nde que recebais sua obra com ingratidão:\nem coisas comuns do mundo, chama-se ingrato\nquem, com tola má vontade, paga uma dívida\nque foi bondosamente emprestada por mão generosa;\nmuito mais opor-se assim ao céu,\npois ele reclama a dívida real que vos emprestou.","riversmadambethinkyoulikeacarefulmothero~oysinlivingedwardsthrone~190":"Rivers — Senhora, pensai, como mãe cuidadosa,\nno jovem príncipe vosso filho: mandai buscá-lo logo;\nque seja coroado; nele vive vosso consolo:\nafogai o desesperado pesar na cova do morto Eduardo\ne plantai vossas alegrias no trono do Eduardo vivo.","entergloucesterbuckinghamderbyhastingsan~derbyhastingsandratcliff~49":"Entram Gloucester, Buckingham, Derby, Hastings e Ratcliff.","gloucestermadamhavecomfortallofushavecau~mykneeicraveyourblessing~189":"Gloucester — Senhora, tende consolo: todos nós temos motivo\npara lamentar o ofuscamento de nossa estrela brilhante;\nmas ninguém cura seus males lamentando-os.\nSenhora, minha mãe, peço-vos perdão;\nnão vi Vossa Graça: humildemente de joelhos\nimploro vossa bênção.","duchessgodblesstheeandputmeeknessinthymi~rityobedienceandtrueduty~73":"Duquesa — Deus te abençoe; e ponha mansidão em tua mente,\namor, caridade, obediência e verdadeiro dever!","gloucesterasideamenandmakemedieagoodoldm~whyhergracedidleaveitout~107":"Gloucester — À parte. Amém; e faça-me morrer um bom velho!\nEsse é o fim da bênção de uma mãe:\nadmiro por que Sua Graça o deixou de fora.","buckinghamyoucloudyprincesandheartsorrow~olondontobecrowndourking~399":"Buckingham — Vós, príncipes nublados e pares de coração pesaroso,\nque levais esta mútua carga pesada de lamento,\nagora animai-vos no amor uns dos outros:\nembora tenhamos gasto nossa colheita neste rei,\nvamos colher a colheita de seu filho.\nO rancor quebrado de vossos corações inchados,\nhá pouco estilhaçados, unidos e ligados,\ndeve ser gentilmente preservado, estimado e mantido:\nparece-me bom que, com pequena comitiva,\nde pronto seja trazido de Ludlow o jovem príncipe\naqui a Londres, para ser coroado nosso rei.","riverswhywithsomelittletrainmylordofbuck~etrainmylordofbuckingham~46":"Rivers — Por que com pequena comitiva, meu lorde de Buckingham?","buckinghammarrymylordlestbyamultitudethe~pinionoughttobeprevented~284":"Buckingham — Ora, meu senhor, para que, por uma multidão,\na ferida recém-curada da malícia não se reabra;\no que seria tanto mais perigoso\nquanto o estado é verde e ainda sem governo:\nonde cada cavalo leva suas próprias rédeas\ne pode dirigir o curso como lhe apraz,\ntanto o medo do dano quanto o dano manifesto,\nem minha opinião, devem ser prevenidos.","gloucesterihopethekingmadepeacewithallof~compactisfirmandtrueinme~72":"Gloucester — Espero que o rei tenha feito paz com todos nós;\ne o pacto é firme e verdadeiro em mim.","riversandsoinmeandsoithinkinallyetsincei~ofewshouldfetchtheprince~198":"Rivers — E assim em mim; e assim, penso, em todos:\ncontudo, como é apenas verde, não deve ser posto\nem nenhuma aparente probabilidade de ruptura,\nque talvez por muita companhia fosse provocada:\nportanto digo com o nobre Buckingham\nque convém que tão poucos busquem o príncipe.","hastingsandsosayi~hastingsandsosayi~17":"Hastings — E assim digo eu.","gloucesterthenbeitsoandgowetodeterminewh~resinthisweightybusiness~148":"Gloucester — Então seja assim; e vamos determinar\nquem serão os que partirão logo a Ludlow.\nSenhora, e vós, minha mãe, quereis ir\ndar vossos pareceres neste grave negócio?","queenelizabethduchesswithallourheartsexe~tbuckinghamandgloucester~72":"Rainha Elizabeth e Duquesa — De todo o coração. Saem todos, menos Buckingham e Gloucester.","buckinghammylordwhoeverjourneystotheprin~sproudkindredfromtheking~166":"Buckingham — Meu senhor, quem quer que viaje ao príncipe,\npor Deus, não fiquemos nós dois para trás;\npois, pelo caminho, arranjarei ocasião,\ncomo índice da história de que falamos há pouco,\npara apartar do rei os orgulhosos parentes da rainha.","gloucestermyotherselfmycounselsconsistor~rwellnotstaybehindexeunt~144":"Gloucester — Meu outro eu, consistório de meus conselhos,\nmeu oráculo, meu profeta! Meu caro primo,\neu, como criança, irei por tua direção.\nPara Ludlow, então, pois não ficaremos para trás. Saem.","entertwocitizensmeeting~entertwocitizensmeeting~23":"Entram dois Cidadãos, encontrando-se.","firstcitizenneighbourwellmetwhitheraways~wellmetwhitherawaysofast~45":"Primeiro Cidadão — Vizinho, bom encontro: para onde tão depressa?","secondcitizenipromiseyouiscarcelyknowmys~selfhearyouthenewsabroad~63":"Segundo Cidadão — Prometo-vos, mal sei eu mesmo:\nouvistes as novas por aí?","firstcitizenaythatthekingisdead~tizenaythatthekingisdead~31":"Primeiro Cidadão — Sim, que o rei está morto.","secondcitizenbadnewsbyrladyseldomcomesth~willproveatroublousworld~82":"Segundo Cidadão — Más novas, por Nossa Senhora; raramente vêm melhores:\ntemo, temo que será um mundo turbulento.","enteranothercitizen~enteranothercitizen~19":"Entra outro Cidadão.","thirdcitizenneighboursgodspeed~itizenneighboursgodspeed~30":"Terceiro Cidadão — Vizinhos, Deus vos guie!","firstcitizengiveyougoodmorrowsir~izengiveyougoodmorrowsir~32":"Primeiro Cidadão — Deus vos dê bom dia, senhor.","thirdcitizendoththisnewsholdofgoodkinged~ldofgoodkingedwardsdeath~50":"Terceiro Cidadão — Confirma-se esta notícia da morte do bom rei Eduardo?","secondcitizenaysiritistootruegodhelpthew~istootruegodhelpthewhile~44":"Segundo Cidadão — Sim, senhor, é verdade demais; Deus ajude enquanto isso!","thirdcitizenthenmasterslooktoseeatroublo~looktoseeatroublousworld~47":"Terceiro Cidadão — Então, senhores, esperai um mundo turbulento.","firstcitizennonobygodsgoodgracehissonsha~oodgracehissonshallreign~47":"Primeiro Cidadão — Não, não; pela boa graça de Deus seu filho reinará.","thirdcitizenwoetothelandthatsgoverndbyac~landthatsgoverndbyachild~44":"Terceiro Cidadão — Ai da terra governada por uma criança!","secondcitizeninhimthereisahopeofgovernme~henandtillthengovernwell~142":"Segundo Cidadão — Nele há esperança de governo,\nque em sua menoridade o conselho sob ele,\ne em seus anos plenos e amadurecidos ele mesmo,\nsem dúvida governarão bem então e até então.","firstcitizensostoodthestatewhenhenrythes~nparisbutatninemonthsold~78":"Primeiro Cidadão — Assim estava o Estado quando Henrique VI\nfoi coroado em Paris com apenas nove meses.","thirdcitizenstoodthestatesononogoodfrien~sunclestoprotecthisgrace~149":"Terceiro Cidadão — Estava assim o Estado? Não, não, bons amigos, Deus sabe;\npois então esta terra era famosamente enriquecida\ncom políticos e graves conselhos; então o rei\ntinha tios virtuosos para proteger Sua Graça.","firstcitizenwhysohaththisbothbythefather~bothbythefatherandmother~49":"Primeiro Cidadão — Ora, assim tem este, tanto pelo pai quanto pela mãe.","thirdcitizenbetteritweretheyallcamebythe~ylandmightsolaceasbefore~285":"Terceiro Cidadão — Melhor fora que todos viessem pelo pai,\nou que pelo pai não houvesse nenhum;\npois a emulação agora, de quem será o mais próximo,\nnos tocará a todos perto demais, se Deus não impedir.\nOh, cheio de perigo é o duque de Gloucester!\nE os filhos e irmãos da rainha, altivos e orgulhosos:\ne se fossem governados, e não governassem,\nesta terra enferma poderia ter consolo como antes.","firstcitizencomecomewefeartheworstallsha~artheworstallshallbewell~48":"Primeiro Cidadão — Vamos, vamos, tememos o pior; tudo ficará bem.","thirdcitizenwhencloudsappearwisemenputon~rethanwedeserveoriexpect~214":"Terceiro Cidadão — Quando aparecem nuvens, os sábios vestem as capas;\nquando caem as grandes folhas, o inverno está à mão;\nquando o sol se põe, quem não espera a noite?\nTempestades fora de época fazem os homens esperar carestia.\nTudo pode estar bem; mas, se Deus assim o dispuser,\né mais do que merecemos, ou eu espero.","secondcitizentrulythesoulsofmenarefullof~snotheavilyandfulloffear~105":"Segundo Cidadão — Em verdade, as almas dos homens estão cheias de pavor:\nquase não se pode razoar com um homem\nque não tenha o olhar pesado e cheio de medo.","thirdcitizenbeforethetimesofchangestilli~aveitalltogodwhitheraway~172":"Terceiro Cidadão — Antes dos tempos de mudança, é sempre assim:\npor um instinto divino, as mentes dos homens desconfiam\ndos perigos que se seguem; como, por prova, vemos\nas águas incharem antes de uma tempestade violenta.\nMas deixemos tudo a Deus. Para onde ides?","secondcitizenmarryweweresentfortothejust~weresentfortothejustices~44":"Segundo Cidadão — Ora, fomos chamados aos juízes.","thirdcitizenandsowasiillbearyoucompanyex~iillbearyoucompanyexeunt~44":"Terceiro Cidadão — E eu também: far-vos-ei companhia. Saem.","enterthearchbishopofyorktheyoungdukeofyo~abethandtheduchessofyork~75":"Entram o Arcebispo de York, o jovem Duque de York, a Rainha Elizabeth e a Duquesa de York.","archbishoplastnightiheartheylayatnortham~wornextdaytheywillbehere~108":"Arcebispo — Ontem à noite, ouço, pernoitaram em Northampton;\nem Stony-Stratford estarão esta noite:\namanhã, ou depois, estarão aqui.","duchessilongwithallmyhearttoseetheprince~uchgrownsincelastisawhim~74":"Duquesa — Anseio de todo o coração por ver o príncipe:\nespero que tenha crescido muito desde que o vi.","queenelizabethbutihearnotheysaymysonofyo~stovertaenhiminhisgrowth~74":"Rainha Elizabeth — Mas ouço que não; dizem que meu filho de York\nquase o alcançou no crescimento.","yorkaymotherbutiwouldnothaveitso~therbutiwouldnothaveitso~32":"York — Sim, mãe; mas eu não queria que fosse assim.","duchesswhymyyoungcousinitisgoodtogrow~oungcousinitisgoodtogrow~37":"Duquesa — Ora, meu jovem neto, é bom crescer.","yorkgrandamonenightaswedidsitatsuppermyu~areslowandweedsmakehaste~225":"York — Avó, uma noite, quando estávamos à ceia,\nmeu tio Rivers disse como eu crescia\nmais que meu irmão: “Sim”, disse meu tio Gloucester,\n“ervas pequenas têm graça, ervas daninhas crescem depressa”:\ne desde então, parece-me, não quereria crescer tão rápido,\nporque flores doces são lentas e ervas daninhas têm pressa.","duchessgoodfaithgoodfaiththesayingdidnot~retrueheshouldbegracious~180":"Duquesa — Por minha fé, por minha fé, o ditado não valeu\nnaquele que o lançou contra ti:\nera a criatura mais miserável quando jovem,\ntão longo em crescer e tão vagaroso,\nque, se esta regra fosse verdadeira, deveria ser gracioso.","archbishopwhymadamsonodoubtheis~hopwhymadamsonodoubtheis~31":"Arcebispo — Ora, senhora, assim é, sem dúvida.","duchessihopeheisbutyetletmothersdoubt~eisbutyetletmothersdoubt~37":"Duquesa — Espero que seja; mas deixai as mães duvidarem.","yorknowbymytrothifihadbeenrememberdicoul~thnearerthanhetouchdmine~107":"York — Agora, por minha fé, se me tivesse lembrado,\npoderia ter dado a Sua Graça meu tio uma zombaria,\npara tocar seu crescimento mais de perto do que ele tocou o meu.","duchesshowmyprettyyorkipraytheeletmehear~yorkipraytheeletmehearit~42":"Duquesa — Como, meu pequeno York? Peço-te, deixa-me ouvir.","yorkmarrytheysaymyunclegrewsofastthathec~wouldhavebeenabitingjest~136":"York — Ora, dizem que meu tio cresceu tão depressa\nque podia roer uma côdea com duas horas de vida:\ncustou-me dois anos inteiros até ter um dente.\nAvó, isto teria sido uma troça mordaz.","duchessipraytheeprettyyorkwhotoldtheethi~rettyyorkwhotoldtheethis~41":"Duquesa — Peço-te, pequeno York, quem te disse isto?","yorkgrandamhisnurse~yorkgrandamhisnurse~19":"York — Avó, a ama dele.","duchesshisnursewhyshewasdeaderethouwertb~hewasdeaderethouwertborn~43":"Duquesa — A ama dele! ora, ela estava morta antes de teu nascimento.","yorkiftwerenotsheicannottellwhotoldme~tsheicannottellwhotoldme~37":"York — Se não foi ela, não sei quem me disse.","queenelizabethaparlousboygotoyouaretoosh~usboygotoyouaretooshrewd~44":"Rainha Elizabeth — Um menino perigoso: ora essa, és esperto demais.","archbishopgoodmadambenotangrywiththechil~ambenotangrywiththechild~41":"Arcebispo — Boa senhora, não vos zangueis com a criança.","queenelizabethpitchershaveears~lizabethpitchershaveears~30":"Rainha Elizabeth — Os cântaros têm orelhas.","enteramessenger~enteramessenger~15":"Entra um Mensageiro.","archbishopherecomesamessengerwhatnews~ecomesamessengerwhatnews~37":"Arcebispo — Aí vem um mensageiro. Que novas?","messengersuchnewsmylordasgrievesmetounfo~ylordasgrievesmetounfold~42":"Mensageiro — Tais novas, meu senhor, que me dói revelar.","queenelizabethhowfarestheprince~izabethhowfarestheprince~31":"Rainha Elizabeth — Como vai o príncipe?","messengerwellmadamandinhealth~ngerwellmadamandinhealth~29":"Mensageiro — Bem, senhora, e com saúde.","duchesswhatisthynewsthen~duchesswhatisthynewsthen~24":"Duquesa — Qual é então a tua notícia?","messengerlordriversandlordgreyaresenttop~irthomasvaughanprisoners~79":"Mensageiro — Lorde Rivers e lorde Grey foram enviados a Pomfret,\ne com eles sir Thomas Vaughan, prisioneiros.","duchesswhohathcommittedthem~hesswhohathcommittedthem~27":"Duquesa — Quem os mandou prender?","messengerthemightydukesgloucesterandbuck~sgloucesterandbuckingham~46":"Mensageiro — Os poderosos duques\nGloucester e Buckingham.","queenelizabethforwhatoffence~nelizabethforwhatoffence~28":"Rainha Elizabeth — Por que ofensa?","messengerthesumofallicanihavedisclosedwh~nknowntomemygraciouslady~104":"Mensageiro — A soma de tudo o que posso, revelei;\npor que ou por que razão esses nobres foram presos\né-me de todo desconhecido, minha graciosa senhora.","queenelizabethaymeiseethedownfallofourho~eiseeasinamaptheendofall~192":"Rainha Elizabeth — Ai de mim, vejo a queda de nossa casa!\nO tigre agora agarrou a gentil corça;\na tirania insolente começa a empavonar-se\nsobre o trono inocente e sem temor:\nBem-vindas, destruição, morte e massacre!\nVejo, como num mapa, o fim de tudo.","duchessaccursedandunquietwranglingdaysho~medietolookondeathnomore~364":"Duquesa — Malditos e inquietos dias de contenda,\nquantos de vós meus olhos viram!\nMeu marido perdeu a vida para ganhar a coroa;\ne muitas vezes meus filhos foram jogados para cima e para baixo,\npara eu me alegrar e chorar seus ganhos e perdas:\ne, estando instalados e as querelas domésticas\ntotalmente passadas, eles mesmos, os conquistadores,\nfazem guerra a si mesmos; sangue contra sangue,\neu contra eu: oh, despropositado\ne frenético ultraje, acaba teu maldito rancor;\nou deixa-me morrer, para não ver mais a morte!","queenelizabethcomecomemyboywewilltosanct~tosanctuarymadamfarewell~57":"Rainha Elizabeth — Vem, vem, meu menino; iremos ao santuário.\nSenhora, adeus.","duchessillgoalongwithyou~duchessillgoalongwithyou~24":"Duquesa — Irei convosco.","queenelizabethyouhavenocause~nelizabethyouhavenocause~28":"Rainha Elizabeth — Não tendes motivo.","archbishopmygraciousladygoandthitherbear~tyoutothesanctuaryexeunt~188":"Arcebispo — Minha graciosa senhora, ide;\ne levai para lá vosso tesouro e vossos bens.\nQuanto a mim, entregarei a Vossa Graça\no selo que guardo: e assim me suceda\ncomo bem vos estimo a vós e a todos os vossos!\nVinde, conduzir-vos-ei ao santuário. Saem.","thetrumpetssoundentertheyoungprincethedu~ourchiercatesbyandothers~101":"Soam as trombetas. Entram o jovem Príncipe, os Duques de Gloucester e de Buckingham, o Cardeal Bourchier, Catesby e outros.","buckinghamwelcomesweetprincetolondontoyo~ncetolondontoyourchamber~49":"Buckingham — Bem-vindo, doce príncipe, a Londres, a vossos aposentos.","gloucesterwelcomedearcousinmythoughtssov~wayhathmadeyoumelancholy~78":"Gloucester — Bem-vindo, caro primo, soberano de meus pensamentos:\nO cansativo caminho vos deixou melancólico.","princenounclebutourcrossesonthewayhavema~oreunclesheretowelcomeme~98":"Prince — Não, tio; mas os percalços da estrada\nTornaram-na tediosa, fatigante e pesada:\nFaltam-me aqui mais tios para me dar as boas-vindas.","gloucestersweetprincetheuntaintedvirtueo~mandfromsuchfalsefriends~328":"Gloucester — Doce príncipe, a virtude imaculada de vossos anos\nAinda não mergulhou no engano do mundo:\nNem podeis distinguir num homem\nMais que sua aparência exterior, a qual, Deus o sabe,\nRaramente ou nunca concorda com o coração.\nEsses tios que vos faltam eram perigosos;\nVossa graça atendia às suas palavras açucaradas,\nMas não via o veneno de seus corações:\nDeus vos guarde deles e de tais falsos amigos!","princegodkeepmefromfalsefriendsbuttheywe~sefriendsbuttheywerenone~46":"Prince — Deus me guarde de falsos amigos! Mas eles não o eram.","gloucestermylordthemayoroflondoncomestog~roflondoncomestogreetyou~47":"Gloucester — Meu senhor, o prefeito de Londres vem saudar-vos.","enterthelordmayorandhistrain~rthelordmayorandhistrain~28":"Entram o Lorde Prefeito e seu séquito.","mayorgodblessyourgracewithhealthandhappy~cewithhealthandhappydays~44":"Mayor — Deus abençoe vossa graça com saúde e dias felizes!","princeithankyougoodmylordandthankyoualli~swhethertheywillcomeorno~171":"Prince — Agradeço-vos, bom senhor; e agradeço a todos.\nPensei que minha mãe e meu irmão York\nJá nos teriam encontrado há muito pelo caminho:\nOra, que lesma é Hastings, que não vem\nDizer-nos se virão ou não!","buckinghamandingoodtimeherecomesthesweat~herecomesthesweatinglord~47":"Buckingham — E em boa hora, eis que chega o suarento lorde.","princewelcomemylordwhatwillourmothercome~ordwhatwillourmothercome~40":"Prince — Bem-vindo, senhor: então, nossa mãe virá?","hastingsonwhatoccasiongodheknowsnotitheq~otherwasperforcewithheld~176":"Hastings — Por que motivo, Deus o sabe, eu não,\nA rainha vossa mãe e vosso irmão York\nBuscaram refúgio no santuário: o terno príncipe\nQueria ter vindo comigo ao encontro de vossa graça,\nMas a mãe à força o reteve.","buckinghamfiewhatanindirectandpeevishcou~lousarmspluckhimperforce~213":"Buckingham — Ora, que proceder torto e birrento\nÉ esse dela! Senhor cardeal, vossa graça\nQuer persuadir a rainha a enviar o Duque de York\nAo príncipe seu irmão sem demora?\nSe ela recusar, Lorde Hastings, ide com ele\nE arrancai-o à força de seus braços ciumentos.","cardinalmylordofbuckinghamifmyweakorator~uldibeguiltyofsodeepasin~234":"Cardinal — Meu Lorde de Buckingham, se minha fraca oratória\nPuder ganhar o Duque de York de sua mãe,\nEsperai-o aqui em breve; mas se ela se mostrar obstinada\nDiante de rogos suaves, Deus no céu nos livre\nDe infringirmos o sagrado privilégio\nDo bendito santuário! Nem por toda esta terra\nSeria eu culpado de tão grave pecado.","buckinghamyouaretoosenselessobstinatemyl~tuarychildrenneertillnow~454":"Buckingham — Sois obstinado até a cegueira, senhor,\nCerimonioso e apegado em demasia à tradição:\nPesai a questão com a grosseria desta época,\nE vereis que não violais o santuário ao tomá-lo.\nO benefício dele é sempre concedido\nÀqueles cujos feitos mereceram o lugar,\nE àqueles que têm o juízo de reivindicá-lo:\nEste príncipe nem o reivindicou nem o mereceu;\nE portanto, em minha opinião, não pode tê-lo:\nAssim, tirando de lá quem lá não está,\nNão rompeis privilégio nem carta alguma.\nMuitas vezes ouvi falar de homens de santuário;\nMas de crianças de santuário, nunca, até agora.","cardinalmylordyoushalloerrulemymindforon~dhastingswillyougowithme~75":"Cardinal — Meu senhor, desta vez dominareis meu parecer.\nVamos, Lorde Hastings, vindes comigo?","hastingsigomylord~hastingsigomylord~17":"Hastings — Vou, meu senhor.","princegoodlordsmakeallthespeedyhasteyoum~sojourntillourcoronation~137":"Prince — Bons senhores, apressai-vos o mais que puderdes. Saem o Cardeal e Hastings.\nDizei, tio Gloucester, se nosso irmão vier,\nOnde nos alojaremos até a coroação?","gloucesterwhereitseemsbestuntoyourroyals~rbesthealthandrecreation~179":"Gloucester — Onde parecer melhor a vós mesmo, real senhor.\nSe me permitis aconselhar, um dia ou dois\nVossa alteza repousará na Torre:\nDepois, onde vos aprouver e for tido por mais apropriado\nPara vossa melhor saúde e recreio.","princeidonotlikethetowerofanyplacedidjul~esarbuildthatplacemylord~69":"Prince — Não gosto da Torre, mais que de qualquer lugar.\nFoi Júlio César quem construiu aquele lugar, senhor?","buckinghamhedidmygraciouslordbeginthatpl~ceedingageshavereedified~80":"Buckingham — Foi ele, meu gracioso senhor, quem o começou;\nQue, depois, eras sucessivas reedificaram.","princeisituponrecordorelsereportedsucces~elyfromagetoagehebuiltit~67":"Prince — Está nos registros, ou apenas se conta,\nDe era em era, que ele a construiu?","buckinghamuponrecordmygraciouslord~uponrecordmygraciouslord~34":"Buckingham — Nos registros, meu gracioso senhor.","princebutsaymylorditwerenotregisterdmeth~tothegeneralallendingday~130":"Prince — Mas dizei, senhor, se não estivesse registrado,\nParece-me que a verdade deveria viver de era em era,\nComo se fosse contada a toda a posteridade,\nAté o dia geral que tudo encerra.","gloucesterasidesowisesoyoungtheysaydonev~ngtheysaydoneverlivelong~50":"Gloucester — À parte. Tão sábios tão jovens, dizem, nunca vivem muito.","princewhatsayyouuncle~princewhatsayyouuncle~21":"Prince — Que dizeis, tio?","gloucesterisaywithoutcharactersfamelives~lizetwomeaningsinoneword~107":"Gloucester — Digo que, sem letras, a fama vive muito.\nÀ parte. Assim, como o formal Vício, a Iniquidade,\nMoralizo dois sentidos numa só palavra.","princethatjuliuscaesarwasafamousmanwithw~ouwhatmycousinbuckingham~200":"Prince — Que Júlio César foi um homem famoso;\nO que o valor lhe deu em engenho,\nO engenho registrou para fazer viver o valor:\nA morte não faz conquista deste conquistador;\nPois agora ele vive na fama, ainda que não na vida.\nVou dizer-vos uma coisa, meu primo Buckingham —","buckinghamwhatmygraciouslord~inghamwhatmygraciouslord~28":"Buckingham — O quê, meu gracioso senhor?","princeanifiliveuntilibeamanillwinouranci~dieasoldierasilivedaking~87":"Prince — Se eu viver até ser homem,\nReconquistarei nosso antigo direito na França,\nOu morrerei soldado, como vivi rei.","gloucesterasideshortsummerslightlyhaveaf~ightlyhaveaforwardspring~52":"Gloucester — À parte. Verões breves costumam ter primavera precoce.","enteryoungyorkhastingsandthecardinal~rkhastingsandthecardinal~36":"Entram o jovem York, Hastings e o Cardeal.","buckinghamnowingoodtimeherecomesthedukeo~meherecomesthedukeofyork~45":"Buckingham — Em boa hora, eis que chega o Duque de York.","princerichardofyorkhowfaresourlovingbrot~howfaresourlovingbrother~43":"Prince — Richard de York! Como vai nosso querido irmão?","yorkwellmydreadlordsomusticallyounow~eadlordsomusticallyounow~36":"York — Bem, meu temido senhor; assim devo chamar-vos agora.","princeaybrothertoourgriefasitisyourstool~deathhathlostmuchmajesty~109":"Prince — Sim, irmão, para nossa dor, como é a vossa:\nCedo demais morreu aquele que poderia ter conservado esse título,\nQue com a sua morte perdeu muita majestade.","gloucesterhowfaresourcousinnoblelordofyo~ourcousinnoblelordofyork~42":"Gloucester — Como vai nosso primo, nobre Lorde de York?","yorkithankyougentleuncleomylordyousaidth~brotherhathoutgrownmefar~101":"York — Agradeço-vos, gentil tio. Ó, meu senhor,\nDissestes que as ervas ociosas crescem depressa:\nO príncipe meu irmão me ultrapassou de muito.","gloucesterhehathmylord~gloucesterhehathmylord~22":"Gloucester — Ultrapassou, meu senhor.","yorkandthereforeisheidle~yorkandthereforeisheidle~24":"York — E por isso é ocioso?","gloucesteromyfaircousinimustnotsayso~yfaircousinimustnotsayso~36":"Gloucester — Ó, meu belo primo, não devo dizê-lo.","yorkthenishemorebeholdingtoyouthani~emorebeholdingtoyouthani~35":"York — Então ele vos deve mais que eu.","gloucesterhemaycommandmeasmysovereignbut~avepowerinmeasinakinsman~68":"Gloucester — Ele pode comandar-me como a seu soberano;\nMas vós tendes poder sobre mim como sobre um parente.","yorkiprayyouunclegivemethisdagger~youunclegivemethisdagger~33":"York — Peço-vos, tio, dai-me este punhal.","gloucestermydaggerlittlecousinwithallmyh~ttlecousinwithallmyheart~44":"Gloucester — Meu punhal, pequeno primo? De todo o coração.","princeabeggarbrother~princeabeggarbrother~20":"Prince — Um mendigo, irmão?","yorkofmykindunclethatiknowwillgiveandbei~atoywhichisnogrieftogive~69":"York — Do meu bondoso tio, que sei que dará;\nE sendo apenas um brinquedo, que não custa dar.","gloucesteragreatergiftthanthatillgivemyc~tthanthatillgivemycousin~45":"Gloucester — Um presente maior que esse darei a meu primo.","yorkagreatergiftothatstheswordtoit~ergiftothatstheswordtoit~34":"York — Um presente maior! Ó, é a espada, então.","gloucesteraygentlecousinwereitlightenoug~ecousinwereitlightenough~41":"Gloucester — Sim, gentil primo, se fosse leve bastante.","yorkotheniseeyouwillpartbutwithlightgift~thingsyoullsayabeggarnay~76":"York — Ó, então vejo que só vos desfareis de presentes leves;\nEm coisas de mais peso direis não a um mendigo.","gloucesteritistooheavyforyourgracetowear~oheavyforyourgracetowear~40":"Gloucester — É pesada demais para vossa graça portar.","yorkiweighitlightlywereitheavier~ghitlightlywereitheavier~32":"York — Eu a pesaria pouco, ainda que fosse mais pesada.","gloucesterwhatwouldyouhavemyweaponlittle~ouhavemyweaponlittlelord~44":"Gloucester — Como, quereis minha arma, pequeno senhor?","yorkiwouldthatimightthankyouasyoucallme~mightthankyouasyoucallme~39":"York — Quereria, para poder agradecer-vos como me chamais.","gloucesterhow~gloucesterhow~13":"Gloucester — Como?","yorklittle~yorklittle~10":"York — Pequeno.","princemylordofyorkwillstillbecrossintalk~aceknowshowtobearwithhim~75":"Prince — Meu Lorde de York será sempre ranzinza no falar:\nTio, vossa graça sabe como suportá-lo.","yorkyoumeantobearmenottobearwithmeunclem~uldbearmeonyourshoulders~136":"York — Quereis dizer, carregar-me, não suportar-me:\nTio, meu irmão zomba de vós e de mim;\nPorque sou pequeno, como um macaco,\nPensa que deveis carregar-me nos ombros.","buckinghamwithwhatasharpprovidedwitherea~ingandsoyoungiswonderful~138":"Buckingham — Com que agudo engenho ele raciocina!\nPara suavizar o escárnio que dirige ao tio,\nZomba de si mesmo com graça e propriedade:\nTanta astúcia em tão pouca idade é admirável.","gloucestermylordwilltpleaseyoupassalongm~uatthetowerandwelcomeyou~132":"Gloucester — Meu senhor, quereis seguir adiante?\nEu e meu bom primo Buckingham\nIremos à vossa mãe, rogar-lhe\nQue vos encontre na Torre e vos dê as boas-vindas.","yorkwhatwillyougountothetowermylord~lyougountothetowermylord~35":"York — Como, ireis à Torre, meu senhor?","princemylordprotectorneedswillhaveitso~otectorneedswillhaveitso~38":"Prince — O lorde protetor assim o quer.","yorkishallnotsleepinquietatthetower~otsleepinquietatthetower~35":"York — Não dormirei tranquilo na Torre.","gloucesterwhywhatshouldyoufear~sterwhywhatshouldyoufear~30":"Gloucester — Ora, que podeis temer?","yorkmarrymyuncleclarenceangryghostmygran~mtoldmehewasmurderdthere~66":"York — Pois, o espectro irado de meu tio Clarence:\nMinha avó me disse que foi assassinado lá.","princeifearnounclesdead~princeifearnounclesdead~23":"Prince — Não temo tios mortos.","gloucesternornonethatliveihope~sternornonethatliveihope~30":"Gloucester — Nem os vivos, espero.","princeaniftheyliveihopeineednotfearbutco~sterbuckinghamandcatesby~144":"Prince — Se vivem, espero não precisar temê-los.\nMas vinde, senhor; e de coração pesado,\nPensando neles, vou eu à Torre. Toque de trombeta. Saem todos, exceto Gloucester, Buckingham e Catesby.","buckinghamthinkyoumylordthislittlepratin~cornyouthusopprobriously~111":"Buckingham — Pensais, senhor, que este pequeno tagarela York\nNão foi instigado por sua sutil mãe\nA zombar e escarnecer de vós tão ultrajosamente?","gloucesternodoubtnodoubtotisaparlousboyb~hemothersfromthetoptotoe~103":"Gloucester — Sem dúvida, sem dúvida: oh, é um menino perigoso;\nOusado, rápido, engenhoso, atrevido, capaz:\nÉ todo da mãe, da cabeça aos pés.","buckinghamwellletthemrestcomehithercates~eatroyalofthisfamousisle~276":"Buckingham — Bem, deixemo-los em paz. Vem cá, Catesby.\nEstás juramentado tão firmemente a realizar o que pretendemos\nQuanto a ocultar com segredo o que te confiamos:\nConheces as razões que expusemos pelo caminho;\nQue pensas? Não é fácil\nGanhar William, Lorde Hastings, para o nosso intento,\nPara a instalação deste nobre duque\nNo assento real desta famosa ilha?","catesbyheforhisfatherssakesolovestheprin~otbewontoaughtagainsthim~77":"Catesby — Ele, por amor ao pai, estima tanto o príncipe\nQue não será levado a nada contra ele.","buckinghamwhatthinkstthouthenofstanleywh~uthenofstanleywhatwillhe~48":"Buckingham — E que pensas de Stanley? Que fará ele?","catesbyhewilldoallinallashastingsdoth~doallinallashastingsdoth~37":"Catesby — Fará em tudo o que Hastings fizer.","buckinghamwellthennomorebutthisgogentlec~selfshalthighlybeemployd~393":"Buckingham — Bem, então, não mais que isto: vai, gentil Catesby,\nE, como de longe, sonda Lorde Hastings\nSobre como se inclina quanto a nosso propósito;\nE convoca-o amanhã à Torre,\nPara tratar da coroação.\nSe o achares dócil a nós,\nAnima-o e mostra-lhe todas as nossas razões:\nSe for chumbo, gelo frio, relutante,\nSê tu também; e assim interrompe a conversa,\nE dá-nos notícia de sua disposição:\nPois amanhã teremos dois conselhos separados,\nNos quais tu mesmo serás altamente empregado.","gloucestercommendmetolordwilliamtellhimc~horeonegentlekissthemore~187":"Gloucester — Recomenda-me a Lorde William: dize-lhe, Catesby,\nQue seu antigo nó de adversários perigosos\nAmanhã terá o sangue sangrado no castelo de Pomfret;\nE manda meu amigo, em júbilo por esta boa nova,\nDar um beijo gentil a mais em Mistress Shore.","buckinghamgoodcatesbygoeffectthisbusines~ffectthisbusinesssoundly~48":"Buckingham — Bom Catesby, vai, cumpre este negócio com firmeza.","catesbymygoodlordsbothwithalltheheedimay~dsbothwithalltheheedimay~40":"Catesby — Meus bons senhores, com todo o cuidado que puder.","gloucestershallwehearfromyoucatesbyerewe~fromyoucatesbyerewesleep~45":"Gloucester — Teremos notícias tuas, Catesby, antes de dormir?","catesbyyoushallmylord~catesbyyoushallmylord~21":"Catesby — Tereis, meu senhor.","gloucesteratcrosbyplacethereshallyoufind~youfindusbothexitcatesby~57":"Gloucester — Em Crosby Place, lá nos encontrarás a ambos. Sai Catesby.","buckinghamnowmylordwhatshallwedoifweperc~illnotyieldtoourcomplots~81":"Buckingham — Agora, senhor, que faremos, se percebermos\nQue Lorde Hastings não cede a nossas tramas?","gloucesterchopoffhisheadmansomewhatwewil~ngmybrotherstoodpossessd~145":"Gloucester — Corta-lhe a cabeça, homem; algo faremos:\nE olha, quando eu for rei, reclama de mim\nO condado de Hereford e os bens móveis\nQue o rei meu irmão possuía.","buckinghamillclaimthatpromiseatyourgrace~promiseatyourgraceshands~46":"Buckingham — Reclamarei essa promessa das mãos de vossa graça.","gloucesterandlooktohaveityieldedwithallw~complotsinsomeformexeunt~121":"Gloucester — E espera obtê-la com toda a boa vontade.\nVamos, ceemos cedo, para que depois\nPossamos digerir nossas tramas em ordem. Saem.","beforelordhastingshouse~beforelordhastingshouse~23":"Diante da casa de Lorde Hastings.","messengerwhathomylord~messengerwhathomylord~21":"Messenger — Ó de casa! Meu senhor!","hastingswithinwhoknocksatthedoor~withinwhoknocksatthedoor~32":"Hastings — Dentro. Quem bate à porta?","messengeramessengerfromthelordstanley~sengerfromthelordstanley~37":"Messenger — Um mensageiro de Lorde Stanley.","hastingswhatistoclock~hastingswhatistoclock~21":"Hastings — Que horas são?","messengeruponthestrokeoffour~engeruponthestrokeoffour~28":"Messenger — Dão as quatro.","hastingscannotthymastersleepthesetedious~rsleepthesetediousnights~46":"Hastings — Teu amo não consegue dormir nestas noites tediosas?","messengersoitshouldseembythatihavetosayf~dshimtoyournoblelordship~76":"Messenger — Assim parece, pelo que tenho a dizer.\nPrimeiro, ele se recomenda a vossa nobre senhoria.","hastingsandthen~hastingsandthen~15":"Hastings — E depois?","messengerandthenhesendsyouwordhedreamtto~dangerthathissouldivines~319":"Messenger — E depois ele vos manda dizer\nQue sonhou esta noite que o javali lhe arrancara o elmo:\nAlém disso, diz que há dois conselhos convocados;\nE que o que se decidir num\nPoderá fazer-vos e a ele lamentar no outro.\nPor isso manda saber o desejo de vossa senhoria,\nSe quereis montar logo a cavalo com ele,\nE com toda a pressa seguir com ele rumo ao norte,\nPara fugir ao perigo que sua alma pressente.","hastingsgofellowgoreturnuntothylordbidhi~eetheboarwilluseuskindly~496":"Hastings — Vai, camarada, vai, volta a teu senhor;\nDize-lhe que não tema os conselhos separados:\nSua honra e eu estamos num,\nE no outro está meu servidor Catesby;\nOnde nada pode andar que nos toque\nSem que eu tenha notícia.\nDize-lhe que seus temores são rasos, sem fundamento:\nE quanto a seus sonhos, admiro que seja tão tolo\nDe confiar na zombaria de sonos inquietos:\nFugir do javali antes que o javali persiga\nSeria açular o javali a seguir-nos\nE perseguir onde não pretendia caça.\nVai, manda teu amo levantar-se e vir a mim;\nE iremos juntos à Torre,\nOnde ele verá que o javali nos tratará com gentileza.","messengermygraciouslordilltellhimwhatyou~illtellhimwhatyousayexit~47":"Messenger — Meu gracioso senhor, direi a ele o que dizeis. Sai.","catesbymanygoodmorrowstomynoblelord~goodmorrowstomynoblelord~35":"Catesby — Muitos bons dias a meu nobre senhor!","hastingsgoodmorrowcatesbyyouareearlystir~sinthisourtotteringstate~83":"Hastings — Bom dia, Catesby; madrugais:\nQue novas, que novas neste nosso Estado vacilante?","catesbyitisareelingworldindeedmylordandi~wearthegarlandoftherealm~104":"Catesby — É um mundo cambaleante, de fato, senhor;\nE creio que nunca se erguerá\nAté que Richard cinja a guirlanda do reino.","hastingshowwearthegarlanddostthoumeanthe~landdostthoumeanthecrown~45":"Hastings — Como! cingir a guirlanda! Queres dizer a coroa?","catesbyaymygoodlord~catesbyaymygoodlord~19":"Catesby — Sim, meu bom senhor.","hastingsillhavethiscrownofminecutfrommys~ouguessthathedothaimatit~116":"Hastings — Preferiria ter esta minha cabeça cortada dos ombros\nA ver a coroa tão torpemente mal posta.\nMas podes supor que ele a ambiciona?","catesbyayonmylifeandhopestofindyouforwar~thequeenmustdieatpomfret~170":"Catesby — Sim, por minha vida; e espera achar-vos disposto\nA seu partido pelo ganho que daí advém:\nE por isso vos manda esta boa nova,\nQue neste mesmo dia vossos inimigos,\nOs parentes da rainha, devem morrer em Pomfret.","hastingsindeediamnomournerforthatnewsbec~wsiwillnotdoittothedeath~169":"Hastings — Na verdade, não sou carpideira dessa notícia,\nPorque sempre foram meus inimigos:\nMas dar minha voz ao lado de Richard\nPara barrar os herdeiros de meu amo na legítima descendência,\nDeus sabe que não o farei, até a morte.","catesbygodkeepyourlordshipinthatgracious~rdshipinthatgraciousmind~44":"Catesby — Deus guarde vossa senhoria nessa graciosa disposição!","hastingsbutishalllaughatthisatwelvemonth~rtragedyitelltheecatesby~123":"Hastings — Mas hei de rir disto daqui a um ano,\nQue aqueles que me trouxeram o ódio de meu amo,\nEu viva para ver sua tragédia.\nDigo-te, Catesby —","catesbywhatmylord~catesbywhatmylord~17":"Catesby — O quê, meu senhor?","hastingsereafortnightmakemeelderillsends~ckingthatyetthinknotonit~69":"Hastings — Antes que uma quinzena me envelheça,\nMandarei embora alguns que ainda nem pensam nisso.","catesbytisavilethingtodiemygraciouslordw~npreparedandlooknotforit~74":"Catesby — É coisa vil morrer, meu gracioso senhor,\nQuando os homens estão despreparados e não esperam.","hastingsomonstrousmonstrousandsofallsito~lyrichardandtobuckingham~178":"Hastings — Ó monstruoso, monstruoso! E assim acontece\nCom Rivers, Vaughan, Grey: e assim será\nCom alguns outros, que se julgam tão seguros\nQuanto tu e eu; que, como sabes, são caros\nAo principesco Richard e a Buckingham.","catesbytheprincesbothmakehighaccountofyo~ounthisheaduponthebridge~80":"Catesby — Os príncipes ambos vos têm em alta conta;\nÀ parte. Pois contam sua cabeça sobre a ponte.","hastingsiknowtheydoandihavewelldeservedi~doandihavewelldeservedit~41":"Hastings — Sei que sim; e bem o mereci.","enterlordstanley~enterlordstanley~16":"Entra Lorde Stanley.","comeoncomeonwhereisyourboarspearmanfeary~theboarandgosounprovided~66":"Vamos, vamos; onde está tua lança de caça ao javali, homem?\nTemeis o javali e andais tão desprovido?","stanleymylordgoodmorrowgoodmorrowcatesby~iketheseseveralcouncilsi~99":"Stanley — Meu senhor, bom dia; bom dia, Catesby:\nPodeis continuar a gracejar, mas, pela santa cruz,\nNão gosto desses conselhos separados, eu.","hastingsmylordiholdmylifeasdearasyoudoyo~wouldbesotriumphantasiam~159":"Hastings — Meu senhor,\nPrezo minha vida tanto quanto vós a vossa;\nE nunca em minha vida, protesto,\nFoi-me mais preciosa do que agora:\nPensais que, se não soubesse nosso Estado seguro,\nEstaria tão triunfante como estou?","stanleythelordsatpomfretwhentheyrodefrom~ardthetowerthedayisspent~251":"Stanley — Os lordes de Pomfret, quando saíram de Londres,\nEram joviais e supunham seguro o seu estado,\nE de fato não tinham causa de desconfiança;\nMas vede quão depressa o dia se anuviou.\nDesconfio desta súbita punhalada de rancor:\nPraza a Deus, digo, que eu seja um covarde sem razão!\nEntão, vamos à Torre? O dia se gasta.","hastingscomecomehavewithyouwotyouwhatmyl~ordsyoutalkofarebeheaded~76":"Hastings — Vamos, vamos, convosco. Sabeis, meu senhor?\nHoje os lordes de quem falais são decapitados.","stanleytheyfortheirtruthmightbetterweart~tsbutcomemylordletusaway~111":"Stanley — Eles, por sua lealdade, poderiam melhor usar a cabeça\nDo que alguns que os acusaram usam o chapéu.\nMas vinde, senhor, partamos.","enterapursuivant~enterapursuivant~16":"Entra um Arauto.","hastingsgoonbeforeilltalkwiththisgoodfel~hhowgoestheworldwiththee~101":"Hastings — Ide na frente; falarei com este bom homem. Saem Stanley e Catesby.\nEntão, rapaz! Como vai o mundo contigo?","pursuivantthebetterthatyourlordshippleas~tyourlordshippleasetoask~46":"Pursuivant — Melhor, por vossa senhoria querer perguntar.","hastingsitelltheemantisbetterwithmenowth~inbetterstatethaneeriwas~225":"Hastings — Digo-te, homem, vai melhor comigo agora\nDo que quando te encontrei da última vez onde agora nos encontramos:\nEntão ia eu prisioneiro para a Torre,\nPor instigação dos aliados da rainha;\nMas agora, digo-te — guarda-o para ti —\nHoje esses inimigos são mortos,\nE eu estou em melhor estado do que nunca.","pursuivantgodholdittoyourhonoursgoodcont~toyourhonoursgoodcontent~43":"Pursuivant — Deus o conserve, para o contentamento de vossa honra!","hastingsgramercyfellowtheredrinkthatform~atformethrowshimhispurse~58":"Hastings — Obrigado, camarada: toma, bebe isto por mim. Atira-lhe a bolsa.","pursuivantgodsaveyourlordshipexit~tgodsaveyourlordshipexit~33":"Pursuivant — Deus guarde vossa senhoria! Sai.","enterapriest~enterapriest~12":"Entra um Sacerdote.","priestwellmetmylordiamgladtoseeyourhonou~rdiamgladtoseeyourhonour~41":"Priest — Bem encontrado, meu senhor; folgo em ver vossa honra.","hastingsithanktheegoodsirjohnwithallmyhe~entyouhewhispersinhisear~129":"Hastings — Agradeço-te, bom Sir John, de todo o coração.\nEstou em dívida convosco pelo vosso último ofício;\nVinde no próximo sabá, e vos satisfarei. Cochicha-lhe ao ouvido.","enterbuckingham~enterbuckingham~15":"Entra Buckingham.","buckinghamwhattalkingwithapriestlordcham~hathnoshrivingworkinhand~120":"Buckingham — Quê, conversando com um padre, lorde camareiro?\nVossos amigos em Pomfret, esses sim precisam do padre;\nVossa honra não tem serviço de confissão em mãos.","hastingsgoodfaithandwhenimetthisholymant~dwhatgoyoutowardthetower~93":"Hastings — Por minha fé, quando encontrei este santo homem,\nEsses homens de quem falais me vieram à mente.\nQuê, ides à Torre?","buckinghamidomylordbutlongishallnotstayi~beforeyourlordshipthence~75":"Buckingham — Vou, meu senhor; mas não ficarei muito:\nVoltarei de lá antes de vossa senhoria.","hastingstislikeenoughforistaydinnerthere~noughforistaydinnerthere~40":"Hastings — É provável, pois lá fico para o jantar.","buckinghamasideandsuppertooalthoughthouk~knowstitnotcomewillyougo~63":"Buckingham — À parte. E para a ceia também, embora não o saibas.\nVamos, quereis ir?","hastingsillwaituponyourlordshipexeunt~ituponyourlordshipexeunt~37":"Hastings — Acompanharei vossa senhoria. Saem.","pomfretcastle~pomfretcastle~13":"Castelo de Pomfret.","entersirrichardratcliffwithhalberdscarry~ersgreyandvaughantodeath~70":"Entra Sir Richard Ratcliff, com alabardeiros, conduzindo Rivers, Grey e Vaughan à morte.","ratcliffcomebringforththeprisoners~mebringforththeprisoners~34":"Ratcliff — Vamos, trazei os prisioneiros.","riverssirrichardratcliffletmetelltheethi~ruthfordutyandforloyalty~100":"Rivers — Sir Richard Ratcliff, deixa-me dizer-te isto:\nHoje verás morrer um súdito\nPela verdade, pelo dever e pela lealdade.","greygodkeeptheprincefromallthepackofyoua~uareofdamnedbloodsuckers~70":"Grey — Deus guarde o príncipe de toda a vossa matilha!\nSois um nó de malditos sanguessugas.","vaughanyoulivethatshallcrywoeforthishere~llcrywoeforthishereafter~45":"Vaughan — Vivereis para clamar desgraça por isto no futuro.","ratcliffdispatchthelimitofyourlivesisout~thelimitofyourlivesisout~40":"Ratcliff — Despachai; o limite de vossas vidas se esgotou.","riversopomfretpomfretothoubloodyprisonfa~ourguiltlessbloodtodrink~200":"Rivers — Ó Pomfret, Pomfret! Ó tu, sangrenta prisão,\nFatal e agourenta para nobres pares!\nDentro do culpado recinto de tuas muralhas\nRichard II foi aqui retalhado até a morte;\nE, para maior infâmia de tua sombria sede,\nEntregamos-te nosso sangue inocente para beber.","greynowmargaretscurseisfallnuponourheads~ywhenrichardstabbdherson~76":"Grey — Agora a maldição de Margaret caiu sobre nossas cabeças,\nPor termos ficado a olhar quando Richard apunhalou seu filho.","riversthencursedshehastingsthencursedshe~nowstunjustlymustbespilt~217":"Rivers — Então amaldiçoou Hastings, então amaldiçoou Buckingham,\nEntão amaldiçoou Richard. Ó, lembra-te, Deus,\nDe ouvir suas preces por eles, como agora por nós!\nE por minha irmã e seus filhos principescos,\nDá-te por satisfeito, caro Deus, com nosso sangue leal,\nQue, como sabes, será derramado injustamente.","ratcliffmakehastethehourofdeathisexpiate~ethehourofdeathisexpiate~40":"Ratcliff — Depressa; a hora da morte chegou.","riverscomegreycomevaughanletusallembrace~ntilwemeetinheavenexeunt~80":"Rivers — Vem, Grey, vem, Vaughan, abracemo-nos todos:\nE despeçamo-nos, até nos encontrarmos no céu. Saem.","thetoweroflondon~thetoweroflondon~16":"A Torre de Londres.","enterbuckinghamderbyhastingsthebishopofe~ndtaketheirseatsatatable~90":"Entram Buckingham, Derby, Hastings, o Bispo de Ely, Ratcliff, Lovel e outros, e tomam seus lugares a uma mesa.","hastingsmylordsatoncethecausewhywearemet~mespeakwhenistheroyalday~100":"Hastings — Meus senhores, sem rodeios: a causa por que nos reunimos\nÉ decidir sobre a coroação.\nEm nome de Deus, falai: quando é o dia real?","buckinghamareallthingsfittingforthatroya~sfittingforthatroyaltime~45":"Buckingham — Está tudo pronto para esse momento real?","derbyitisandwantsbutnomination~tisandwantsbutnomination~30":"Derby — Está, e só falta designar a data.","elytomorrowthenijudgeahappyday~orrowthenijudgeahappyday~30":"Ely — Amanhã, então, julgo um dia feliz.","buckinghamwhoknowsthelordprotectorsmindh~stinwardwiththenobleduke~76":"Buckingham — Quem conhece a intenção do lorde protetor nisto?\nQuem é mais íntimo do nobre duque?","elyyourgracewethinkshouldsoonestknowhism~shouldsoonestknowhismind~43":"Ely — Vossa graça, cremos, seria quem mais cedo lhe conhece o pensamento.","buckinghamwhoimylordweknoweachothersface~ngsyouandhearenearinlove~148":"Buckingham — Quem, eu, meu senhor! Conhecemos os rostos um do outro,\nMas quanto aos corações, ele não sabe mais do meu\nDo que eu do vosso;\nNem eu mais do dele do que vós do meu.\nLorde Hastings, vós e ele sois próximos no afeto.","hastingsithankhisgraceiknowhelovesmewell~sumehelltakeingentlepart~232":"Hastings — Agradeço a sua graça, sei que me estima bem;\nMas quanto ao seu propósito na coroação,\nNão o sondei, nem ele declarou\nSeu gracioso desejo a esse respeito:\nMas vós, meus nobres senhores, podeis marcar a data;\nE em nome do duque darei meu voto,\nQue, presumo, ele receberá de bom grado.","elynowingoodtimeherecomesthedukehimself~eherecomesthedukehimself~39":"Ely — Em boa hora, eis que chega o próprio duque.","gloucestermynoblelordsandcousinsallgoodm~cemighthavebeenconcluded~147":"Gloucester — Meus nobres senhores e primos todos, bom dia.\nFui longo tempo dorminhoco; mas, espero,\nMinha ausência não negligencia grandes desígnios\nQue minha presença poderia ter concluído.","buckinghamhadnotyoucomeuponyourcuemylord~oiceforcrowningoftheking~114":"Buckingham — Se não tivésseis chegado na deixa, meu senhor,\nWilliam, Lorde Hastings, teria dito vossa parte —\nQuero dizer, vosso voto — pela coroação do rei.","gloucesterthanmylordhastingsnomanmightbe~nowsmewellandlovesmewell~82":"Gloucester — Ninguém poderia ser mais ousado que meu Lorde Hastings;\nSua senhoria me conhece bem e me estima bem.","hastingsithankyourgrace~hastingsithankyourgrace~23":"Hastings — Agradeço a vossa graça.","gloucestermylordofely~gloucestermylordofely~21":"Gloucester — Meu lorde de Ely!","elymylord~elymylord~9":"Ely — Meu senhor?","gloucesterwheniwaslastinholbornisawgoods~eechyousendforsomeofthem~98":"Gloucester — Quando estive por último em Holborn,\nVi bons morangos em vosso jardim de lá:\nRogo-vos que mandeis buscar alguns.","elymarryandwillmylordwithallmyheartexit~mylordwithallmyheartexit~39":"Ely — Pois não, e mandarei, meu senhor, de todo o coração. Sai.","gloucestercousinofbuckinghamawordwithyou~eroyaltyofenglandsthrone~228":"Gloucester — Primo de Buckingham, uma palavra convosco. Puxa-o de lado.\nCatesby sondou Hastings em nosso negócio,\nE acha o irascível cavalheiro tão ardente\nQue perderá a cabeça antes de consentir\nQue o filho de seu amo, tão venerável quanto ele o chama,\nPerca a realeza do trono da Inglaterra.","buckinghamwithdrawyouhencemylordillfollo~esterbuckinghamfollowing~77":"Buckingham — Retirai-vos daqui, meu senhor, eu vos seguirei. Sai Gloucester, seguido por Buckingham.","derbywehavenotyetsetdownthisdayoftriumph~ouldbewerethedayprolongd~133":"Derby — Ainda não fixamos este dia de triunfo.\nAmanhã, em minha opinião, é muito repentino;\nPois eu mesmo não estou tão bem provido\nQuanto estaria, se o dia fosse prorrogado.","reenterbishopofely~reenterbishopofely~18":"Reentra o Bispo de Ely.","elywhereismylordprotectorihavesentforthe~sentforthesestrawberries~54":"Ely — Onde está o lorde protetor? Mandei buscar esses morangos.","hastingshisgracelookscheerfullyandsmooth~ightshallyouknowhisheart~227":"Hastings — Sua graça tem hoje o semblante alegre e plácido;\nAlgum pensamento lhe agrada bem,\nQuando dá bom dia com tal ânimo.\nCreio que não há homem na cristandade\nQue esconda menos o amor ou o ódio do que ele;\nPois pelo rosto logo se lhe conhece o coração.","derbywhatofhisheartperceiveyouinhisfaceb~nylikelihoodheshowdtoday~66":"Derby — Que vedes de seu coração em seu rosto,\nPor qualquer indício que mostrou hoje?","hastingsmarrythatwithnomanhereheisoffend~hehehadshownitinhislooks~73":"Hastings — Ora, que com ninguém aqui está ofendido;\nPois, se estivesse, teria mostrado nos olhares.","derbyipraygodhebenotisay~derbyipraygodhebenotisay~24":"Derby — Rogo a Deus que não esteja, digo.","reentergloucesterandbuckingham~rgloucesterandbuckingham~30":"Reentram Gloucester e Buckingham.","gloucesteriprayyoualltellmewhattheydeser~dywiththeirhellishcharms~149":"Gloucester — Rogo-vos todos, dizei-me o que merecem\nOs que conspiram minha morte com tramas diabólicas\nDe maldita feitiçaria, e que prevaleceram\nSobre meu corpo com seus encantos infernais?","hastingsthetenderloveibearyourgracemylor~ordtheyhavedeserveddeath~143":"Hastings — O terno amor que dedico a vossa graça, senhor,\nFaz-me o mais pronto, nesta nobre presença,\nA condenar os ofensores, sejam quem forem:\nDigo, senhor, que mereceram a morte.","gloucesterthenbeyoureyesthewitnessofthis~tchcraftthushavemarkedme~214":"Gloucester — Então sejam vossos olhos testemunhas deste mal:\nVede como estou enfeitiçado; olhai, meu braço\nEstá, como um arbusto fulminado, mirrado:\nE isto é obra da mulher de Edward, aquela monstruosa bruxa,\nEm conluio com aquela rameira meretriz Shore,\nQue por sua feitiçaria assim me marcaram.","hastingsiftheyhavedonethisthingmygraciou~ethisthingmygraciouslord~45":"Hastings — Se fizeram tal coisa, meu gracioso senhor —","gloucesterifthouprotectorofthisdamnedstr~hastingsratcliffandlovel~240":"Gloucester — Se! Tu, protetor desta maldita meretriz,\nFalas-me de “ses”? És um traidor:\nFora com a cabeça dele! Agora, por São Paulo, juro,\nNão jantarei até ver isso feito.\nLovel e Ratcliff, cuidai que se faça:\nOs demais, que me amam, levantai-vos e segui-me. Saem todos, exceto Hastings, Ratcliff e Lovel.","hastingswoewoeforenglandnotawhitformefor~poorhastingswretchedhead~470":"Hastings — Ai, ai pela Inglaterra! Nada por mim;\nPois eu, tolo demais, poderia ter evitado isto.\nStanley sonhou que o javali lhe arrancara o elmo;\nMas eu o desdenhei e desprezei fugir:\nTrês vezes hoje meu cavalo de gualdrapa tropeçou,\nE se assustou, quando olhou para a Torre,\nComo se relutasse em levar-me ao matadouro.\nÓ, agora me faz falta o padre que me falou:\nAgora me arrependo de ter contado ao arauto,\nComo que triunfando sobre meus inimigos,\nComo em Pomfret foram sangrentamente chacinados,\nE eu mesmo seguro em graça e favor.\nÓ Margaret, Margaret, agora tua pesada maldição\nCaiu sobre a infeliz cabeça do pobre Hastings!","ratcliffdispatchmylordthedukewouldbeatdi~rifthelongstoseeyourhead~80":"Ratcliff — Despachai, meu senhor; o duque quer jantar:\nFazei uma confissão breve; ele anseia por ver vossa cabeça.","hastingsomomentarygraceofmortalmenwhichw~othefatalbowelsofthedeep~192":"Hastings — Ó momentânea graça dos mortais,\nQue mais perseguimos que a graça de Deus!\nQuem constrói suas esperanças no ar de vossos bons olhares\nVive como um marinheiro bêbado sobre um mastro,\nPronto, a cada aceno, a despencar\nNas entranhas fatais do abismo.","lovelcomecomedispatchtisbootlesstoexclai~atchtisbootlesstoexclaim~41":"Lovel — Vamos, vamos, despachai; é inútil clamar.","hastingsobloodyrichardmiserableenglandip~shortlyshallbedeadexeunt~176":"Hastings — Ó sanguinário Richard! Miserável Inglaterra!\nProfetizo-te o tempo mais terrível\nQue jamais uma época desgraçada contemplou.\nVamos, levai-me ao cepo; levai-lhe minha cabeça:\nSorriem de mim os que em breve estarão mortos. Saem.","scenev~scenev~6":"Cena V","thetowerwalls~thetowerwalls~13":"As muralhas da Torre.","entergloucesterandbuckinghaminrottenarmo~ourmarvellousillfavoured~63":"Entram Gloucester e Buckingham, em armaduras podres, de aspecto maravilhosamente sinistro.","gloucestercomecousincanstthouquakeandcha~straughtandmadwithterror~152":"Gloucester — Vem, primo, sabes tremer e mudar de cor,\nAssassinar o fôlego no meio de uma palavra,\nE depois recomeçar e parar de novo,\nComo se estivesses fora de ti, louco de terror?","buckinghamtuticancounterfeitthedeeptrage~gemsbutwhatiscatesbygone~252":"Buckingham — Ora, sei imitar o profundo trágico;\nFalar e olhar para trás, espreitar de todos os lados,\nTremer e sobressaltar-me ao mexer de uma palha,\nFingindo funda suspeita: olhares espectrais\nEstão a meu serviço, como sorrisos forçados;\nE ambos estão prontos em seus ofícios,\nA qualquer hora, para adornar meus estratagemas.\nMas então, Catesby partiu?","gloucesterheisandseehebringsthemayoralon~seehebringsthemayoralong~41":"Gloucester — Partiu; e, olha, traz o prefeito consigo.","enterthemayorandcatesby~enterthemayorandcatesby~23":"Entram o Prefeito e Catesby.","buckinghamlordmayor~buckinghamlordmayor~19":"Buckingham — Lorde prefeito —","gloucesterlooktothedrawbridgethere~looktothedrawbridgethere~34":"Gloucester — Vigiai a ponte levadiça ali!","buckinghamharkadrum~buckinghamharkadrum~19":"Buckingham — Ouvi! Um tambor.","gloucestercatesbyoerlookthewalls~ercatesbyoerlookthewalls~32":"Gloucester — Catesby, inspeciona as muralhas.","buckinghamlordmayorthereasonwehavesent~mayorthereasonwehavesent~38":"Buckingham — Lorde prefeito, a razão por que mandamos —","gloucesterlookbackdefendtheehereareenemi~defendtheehereareenemies~42":"Gloucester — Olha atrás, defende-te, aqui há inimigos.","buckinghamgodandourinnocencydefendandgua~nnocencydefendandguardus~44":"Buckingham — Deus e nossa inocência nos defendam e guardem!","gloucesterbepatienttheyarefriendsratclif~efriendsratcliffandlovel~49":"Gloucester — Calma, são amigos, Ratcliff e Lovel.","enterlovelandratcliffwithhastingshead~ratcliffwithhastingshead~37":"Entram Lovel e Ratcliff, com a cabeça de Hastings.","lovelhereistheheadofthatignobletraitorth~usandunsuspectedhastings~72":"Lovel — Eis a cabeça daquele ignóbil traidor,\nO perigoso e insuspeitado Hastings.","gloucestersodearilovedthemanthatimustwee~romallattainderofsuspect~315":"Gloucester — Tanto amei esse homem que devo chorar.\nTomei-o pela criatura mais simples e inofensiva\nQue respirou sobre esta terra como cristão;\nFiz dele meu livro, no qual minha alma registrava\nA história de todos os seus pensamentos secretos:\nTão habilmente disfarçava o vício com ares de virtude\nQue, omitida sua culpa evidente e aberta,\nQuero dizer, o trato com a mulher de Shore,\nVivia livre de toda mácula de suspeita.","buckinghamwellwellhewasthecovertstshelte~ndmygoodlordofgloucester~225":"Buckingham — Bem, bem, foi o traidor mais bem encoberto\nQue jamais viveu.\nImaginarieis, ou quase acreditaríeis,\nNão fosse que, por grande providência,\nVivemos para contá-lo, que o sutil traidor\nNeste dia tramara, na sala do conselho,\nAssassinar a mim e a meu bom Lorde de Gloucester?","mayorwhathadheso~mayorwhathadheso~16":"Mayor — Quê, ele tinha tramado?","gloucesterwhatthinkyouweareturksorinfide~nforcedustothisexecution~201":"Gloucester — Quê, pensais que somos turcos ou infiéis?\nOu que, contra a forma da lei,\nProcederíamos tão precipitadamente à morte do vilão,\nNão fosse o extremo perigo do caso,\nA paz da Inglaterra e a segurança de nossas pessoas\nTerem-nos forçado a esta execução?","mayornowfairbefallyouhedeservedhisdeatha~efellinwithmistressshore~179":"Mayor — Que a boa sorte vos acompanhe! Ele mereceu a morte;\nE vós, meus bons senhores, procedestes bem\nEm advertir falsos traidores contra tais tentativas.\nNunca esperei melhor dele,\nDepois que caiu nas mãos de Mistress Shore.","gloucesteryethadnotwedeterminedheshouldd~ueusinhimandwailhisdeath~352":"Gloucester — Contudo não tínhamos decidido que ele morreria\nAté que vossa senhoria viesse ver sua morte;\nQue agora o afetuoso açodamento destes nossos amigos,\nUm tanto contra nossa intenção, antecipou:\nPorque, senhor, queríamos que o ouvísseis\nO traidor falar, e confessar, temeroso,\nO modo e o propósito de sua traição;\nPara que pudésseis bem comunicá-lo\nAos cidadãos, que talvez\nNos interpretem mal quanto a ele e lamentem sua morte.","mayorbutmygoodlordyourgraceswordshallser~stproceedingsinthiscause~178":"Mayor — Mas, meu bom senhor, a palavra de vossa graça servirá\nTão bem como se eu o tivesse visto e ouvido falar:\nE não duvideis, nobilíssimos príncipes ambos,\nQue informarei nossos cidadãos devotados\nDe todos os vossos justos procedimentos nesta causa.","gloucesterandtothatendwewishdyourlordshi~arpingcensuresoftheworld~80":"Gloucester — E com esse fim desejávamos vossa senhoria aqui,\nPara evitar as censuras mordazes do mundo.","buckinghambutsinceyoucometoolateofourint~orwebidfarewellexitmayor~118":"Buckingham — Mas já que chegastes tarde para nossos intentos,\nAo menos testemunhai o que ouvis que pretendíamos:\nE assim, meu bom lorde prefeito, despedimo-nos. Sai o Prefeito.","gloucestergoafteraftercousinbuckinghamth~uknowmylordmymotherlives~780":"Gloucester — Vai, atrás dele, primo Buckingham.\nO prefeito corre a toda pressa para Guildhall:\nLá, na ocasião mais oportuna do momento,\nAlega a bastardia dos filhos de Edward:\nConta-lhes como Edward mandou matar um cidadão\nSó por dizer que faria seu filho\nHerdeiro da coroa; referindo-se, na verdade, à sua casa,\nQue, pelo letreiro, assim se chamava.\nAlém disso, insiste em sua odiosa luxúria\nE apetite bestial na troca de volúpias;\nQue se estendia às criadas, filhas, esposas,\nAté onde seu olho lascivo ou coração selvagem,\nSem freio, quis fazer sua presa.\nMais, se preciso, chega até aqui perto de mim:\nDize-lhes que, quando minha mãe estava grávida\nDaquele insaciável Edward, o nobre York,\nMeu príncipe pai, estava então em guerra na França;\nE, por justo cômputo do tempo,\nAchou que a criança não era por ele gerada;\nO que bem se via em suas feições,\nEm nada parecido com o nobre duque, meu pai:\nMas toca nisto com parcimônia, como de longe;\nPorque sabeis, senhor, que minha mãe vive.","buckinghamfearnotmylordillplaytheoratora~ormyselfandsomylordadieu~98":"Buckingham — Não temais, senhor, farei o orador\nComo se o ouro de honorários por que advogo\nFosse para mim mesmo: e assim, senhor, adeus.","gloucesterifyouthrivewellbringthemtobayn~ersandwelllearnedbishops~124":"Gloucester — Se tiveres êxito, traze-os ao Castelo de Baynard;\nOnde me encontrarás bem acompanhado\nDe reverendos padres e bispos doutos.","buckinghamigoandtowardsthreeorfouroclock~ttheguildhallaffordsexit~81":"Buckingham — Vou; e por volta das três ou quatro horas\nEsperai as novas que Guildhall oferecer. Sai.","gloucestergolovelwithallspeedtodoctorsha~courseuntotheprincesexit~276":"Gloucester — Vai, Lovel, com toda a pressa ao Doutor Shaw;\nA Catesby. Vai tu ao Frei Penker; manda ambos\nEncontrarem-me dentro de uma hora no Castelo de Baynard. Saem todos, exceto Gloucester.\nAgora entrarei, para dar alguma ordem secreta\nQue tire de vista os pirralhos de Clarence;\nE para dar aviso de que pessoa alguma, de qualquer espécie,\nTenha em tempo algum acesso aos príncipes. Sai.","scenevi~scenevi~7":"Cena VI","thesame~thesame~7":"O mesmo lugar.","enterascrivenerwithapaperinhishand~venerwithapaperinhishand~34":"Entra um Escrivão, com um papel na mão.","scrivenerthisistheindictmentofthegoodlor~smustbeseeninthoughtexit~498":"Scrivener — Esta é a acusação do bom Lorde Hastings;\nQue em letra de forma foi belamente passada a limpo,\nPara que seja lida hoje em São Paulo.\nE notai como bem se encadeia a sequência:\nOnze horas gastei para copiá-la,\nPois ontem à noite Catesby ma trouxe;\nO original levou tanto tempo a fazer quanto esta cópia.\nE ainda assim, há cinco horas, vivia Lorde Hastings,\nSem mácula, sem inquérito, livre, em liberdade.\nBelo mundo este, entretanto! Ora, quem é tão obtuso\nQue não vê esta trama palpável?\nMas quem é tão cego que diga que não a vê?\nMau é o mundo; e tudo dará em nada,\nQuando tais maus tratos só podem ser vistos em pensamento. Sai.","scenevii~scenevii~8":"Cena VII","baynardscastle~baynardscastle~14":"Castelo de Baynard.","entergloucesterandbuckinghamatseveraldoo~buckinghamatseveraldoors~42":"Entram Gloucester e Buckingham, por portas diferentes.","gloucesterhownowmylordwhatsaythecitizens~mylordwhatsaythecitizens~40":"Gloucester — Então, senhor, que dizem os cidadãos?","buckinghamnowbytheholymotherofourlordthe~nsaremumandspeaknotaword~70":"Buckingham — Pela santa mãe de Nosso Senhor,\nOs cidadãos estão mudos e não dizem palavra.","gloucestertouchdyouthebastardyofedwardsc~astardyofedwardschildren~47":"Gloucester — Tocastes na bastardia dos filhos de Edward?","buckinghamididwithhiscontractwithladyluc~richardenglandsroyalking~590":"Buckingham — Toquei; com o contrato dele com Lady Lucy,\nE seu contrato por procuração na França;\nA insaciável avidez de seus desejos,\nE sua violência contra as esposas da cidade;\nSua tirania por ninharias; sua própria bastardia,\nPor ter sido gerado quando vosso pai estava na França,\nSua semelhança, por não ser como o duque:\nAlém disso, aleguei vossas feições,\nRetrato fiel de vosso pai,\nTanto na forma quanto na nobreza de espírito;\nExpus todas as vossas vitórias na Escócia,\nVossa disciplina na guerra, sabedoria na paz,\nVossa generosidade, virtude, bela humildade;\nNa verdade, nada conveniente ao propósito deixei\nIntocado, ou levemente tratado, no discurso:\nE quando minha oratória chegou ao fim,\nPedi aos que amavam o bem de seu país\nQue gritassem “Deus guarde Richard, real rei da Inglaterra!”","gloucesterahanddidtheyso~gloucesterahanddidtheyso~24":"Gloucester — Ah! E o fizeram?","buckinghamnosogodhelpmetheyspakenotaword~nherebrakeoffandcameaway~622":"Buckingham — Não, Deus me ajude, não disseram palavra;\nMas, como estátuas mudas ou pedras que respiram,\nFitaram-se uns aos outros, e ficaram mortalmente pálidos.\nO que, quando vi, repreendi-os;\nE perguntei ao prefeito que significava esse silêncio obstinado:\nSua resposta foi que o povo não costumava\nSer falado senão pelo recorder.\nEntão foi instado a repetir meu discurso:\n“Assim diz o duque, assim concluiu o duque”;\nMas nada disse por autoridade própria.\nQuando terminou, alguns seguidores meus,\nNo fundo do salão, lançaram os chapéus ao ar,\nE uns dez vozes gritaram “Deus guarde o Rei Richard!”\nE assim aproveitei a vantagem desses poucos,\n“Obrigado, gentis cidadãos e amigos”, disse eu;\n“Este aplauso geral e brado afetuoso\nProva vossa sabedoria e vosso amor a Richard”:\nE aqui mesmo interrompi e vim embora.","gloucesterwhattonguelessblocksweretheywo~eretheywouldnottheyspeak~55":"Gloucester — Que blocos sem língua eram! Não queriam falar?","buckinghamnobymytrothmylord~kinghamnobymytrothmylord~27":"Buckingham — Não, por minha fé, senhor.","gloucesterwillnotthemayorthenandhisbreth~orthenandhisbrethrencome~47":"Gloucester — Não virão, então, o prefeito e seus irmãos?","buckinghamthemayorishereathandintendsome~tstillanswernayandtakeit~250":"Buckingham — O prefeito está à mão: fingi algum temor;\nNão vos deixeis falar senão a custo de grande instância:\nE cuidai de ter um livro de orações na mão,\nE de ficar entre dois clérigos, bom senhor;\nPois sobre esse fundamento construirei um canto sagrado:\nE não vos deixeis ganhar facilmente a nosso pedido:\nFazei o papel da donzela, respondei sempre não, e aceitai.","gloucesterigoandifyoupleadaswellforthema~wellbringittoahappyissue~97":"Gloucester — Vou; e se advogardes tão bem por eles\nComo eu sei dizer não a ti por mim mesmo,\nSem dúvida levaremos isto a um feliz desfecho.","buckinghamgogouptotheleadsthelordmayorkn~ayorknocksexitgloucester~58":"Buckingham — Ide, ide, para o terraço; o lorde prefeito bate. Sai Gloucester.","enterthemayorandcitizens~enterthemayorandcitizens~24":"Entram o Prefeito e os Cidadãos.","welcomemylordidanceattendancehereithinkt~dukewillnotbespokewithal~66":"Bem-vindo, senhor: aqui faço antecâmara;\nCreio que o duque não quer ser abordado.","herecomeshisservanthownowcatesbywhatsays~thownowcatesbywhatsayshe~42":"Eis seu servidor: então, Catesby,\nQue diz ele?","catesbymylordhedothentreatyourgracetovis~awhimfromhisholyexercise~181":"Catesby — Meu senhor, ele rogaria a vossa graça\nQue o visiteis amanhã ou depois de amanhã:\nEstá lá dentro, com dois reverendíssimos padres,\nDivinamente entregue à meditação;\nE nenhum pedido mundano o demoveria\nPara afastá-lo de seu santo exercício.","buckinghamreturngoodcatesbytothylordagai~meconferencewithhisgrace~181":"Buckingham — Volta, bom Catesby, a teu senhor;\nDize-lhe que eu mesmo, o prefeito e os cidadãos,\nEm graves desígnios e matérias de grande momento,\nDe importância não menor que nosso bem geral,\nViemos ter alguma conferência com sua graça.","catesbyilltellhimwhatyousaymylordexit~lhimwhatyousaymylordexit~37":"Catesby — Direi a ele o que dizeis, senhor. Sai.","buckinghamahhamylordthisprinceisnotanedw~earweshallneerwinhimtoit~329":"Buckingham — Ah, ha, senhor, este príncipe não é um Edward!\nNão está refestelado em leito de dia lascivo,\nMas de joelhos em meditação;\nNão se entretém com um par de cortesãs,\nMas medita com dois profundos teólogos;\nNão dorme, para engordar o corpo ocioso,\nMas reza, para enriquecer a alma vigilante:\nFeliz seria a Inglaterra, se este gracioso príncipe\nTomasse sobre si a soberania dela:\nMas, certo, receio que nunca o convenceremos a isso.","mayormarrygodforbidhisgraceshouldsayusna~idhisgraceshouldsayusnay~41":"Mayor — Ora, Deus não permita que sua graça nos diga não!","buckinghamifearhewill~buckinghamifearhewill~21":"Buckingham — Receio que dirá.","reentercatesby~reentercatesby~14":"Reentra Catesby.","hownowcatesbywhatsaysyourlord~wcatesbywhatsaysyourlord~29":"Então, Catesby, que diz vosso senhor?","catesbymylordhewonderstowhatendyouhaveas~efearsyoumeannogoodtohim~146":"Catesby — Meu senhor,\nEle se admira com que fim reunistes\nTais tropas de cidadãos para falar com ele,\nSua graça não tendo sido avisada antes:\nMeu senhor, ele teme que não lhe queirais bem.","buckinghamsorryiammynoblecousinshouldsus~etiszealouscontemplation~238":"Buckingham — Pesa-me que meu nobre primo\nSuspeite de mim, que não lhe quero bem:\nPelo céu, venho em perfeito amor por ele;\nE assim volta uma vez mais e diz a sua graça. Sai Catesby.\nQuando homens religiosos, santos e devotos,\nEstão com seus rosários, é difícil arrancá-los dali,\nTão doce é a contemplação fervorosa.","entergloucesteraloftbetweentwobishopscat~twobishopscatesbyreturns~51":"Entra Gloucester no alto, entre dois Bispos. Catesby volta.","mayorseewherehestandsbetweentwoclergymen~tandsbetweentwoclergymen~40":"Mayor — Vede, ali está ele entre dois clérigos!","buckinghamtwopropsofvirtueforachristianp~ionandrightchristianzeal~253":"Buckingham — Dois esteios de virtude para um príncipe cristão,\nPara sustê-lo contra a queda da vaidade:\nE vede, um livro de orações em sua mão,\nVerdadeiros ornamentos para se conhecer um santo homem.\nFamoso Plantageneta, graciosíssimo príncipe,\nEmprestai ouvidos favoráveis a nosso pedido;\nE perdoai-nos a interrupção\nDe vossa devoção e justo zelo cristão.","gloucestermylordthereneedsnosuchapologyi~whatisyourgracespleasure~164":"Gloucester — Meu senhor, não há necessidade de tal desculpa:\nAntes, rogo-vos que me perdoeis,\nEu que, empenhado no serviço de meu Deus,\nDescuido a visita de meus amigos.\nMas, deixando isto, qual é o desejo de vossa graça?","buckinghameventhatihopewhichpleasethgoda~odmenofthisungoverndisle~76":"Buckingham — Aquele mesmo, espero, que agrada a Deus no alto,\nE a todos os homens de bem desta ilha desgovernada.","gloucesteridosuspectihavedonesomeoffence~metoreprehendmyignorance~110":"Gloucester — Suspeito ter cometido alguma ofensa\nQue parece desgraciosa aos olhos da cidade,\nE que vindes repreender minha ignorância.","buckinghamyouhavemylordwoulditmightpleas~treatiestoamendthatfault~81":"Buckingham — Cometestes, meu senhor: prouvera a vossa graça,\nA nossos rogos, emendar essa falta!","gloucesterelsewhereforebreatheiinachrist~breatheiinachristianland~47":"Gloucester — Senão, por que respiro numa terra cristã?","buckinghamthenknowitisyourfaultthatyoure~suitcomeitomoveyourgrace~803":"Buckingham — Sabei, então, que é vossa falta que abdiqueis\nO assento supremo, o trono majestoso,\nO ofício de cetro de vossos ancestrais,\nVosso estado de fortuna e vosso direito de nascença,\nA glória hereditária de vossa casa real,\nÀ corrupção de um tronco manchado:\nEnquanto, na mansidão de vossos pensamentos sonolentos,\nQue aqui despertamos para o bem de nosso país,\nEsta nobre ilha carece de seus membros próprios;\nSeu rosto desfigurado por cicatrizes de infâmia,\nSeu tronco real enxertado de plantas ignóbeis,\nE quase lançada ao ombro no golfo devorador\nDo cego esquecimento e da obscura oblivião.\nPara sanar o que, solicitamos de coração\nQue vossa graciosa pessoa tome a seu cargo\nO governo régio desta vossa terra;\nNão como protetor, mordomo, substituto\nOu humilde feitor para ganho alheio;\nMas como sucessão de sangue em sangue,\nVosso direito de nascença, vosso império, vosso próprio.\nPor isso, em companhia dos cidadãos,\nVossos veneráveis e afetuosos amigos,\nE por sua veemente instigação,\nVenho eu a mover vossa graça neste justo pedido.","gloucesteriknownotwhethertodepartinsilen~dthatishouldwringfromhim~1049":"Gloucester — Não sei se partir em silêncio,\nOu falar com aspereza em vossa repreensão,\nMelhor convém a meu grau ou a vossa condição:\nSe não responder, poderíeis talvez pensar\nQue a ambição de língua atada, não respondendo, cedeu\nA suportar o jugo dourado da soberania,\nQue insensatamente quereríeis aqui impor-me;\nSe repreender-vos por este vosso pedido,\nTão temperado com vosso fiel amor por mim,\nEntão, por outro lado, eu censuraria meus amigos.\nPortanto, para falar, e evitar o primeiro,\nE depois, ao falar, não incorrer no último,\nRespondo-vos assim, de modo definitivo.\nVosso amor merece meu agradecimento; mas meu desmerecimento,\nIndigno, foge a vosso alto pedido.\nPrimeiro, se todos os obstáculos fossem removidos,\nE meu caminho fosse plano até a coroa,\nComo meu maduro rendimento e direito de nascença;\nAinda assim é tanta a minha pobreza de espírito,\nTão poderosas e tantas as minhas deficiências,\nQue antes me esconderia de minha grandeza,\nSendo uma barca que não suporta mar poderoso,\nDo que, em minha grandeza, cobiçar ser escondido,\nE no vapor de minha glória sufocado.\nMas, graças a Deus, não há necessidade de mim,\nE muito preciso para vos ajudar, se necessário fosse;\nA árvore real nos deixou fruto real,\nQue, amadurecido pelas horas furtivas do tempo,\nBem convirá ao assento da majestade,\nE nos fará, sem dúvida, felizes com seu reinado.\nA ele imponho o que quereis impor-me,\nO direito e a fortuna de suas ditosas estrelas;\nO que Deus defenda que eu lhe arranque!","buckinghammylordthisarguesconscienceinyo~alinealtruederivedcourse~863":"Buckingham — Meu senhor, isto revela consciência em vossa graça;\nMas os escrúpulos dela são melindrosos e triviais,\nBem consideradas todas as circunstâncias.\nDizeis que Edward é filho de vosso irmão:\nDizemos nós também, mas não da esposa de Edward;\nPois primeiro ele foi contratado com Lady Lucy —\nVossa mãe vive como testemunha desse voto —\nE depois, por procurador, prometido\nA Bona, irmã do Rei da França.\nPostos de lado ambos, uma pobre suplicante,\nUma mãe de muitos filhos, enlouquecida de cuidados,\nUma viúva aflita, de beleza declinante,\nJá na tarde de seus melhores dias,\nFeita presa e conquista de seu olho lascivo,\nSeduziu o tom e a altura de todos os seus pensamentos\nA baixa decadência e odiosa bigamia:\nDela, em seu leito ilegítimo, gerou\nEste Edward, a quem nossos costumes chamam de príncipe.\nMais amargamente poderia eu protestar,\nSe não fosse que, por reverência a alguns vivos,\nDou parco limite à minha língua.\nEntão, bom senhor, tomai para vossa real pessoa\nEste oferecido benefício de dignidade;\nSe não para nos abençoar e à terra também,\nAo menos para tirar vossa nobre ancestralidade\nDa corrupção de tempos abusivos\nE levá-la a um curso de linhagem direta e verdadeira.","mayordogoodmylordyourcitizensentreatyou~rdyourcitizensentreatyou~39":"Mayor — Fazei-o, bom senhor, vossos cidadãos vos rogam.","buckinghamrefusenotmightylordthisproffer~ghtylordthisprofferdlove~45":"Buckingham — Não recuseis, poderoso senhor, este amor oferecido.","catesbyomakethemjoyfulgranttheirlawfulsu~yfulgranttheirlawfulsuit~42":"Catesby — Ó, alegrai-os, concedei seu legítimo pedido!","gloucesteralaswhywouldyouheapthesecareso~notnoriwillnotyieldtoyou~124":"Gloucester — Ai, por que quereis amontoar estes cuidados sobre mim?\nSou inapto para o estado e a majestade:\nRogo-vos, não leveis a mal;\nNão posso nem quero ceder a vós.","buckinghamifyourefuseitasinloveandzeallo~nszoundsillentreatnomore~397":"Buckingham — Se o recusais — como, por amor e zelo,\nRelutante em depor a criança, filho de vosso irmão;\nComo bem sabemos vossa ternura de coração\nE gentil, bondoso, afeminado remorso,\nQue temos notado em vós para com vossos parentes,\nE igualmente, na verdade, para com todos os estados —\nContudo, aceiteis ou não nosso pedido,\nO filho de vosso irmão jamais reinará como nosso rei;\nMas plantaremos algum outro no trono,\nPara desgraça e queda de vossa casa:\nE nesta resolução aqui vos deixamos. —\nVamos, cidadãos: por Deus! Não rogarei mais.","gloucesterodonotswearmylordofbuckinghame~uckinghamwiththecitizens~68":"Gloucester — Ó, não jureis, meu lorde de Buckingham. Sai Buckingham com os Cidadãos.","catesbycallthemagainmylordandaccepttheir~mylordandaccepttheirsuit~44":"Catesby — Chamai-os de volta, senhor, e aceitai seu pedido.","anotherdogoodmylordlestallthelanddorueit~ordlestallthelanddorueit~40":"Another — Fazei-o, bom senhor, para que toda a terra não o lamente.","gloucesterwouldyouenforcemetoaworldofcar~nstmyconscienceandmysoul~141":"Gloucester — Quereis forçar-me a um mundo de cuidados?\nBem, chamai-os de volta. Não sou feito de pedra,\nMas penetrável a vossos bondosos rogos,\nEmbora contra minha consciência e minha alma.","reenterbuckinghamandtherest~nterbuckinghamandtherest~27":"Reentram Buckingham e os demais.","cousinofbuckinghamandyousagegravemensinc~riamfromthedesirethereof~334":"Primo de Buckingham, e vós, sábios e graves homens,\nJá que quereis afivelar a fortuna às minhas costas,\nPara levar-lhe o fardo, queira eu ou não,\nDevo ter paciência para suportar a carga:\nMas se negro escândalo ou rosto hediondo de censura\nAcompanharem a sequela de vossa imposição,\nVossa pura coação me absolverá\nDe todas as impuras nódoas e manchas dela;\nPois Deus o sabe, e vós em parte podeis ver,\nQuão longe estou do desejo disso.","mayorgodblessyourgraceweseeitandwillsayi~graceweseeitandwillsayit~41":"Mayor — Deus abençoe vossa graça! Nós o vemos e o diremos.","gloucesterinsayingsoyoushallbutsaythetru~soyoushallbutsaythetruth~42":"Gloucester — Dizendo-o, apenas direis a verdade.","buckinghamthenisaluteyouwiththiskinglyti~richardenglandsroyalking~75":"Buckingham — Então vos saúdo com este título régio:\nViva longamente Richard, real rei da Inglaterra!","mayorcitizensamen~mayorcitizensamen~17":"Mayor / Citizens — Amém.","buckinghamtomorrowwillitpleaseyoutobecro~illitpleaseyoutobecrownd~43":"Buckingham — Amanhã vos aprazerá ser coroado?","gloucesterevenwhenyoupleasesinceyouwillh~easesinceyouwillhaveitso~47":"Gloucester — Quando quiserdes, já que assim o desejais.","buckinghamtomorrowthenwewillattendyourgr~stjoyfullywetakeourleave~74":"Buckingham — Amanhã, então, atenderemos a vossa graça:\nE assim, muito alegres, nos despedimos.","gloucestercomeletustoourholytaskagainfar~ewellgentlefriendsexeunt~82":"Gloucester — Vinde, voltemos à nossa santa tarefa.\nAdeus, bom primo; adeus, gentis amigos. Saem."}$tr$::jsonb, 776)
