insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_romeo-and-juliet', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","veronaapublicplace~veronaapublicplace~18":"Verona. Um lugar público.","entersampsonandgregoryofthehouseofcapule~medwithswordsandbucklers~67":"Entram Sansão e Gregório, da casa dos Capuleto, armados de espadas e escudos.","sampsongregoryomywordwellnotcarrycoals~omywordwellnotcarrycoals~38":"SANSÃO — Gregório, palavra minha, não vamos carregar carvão.","gregorynoforthenweshouldbecolliers~orthenweshouldbecolliers~34":"GREGÓRIO — Não, pois então seríamos carvoeiros.","sampsonimeananwebeincholerwelldraw~ananwebeincholerwelldraw~34":"SANSÃO — Quero dizer, se nos irarmos, sacaremos da espada.","gregoryaywhileyoulivedrawyourneckoutothe~rawyourneckoutothecollar~46":"GREGÓRIO — Sim, enquanto viveres, tira o pescoço da coleira.","sampsonistrikequicklybeingmoved~istrikequicklybeingmoved~31":"SANSÃO — Firo depressa, quando me provocam.","gregorybutthouartnotquicklymovedtostrike~tnotquicklymovedtostrike~40":"GREGÓRIO — Mas não és depressa provocado a ferir.","sampsonadogofthehouseofmontaguemovesme~hehouseofmontaguemovesme~38":"SANSÃO — Um cão da casa dos Montéquio me provoca.","gregorytomoveistostirandtobevaliantistos~ouartmovedthourunnstaway~81":"GREGÓRIO — Provocar é mover-se; e ser valente é manter-se firme: portanto, se és provocado, foges.","sampsonadogofthathouseshallmovemetostand~fanymanormaidofmontagues~81":"SANSÃO — Um cão daquela casa me fará ficar firme: tomarei o lado da parede de qualquer homem ou donzela dos Montéquio.","gregorythatshowstheeaweakslavefortheweak~rtheweakestgoestothewall~56":"GREGÓRIO — Isso mostra que és um escravo fraco; pois o mais fraco vai de encontro à parede.","sampsontrueandthereforewomenbeingtheweak~dthrusthismaidstothewall~138":"SANSÃO — É verdade; e por isso as mulheres, sendo os vasos mais frágeis, são sempre empurradas contra a parede: portanto empurrarei os homens dos Montéquio para longe da parede, e empurrarei suas donzelas contra a parede.","gregorythequarrelisbetweenourmastersandu~nourmastersandustheirmen~49":"GREGÓRIO — A briga é entre nossos amos e nós, seus criados.","sampsontisalloneiwillshowmyselfatyrantwh~maidsandcutofftheirheads~106":"SANSÃO — Tanto faz, mostrar-me-ei um tirano: quando tiver lutado com os homens, serei cruel com as donzelas e lhes cortarei as cabeças.","gregorytheheadsofthemaids~regorytheheadsofthemaids~25":"GREGÓRIO — As cabeças das donzelas?","sampsonaytheheadsofthemaidsortheirmaiden~akeitinwhatsensethouwilt~70":"SANSÃO — Sim, as cabeças das donzelas, ou suas donzelices; toma no sentido que quiseres.","gregorytheymusttakeitinsensethatfeelit~ttakeitinsensethatfeelit~38":"GREGÓRIO — Hão de tomar no sentido as que o sentirem.","sampsonmetheyshallfeelwhileiamabletostan~wniamaprettypieceofflesh~74":"SANSÃO — A mim hão de sentir enquanto eu puder me manter em pé: e é sabido que sou um belo pedaço de carne.","gregorytiswellthouartnotfishifthouhadstt~ofthehouseofthemontagues~107":"GREGÓRIO — É bom que não sejas peixe; se fosses, serias um pobre bacalhau. Saca a tua ferramenta; aí vêm dois da casa dos Montéquio.","sampsonmynakedweaponisoutquarreliwillbac~soutquarreliwillbackthee~45":"SANSÃO — Minha arma nua já está fora: puxa a briga, eu te apoiarei.","gregoryhowturnthybackandrun~goryhowturnthybackandrun~27":"GREGÓRIO — Como! Virar as costas e correr?","sampsonfearmenot~sampsonfearmenot~16":"SANSÃO — Não me temas.","gregorynomarryifearthee~gregorynomarryifearthee~23":"GREGÓRIO — Não, por Nossa Senhora; eu, temer-te!","sampsonletustakethelawofoursidesletthemb~awofoursidesletthembegin~44":"SANSÃO — Fiquemos com a lei do nosso lado; deixemos que eles comecem.","gregoryiwillfrownasipassbyandletthemtake~dletthemtakeitastheylist~52":"GREGÓRIO — Franzirei o cenho ao passar, e que o tomem como quiserem.","sampsonnayastheydareiwillbitemythumbatth~sgracetothemiftheybearit~76":"SANSÃO — Não, como ousarem. Morderei o polegar para eles; o que é uma afronta, se a aguentarem.","enterabrahamandbalthasar~enterabrahamandbalthasar~24":"Entram Abraão e Baltasar.","abrahamdoyoubiteyourthumbatussir~oyoubiteyourthumbatussir~32":"ABRAÃO — Mordeis o polegar para nós, senhor?","sampsonidobitemythumbsir~sampsonidobitemythumbsir~24":"SANSÃO — Eu mordo o polegar, senhor.","sampsonasidetogregoryisthelawofoursideif~sthelawofoursideifisayay~46":"SANSÃO — À parte, a Gregório. A lei está do nosso lado, se eu disser que sim?","gregoryno~gregoryno~9":"GREGÓRIO — Não.","sampsonnosiridonotbitemythumbatyousirbut~yousirbutibitemythumbsir~55":"SANSÃO — Não, senhor, não mordo o polegar para vós, senhor, mas mordo o polegar, senhor.","gregorydoyouquarrelsir~gregorydoyouquarrelsir~22":"GREGÓRIO — Quereis briga, senhor?","abrahamquarrelsirnosir~abrahamquarrelsirnosir~22":"ABRAÃO — Briga, senhor! Não, senhor.","sampsonifyoudosiriamforyouiserveasgoodam~youiserveasgoodamanasyou~47":"SANSÃO — Se quereis, senhor, estou às vossas ordens: sirvo a um homem tão bom quanto o vosso.","abrahamnobetter~abrahamnobetter~15":"ABRAÃO — Não melhor.","sampsonwellsir~sampsonwellsir~14":"SANSÃO — Pois bem, senhor.","gregorysaybetterherecomesoneofmymastersk~mesoneofmymasterskinsmen~46":"GREGÓRIO — Diz “melhor”: aí vem um parente do meu amo.","sampsonyesbettersir~sampsonyesbettersir~19":"SANSÃO — Sim, melhor, senhor.","abrahamyoulie~abrahamyoulie~13":"ABRAÃO — Mentis.","sampsondrawifyoubemengregoryrememberthys~thyswashingblowtheyfight~60":"SANSÃO — Sacai, se sois homens. Gregório, lembra-te do teu golpe de arrasar. Lutam.","enterbenvolio~enterbenvolio~13":"Entra Benvólio.","benvoliopartfoolsputupyourswordsyouknown~oudobeatsdowntheirswords~71":"BENVÓLIO — Separai, tolos! \n Embainhai as espadas; não sabeis o que fazeis. Abate-lhes as espadas.","entertybalt~entertybalt~11":"Entra Teobaldo.","tybaltwhatartthoudrawnamongtheseheartles~benvoliolookuponthydeath~78":"TEOBALDO — Que, tu, sacado entre estes covardes servos? \n Volta-te, Benvólio, e olha a tua morte.","benvolioidobutkeepthepeaceputupthyswordo~geittopartthesemenwithme~69":"BENVÓLIO — Só mantenho a paz: embainha a tua espada, \n ou usa-a para ajudar-me a separar estes homens.","tybaltwhatdrawnandtalkofpeaceihatethewor~aveattheecowardtheyfight~96":"TEOBALDO — Que, sacado e a falar de paz! Odeio a palavra, \n como odeio o inferno, todos os Montéquio, e a ti: \n Em guarda, covarde! Lutam.","enterseveralofbothhouseswhojointhefrayth~enentercitizenswithclubs~64":"Entram vários de ambas as casas, que se juntam à briga; depois entram Cidadãos, com porretes.","firstcitizenclubsbillsandpartisansstrike~letsdownwiththemontagues~91":"PRIMEIRO CIDADÃO — Porretes, alabardas e partasanas! Batei! Abatei-os! \n Abaixo os Capuleto! Abaixo os Montéquio!","entercapuletinhisgownandladycapulet~tinhisgownandladycapulet~35":"Entram Capulet, de roupão, e Lady Capulet.","capuletwhatnoiseisthisgivememylongswordh~sthisgivememylongswordho~41":"Capulet — Que barulho é esse? Dai-me minha espada longa, ó!","ladycapuletacrutchacrutchwhycallyouforas~rutchwhycallyouforasword~44":"Lady Capulet — Uma muleta, uma muleta! Por que pedis espada?","capuletmyswordisayoldmontagueiscomeandfl~isheshisbladeinspiteofme~67":"Capulet — Minha espada, digo! O velho Montague chegou,\nE brande a lâmina para me afrontar.","entermontagueandladymontague~rmontagueandladymontague~28":"Entram Montague e Lady Montague.","montaguethouvillaincapuletholdmenotletme~ncapuletholdmenotletmego~42":"Montague — Vilão Capulet! — Não me segureis, deixai-me ir.","ladymontaguethoushaltnotstirafoottoseeka~ltnotstirafoottoseekafoe~43":"Lady Montague — Não darás um passo em busca de um inimigo.","enterprincewithattendants~nterprincewithattendants~25":"Entra o Príncipe, com Criados.","princerebellioussubjectsenemiestopeacepr~eladymontagueandbenvolio~824":"Prince — Súditos rebeldes, inimigos da paz,\nProfanadores deste aço manchado de sangue vizinho —\nNão querem ouvir? Ei, vós, homens, vós, feras,\nQue apagais o fogo de vossa raiva perniciosa\nCom fontes purpúreas jorradas de vossas veias,\nSob pena de tortura, dessas mãos sangrentas\nLançai ao chão vossas armas mal temperadas,\nE ouvi a sentença de vosso príncipe irado.\nTrês brigas civis, nascidas de uma palavra ao vento,\nPor ti, velho Capulet, e por Montague,\nTrês vezes perturbaram o sossego de nossas ruas\nE fizeram os anciãos de Verona\nPôr de lado seus graves ornamentos decentes\nPara empunhar velhas partasanas em mãos igualmente velhas,\nEnferrujadas de paz, para apartar vosso ódio corroído:\nSe jamais perturbardes de novo nossas ruas,\nVossas vidas pagarão a multa da paz.\nPor esta vez, todos os demais se retirem:\nTu, Capulet, virás comigo:\nE tu, Montague, vem esta tarde,\nPara saber nossa ulterior vontade neste caso,\nÀ velha Vila-Franca, nosso lugar comum de julgamento.\nMais uma vez, sob pena de morte, todos se retirem. Saem todos, exceto Montague, Lady Montague e Benvolio.","montaguewhosetthisancientquarrelnewabroa~phewwereyoubywhenitbegan~73":"Montague — Quem reabriu esta antiga querela?\nFalai, sobrinho, estáveis presente quando começou?","benvoliohereweretheservantsofyouradversa~ecamewhopartedeitherpart~356":"Benvolio — Aqui estavam os criados de vosso adversário\nE os vossos, lutando de perto, antes que eu chegasse:\nSaquei para apartá-los: no instante chegou\nO fogoso Tybalt, de espada em punho,\nQue, enquanto me soprava desafios aos ouvidos,\nGirava sobre a cabeça e fendia os ventos,\nQue, sem dano algum, silvavam-lhe em desdém:\nEnquanto trocávamos estocadas e golpes,\nVieram mais e mais, e lutaram de um lado e de outro,\nAté que veio o príncipe, que separou ambos os lados.","ladymontagueowhereisromeosawyouhimtodayr~ladiamhewasnotatthisfray~69":"Lady Montague — Ó, onde está Romeo? Vistes-o hoje?\nMuito me alegra que não estivesse nesta contenda.","benvoliomadamanhourbeforetheworshippdsun~hunndwhogladlyfledfromme~392":"Benvolio — Senhora, uma hora antes que o adorado sol\nEspiasse pela dourada janela do oriente,\nUm espírito perturbado me levou a passear fora;\nOnde, sob o bosque de sicômoros\nQue cresce a oeste, junto à cidade,\nTão cedo caminhando vi vosso filho:\nDirigi-me a ele, mas ele me percebeu\nE esgueirou-se para o abrigo da mata:\nEu, medindo suas afeições pelas minhas,\nQue mais se ocupam quando mais estão a sós,\nSegui meu humor sem perseguir o dele,\nE de bom grado evitei quem de bom grado fugiu de mim.","montaguemanyamorninghathhetherebeenseenw~counselmaythecauseremove~418":"Montague — Muitas manhãs foi ele visto ali,\nCom lágrimas aumentando o orvalho fresco da manhã,\nJuntando às nuvens mais nuvens com seus fundos suspiros;\nMas tão logo o sol, que a todos alegra,\nNo mais distante oriente começa a puxar\nAs sombrias cortinas do leito de Aurora,\nPara longe da luz furta-se para casa meu pesaroso filho,\nE a sós em seu quarto se encerra,\nFecha as janelas, tranca fora a bela luz do dia\nE faz para si uma noite artificial:\nNegro e agourento há de se mostrar esse humor,\nA menos que bom conselho lhe remova a causa.","benvoliomynobleuncledoyouknowthecause~leuncledoyouknowthecause~37":"Benvolio — Nobre tio, conheceis a causa?","montagueineitherknowitnorcanlearnofhim~erknowitnorcanlearnofhim~38":"Montague — Nem a conheço, nem posso sabê-la dele.","benvoliohaveyouimportunedhimbyanymeans~uimportunedhimbyanymeans~38":"Benvolio — Importunastes-o por algum meio?","montaguebothbymyselfandmanyotherfriendsb~swillinglygivecureasknow~322":"Montague — Tanto eu mesmo quanto muitos outros amigos:\nMas ele, conselheiro de suas próprias afeições,\nÉ para si — não direi quão fiel —\nMas para si tão secreto e fechado,\nTão distante de sondagem e descoberta,\nComo o botão mordido por um verme invejoso\nAntes que possa abrir suas doces folhas ao ar\nOu dedicar sua beleza ao sol.\nSe ao menos soubéssemos de onde brotam suas mágoas,\nTão de bom grado daríamos a cura quanto a saberíamos.","enterromeo~enterromeo~10":"Entra Romeu.","benvolioseewherehecomessopleaseyoustepas~sgrievanceorbemuchdenied~76":"Benvolio — Vede, ali vem ele: se vos apraz, afastai-vos;\nSaberei sua queixa, ou serei muito recusado.","montagueiwouldthouwertsohappybythystayto~wayexeuntmontagueandlady~92":"Montague — Quisera que fosses tão feliz em ficar\nQue ouvisses boa confissão. Vamos, senhora, partamos. Saem Montague e Lady.","benvoliogoodmorrowcousin~benvoliogoodmorrowcousin~24":"Benvolio — Bom dia, primo.","romeoisthedaysoyoung~romeoisthedaysoyoung~20":"Romeo — O dia é tão jovem?","benvoliobutnewstrucknine~benvoliobutnewstrucknine~24":"Benvolio — Acabam de bater nove.","romeoaymesadhoursseemlongwasthatmyfather~atherthatwenthencesofast~59":"Romeo — Ai de mim! Horas tristes parecem longas.\nEra meu pai que saiu daqui tão depressa?","benvolioitwaswhatsadnesslengthensromeosh~nesslengthensromeoshours~44":"Benvolio — Era. Que tristeza alonga as horas de Romeo?","romeonothavingthatwhichhavingmakesthemsh~hichhavingmakesthemshort~43":"Romeo — Não ter aquilo que, tendo, as faz curtas.","benvolioinlove~benvolioinlove~14":"Benvolio — Apaixonado?","romeoout~romeoout~8":"Romeo — Fora —","benvoliooflove~benvoliooflove~14":"Benvolio — Do amor?","romeooutofherfavourwhereiaminlove~fherfavourwhereiaminlove~33":"Romeo — Fora do favor dela, onde estou apaixonado.","benvolioalasthatlovesogentleinhisviewsho~tyrannousandroughinproof~71":"Benvolio — Ai, que o amor, tão gentil à vista,\nSeja tão tirânico e áspero na prova!","romeoalasthatlovewhoseviewismuffledstill~veinthisdostthounotlaugh~421":"Romeo — Ai, que o amor, cuja vista é sempre vendada,\nSem olhos veja caminhos para sua vontade!\nOnde jantaremos? Ai de mim! Que briga houve aqui?\nMas não me digas, pois ouvi tudo.\nHá aqui muito que ver com o ódio, mas mais com o amor.\nOra, então, ó amor brigão! Ó ódio amoroso!\nÓ tudo, criado primeiro do nada!\nÓ leveza pesada! Seriedade vã!\nCaos disforme de formas de boa aparência!\nPluma de chumbo, fumaça luminosa, fogo frio, saúde doente!\nSono sempre desperto, que não é o que é!\nEste amor sinto eu, que nenhum amor sinto nisto.\nNão ris?","benvolionocoziratherweep~benvolionocoziratherweep~24":"Benvolio — Não, primo, antes choro.","romeogoodheartatwhat~romeogoodheartatwhat~20":"Romeo — Bom coração, de quê?","benvolioatthygoodheartsoppression~tthygoodheartsoppression~33":"Benvolio — Da opressão de teu bom coração.","romeowhysuchislovestransgressiongriefsof~ervingsweetfarewellmycoz~359":"Romeo — Ora, tal é a transgressão do amor.\nMágoas minhas pesam em meu peito,\nQue tu propagarás, ao querer vê-lo premido\nCom mais das tuas: este amor que mostraste\nSoma mais dor à demasiada que é minha.\nO amor é uma fumaça erguida com o vapor de suspiros;\nPurgado, um fogo faiscando nos olhos dos amantes;\nVexado, um mar nutrido de lágrimas de amantes:\nQue mais é? Uma loucura discretíssima,\nUm fel sufocante e uma doçura que conserva.\nAdeus, meu primo.","benvoliosoftiwillgoalonganifyouleavemeso~youleavemesoyoudomewrong~52":"Benvolio — Calma! Irei contigo;\nSe me deixas assim, ofendes-me.","romeotutihavelostmyselfiamnotherethisisn~otromeohessomeotherwhere~64":"Romeo — Ora, perdi-me a mim mesmo; não estou aqui;\nEste não é Romeo, ele está noutro lugar.","benvoliotellmeinsadnesswhoisthatyoulove~nsadnesswhoisthatyoulove~39":"Benvolio — Dize-me com seriedade quem é a que amas.","romeowhatshalligroanandtellthee~atshalligroanandtellthee~31":"Romeo — Quê, hei de gemer e dizer-te?","benvoliogroanwhynobutsadlytellmewho~anwhynobutsadlytellmewho~35":"Benvolio — Gemer! Ora, não;\nMas dize-me sério quem.","romeobidasickmaninsadnessmakehiswillahwo~dnesscousinidoloveawoman~94":"Romeo — Manda um doente fazer testamento com seriedade:\nAh, palavra mal empregada a quem está tão mal!\nCom seriedade, primo, amo uma mulher.","benvolioiaimdsonearwhenisupposedyouloved~earwhenisupposedyouloved~40":"Benvolio — Mirei bem perto, quando supus que amavas.","romeoarightgoodmarkmanandshesfairilove~dmarkmanandshesfairilove~38":"Romeo — Ótimo atirador! E é bela a que amo.","benvolioarightfairmarkfaircozissoonesthi~rmarkfaircozissoonesthit~41":"Benvolio — Um belo alvo, belo primo, é o mais depressa atingido.","romeowellinthathityoumissshellnotbehitwi~eswithbeautydiesherstore~304":"Romeo — Bem, nesse tiro erras: ela não será atingida\nPela flecha de Cupido; tem o engenho de Diana;\nE, bem armada com a forte couraça da castidade,\nDo fraco arco pueril do amor vive ilesa.\nNão suportará o cerco de termos amorosos,\nNem resistirá ao encontro de olhos assaltantes,\nNem abrirá o regaço a ouro que seduz santos:\nÓ, é rica em beleza, só é pobre\nEm que, quando ela morre, com a beleza morre sua riqueza.","benvoliothenshehathswornthatshewillstill~atshewillstilllivechaste~50":"Benvolio — Então jurou que viverá sempre casta?","romeoshehathandinthatsparingmakeshugewas~edeadthatlivetotellitnow~226":"Romeo — Jurou, e nessa parcimônia faz enorme desperdício,\nPois a beleza, esfomeada pela severidade dela,\nCorta a beleza de toda a posteridade.\nÉ bela demais, sábia demais, sabiamente bela demais,\nPara merecer a bem-aventurança fazendo-me desesperar:\nJurou renunciar ao amor, e nesse voto\nVivo morto eu, que vivo para contá-lo agora.","benvolioberuledbymeforgettothinkofher~edbymeforgettothinkofher~37":"Benvolio — Deixa-te guiar por mim, esquece de pensar nela.","romeooteachmehowishouldforgettothink~ehowishouldforgettothink~36":"Romeo — Ó, ensina-me como esquecer de pensar.","benvoliobygivinglibertyuntothineeyesexam~eyesexamineotherbeauties~56":"Benvolio — Dando liberdade a teus olhos;\nExamina outras belezas.","romeotisthewaytocallhersexquisiteinquest~ucanstnotteachmetoforget~325":"Romeo — Esse é o caminho\nPara tornar a dela mais requintada, ao pô-la em questão:\nEstas máscaras felizes que beijam a fronte de belas damas,\nSendo negras, lembram-nos que escondem o belo;\nQuem foi ferido de cegueira não pode esquecer\nO precioso tesouro da vista perdida:\nMostra-me uma senhora de beleza sem par,\nPara que serve sua beleza, senão como uma nota\nOnde eu possa ler quem superou aquela beleza sem par?\nAdeus: não podes ensinar-me a esquecer.","benvolioillpaythatdoctrineorelsedieindeb~ineorelsedieindebtexeunt~47":"Benvolio — Pagarei essa lição, ou morrerei em dívida. Saem.","sceneii~sceneii~7":"Cena II","astreet~astreet~7":"Uma rua.","entercapuletparisandservant~ercapuletparisandservant~27":"Entram Capulet, Paris e um Criado.","capuletbutmontagueisboundaswellasiinpena~nsooldaswetokeepthepeace~96":"Capulet — Mas Montague está obrigado tanto quanto eu,\nSob igual pena; e não é difícil, penso,\nPara homens tão velhos como nós, guardar a paz.","parisofhonourablereckoningareyoubothandp~mylordwhatsayyoutomysuit~96":"Paris — De honrada reputação sois ambos;\nE é pena que tanto tempo tenhais vivido em discórdia.\nMas agora, senhor, que dizeis de minha pretensão?","capuletbutsayingoerwhatihavesaidbeforemy~aythinkherripetobeabride~172":"Capulet — Apenas repito o que já disse antes:\nMinha filha ainda é estranha ao mundo;\nNão viu a passagem de catorze anos;\nDeixemos murchar mais dois verões em seu esplendor\nAntes de julgá-la madura para ser noiva.","parisyoungerthanshearehappymothersmade~anshearehappymothersmade~38":"Paris — Mais jovens que ela são feitas mães felizes.","capuletandtoosoonmarrdarethosesoearlymad~tayexeuntcapuletandparis~884":"Capulet — E cedo demais estragadas as que tão cedo se fazem.\nA terra engoliu todas as minhas esperanças, exceto ela,\nEla é a esperançosa senhora de minha terra:\nMas corteja-a, gentil Paris, ganha-lhe o coração,\nMinha vontade é só uma parte de seu consentimento;\nSe ela concordar, dentro do âmbito de sua escolha\nEstarão meu consentimento e meu voto de bom grado.\nEsta noite dou uma antiga festa costumeira,\nPara a qual convidei muitos hóspedes,\nDos que amo; e tu, entre a multidão,\nMais um, muito bem-vindo, aumenta meu número.\nEm minha pobre casa espera ver esta noite\nEstrelas que pisam a terra e iluminam o céu escuro:\nTal conforto como sentem os jovens vigorosos\nQuando abril, bem trajado, no encalço\nDo inverno manco pisa, tal deleite\nEntre frescos botões femininos desfrutarás esta noite\nEm minha casa; ouve a todas, vê a todas,\nE gosta mais da que mais mérito tiver:\nDentre as quais, à vista de muitas, minha filha sendo uma,\nPode contar-se no número, embora em valor nenhuma.\nVem, vai comigo. Ao Criado, dando-lhe um papel. Vai, rapaz, corre\nPor toda a bela Verona; encontra as pessoas\nCujos nomes aqui estão escritos, e dize-lhes\nQue minha casa e boas-vindas aguardam seu prazer. Saem Capulet e Paris.","servantfindthemoutwhosenamesarewrittenhe~sttothelearnedingoodtime~289":"Servant — Encontrar aqueles cujos nomes aqui estão escritos! Está escrito que o sapateiro se meta com sua régua e o alfaiate com sua forma, o pescador com seu pincel e o pintor com suas redes; mas eu sou mandado encontrar as pessoas cujos nomes aqui estão escritos, e nunca consigo achar que nomes a pessoa escrevente aqui escreveu. Devo ir aos letrados. — Em boa hora.","enterbenvolioandromeo~enterbenvolioandromeo~21":"Entram Benvolio e Romeo.","benvoliotutmanonefireburnsoutanothersbur~ankpoisonoftheoldwilldie~217":"Benvolio — Ora, homem, um fogo apaga a queima de outro,\nUma dor se alivia com a angústia de outra;\nGira até a tontura, e a cura vem do giro inverso;\nUma mágoa desesperada se cura com o definhar de outra:\nToma alguma nova infecção para o olho,\nE o veneno rançoso da velha morrerá.","romeoyourplantainleafisexcellentforthat~inleafisexcellentforthat~39":"Romeo — Tua folha de tanchagem é excelente para isso.","benvolioforwhatipraythee~benvolioforwhatipraythee~24":"Benvolio — Para quê, peço-te?","romeoforyourbrokenshin~romeoforyourbrokenshin~22":"Romeo — Para tua canela quebrada.","benvoliowhyromeoartthoumad~nvoliowhyromeoartthoumad~26":"Benvolio — Ora, Romeo, estás louco?","romeonotmadbutboundmorethanamadmanisshut~entedandgoddengoodfellow~104":"Romeo — Louco não, mas mais atado que um louco;\nTrancado em prisão, mantido sem comida,\nAçoitado e atormentado e — boa tarde, bom homem.","servantgodgigoddenipraysircanyouread~goddenipraysircanyouread~36":"Servant — Deus vos dê boa tarde. Peço-vos, senhor, sabeis ler?","romeoaymineownfortuneinmymisery~mineownfortuneinmymisery~31":"Romeo — Sim, a minha própria sorte em minha miséria.","servantperhapsyouhavelearneditwithoutboo~canyoureadanythingyousee~73":"Servant — Talvez a tenhais aprendido sem livro: mas, peço-vos, sabeis ler qualquer coisa que vejais?","romeoayifiknowthelettersandthelanguage~thelettersandthelanguage~38":"Romeo — Sim, se conheço as letras e a língua.","servantyesayhonestlyrestyoumerry~esayhonestlyrestyoumerry~32":"Servant — Falais honestamente: ficai com Deus!","romeostayfellowicanreadreadssigniormarti~blywhithershouldtheycome~334":"Romeo — Espera, camarada; sei ler. Lê. “Signor Martino e sua esposa e filhas; o Conde Anselme e suas belas irmãs; a senhora viúva de Vitruvio; Signor Placentio e suas amáveis sobrinhas; Mercutio e seu irmão Valentine; meu tio Capulet, sua esposa e filhas; minha bela sobrinha Rosaline; Livia; Signor Valentio e seu primo Tybalt; Lucio e a animada Helena.” Bela assembleia: aonde devem vir?","servantup~servantup~9":"Servant — Lá em cima.","romeowhither~romeowhither~12":"Romeo — Aonde?","servanttosuppertoourhouse~ervanttosuppertoourhouse~25":"Servant — Para a ceia; em nossa casa.","romeowhosehouse~romeowhosehouse~15":"Romeo — De quem a casa?","servantmymasters~servantmymasters~16":"Servant — De meu amo.","romeoindeedishouldhaveaskdyouthatbefore~uldhaveaskdyouthatbefore~39":"Romeo — Na verdade, eu deveria ter perguntado isso antes.","servantnowilltellyouwithoutaskingmymaste~upofwinerestyoumerryexit~139":"Servant — Agora direi sem perguntardes: meu amo é o grande e rico Capulet; e se não sois da casa dos Montagues, peço-vos, vinde e esvaziai uma taça de vinho. Ficai com Deus! Sai.","benvolioatthissameancientfeastofcapulets~aketheethinkthyswanacrow~207":"Benvolio — Nesta mesma antiga festa de Capulet\nCeia a bela Rosaline que tanto amas,\nCom todas as admiradas beldades de Verona:\nVai lá; e, com olhar imaculado,\nCompara-lhe o rosto com alguns que te mostrarei,\nE farei com que penses que teu cisne é um corvo.","romeowhenthedevoutreligionofmineeyemaint~hsincefirsttheworldbegun~218":"Romeo — Quando a devota religião de meus olhos\nSustentar tal falsidade, que as lágrimas se tornem fogos;\nE estes, que muitas vezes afogados nunca puderam morrer,\nHereges transparentes, sejam queimados por mentirosos!\nAlguém mais bela que meu amor! O sol que tudo vê\nNunca viu seu par desde que o mundo começou.","benvoliotutyousawherfairnoneelsebeingbyh~showwellthatnowshowsbest~219":"Benvolio — Ora, viste-a bela, não havendo outra por perto,\nEla equilibrada consigo mesma em cada olho:\nMas nessa balança de cristal sejam pesados\nO amor de tua dama contra o de alguma outra donzela\nQue te mostrarei brilhando nesta festa,\nE a que agora parece melhor mal parecerá bem.","romeoillgoalongnosuchsighttobeshownbutto~splendourofmineownexeunt~73":"Romeo — Irei contigo, não para ver tal visão,\nMas para me regozijar com o esplendor da minha. Saem.","sceneiii~sceneiii~8":"Cena III","aroomincapuletshouse~aroomincapuletshouse~20":"Um aposento na casa dos Capuletos.","enterladycapuletandnurse~enterladycapuletandnurse~24":"Entram Lady Capulet e a Ama.","ladycapuletnursewheresmydaughtercallherf~daughtercallherforthtome~48":"Lady Capulet — Ama, onde está minha filha? Chama-a a mim.","nursenowbymymaidenheadattwelveyearoldiba~wheresthisgirlwhatjuliet~102":"Nurse — Pois, por minha donzelice, aos doze anos,\nMandei-a vir. Ora, cordeirinha! Ora, joaninha!\nDeus me livre! Onde está esta menina? Ora, Juliet!","enterjuliet~enterjuliet~11":"Entra Julieta.","juliethownowwhocalls~juliethownowwhocalls~20":"Juliet — Então! Quem chama?","nurseyourmother~nurseyourmother~15":"Nurse — Vossa mãe.","julietmadamiamherewhatisyourwill~damiamherewhatisyourwill~32":"Juliet — Senhora, aqui estou.\nQual é vossa vontade?","ladycapuletthisisthematternursegiveleave~tmydaughtersofaprettyage~150":"Lady Capulet — É o seguinte: — Ama, dá-nos licença um instante,\nTemos de falar em segredo: — ama, volta de novo;\nLembrei-me, ouvirás nosso conselho.\nSabes que minha filha está numa bela idade.","nursefaithicantellherageuntoanhour~icantellherageuntoanhour~34":"Nurse — Por minha fé, sei dizer-lhe a idade até a hora.","ladycapuletshesnotfourteen~dycapuletshesnotfourteen~26":"Lady Capulet — Não tem catorze.","nurseilllayfourteenofmyteethandyettomyte~wlongisitnowtolammastide~106":"Nurse — Aposto catorze dos meus dentes —\nE contudo, para minha mágoa seja dito, só tenho quatro —\nEla não tem catorze. Quanto falta agora\nPara o dia de Lammas?","ladycapuletafortnightandodddays~uletafortnightandodddays~31":"Lady Capulet — Uma quinzena e uns dias.","nurseevenoroddofalldaysintheyearcomelamm~tyfoolitstintedandsaiday~1069":"Nurse — Par ou ímpar, de todos os dias do ano,\nNa véspera de Lammas, à noite, ela fará catorze.\nSusan e ela — Deus dê descanso a todas as almas cristãs! —\nEram da mesma idade: bem, Susan está com Deus;\nEra boa demais para mim: mas, como eu dizia,\nNa véspera de Lammas, à noite, fará catorze;\nFará, por certo; lembro-me bem.\nFaz onze anos agora do terremoto;\nE ela foi desmamada — nunca o esquecerei —\nDe todos os dias do ano, justamente nesse dia:\nPois eu tinha passado losna no meu peito,\nSentada ao sol sob o muro do pombal;\nMeu senhor e vós estáveis então em Mântua: —\nNão, tenho boa cabeça: — mas, como dizia,\nQuando ela provou a losna no bico\nDo meu peito e o sentiu amargo, a doce tolinha,\nVer como ficou irritada e brigou com o peito!\n“Treme”, disse o pombal: não foi preciso, creio,\nMandar-me correr:\nE desde então fazem onze anos;\nPois então ela já ficava de pé sozinha; não, pela cruz,\nPodia correr e bamboleiar por toda parte;\nPois no dia anterior mesmo, quebrou a testa:\nE então meu marido — Deus esteja com sua alma!\nEra um homem alegre — pegou a criança:\n“Ora”, disse ele, “caíste de cara?\nCairás de costas quando tiveres mais juízo;\nNão cairás, Julinha?” e, por minha santa dama,\nA doce pestinha parou de chorar e disse “Sim.”\nVer agora como uma pilhéria pode se cumprir!\nGaranto, ainda que eu viva mil anos,\nNunca o esquecerei: “Não cairás, Julinha?”, disse ele;\nE, doce tolinha, calou-se e disse “Sim.”","ladycapuletenoughofthisipraytheeholdthyp~hisipraytheeholdthypeace~44":"Lady Capulet — Basta disso; peço-te, cala-te.","nurseyesmadamyeticannotchoosebutlaughtot~otjuleitstintedandsaiday~270":"Nurse — Sim, senhora: contudo não posso deixar de rir,\nAo pensar que parou de chorar e disse “Sim.”\nE contudo, garanto, tinha na testa\nUm calombo grande como testículo de frango novo;\nUma pancada perigosa; e chorou amargamente:\n“Ora”, disse meu marido, “caíste de cara?\nCairás de costas quando chegares à idade;\nNão cairás, Julinha?” calou-se e disse “Sim.”","julietandstintthoutooipraytheenursesayi~houtooipraytheenursesayi~39":"Juliet — E cala-te tu também, peço-te, ama, digo eu.","nursepeaceihavedonegodmarktheetohisgrace~eemarriedonceihavemywish~121":"Nurse — Paz, já acabei. Deus te marque com sua graça!\nFoste o bebê mais lindo que já amamentei:\nSe eu viver para ver-te casada algum dia,\nTerei meu desejo.","ladycapuletmarrythatmarryistheverythemei~urdispositiontobemarried~107":"Lady Capulet — Pois bem, esse “casar” é justamente o tema\nSobre que vim falar. Dize-me, filha Juliet,\nComo estás disposta a casar-te?","julietitisanhonourthatidreamnotof~sanhonourthatidreamnotof~33":"Juliet — É uma honra com que nem sonho.","nurseanhonourwerenotithineonlynurseiwoul~stsuckdwisdomfromthyteat~75":"Nurse — Uma honra! Se eu não fosse tua única ama,\nDiria que sugaste sabedoria do meu peito.","ladycapuletwellthinkofmarriagenowyounger~tparisseeksyouforhislove~201":"Lady Capulet — Pois bem, pensa agora em casamento; mais jovens que tu,\nAqui em Verona, damas de estima,\nJá são feitas mães: pela minha conta,\nEu era tua mãe quase na idade\nEm que agora és donzela. Assim, em breve:\nO valoroso Paris te procura para seu amor.","nurseamanyoungladyladysuchamanasallthewo~ltheworldwhyhesamanofwax~58":"Nurse — Um homem, jovem dama! Senhora, um homem tal\nComo o mundo todo — ora, é um homem de cera.","ladycapuletveronassummerhathnotsuchaflow~summerhathnotsuchaflower~42":"Lady Capulet — O verão de Verona não tem flor assim.","nursenayhesaflowerinfaithaveryflower~flowerinfaithaveryflower~36":"Nurse — Não, é uma flor; por minha fé, uma verdadeira flor.","ladycapuletwhatsayyoucanyoulovethegentle~ghimmakingyourselfnoless~547":"Lady Capulet — Que dizes? Podes amar o cavalheiro?\nEsta noite o verás em nossa festa;\nLê o volume do rosto do jovem Paris,\nE acha o deleite escrito ali com a pena da beleza;\nExamina cada traço casado com o outro,\nE vê como um empresta contentamento ao outro,\nE o que se oculta neste belo volume\nAcha escrito na margem de seus olhos.\nEste precioso livro de amor, este amante sem encadernação,\nPara se embelezar, só lhe falta uma capa:\nO peixe vive no mar, e é grande orgulho\nQue a beleza de fora esconda a beleza de dentro:\nEsse livro, aos olhos de muitos, partilha a glória\nQue em fechos de ouro tranca a história dourada;\nAssim partilharás tudo o que ele possui,\nTendo-o, sem te fazeres menos.","nursenolessnaybiggerwomengrowbymen~snaybiggerwomengrowbymen~34":"Nurse — Menos! Não, maior; as mulheres crescem com os homens.","ladycapuletspeakbrieflycanyoulikeofparis~flycanyoulikeofparislove~44":"Lady Capulet — Fala em breve, podes gostar do amor de Paris?","julietilllooktolikeiflookinglikingmovebu~givesstrengthtomakeitfly~108":"Juliet — Hei de olhar para gostar, se o olhar mover o gostar:\nMas não mais fundo cravarei meu olhar\nDo que o vosso consentimento dá força para fazê-lo voar.","enteraservant~enteraservant~13":"Entra um Criado.","servantmadamtheguestsarecomesupperserved~beseechyoufollowstraight~160":"Servant — Senhora, os convidados chegaram, a ceia está servida, a senhora foi chamada, a jovem dama procurada, a ama amaldiçoada na despensa, e tudo no extremo. Devo ir servir; suplico-vos, segui logo.","ladycapuletwefollowtheeexitservantjuliet~vantjulietthecountystays~54":"Lady Capulet — Seguimos-te. Sai o Criado. Juliet, o conde espera.","nursegogirlseekhappynightstohappydaysexe~ynightstohappydaysexeunt~43":"Nurse — Vai, menina, busca noites felizes para dias felizes. Saem.","sceneiv~sceneiv~7":"Cena IV","enterromeomercutiobenvoliowithfiveorsixm~erstorchbearersandothers~67":"Entram Romeo, Mercutio, Benvolio, com cinco ou seis Mascarados, Porta-tochas e outros.","romeowhatshallthisspeechbespokeforourexc~rshallweonwithoutapology~68":"Romeo — Quê, diremos este discurso por desculpa?\nOu entraremos sem apologia?","benvoliothedateisoutofsuchprolixitywellh~urethemameasureandbegone~262":"Benvolio — Passou o tempo de tal prolixidade:\nNão teremos Cupido de olhos vendados com um lenço,\nPortando o arco pintado de ripa de um tártaro,\nAssustando as damas como espantalho de corvos;\nNem prólogo decorado, mal falado\nApós o ponto, para nossa entrada:\nMas que nos meçam por quanto quiserem;\nMediremos uma dança para elas, e partiremos.","romeogivemeatorchiamnotforthisamblingbei~utheavyiwillbearthelight~67":"Romeo — Dai-me uma tocha: não sou para esse passeio;\nSendo pesado, levarei a luz.","mercutionaygentleromeowemusthaveyoudance~eromeowemusthaveyoudance~40":"Mercutio — Não, gentil Romeo, temos de te fazer dançar.","romeonotibelievemeyouhavedancingshoeswit~metothegroundicannotmove~100":"Romeo — Eu não, crede-me: tendes sapatos de dança\nDe solas ágeis: tenho uma alma de chumbo\nQue me crava ao chão e não posso mover-me.","mercutioyouarealoverborrowcupidswingsand~iththemaboveacommonbound~69":"Mercutio — És um amante; toma emprestadas as asas de Cupido\nE eleva-te com elas acima de um salto comum.","romeoiamtoosoreenpiercedwithhisshafttoso~rlovesheavyburdendoisink~130":"Romeo — Estou por demais cruelmente atravessado por sua flecha\nPara alçar-me com suas penas leves, e tão atado,\nNão posso saltar um palmo acima do tédio da dor:\nSob o pesado fardo do amor eu afundo.","mercutioandtosinkinitshouldyouburdenlove~ppressionforatenderthing~73":"Mercutio — E, para afundar nele, tu sobrecarregarias o amor;\nOpressão demasiada para coisa tão terna.","romeoisloveatenderthingitistooroughtooru~rousanditprickslikethorn~75":"Romeo — O amor é coisa terna? É áspero demais,\nRude demais, tumultuoso demais, e fere como espinho.","mercutioifloveberoughwithyouberoughwithl~etlebrowsshallblushforme~201":"Mercutio — Se o amor é áspero contigo, sê áspero com o amor;\nFere o amor por ferir, e abaterás o amor.\nDai-me um estojo para pôr meu rosto:\nUma máscara para uma máscara! Que me importa\nQue olho curioso repare nas deformidades?\nAqui estão as sobrancelhas de besouro que corarão por mim.","benvoliocomeknockandenterandnosoonerinbu~erymanbetakehimtohislegs~67":"Benvolio — Vamos, batamos e entremos; e mal dentro,\nCada homem recorra às pernas.","romeoatorchformeletwantonslightofheartti~ewasneersofairandiamdone~167":"Romeo — Uma tocha para mim: que os levianos de coração leve\nFaçam cócegas com os calcanhares nos juncos insensíveis,\nPois sou premunido por um provérbio de avô;\nSerei porta-vela, e olharei.\nO jogo nunca foi tão bom, e eu desisto.","mercutiotutdunsthemousetheconstablesownw~earscomeweburndaylightho~149":"Mercutio — Ora, “pardo é o rato”, palavra do próprio guarda:\nSe estás pardo, te tiraremos do lamaçal\nDeste amor, com perdão da palavra, em que estás atolado\nAté as orelhas. Vamos, queimamos a luz do dia, ó!","romeonaythatsnotso~romeonaythatsnotso~18":"Romeo — Não, não é assim.","mercutioimeansirindelaywewasteourlightsi~thatereonceinourfivewits~130":"Mercutio — Quero dizer, senhor, que na demora\nGastamos nossas luzes em vão, como lâmpadas de dia.\nToma nossa boa intenção, pois nosso juízo reside\nCinco vezes mais nela que uma só vez em nossos cinco sentidos.","romeoandwemeanwellingoingtothismaskbutti~othismaskbuttisnowittogo~50":"Romeo — E temos boa intenção em ir a esta mascarada;\nMas não é sensatez ir.","mercutiowhymayoneask~mercutiowhymayoneask~20":"Mercutio — Por quê, pode-se perguntar?","romeoidreamdadreamtonight~omeoidreamdadreamtonight~25":"Romeo — Tive um sonho esta noite.","mercutioandsodidi~mercutioandsodidi~17":"Mercutio — E eu também.","romeowellwhatwasyours~romeowellwhatwasyours~21":"Romeo — Bem, qual foi o teu?","mercutiothatdreamersoftenlie~utiothatdreamersoftenlie~28":"Mercutio — Que os sonhadores muitas vezes mentem.","romeoinbedasleepwhiletheydodreamthingstr~iletheydodreamthingstrue~42":"Romeo — Na cama, dormindo, enquanto sonham coisas verdadeiras.","mercutiootheniseequeenmabhathbeenwithyou~nofgoodcarriagethisisshe~1458":"Mercutio — Ó, então vejo que a Rainha Mab esteve contigo.\nEla é a parteira das fadas, e vem\nEm forma não maior que uma ágata\nNo indicador de um vereador,\nPuxada por uma parelha de pequenos átomos\nAtravés dos narizes dos homens quando dormem;\nOs raios de seu carro feitos de longas pernas de aranha,\nA capota, das asas de gafanhotos,\nOs tirantes, da teia da menor aranha,\nAs coleiras, dos úmidos raios do luar,\nSeu chicote de osso de grilo, a tira de película,\nSeu cocheiro um pequeno mosquito de casaca cinzenta,\nNem metade tão grande quanto um redondo vermezinho\nEspetado do dedo preguiçoso de uma donzela;\nSeu coche é uma avelã vazia\nFeita pelo esquilo marceneiro ou pela velha larva,\nDesde tempos imemoriais os carroceiros das fadas.\nE nesse estado galopa noite após noite\nPelos cérebros dos amantes, e então sonham com amor;\nSobre os joelhos dos cortesãos, que sonham logo com mesuras,\nSobre os dedos dos advogados, que sonham logo com honorários,\nSobre os lábios das damas, que sonham logo com beijos,\nQue a irada Mab muitas vezes aflige com bolhas,\nPorque seus hálitos são manchados de doces:\nÀs vezes galopa sobre o nariz de um cortesão,\nE então ele sonha farejar uma pretensão;\nE às vezes vem com o rabo de um porco do dízimo\nFazendo cócegas no nariz de um pároco enquanto dorme,\nEntão ele sonha com outro benefício:\nÀs vezes passa sobre o pescoço de um soldado,\nE então ele sonha cortar gargantas estrangeiras,\nDe brechas, emboscadas, lâminas espanholas,\nDe brindes de cinco braças de fundo; e logo\nTambores em seu ouvido, com o que se assusta e acorda,\nE assim assustado jura uma oração ou duas\nE dorme de novo. Esta é a própria Mab\nQue trança as crinas dos cavalos à noite,\nE assa os nós das fadas em cabelos sórdidos e sujos,\nQue uma vez desenredados pressagiam muita desgraça:\nEsta é a bruxa que, quando as donzelas dormem de costas,\nPesa sobre elas e lhes ensina primeiro a suportar,\nFazendo-as mulheres de bom porte:\nEsta é ela —","romeopeacepeacemercutiopeacethoutalkstof~peacethoutalkstofnothing~47":"Romeo — Paz, paz, Mercutio, paz!\nFalas de nada.","mercutiotrueitalkofdreamswhicharethechil~acetothedewdroppingsouth~252":"Mercutio — É verdade, falo de sonhos,\nQue são filhos de um cérebro ocioso,\nGerados de nada senão de vã fantasia,\nQue é tão tênue de substância quanto o ar\nE mais inconstante que o vento, que corteja\nAgora mesmo o seio gelado do norte,\nE, irado, sopra para longe dali,\nVoltando o rosto para o sul gotejante de orvalho.","benvoliothiswindyoutalkofblowsusfromours~oneandweshallcometoolate~78":"Benvolio — Esse vento de que falas nos sopra para fora de nós mesmos;\nA ceia acabou, e chegaremos tarde demais.","romeoifeartooearlyformymindmisgivessomec~ctmysailonlustygentlemen~263":"Romeo — Receio que cedo demais: pois minha mente pressente\nQue alguma consequência ainda suspensa nas estrelas\nComeçará amargamente seu temido prazo\nCom os festejos desta noite e expirará o termo\nDe uma vida desprezada encerrada em meu peito\nPor algum vil resgate de morte prematura.\nMas Aquele que tem o leme de meu curso\nDirija minha vela! Adiante, vigorosos cavalheiros.","benvoliostrikedrumexeunt~benvoliostrikedrumexeunt~24":"Benvolio — Toca, tambor. Saem.","scenev~scenev~6":"Cena V","ahallincapuletshouse~ahallincapuletshouse~20":"Um salão na casa de Capulet.","musicianswaitingenterservingmenwithnapki~terservingmenwithnapkins~42":"Músicos à espera. Entram Criados com guardanapos.","firstservingmanwherespotpanthathehelpsno~rencherhescrapeatrencher~84":"First Servingman — Onde está Potpan, que não ajuda a tirar a mesa? Ele muda um prato? Ele raspa um prato!","secondservingmanwhengoodmannersshallliea~unwashedtootisafoulthing~92":"Second Servingman — Quando a boa educação estiver toda nas mãos de um ou dois homens, e ainda por cima sem lavar, é coisa feia.","firstservingmanawaywiththejointstoolsrem~neandnellantonyandpotpan~175":"First Servingman — Fora com os bancos, tira o aparador, cuida da prataria. Bom amigo, guarda-me um pedaço de maçapão; e, se me queres bem, manda o porteiro deixar entrar Susan Grindstone e Nell. Antony, e Potpan!","secondservingmanayboyready~condservingmanayboyready~26":"Second Servingman — Sim, rapaz, pronto.","firstservingmanyouarelookedforandcalledf~ughtforinthegreatchamber~79":"First Servingman — Estão te esperando e chamando, perguntando e procurando, na grande sala.","secondservingmanwecannotbehereandthereto~andthelongerlivertakeall~89":"Second Servingman — Não podemos estar aqui e lá também. Ânimo, rapazes; sede vivos um pouco, e quem viver mais leve tudo.","entercapuletwithjulietandothersofhishous~etingtheguestsandmaskers~67":"Entra Capulet, com Juliet e outros de sua casa, recebendo os Convidados e Mascarados.","capuletwelcomegentlemenladiesthathavethe~tyourselfandiwereinamask~621":"Capulet — Bem-vindos, cavalheiros! As damas que têm os dedos dos pés\nLivres de calos dançarão convosco.\nAh ha, minhas senhoras! Qual de vós todas\nRecusará agora dançar? A que faz melindres,\nEssa, juro, tem calos; toquei-vos agora?\nBem-vindos, cavalheiros! Vi o dia\nEm que usei máscara e sabia contar\nUma história ao ouvido de uma bela dama,\nTal que agradasse: passou, passou, passou:\nSois bem-vindos, cavalheiros! Vamos, músicos, tocai.\nEspaço, espaço! Dai lugar! E dançai, meninas. A música toca, e dançam.\nMais luz, seus patifes; e virai as mesas,\nE apagai o fogo, a sala ficou quente demais.\nAh, rapaz, este divertimento inesperado cai bem.\nNão, sentai, sentai, bom primo Capulet;\nPois vós e eu passamos dos dias de dançar:\nQuanto tempo faz desde que vós e eu\nEstivemos numa mascarada?","secondcapuletbyrladythirtyyears~apuletbyrladythirtyyears~31":"Second Capulet — Por Nossa Senhora, trinta anos.","capuletwhatmantisnotsomuchtisnotsomuchti~wentyyearsandthenwemaskd~133":"Capulet — Quê, homem! Não é tanto, não é tanto:\nFoi desde as bodas de Lucentio,\nVenha o Pentecostes tão depressa quanto quiser,\nUns vinte e cinco anos; e então mascaramos.","secondcapulettismoretismorehissoniselder~iseldersirhissonisthirty~57":"Second Capulet — É mais, é mais: o filho dele é mais velho, senhor;\nSeu filho tem trinta.","capuletwillyoutellmethathissonwasbutawar~onwasbutawardtwoyearsago~52":"Capulet — Vais dizer-me isso?\nSeu filho era apenas tutelado há dois anos.","romeotoaservingmanwhatladyisthatwhichdot~ichthehandofyonderknight~68":"Romeo — A um Criado. Que dama é aquela que enriquece a mão\nDaquele cavaleiro ali?","servingmaniknownotsir~servingmaniknownotsir~21":"Servingman — Não sei, senhor.","romeooshedothteachthetorchestoburnbright~wtruebeautytillthisnight~344":"Romeo — Ó, ela ensina as tochas a arder com brilho!\nParece que ela pende da face da noite\nComo rica joia na orelha de um etíope;\nBeleza rica demais para o uso, cara demais para a terra!\nAssim parece uma pomba nívea em meio a corvos,\nComo aquela dama sobre suas companheiras.\nTerminada a dança, observarei seu lugar de pé,\nE, tocando a mão dela, abençoarei minha mão rude.\nMeu coração amou até agora? Renega-o, vista!\nPois nunca vi verdadeira beleza até esta noite.","tybaltthisbyhisvoiceshouldbeamontaguefet~ikehimdeadiholditnotasin~190":"Tybalt — Esta, pela voz, deve ser um Montague.\nTraze-me minha espada, rapaz. Como ousa o escravo,\nVindo aqui coberto de um rosto grotesco,\nZombar e escarnecer de nossa solenidade?\nAgora, pela estirpe e honra de meus parentes,\nMatá-lo não tenho por pecado.","capuletwhyhownowkinsmanwhereforestormyou~nsmanwhereforestormyouso~42":"Capulet — Ora, que é isso, parente! Por que tanta fúria?","tybaltunclethisisamontagueourfoeavillain~natoursolemnitythisnight~93":"Tybalt — Tio, este é um Montague, nosso inimigo,\nUm vilão que aqui veio por despeito,\nPara escarnecer de nossa solenidade esta noite.","capuletyoungromeoisit~capuletyoungromeoisit~21":"Capulet — É o jovem Romeo?","tybalttishethatvillainromeo~alttishethatvillainromeo~27":"Tybalt — É ele, aquele vilão Romeo.","capuletcontenttheegentlecozlethimalonehe~eemingsemblanceforafeast~326":"Capulet — Acalma-te, gentil primo, deixa-o em paz;\nPorta-se como um cavalheiro de boa presença;\nE, para dizer a verdade, Verona se gaba dele\nComo jovem virtuoso e bem-educado:\nNão quereria, pela riqueza de toda a cidade,\nFazer-lhe aqui em minha casa qualquer desfeita:\nPortanto, sê paciente, não faças caso dele:\nÉ minha vontade, e se a respeitas,\nMostra um semblante afável e põe de lado esses franzidos,\nAparência mal-ajustada a uma festa.","tybaltitfitswhensuchavillainisaguestilln~nisaguestillnotendurehim~51":"Tybalt — Ajusta-se quando um tal vilão é convidado:\nNão o suportarei.","capuletheshallbeenduredwhatgoodmanboyisa~etcockahoopyoullbetheman~173":"Capulet — Será suportado:\nQuê, mocinho! Digo que será: vamos;\nSou eu o senhor aqui, ou tu? Vamos.\nNão o suportarás! Deus me salve a alma!\nQueres fazer motim entre meus convidados!\nQueres armar bravata! Queres ser o homem!","tybaltwhyuncletisashame~tybaltwhyuncletisashame~23":"Tybalt — Ora, tio, é uma vergonha.","capuletgotogotoyouareasaucyboyistsoindee~quietwhatcheerlymyhearts~209":"Capulet — Vamos, vamos;\nÉs um rapaz atrevido: é assim, de fato?\nEsta artimanha pode vir a prejudicar-te, sei bem o quê:\nTens de me contrariar! Ora, é tempo.\nBem dito, meus corações! Tu és um fedelho; vai:\nFica quieto, ou — Mais luz, mais luz! Que vergonha!\nEu te farei calar. Quê, ânimo, meus corações!","tybaltpatienceperforcewithwilfulcholerme~tconverttobittergallexit~160":"Tybalt — A paciência forçada encontrando a cólera obstinada\nFaz minha carne tremer no choque dos dois.\nRetirar-me-ei: mas esta intrusão, agora\nAparentemente doce, converter-se-á em fel amargo. Sai.","romeotojulietifiprofanewithmyunworthiest~oughtouchwithatenderkiss~149":"Romeo — A Juliet. Se profano com minha indignísima mão\nEste santo relicário, a gentil penitência é esta:\nMeus lábios, dois peregrinos corados, estão prontos\nPara suavizar esse toque rude com um terno beijo.","julietgoodpilgrimyoudowrongyourhandtoomu~mtopalmisholypalmerskiss~146":"Juliet — Bom peregrino, fazeis demasiado mal à vossa mão,\nQue mostra nisto polida devoção;\nPois os santos têm mãos que as mãos dos peregrinos tocam,\nE palma com palma é o beijo dos santos palmeiros.","romeohavenotsaintslipsandholypalmerstoo~ntslipsandholypalmerstoo~39":"Romeo — Não têm lábios os santos, e os santos palmeiros também?","julietaypilgrimlipsthattheymustuseinpray~sthattheymustuseinprayer~42":"Juliet — Sim, peregrino, lábios que devem usar na oração.","romeoothendearsaintletlipsdowhathandsdot~oulestfaithturntodespair~78":"Romeo — Ó, então, cara santa, que os lábios façam o que fazem as mãos;\nEles rezam, concede, para que a fé não se torne desespero.","julietsaintsdonotmovethoughgrantforpraye~houghgrantforprayerssake~46":"Juliet — Os santos não se movem, embora concedam por causa das preces.","romeothenmovenotwhilemyprayerseffectitak~lipsbyyoursmysinispurged~75":"Romeo — Então não te movas, enquanto recebo o efeito de minha prece.\nAssim, de meus lábios, pelos teus, meu pecado é purgado.","julietthenhavemylipsthesinthattheyhaveto~psthesinthattheyhavetook~42":"Juliet — Então meus lábios têm o pecado que tomaram.","romeosinfromthylipsotrespasssweetlyurged~tlyurgedgivememysinagain~56":"Romeo — Pecado de teus lábios? Ó transgressão docemente instada!\nDevolve-me meu pecado.","julietyoukissbythebook~julietyoukissbythebook~22":"Juliet — Beijais pelo livro.","nursemadamyourmothercravesawordwithyou~mothercravesawordwithyou~38":"Nurse — Senhora, vossa mãe pede uma palavra convosco.","romeowhatishermother~romeowhatishermother~20":"Romeo — Quem é a mãe dela?","nursemarrybachelorhermotheristheladyofth~dofhershallhavethechinks~160":"Nurse — Ora, rapaz,\nSua mãe é a senhora da casa,\nE boa senhora, e sábia e virtuosa:\nEu amamentei a filha, com quem falastes;\nDigo-vos que quem puder pôr a mão nela\nTerá o dinheiro.","romeoissheacapuletodearaccountmylifeismy~ccountmylifeismyfoesdebt~48":"Romeo — Ela é uma Capulet?\nÓ conta cara! Minha vida é dívida de meu inimigo.","benvolioawaybegonethesportisatthebest~egonethesportisatthebest~37":"Benvolio — Vamos, partamos; o divertimento está no auge.","romeoaysoifearthemoreismyunrest~soifearthemoreismyunrest~31":"Romeo — Sim, receio; é maior meu desassossego.","capuletnaygentlemenpreparenottobegoneweh~euntallbutjulietandnurse~231":"Capulet — Não, cavalheiros, não vos preparais para partir;\nTemos uma pequena e tola ceia a caminho.\nÉ mesmo assim? Ora, então, agradeço a todos;\nAgradeço-vos, honestos cavalheiros; boa noite.\nMais tochas aqui! Vamos então, para a cama.\nAh, rapaz, por minha fé, vai ficando tarde:\nVou ao meu repouso. Saem todos, exceto Juliet e a Ama.","julietcomehithernursewhatisyondgentleman~nursewhatisyondgentleman~40":"Juliet — Vem cá, ama. Quem é aquele cavalheiro?","nursethesonandheirofoldtiberio~hesonandheirofoldtiberio~30":"Nurse — O filho e herdeiro do velho Tiberio.","julietwhatshethatnowisgoingoutofdoor~ethatnowisgoingoutofdoor~36":"Juliet — Quem é aquele que agora sai pela porta?","nursemarrythatithinkbeyoungpetrucio~hatithinkbeyoungpetrucio~35":"Nurse — Ora, aquele, penso, é o jovem Petrucio.","julietwhatshethatfollowstherethatwouldno~wstherethatwouldnotdance~46":"Juliet — Quem é aquele que segue ali, que não quis dançar?","nurseiknownot~nurseiknownot~13":"Nurse — Não sei.","julietgoaskhisnameifhebemarriedmygraveis~veisliketobemyweddingbed~60":"Juliet — Vai perguntar-lhe o nome: se for casado,\nMinha sepultura será provavelmente meu leito de núpcias.","nursehisnameisromeoandamontaguetheonlyso~eonlysonofyourgreatenemy~57":"Nurse — Seu nome é Romeo, e um Montague;\nO único filho de vosso grande inimigo.","julietmyonlylovesprungfrommyonlyhatetooe~atimustlovealoathedenemy~125":"Juliet — Meu único amor nascido de meu único ódio!\nCedo demais visto sem ser conhecido, e conhecido tarde demais!\nProdigioso nascimento de amor é este para mim,\nQue eu deva amar um inimigo detestado.","nursewhatsthiswhatsthis~nursewhatsthiswhatsthis~23":"Nurse — Que é isso? Que é isso?","julietarhymeilearndevennowofoneidancedwi~thalonecallswithinjuliet~64":"Juliet — Uma rima que aprendi agora mesmo\nDe alguém com quem dancei. Chamam de dentro “Juliet.”","nurseanonanoncomeletsawaythestrangersall~trangersallaregoneexeunt~53":"Nurse — Já vai, já vai!\nVem, vamos; os estranhos todos se foram. Saem.","prologue~prologue~8":"Prólogo","enterchorus~enterchorus~11":"Entra o Coro.","chorusnowolddesiredothinhisdeathbedliean~tieswithextremesweetexit~487":"Chorus — Agora o velho desejo jaz em seu leito de morte,\nE a jovem afeição anseia por ser sua herdeira;\nAquela beleza por que o amor gemia e queria morrer,\nComparada à terna Juliet, já não é bela.\nAgora Romeo é amado e ama de volta,\nAmbos enfeitiçados pelo encanto dos olhares,\nMas ao suposto inimigo deve queixar-se,\nE ela furtar a doce isca do amor de anzóis temíveis:\nTido por inimigo, ele não pode ter acesso\nPara respirar os votos que os amantes costumam jurar;\nE ela, tão enamorada, com meios muito menores\nDe encontrar seu novo amado em qualquer lugar:\nMas a paixão lhes dá poder, o tempo, meios de se encontrar,\nTemperando extremos de dor com extrema doçura. Sai.","alanebythewallofcapuletsorchard~thewallofcapuletsorchard~31":"Uma travessa junto ao muro do pomar de Capulet.","romeocanigoforwardwhenmyheartishereturnb~wallandleapsdownwithinit~106":"Romeo — Posso ir adiante quando meu coração está aqui?\nVolta atrás, terra obtusa, e encontra teu centro. Escala o muro e salta para dentro.","enterbenvolioandmercutio~enterbenvolioandmercutio~24":"Entram Benvolio e Mercutio.","benvolioromeomycousinromeo~nvolioromeomycousinromeo~26":"Benvolio — Romeo! Meu primo Romeo!","mercutioheiswiseandonmyliehathstolnhimho~liehathstolnhimhometobed~47":"Mercutio — Ele é sábio;\nE, sobre minha palavra, esgueirou-se para casa, para a cama.","benvolioheranthiswayandleapdthisorchardw~hardwallcallgoodmercutio~59":"Benvolio — Correu por aqui e saltou este muro do pomar:\nChama, bom Mercutio.","mercutionayillconjuretooromeohumoursmadm~hylikenessthouappeartous~516":"Mercutio — Não, eu também conjurarei.\nRomeo! Humores! Louco! Paixão! Amante!\nAparece na forma de um suspiro:\nDiz uma só rima e estou satisfeito;\nGrita apenas “Ai de mim!”, pronuncia só “amor” e “ardor”;\nDize a minha comadre Vênus uma bela palavra,\nUm apelido para seu filho e herdeiro míope,\nO jovem Adão Cupido, aquele que atirou tão bem\nQuando o Rei Cofetua amou a mendiga!\nEle não ouve, não se agita, não se move;\nO macaco está morto, e devo conjurá-lo.\nConjuro-te pelos olhos brilhantes de Rosaline,\nPor sua fronte alta e seu lábio escarlate,\nPor seu belo pé, perna reta e coxa trêmula\nE os domínios que ali adjacentes jazem,\nQue em tua própria forma apareças a nós!","benvolioandifheheartheethouwiltangerhim~heartheethouwiltangerhim~39":"Benvolio — E se ele te ouvir, vais irritá-lo.","mercutiothiscannotangerhimtwouldangerhim~njureonlybuttoraiseuphim~235":"Mercutio — Isto não pode irritá-lo: irritá-lo-ia\nLevantar um espírito no círculo de sua amada,\nDe natureza estranha, deixando-o ali parado\nAté que ela o aquietasse e o conjurasse de volta;\nIsso seria uma maldade: minha invocação\nÉ honesta e justa, e em nome de sua amada\nConjuro apenas para levantá-lo.","benvoliocomehehathhidhimselfamongthesetr~loveandbestbefitsthedark~110":"Benvolio — Vamos, ele se escondeu entre estas árvores,\nPara ser companheiro da noite caprichosa:\nCego é o seu amor e convém-lhe melhor a escuridão.","mercutioiflovebeblindlovecannothitthemar~ormetosleepcomeshallwego~273":"Mercutio — Se o amor é cego, não pode acertar o alvo.\nAgora ele se sentará sob uma nespereira,\nE desejará que sua amada seja esse tipo de fruta\nQue as donzelas chamam de nêsperas, quando riem a sós.\nÓ, Romeo, quem dera fosse ela, quem dera fosse\nUma fruta aberta, e tu uma pera pop’rin!\nRomeo, boa noite: vou para minha cama de rodízio;\nEste leito de campo é frio demais para eu dormir:\nVamos, vamos?","benvoliogothenfortisinvaintoseekhimheret~tmeansnottobefoundexeunt~66":"Benvolio — Vamos, então; pois é em vão\nProcurar aqui quem não quer ser achado. Saem.","capuletsorchard~capuletsorchard~15":"O pomar dos Capuletos.","romeohejestsatscarsthatneverfeltawoundju~thatimighttouchthatcheek~843":"Romeo — Ri das cicatrizes quem nunca sentiu ferida. Juliet aparece no alto, a uma janela.\nMas, silêncio! Que luz rompe por aquela janela?\nÉ o oriente, e Juliet é o sol.\nErgue-te, belo sol, e mata a lua invejosa,\nQue já está doente e pálida de dor,\nPorque tu, sua serva, és bem mais bela que ela:\nNão sejas sua serva, já que ela é invejosa;\nSua libré de vestal é apenas doentia e verde\nE só os tolos a vestem; despe-a.\nÉ minha senhora, ó, é meu amor!\nÓ, se ela soubesse que o é!\nEla fala, e no entanto nada diz: que importa?\nSeu olhar discorre; eu lhe responderei.\nSou atrevido demais, não é a mim que ela fala:\nDuas das mais belas estrelas de todo o céu,\nTendo algum compromisso, rogam a seus olhos\nQue cintilem em suas esferas até que voltem.\nE se seus olhos estivessem lá, e elas em sua cabeça?\nO brilho de sua face envergonharia aquelas estrelas,\nComo a luz do dia faz com uma lamparina; seus olhos no céu\nJorrariam pela região aérea tão brilhantes\nQue as aves cantariam, pensando que não era noite.\nVede como apoia a face na mão!\nÓ, quem me dera ser uma luva naquela mão,\nPara tocar aquela face!","julietayme~julietayme~10":"Juliet — Ai de mim!","romeoshespeaksospeakagainbrightangelfort~ailsuponthebosomoftheair~236":"Romeo — Ela fala:\nÓ, fala de novo, anjo luminoso! Pois és\nTão glorioso a esta noite, estando acima de minha cabeça,\nComo um mensageiro alado do céu\nAos olhos brancos, erguidos e maravilhados\nDe mortais que se curvam para trás para contemplá-lo\nQuando cavalga as nuvens de lento andar\nE navega sobre o seio do ar.","julietoromeoromeowhereforeartthouromeode~andillnolongerbeacapulet~122":"Juliet — Ó Romeo, Romeo! Por que és tu Romeo?\nRenega teu pai e recusa teu nome;\nOu, se não quiseres, jura apenas ser meu amor,\nE eu não serei mais uma Capulet.","romeoasideshallihearmoreorshallispeakatt~rmoreorshallispeakatthis~43":"Romeo — À parte. Devo ouvir mais, ou falar a isto?","juliettisbutthynamethatismyenemythouartt~opartoftheetakeallmyself~361":"Juliet — Só teu nome é meu inimigo;\nTu és tu mesmo, ainda que não fosses Montague.\nQue é Montague? Não é mão, nem pé,\nNem braço, nem rosto, nem qualquer outra parte\nPertencente a um homem. Ó, sê outro nome!\nQue há num nome? Aquilo que chamamos rosa\nCom qualquer outro nome cheiraria tão doce;\nAssim Romeo, não se chamando Romeo,\nConservaria aquela cara perfeição que possui\nSem esse título. Romeo, despe teu nome,\nE por esse nome, que não é parte de ti,\nToma-me inteira.","romeoitaketheeatthywordcallmebutloveandi~ceforthineverwillberomeo~82":"Romeo — Tomo-te na palavra:\nChama-me apenas amor, e serei novamente batizado;\nDe agora em diante nunca serei Romeo.","julietwhatmanartthouthatthusbescreendinn~htsostumblestonmycounsel~66":"Juliet — Que homem és tu que, assim encoberto pela noite,\nTropeças em meu segredo?","romeobyanameiknownothowtotelltheewhoiamm~writteniwouldteartheword~125":"Romeo — Por um nome\nNão sei como dizer-te quem sou:\nMeu nome, cara santa, é odioso para mim mesmo,\nPorque é inimigo de ti;\nSe o tivesse escrito, rasgaria a palavra.","julietmyearshavenotyetdrunkahundredwords~thounotromeoandamontague~105":"Juliet — Meus ouvidos ainda não beberam cem palavras\nDa voz dessa língua, e contudo conheço o som:\nNão és tu Romeo e um Montague?","romeoneitherfairsaintifeithertheedislike~saintifeithertheedislike~40":"Romeo — Nenhum dos dois, bela santa, se algum te desagrada.","juliethowcamestthouhithertellmeandwheref~yofmykinsmenfindtheehere~144":"Juliet — Como vieste aqui, dize-me, e por quê?\nOs muros do pomar são altos e difíceis de escalar,\nE o lugar é a morte, considerando quem és,\nSe algum de meus parentes te achar aqui.","romeowithloveslightwingsdidioerperchthes~rethykinsmenarenolettome~144":"Romeo — Com as leves asas do amor sobrevoei estes muros;\nPois limites de pedra não detêm o amor,\nE o que o amor pode fazer, isso o amor ousa tentar;\nPortanto teus parentes não são empecilho para mim.","julietiftheydoseetheetheywillmurderthee~eetheetheywillmurderthee~39":"Juliet — Se te virem, te assassinarão.","romeoalackthereliesmoreperilinthineeyeth~mproofagainsttheirenmity~106":"Romeo — Ai, há mais perigo em teus olhos\nDo que em vinte de suas espadas: olha-me apenas com doçura,\nE estou à prova de sua inimizade.","julietiwouldnotfortheworldtheysawtheeher~rtheworldtheysawtheehere~41":"Juliet — Eu não queria, por nada no mundo, que te vissem aqui.","romeoihavenightscloaktohidemefromtheirsi~roroguedwantingofthylove~142":"Romeo — Tenho o manto da noite para esconder-me de sua vista;\nE se não me amas, deixa que me achem aqui:\nMinha vida seria melhor findada pelo ódio deles\nDo que a morte adiada, faltando-me teu amor.","julietbywhosedirectionfoundstthououtthis~nfoundstthououtthisplace~45":"Juliet — Por cuja direção achaste este lugar?","romeobylovewhofirstdidpromptmetoinquireh~entureforsuchmerchandise~166":"Romeo — Pelo amor, que primeiro me instigou a indagar;\nEle me emprestou conselho e eu lhe emprestei olhos.\nNão sou piloto; contudo, se estivesses tão longe\nQuanto aquela vasta praia banhada pelo mais distante mar,\nEu me aventuraria por tal mercadoria.","julietthouknowstthemaskofnightisonmyface~arknighthathsodiscovered~764":"Juliet — Sabes que a máscara da noite está em meu rosto,\nDo contrário um rubor de donzela pintaria minha face\nPelo que me ouviste dizer esta noite.\nDe bom grado me prenderia à etiqueta, de bom grado, de bom grado negaria\nO que falei: mas adeus, cerimônia!\nTu me amas? Sei que dirás “Sim”,\nE tomarei tua palavra: contudo, se jurares,\nPoderás provar-te falso; dos perjúrios dos amantes,\nDizem, Júpiter ri. Ó gentil Romeo,\nSe amas, pronuncia-o fielmente:\nOu se pensas que sou ganha depressa demais,\nFranzirei o cenho e serei perversa e te direi não,\nPara que me cortejes; mas fora disso, nem pelo mundo.\nEm verdade, belo Montague, sou afeiçoada demais,\nE por isso podes pensar leviano meu proceder;\nMas crê-me, cavalheiro, provarei ser mais fiel\nQue as que têm mais astúcia para se fazerem esquivas.\nEu devia ter sido mais esquiva, devo confessar,\nNão fosse que ouviste, antes que eu o soubesse,\nA paixão de meu verdadeiro amor: portanto perdoa-me,\nE não imputes esta rendição a amor leviano,\nO que a noite escura assim revelou.","romeoladybyyonderblessedmooniswearthatti~verallthesefruittreetops~73":"Romeo — Senhora, por aquela lua bendita juro,\nQue prateia todas estas copas de árvores frutíferas —","julietoswearnotbythemoontheinconstantmoo~oveprovelikewisevariable~110":"Juliet — Ó, não jures pela lua, a lua inconstante,\nQue muda todo mês em seu orbe circular,\nPara que teu amor não se prove igualmente variável.","romeowhatshalliswearby~romeowhatshalliswearby~22":"Romeo — Por quem hei de jurar?","julietdonotswearatallorifthouwiltswearby~dolatryandillbelievethee~97":"Juliet — Não jures de modo algum;\nOu, se quiseres, jura por tua graciosa pessoa,\nQue é o deus de minha idolatria,\nE te acreditarei.","romeoifmyheartsdearlove~romeoifmyheartsdearlove~23":"Romeo — Se o caro amor de meu coração —","julietwelldonotswearalthoughijoyintheeih~eartasthatwithinmybreast~320":"Juliet — Bem, não jures: embora eu me alegre em ti,\nNão me alegro com este contrato esta noite:\nÉ precipitado demais, imprudente demais, repentino demais;\nDemais como o relâmpago, que deixa de ser\nAntes que se possa dizer “Relampeja.” Doce, boa noite!\nEste botão de amor, pelo sopro amadurecedor do verão,\nPoderá ser uma bela flor quando nos encontrarmos de novo.\nBoa noite, boa noite! Que doce repouso e descanso\nVenham a teu coração como o que há em meu peito!","romeoowiltthouleavemesounsatisfied~thouleavemesounsatisfied~34":"Romeo — Ó, vais deixar-me assim insatisfeito?","julietwhatsatisfactioncanstthouhavetonig~tioncanstthouhavetonight~42":"Juliet — Que satisfação podes ter esta noite?","romeotheexchangeofthylovesfaithfulvowfor~ylovesfaithfulvowformine~44":"Romeo — A troca do fiel voto de teu amor pelo meu.","julietigavetheeminebeforethoudidstreques~tiwoulditweretogiveagain~72":"Juliet — Dei-te o meu antes que o pedisses:\nE contudo quisera que fosse para dar de novo.","romeowouldstthouwithdrawitforwhatpurpose~drawitforwhatpurposelove~44":"Romeo — Quererias retirá-lo? Para quê, amor?","julietbuttobefrankandgiveittheeagainandy~eiwillcomeagainexitabove~273":"Juliet — Apenas para ser franca e dar-te de novo.\nE contudo só desejo a coisa que tenho:\nMinha generosidade é tão ilimitada como o mar,\nMeu amor tão fundo; quanto mais te dou,\nMais tenho, pois ambos são infinitos. A Ama chama de dentro.\nOuço algum ruído lá dentro; caro amor, adeus!\nJá vou, boa ama! Doce Montague, sê fiel.\nFica só um pouco, voltarei. Sai, no alto.","romeooblessedblessednightiamafeardbeingi~ringsweettobesubstantial~97":"Romeo — Ó bendita, bendita noite! Receio\nQue, sendo noite, tudo isto seja apenas um sonho,\nLisonjeiramente doce demais para ser substancial.","reenterjulietabove~reenterjulietabove~18":"Reentra Juliet, no alto.","julietthreewordsdearromeoandgoodnightind~mylordthroughouttheworld~247":"Juliet — Três palavras, caro Romeo, e boa noite de verdade.\nSe tua inclinação de amor é honrada,\nTeu propósito o casamento, manda-me aviso amanhã,\nPor alguém que arranjarei para ir a ti,\nOnde e a que hora cumprirás o rito;\nE toda a minha fortuna a teus pés deporei\nE seguirei a ti, meu senhor, por todo o mundo.","nursewithinmadam~nursewithinmadam~16":"Nurse — De dentro. Senhora!","julieticomeanonbutifthoumeanstnotwellido~nstnotwellidobeseechthee~51":"Juliet — Já vou. — Mas se não tens boas intenções,\nRogo-te —","julietbyandbyicometoceasethysuitandleave~mygrieftomorrowwillisend~68":"Juliet — Já, já, vou: —\nCessa a tua corte, e deixa-me à minha dor:\nAmanhã enviarei.","romeosothrivemysoul~romeosothrivemysoul~19":"Romeo — Assim prospere minha alma —","julietathousandtimesgoodnightexitabove~dtimesgoodnightexitabove~38":"Juliet — Mil vezes boa noite! Sai, no alto.","romeoathousandtimestheworsetowantthyligh~olwithheavylooksretiring~134":"Romeo — Mil vezes pior, por faltar-me tua luz.\nO amor vai ao encontro do amor, como colegiais fogem de seus livros,\nMas o amor se afasta do amor, rumo à escola com olhar pesado. Retirando-se.","juliethistromeohistoforafalconersvoiceto~repetitionofmyromeosname~203":"Juliet — Psiu! Romeo, psiu! Ó, quem me dera a voz de um falcoeiro,\nPara atrair de volta este gentil falcão!\nO cativeiro é rouco e não pode falar alto;\nDo contrário romperia a caverna onde jaz Eco,\nE faria sua língua aérea mais rouca que a minha,\nCom a repetição do nome de meu Romeo.","romeoitismysoulthatcallsuponmynamehowsil~testmusictoattendingears~104":"Romeo — É minha alma que chama meu nome:\nQue prata-doces soam as línguas dos amantes à noite,\nComo a mais suave música a ouvidos atentos!","julietromeo~julietromeo~11":"Juliet — Romeo!","romeomydear~romeomydear~11":"Romeo — Minha querida?","julietatwhatoclocktomorrowshallisendtoth~tomorrowshallisendtothee~42":"Juliet — A que horas amanhã\nHei de mandar a ti?","romeoatthehourofnine~romeoatthehourofnine~20":"Romeo — À hora das nove.","julietiwillnotfailtistwentyyearstillthen~orgotwhyididcalltheeback~70":"Juliet — Não faltarei: faltam vinte anos até lá.\nEsqueci por que te chamei de volta.","romeoletmestandheretillthourememberit~ndheretillthourememberit~37":"Romeo — Deixa-me ficar aqui até que te lembres.","julietishallforgettohavetheestillstandth~beringhowilovethycompany~72":"Juliet — Esquecerei, para ter-te sempre parado ali,\nLembrando quanto amo tua companhia.","romeoandillstillstaytohavetheestillforge~ttinganyotherhomebutthis~70":"Romeo — E sempre ficarei, para ter-te sempre esquecida,\nEsquecendo qualquer outro lar que não este.","juliettisalmostmorningiwouldhavetheegone~ovingjealousofhisliberty~197":"Juliet — É quase manhã; quereria ver-te partido:\nMas não mais longe que o pássaro de uma travessa;\nQue o deixa saltar um pouco da mão,\nComo um pobre prisioneiro em seus grilhões trançados,\nE com um fio de seda o puxa de volta,\nTão amorosamente ciumenta de sua liberdade.","romeoiwouldiwerethybird~romeoiwouldiwerethybird~23":"Romeo — Quisera ser teu pássaro.","julietsweetsowouldiyetishouldkilltheewit~ttillitbemorrowexitabove~142":"Juliet — Doce, também eu quisera:\nMas te mataria de tanto mimo.\nBoa noite, boa noite! A despedida é uma dor tão doce\nQue direi boa noite até que seja manhã. Sai, no alto.","romeosleepdwelluponthineeyespeaceinthybr~veandmydearhaptotellexit~148":"Romeo — O sono pouse em teus olhos, a paz em teu peito!\nQuisera ser sono e paz, para tão doce repouso!\nDaqui irei à cela de meu pai espiritual,\nPedir-lhe ajuda e contar-lhe minha cara ventura. Sai.","friarlaurencescell~friarlaurencescell~18":"A cela de Frei Lourenço.","enterfriarlaurencewithabasket~friarlaurencewithabasket~29":"Entra Frei Laurence, com um cesto.","friarlaurencethegreyeyedmornsmilesonthef~nkerdeatheatsupthatplant~1073":"Friar Laurence — A manhã de olhos cinzentos sorri à noite carrancuda,\nRiscando as nuvens do oriente com listras de luz,\nE a treva malhada, como um bêbado, cambaleia\nPara fora da senda do dia e das rodas ardentes de Titã:\nAgora, antes que o sol avance seu olho flamejante,\nPara alegrar o dia e secar o orvalho úmido da noite,\nDevo encher este nosso cesto de vime\nCom ervas daninhas e flores de sucos preciosos.\nA terra que é mãe da natureza é seu túmulo;\nO que é sua sepultura é seu ventre,\nE de seu ventre filhos de diversas espécies\nAchamos a mamar em seu seio natural,\nMuitos excelentes por muitas virtudes,\nNenhum sem alguma e, contudo, todos diferentes.\nÓ, grande é a poderosa graça que jaz\nNas ervas, plantas, pedras e suas verdadeiras qualidades:\nPois nada há tão vil que viva sobre a terra\nQue à terra não dê algum bem especial,\nNem nada tão bom que, desviado desse belo uso,\nNão se rebele contra seu verdadeiro nascimento, tropeçando no abuso:\nA própria virtude vira vício, mal aplicada;\nE o vício às vezes é dignificado pela ação.\nDentro da casca infante desta pequena flor\nResidem veneno e poder de remédio:\nPois esta, cheirada, com aquela parte alegra cada parte;\nProvada, mata todos os sentidos com o coração.\nDois reis opostos assim acampam sempre\nNo homem como nas ervas, a graça e a vontade rude;\nE onde o pior é predominante,\nLogo o cancro da morte devora aquela planta.","romeogoodmorrowfather~romeogoodmorrowfather~21":"Romeo — Bom dia, pai.","friarlaurencebenedicitewhatearlytongueso~ohathnotbeeninbedtonight~392":"Friar Laurence — Benedicite!\nQue língua matutina tão doce me saúda?\nJovem filho, denota uma cabeça perturbada\nDar tão cedo bom dia à tua cama:\nO cuidado faz vigília em todo olho de velho,\nE onde o cuidado pousa, o sono nunca se deita;\nMas onde a juventude incólume, de cérebro sem peso,\nDeita os membros, ali reina o dourado sono:\nPortanto tua madrugada me assegura\nQue foste despertado por alguma perturbação;\nOu, se não for assim, então acerto aqui,\nNosso Romeo não esteve na cama esta noite.","romeothatlastistruethesweeterrestwasmine~ruethesweeterrestwasmine~40":"Romeo — Esta última é verdade; o repouso mais doce foi o meu.","friarlaurencegodpardonsinwastthouwithros~nsinwastthouwithrosaline~45":"Friar Laurence — Deus perdoe o pecado! Estiveste com Rosaline?","romeowithrosalinemyghostlyfathernoihavef~tthatnameandthatnameswoe~68":"Romeo — Com Rosaline, meu pai espiritual? Não;\nEsqueci esse nome e a dor desse nome.","friarlaurencethatsmygoodsonbutwherehastt~butwherehastthoubeenthen~51":"Friar Laurence — Esse é meu bom filho: mas onde estiveste, então?","romeoilltelltheeerethouaskitmeagainihave~ssionlikewisesteadsmyfoe~217":"Romeo — Contar-te-ei, antes que me perguntes de novo.\nEstive festejando com meu inimigo,\nOnde de repente alguém me feriu,\nQue é por mim ferido: ambos os nossos remédios\nEstão em tua ajuda e santa medicina:\nNão guardo ódio, homem bendito, pois, vê,\nMinha intercessão serve igualmente a meu inimigo.","friarlaurencebeplaingoodsonandhomelyinth~onfindsbutriddlingshrift~86":"Friar Laurence — Sê claro, bom filho, e simples em teu intento;\nConfissão enigmática acha só absolvição enigmática.","romeothenplainlyknowmyheartsdearloveisse~houconsenttomarryustoday~260":"Romeo — Então saibas claramente que o caro amor do meu coração está posto\nNa bela filha do rico Capulet:\nComo o meu nela, assim o dela está posto em mim;\nE tudo combinado, salvo o que tu deves combinar\nPelo santo matrimônio: quando e onde e como\nNos encontramos, cortejamos e trocamos voto,\nContar-te-ei pelo caminho; mas isto peço,\nQue consintas em casar-nos hoje.","friarlaurenceholysaintfranciswhatachange~hentheresnostrengthinmen~558":"Friar Laurence — Santo São Francisco, que mudança é esta!\nRosaline, a quem amavas tão caro,\nTão depressa abandonada? O amor dos jovens, então,\nNão está de fato no coração, mas nos olhos.\nJesus Maria, que quantidade de salmoura\nLavou tuas faces amareladas por Rosaline!\nQuanta água salgada jogada fora em desperdício,\nPara temperar um amor que não lhe sente o gosto!\nO sol ainda não limpou do céu teus suspiros,\nTeus velhos gemidos ainda ressoam em meus velhos ouvidos;\nVê, aqui na tua face fica a mancha\nDe uma velha lágrima que ainda não foi lavada:\nSe jamais foste tu mesmo e estes pesares teus,\nTu e estes pesares eram todos por Rosaline:\nE estás mudado? Pronuncia então esta sentença:\nAs mulheres podem cair, quando não há força nos homens.","romeothouchidstmeoftforlovingrosaline~stmeoftforlovingrosaline~37":"Romeo — Repreendeste-me muitas vezes por amar Rosaline.","friarlaurencefordotingnotforlovingpupilm~ingnotforlovingpupilmine~43":"Friar Laurence — Por babar-te, não por amar, meu discípulo.","romeoandbadstmeburylove~romeoandbadstmeburylove~23":"Romeo — E mandaste-me enterrar o amor.","friarlaurencenotinagravetolayoneinanothe~layoneinanotherouttohave~50":"Friar Laurence — Não numa sepultura,\nPara pôr um dentro e tirar outro.","romeoipraytheechidenotshewhomilovenowdot~oveallowtheotherdidnotso~89":"Romeo — Peço-te, não repreendas: aquela que amo agora\nDá graça por graça e amor por amor;\nA outra não fazia assim.","friarlaurenceosheknewwellthylovedidreadb~seholdsrancourtopurelove~188":"Friar Laurence — Ó, ela bem sabia\nQue teu amor lia de cor e não sabia soletrar.\nMas vem, jovem vacilante, vem, vai comigo,\nNum ponto serei teu auxiliar;\nPois esta aliança pode ser tão feliz\nQue converta o rancor de vossas casas em puro amor.","romeooletushenceistandonsuddenhaste~henceistandonsuddenhaste~35":"Romeo — Ó, partamos daqui; tenho pressa repentina.","friarlaurencewiselyandslowtheystumbletha~stumblethatrunfastexeunt~54":"Friar Laurence — Com sensatez e devagar; tropeçam os que correm depressa. Saem.","mercutiowherethedevilshouldthisromeobeca~eobecamehenothometonight~58":"Mercutio — Onde diabo estará este Romeo?\nNão voltou para casa esta noite?","benvolionottohisfathersispokewithhisman~sfathersispokewithhisman~39":"Benvolio — Não à casa do pai; falei com seu criado.","mercutioahthatsamepalehardheartedwenchth~imsothathewillsurerunmad~83":"Mercutio — Ah, aquela mesma moça pálida e de coração duro, Rosaline,\nAtormenta-o tanto que ele certamente enlouquecerá.","benvoliotybaltthekinsmanofoldcapulethath~alettertohisfathershouse~68":"Benvolio — Tybalt, o parente do velho Capulet,\nMandou uma carta à casa do pai dele.","mercutioachallengeonmylife~rcutioachallengeonmylife~26":"Mercutio — Um desafio, por minha vida.","benvolioromeowillanswerit~envolioromeowillanswerit~25":"Benvolio — Romeo o responderá.","mercutioanymanthatcanwritemayansweralett~canwritemayansweraletter~42":"Mercutio — Qualquer homem que saiba escrever pode responder a uma carta.","benvolionayhewillanswerthelettersmasterh~sterhowhedaresbeingdared~59":"Benvolio — Não, ele responderá ao dono da carta, como ousa, sendo desafiado.","mercutioalaspoorromeoheisalreadydeadstab~sheamantoencountertybalt~179":"Mercutio — Ai, pobre Romeo! Já está morto: apunhalado pelo olho negro de uma moça branca; atravessado de orelha a orelha por uma canção de amor; o próprio pino do coração fendido pela flecha cega do menino cego do arco: e é ele homem para enfrentar Tybalt?","benvoliowhywhatistybalt~benvoliowhywhatistybalt~23":"Benvolio — Ora, que é Tybalt?","mercutiomorethanprinceofcatsicantellyouo~adothepuntoreversothehai~319":"Mercutio — Mais que príncipe dos gatos, posso dizer-te. Ó, ele é o corajoso capitão dos cumprimentos. Luta como se canta música escrita, guarda compasso, distância e proporção; faz-me sua pausa de mínima, um, dois, e o terceiro em teu peito: o próprio açougueiro de um botão de seda, um duelista, um duelista; um cavalheiro da primeiríssima casa, da primeira e da segunda causa: ah, o imortal passado! o punto reverso! o hai!","benvoliothewhat~benvoliothewhat~15":"Benvolio — O quê?","mercutiothepoxofsuchanticlispingaffectin~nchotheirbonestheirbones~324":"Mercutio — Que a peste leve tais fantasistas esquisitos, ciciantes, afetados; esses novos afinadores de sotaques! “Por Jesus, uma ótima lâmina! um homem muito valente! uma muito boa puta!” Ora, não é coisa lamentável, avô, que sejamos assim afligidos por essas moscas estranhas, esses mercadores de moda, esses perdona-mi’s, que tanto se apegam à nova forma que não conseguem sentar à vontade no velho banco? Ó, seus ossos, seus ossos!","benvolioherecomesromeoherecomesromeo~comesromeoherecomesromeo~36":"Benvolio — Aí vem Romeo, aí vem Romeo.","mercutiowithouthisroelikeadriedherringof~unterfeitfairlylastnight~362":"Mercutio — Sem sua ova, como arenque seco: ó carne, carne, como estás peixificada! Agora ele é para os versos em que Petrarca fluiu: Laura, comparada à sua dama, era apenas uma criada de cozinha; ora, ela teve melhor amor para pô-la em rima; Dido uma desmazelada; Cleópatra uma cigana; Helena e Hero desprezíveis e prostitutas; Tisbe um olho cinzento ou coisa assim, mas não vem ao caso. Signor Romeo, bon jour! eis uma saudação francesa para as tuas calças francesas. Deste-nos o falso de modo admirável ontem à noite.","romeogoodmorrowtoyoubothwhatcounterfeitd~atcounterfeitdidigiveyou~50":"Romeo — Bom dia a ambos. Que falso vos dei?","mercutiotheslipsirtheslipcanyounotconcei~theslipcanyounotconceive~42":"Mercutio — O golpe, senhor, o golpe; não consegues conceber?","romeopardongoodmercutiomybusinesswasgrea~ineamanmaystraincourtesy~82":"Romeo — Perdão, bom Mercutio, meu assunto era grande; e em caso como o meu um homem pode forçar a cortesia.","mercutiothatsasmuchastosaysuchacaseasyou~trainsamantobowinthehams~70":"Mercutio — O que equivale a dizer que um caso como o teu obriga um homem a dobrar os jarretes.","romeomeaningtocourtsy~romeomeaningtocourtsy~21":"Romeo — Isto é, a fazer mesura.","mercutiothouhastmostkindlyhitit~othouhastmostkindlyhitit~31":"Mercutio — Acertaste do modo mais gentil.","romeoamostcourteousexposition~amostcourteousexposition~29":"Romeo — Uma exposição cortesíssima.","mercutionayiamtheverypinkofcourtesy~iamtheverypinkofcourtesy~35":"Mercutio — Ora, sou o próprio cravo da cortesia.","romeopinkforflower~romeopinkforflower~18":"Romeo — Cravo de flor.","mercutioright~mercutioright~13":"Mercutio — Exato.","romeowhythenismypumpwellflowered~thenismypumpwellflowered~32":"Romeo — Pois então meu escarpim está bem florido.","mercutiowellsaidfollowmethisjestnowtillt~erthewearingsolesingular~135":"Mercutio — Bem dito: segue-me esta pilhéria até gastares o escarpim, para que, gasta a sola simples dele, a pilhéria permaneça depois da sola solitária.","romeoosinglesoledjestsolelysingularforth~singularforthesingleness~51":"Romeo — Ó pilhéria de sola simples, solitária e singular pela simplicidade.","mercutiocomebetweenusgoodbenvoliomywitsf~sgoodbenvoliomywitsfaint~44":"Mercutio — Mete-te entre nós, bom Benvolio; meu engenho desfalece.","romeoswitchandspursswitchandspursorillcr~chandspursorillcryamatch~47":"Romeo — Chicote e esporas, chicote e esporas; ou gritarei empate.","mercutionayifthywitsrunthewildgoosechase~iwithyouthereforthegoose~148":"Mercutio — Não, se teu engenho corre a caça ao ganso selvagem, desisto, pois tens mais de ganso selvagem num de teus engenhos do que, estou certo, tenho em todos os meus cinco: estive contigo aí pelo ganso?","romeothouwastneverwithmeforanythingwhent~uwastnotthereforthegoose~66":"Romeo — Nunca estiveste comigo por coisa alguma quando não estavas aí pelo ganso.","mercutioiwillbitetheebytheearforthatjest~etheebytheearforthatjest~40":"Mercutio — Morder-te-ei a orelha por essa pilhéria.","romeonaygoodgoosebitenot~romeonaygoodgoosebitenot~24":"Romeo — Não, bom ganso, não mordas.","mercutiothywitisaverybittersweetingitisa~etingitisamostsharpsauce~54":"Mercutio — Teu engenho é uma maçã muito azeda; é um molho picantíssimo.","romeoandisitnotwellservedintoasweetgoose~ellservedintoasweetgoose~40":"Romeo — E não é bem servido a um ganso doce?","mercutiooheresawitofcheverilthatstretche~aninchnarrowtoanellbroad~69":"Mercutio — Ó, eis um engenho de couro de cabrito, que se estica de uma polegada estreito a uma vara de largo!","romeoistretchitoutforthatwordbroadwhicha~heefarandwideabroadgoose~85":"Romeo — Estico-o por causa dessa palavra “largo”; que, somada a ganso, prova que és, de ponta a ponta, um ganso largo.","mercutiowhyisnotthisbetternowthangroanin~wntohidehisbaubleinahole~209":"Mercutio — Ora, isto não é melhor agora do que gemer de amor? Agora és sociável, agora és Romeo; agora és o que és, por arte tanto quanto por natureza: pois esse amor babão é como um grande tolo de nascença, que corre pendendo para cima e para baixo para esconder seu guizo num buraco.","benvoliostoptherestopthere~nvoliostoptherestopthere~26":"Benvolio — Para aí, para aí.","mercutiothoudesirestmetostopinmytaleagai~opinmytaleagainstthehair~50":"Mercutio — Pedes-me que pare minha história contra o pelo.","benvoliothouwouldstelsehavemadethytalela~elsehavemadethytalelarge~43":"Benvolio — Do contrário a terias feito longa.","mercutioothouartdeceivediwouldhavemadeit~ccupytheargumentnolonger~120":"Mercutio — Ó, enganas-te; tê-la-ia feito curta: pois eu chegara ao fundo de minha história; e pretendia, na verdade, não ocupar mais o assunto.","romeoheresgoodlygear~romeoheresgoodlygear~20":"Romeo — Eis bela matéria!","enternurseandpeter~enternurseandpeter~18":"Entram a Ama e Peter.","mercutioasailasail~mercutioasailasail~18":"Mercutio — Uma vela, uma vela!","benvoliotwotwoashirtandasmock~liotwotwoashirtandasmock~29":"Benvolio — Duas, duas; uma camisa e uma anágua.","nursepeter~nursepeter~10":"Nurse — Peter!","peteranon~peteranon~9":"Peter — Já vou!","nursemyfanpeter~nursemyfanpeter~15":"Nurse — Meu leque, Peter.","mercutiogoodpetertohideherfaceforherfans~eforherfansthefairerface~53":"Mercutio — Bom Peter, para esconder-lhe o rosto; pois o leque dela é o rosto mais belo.","nursegodyegoodmorrowgentlemen~godyegoodmorrowgentlemen~29":"Nurse — Deus vos dê bom dia, cavalheiros.","mercutiogodyegooddenfairgentlewoman~yegooddenfairgentlewoman~35":"Mercutio — Deus vos dê boa tarde, bela senhora.","nurseisitgoodden~nurseisitgoodden~16":"Nurse — Já é boa tarde?","mercutiotisnolessitellyouforthebawdyhand~lisnowupontheprickofnoon~72":"Mercutio — Não menos, digo-vos, pois a mão indecente do relógio está agora sobre o ponto do meio-dia.","nurseoutuponyouwhatamanareyou~outuponyouwhatamanareyou~29":"Nurse — Fora daqui! Que homem sois vós!","romeoonegentlewomanthatgodhathmadeforhim~dhathmadeforhimselftomar~49":"Romeo — Um, senhora, que Deus fez para si mesmo estragar.","nursebymytrothitiswellsaidforhimselftoma~ereimayfindtheyoungromeo~99":"Nurse — Por minha fé, está bem dito; “para si mesmo estragar”, disse ele? Cavalheiros, algum de vós pode dizer-me onde posso achar o jovem Romeo?","romeoicantellyoubutyoungromeowillbeolder~thatnameforfaultofaworse~124":"Romeo — Posso dizer-vos; mas o jovem Romeo será mais velho quando o tiverdes achado do que era quando o procurastes: sou o mais jovem desse nome, na falta de pior.","nurseyousaywell~nurseyousaywell~15":"Nurse — Falais bem.","mercutioyeaistheworstwellverywelltookifa~lltookifaithwiselywisely~55":"Mercutio — Ora, o pior é bem? Muito bem apanhado, por minha fé; com sabedoria, com sabedoria.","nurseifyoubehesiridesiresomeconfidencewi~iresomeconfidencewithyou~45":"Nurse — Se sois ele, senhor, desejo ter convosco uma confidência.","benvolioshewillinditehimtosomesupper~illinditehimtosomesupper~36":"Benvolio — Ela vai convidá-lo para alguma ceia.","mercutioabawdabawdabawdsoho~cutioabawdabawdabawdsoho~27":"Mercutio — Uma alcoviteira, uma alcoviteira, uma alcoviteira! Eia!","romeowhathastthoufound~romeowhathastthoufound~22":"Romeo — Que achaste?","mercutionoharesirunlessaharesirinalenten~therswelltodinnerthither~243":"Mercutio — Nenhuma lebre, senhor; a menos que uma lebre, senhor, numa torta de Quaresma, que está um tanto passada e mofada antes de ser consumida. Canta. Uma velha lebre mofada,\nE uma velha lebre mofada,\nÉ muito boa carne na Quaresma:\nMas uma lebre que está mofada\nÉ demais para uma vintena,\nQuando mofa antes de ser consumida. Romeo, vens à casa de teu pai? Iremos jantar lá.","romeoiwillfollowyou~romeoiwillfollowyou~19":"Romeo — Seguir-vos-ei.","mercutiofarewellancientladyfarewellsingi~xeuntmercutioandbenvolio~79":"Mercutio — Adeus, velha senhora; adeus, Cantando. “senhora, senhora, senhora.” Saem Mercutio e Benvolio.","nursemarryfarewelliprayyousirwhatsaucyme~thatwassofullofhisropery~77":"Nurse — Pois adeus! Peço-vos, senhor, que mercador atrevido era esse, tão cheio de suas velhacarias?","romeoagentlemannursethatlovestohearhimse~hanhewillstandtoinamonth~96":"Romeo — Um cavalheiro, ama, que gosta de ouvir-se falar, e dirá mais num minuto do que sustentará num mês.","nurseanaspeakanythingagainstmeilltakehim~navetousemeathispleasure~233":"Nurse — Se ele disser alguma coisa contra mim, eu o abato, ainda que fosse mais vigoroso do que é, e vinte tais Jacks; e se não puder, acharei quem possa. Patife sarnento! Não sou uma de suas raparigas; não sou uma de suas comparsas de faca. E tu também ficas aí parado, e deixas todo patife usar-me a seu bel-prazer?","peterisawnomanuseyouathispleasureifihadm~quarrelandthelawonmyside~154":"Peter — Não vi homem algum usar-vos a seu bel-prazer; se tivesse visto, minha arma teria saído logo, garanto-vos: ouso sacar tão depressa quanto outro homem, se vejo ocasião numa boa briga, e a lei do meu lado.","nursenowaforegodiamsovexedthateveryparta~ewomanandveryweakdealing~387":"Nurse — Agora, perante Deus, estou tão vexada que cada parte de mim estremece. Patife sarnento! Peço-vos, senhor, uma palavra: e como vos disse, minha jovem senhora mandou-me procurar-vos; o que mandou dizer, guardarei comigo: mas primeiro deixai-me dizer-vos que, se a levásseis a um paraíso de tolos, como dizem, seria um modo de proceder muito grosseiro, como dizem: pois a donzela é jovem; e, portanto, se fôsseis falso com ela, na verdade seria coisa má de se oferecer a qualquer donzela, e trato muito baixo.","romeonursecommendmetothyladyandmistressi~mistressiprotestuntothee~55":"Romeo — Ama, recomenda-me à tua senhora e patroa. Protesto-te —","nursegoodheartandifaithiwilltellherasmuc~ordshewillbeajoyfulwoman~70":"Nurse — Bom coração, e, por minha fé, direi a ela tanto: Senhor, Senhor, será uma mulher feliz.","romeowhatwiltthoutellhernursethoudostnot~ernursethoudostnotmarkme~46":"Romeo — Que lhe dirás, ama? Não me ouves.","nurseiwilltellhersirthatyoudoprotestwhic~eitisagentlemanlikeoffer~71":"Nurse — Direi a ela, senhor, que protestais; o que, a meu ver, é uma oferta digna de cavalheiro.","romeobidherdevisesomemeanstocometoshrift~marriedhereisforthypains~124":"Romeo — Manda-a idear\nAlgum meio de vir à confissão esta tarde;\nE ali, na cela de Frei Laurence,\nSerá confessada e casada. Eis por teus esforços.","nursenotrulysirnotapenny~nursenotrulysirnotapenny~24":"Nurse — Não, em verdade, senhor; nem um tostão.","romeogotoisayyoushall~romeogotoisayyoushall~21":"Romeo — Vamos; digo que aceitarás.","nursethisafternoonsirwellsheshallbethere~onsirwellsheshallbethere~40":"Nurse — Esta tarde, senhor? Bem, ela estará lá.","romeoandstaygoodnursebehindtheabbeywallw~llcommendmetothymistress~236":"Romeo — E espera, boa ama, atrás do muro da abadia:\nDentro de uma hora meu criado estará contigo\nE te trará cordas feitas como escada de cordame;\nQue ao alto gávea de minha alegria\nDeve ser meu comboio na noite secreta.\nAdeus; sê fiel, e recompensarei teus esforços:\nAdeus; recomenda-me à tua senhora.","nursenowgodinheavenblesstheeharkyousir~eavenblesstheeharkyousir~38":"Nurse — Agora Deus no céu te abençoe! Ouvi, senhor.","romeowhatsaystthoumydearnurse~whatsaystthoumydearnurse~29":"Romeo — Que dizes, minha cara ama?","nurseisyourmansecretdidyouneerhearsaytwo~eepcounselputtingoneaway~68":"Nurse — Vosso criado é discreto? Nunca ouvistes dizer:\nDois guardam segredo, se um é posto de lado?","romeoiwarranttheemymansastrueassteel~ttheemymansastrueassteel~36":"Romeo — Garanto-te que meu criado é fiel como o aço.","nursewellsirmymistressisthesweetestladyl~omeobeginbothwithaletter~342":"Nurse — Bem, senhor; minha senhora é a dama mais doce — Senhor, Senhor! quando era uma coisinha tagarela: — Ó, há um nobre na cidade, um tal Paris, que de bom grado lançaria a faca a bordo; mas ela, boa alma, preferiria ver um sapo, um verdadeiro sapo, a vê-lo. Eu a irrito às vezes e digo-lhe que Paris é o homem mais apessoado; mas, garanto-vos, quando digo isso, ela fica pálida como qualquer pano do mundo universal. Alecrim e Romeo não começam ambos com a mesma letra?","romeoaynursewhatofthatbothwithanr~rsewhatofthatbothwithanr~33":"Romeo — Sim, ama; que tem isso? Ambos com um R.","nurseahmockerthatsthedogsnamerisfortheno~itwoulddoyougoodtohearit~153":"Nurse — Ah, zombador! esse é o nome do cão; R é para o — Não; sei que começa com outra letra: — e ela tem a mais bela sentença sobre isso, de vós e do alecrim, que vos faria bem ouvir.","romeocommendmetothylady~romeocommendmetothylady~23":"Romeo — Recomenda-me à tua senhora.","nurseayathousandtimesexitromeopeter~usandtimesexitromeopeter~35":"Nurse — Sim, mil vezes. Sai Romeo. Peter!","nursepetertakemyfanandgobeforeandapaceex~ndgobeforeandapaceexeunt~44":"Nurse — Peter, toma meu leque, e vai adiante, e depressa. Saem.","juliettheclockstruckninewhenididsendthen~ndpaleasleadogodshecomes~583":"Juliet — O relógio bateu nove quando mandei a ama;\nEm meia hora prometeu voltar.\nTalvez não consiga encontrá-lo: não é assim.\nÓ, ela é manca! Os arautos do amor deveriam ser pensamentos,\nQue deslizam dez vezes mais rápido que os raios do sol,\nAfugentando sombras sobre colinas carrancudas:\nPor isso pombas de asas ágeis puxam o amor,\nE por isso o veloz Cupido, como o vento, tem asas.\nAgora o sol está no mais alto monte\nDa jornada deste dia, e das nove ao meio-dia\nSão três longas horas, e ela ainda não veio.\nSe tivesse afeições e sangue jovem e quente,\nSeria tão veloz no movimento quanto uma bola;\nMinhas palavras a atirariam a meu doce amor,\nE as dele a mim:\nMas os velhos, muitos se fingem de mortos;\nPesados, lentos, graves e pálidos como chumbo.\nÓ Deus, ela vem!","ohoneynursewhatnewshastthoumetwithhimsen~metwithhimsendthymanaway~51":"Ó doce ama, que novas?\nEncontraste-te com ele? Manda embora teu criado.","nursepeterstayatthegateexitpeter~erstayatthegateexitpeter~32":"Nurse — Peter, fica no portão. Sai Peter.","julietnowgoodsweetnurseolordwhylooksttho~ingittomewithsosouraface~143":"Juliet — Agora, boa doce ama — Ó Senhor, por que pareces triste?\nAinda que as novas sejam tristes, conta-as alegremente;\nSe boas, envergonhas a música das doces novas\nTocando-a para mim com rosto tão azedo.","nurseiamawearygivemeleaveawhilefiehowmyb~esachewhatajaunthaveihad~66":"Nurse — Estou cansada, dá-me licença um instante:\nOra, como me doem os ossos! Que caminhada tive!","julietiwouldthouhadstmybonesandithynewsn~espeakgoodgoodnursespeak~78":"Juliet — Quisera que tivesses meus ossos, e eu tuas novas.\nNão, vamos, peço-te, fala; boa, boa ama, fala.","nursejesuwhathastecanyounotstayawhiledoy~notseethatiamoutofbreath~66":"Nurse — Jesus, que pressa! Não podes esperar um pouco?\nNão vês que estou sem fôlego?","juliethowartthououtofbreathwhenthouhastb~ebesatisfiedistgoodorbad~237":"Juliet — Como estás sem fôlego, quando tens fôlego\nPara dizer-me que estás sem fôlego?\nA desculpa que dás nesta demora\nÉ mais longa que a história que desculpas.\nSão boas ou más tuas novas? Responde a isso;\nDiz uma ou outra, e esperarei os pormenores:\nSatisfaze-me, são boas ou más?","nursewellyouhavemadeasimplechoiceyouknow~odwhathaveyoudinedathome~300":"Nurse — Bem, fizeste uma escolha tola; não sabes escolher um homem: Romeo! Não, ele não; embora seu rosto seja melhor que o de qualquer homem, sua perna supera a de todos; e quanto a uma mão, e um pé, e um corpo, embora não se deva falar deles, são sem comparação: não é a flor da cortesia, mas, garanto, é manso como um cordeiro. Segue teu caminho, moça; serve a Deus. Então, jantaste em casa?","julietnonobutallthisdidiknowbeforewhatsa~eofourmarriagewhatofthat~67":"Juliet — Não, não: mas tudo isso eu já sabia.\nQue diz ele de nosso casamento? Que diz disso?","nurselordhowmyheadacheswhataheadhaveiitb~athwithjauntingupanddown~169":"Nurse — Senhor, como me dói a cabeça! Que cabeça tenho!\nBate como se fosse cair em vinte pedaços.\nMinhas costas do outro lado — Ó, minhas costas, minhas costas!\nMaldito seja teu coração por me mandar por aí,\nPara apanhar a morte de tanto andar para cima e para baixo!","julietifaithiamsorrythatthouartnotwellsw~ursetellmewhatsaysmylove~78":"Juliet — Por minha fé, lamento que não estejas bem.\nDoce, doce, doce ama, dize-me, que diz meu amor?","nurseyourlovesayslikeanhonestgentlemanan~irtuouswhereisyourmother~108":"Nurse — Vosso amor diz, como honesto cavalheiro, e cortês, e bondoso, e belo, e, garanto, virtuoso — Onde está vossa mãe?","julietwhereismymotherwhysheiswithinwhere~ntlemanwhereisyourmother~121":"Juliet — Onde está minha mãe! Ora, está lá dentro;\nOnde deveria estar? Que resposta estranha!\n“Vosso amor diz, como honesto cavalheiro,\nOnde está vossa mãe?”","nurseogodsladydearareyousohotmarrycomeup~rddoyourmessagesyourself~112":"Nurse — Ó cara senhora de Deus!\nEstás tão quente? Ora, vamos, creio;\nÉ este o emplastro para meus ossos doloridos?\nDaqui por diante faze tu mesma tuas mensagens.","julietheressuchacoilcomewhatsaysromeo~chacoilcomewhatsaysromeo~37":"Juliet — Que alvoroço! Vamos, que diz Romeo?","nursehaveyougotleavetogotoshrifttoday~otleavetogotoshrifttoday~37":"Nurse — Obtiveste licença para ir à confissão hoje?","julietihave~julietihave~11":"Juliet — Obtive.","nursethenhieyouhencetofriarlaurencecellt~ltodinnerhieyoutothecell~332":"Nurse — Então corre à cela de Frei Laurence;\nAli espera um marido para fazer de ti uma esposa:\nAgora sobe o sangue travesso às tuas faces,\nQue ficarão escarlates logo a qualquer notícia.\nCorre à igreja; devo ir por outro lado,\nBuscar uma escada, pela qual teu amor\nDeve subir a um ninho de pássaro logo que escurecer:\nSou a escrava e a labuta de teu deleite,\nMas tu levarás o fardo logo à noite.\nVai; vou jantar; corre à cela.","juliethietohighfortunehonestnursefarewel~onestnursefarewellexeunt~47":"Juliet — Corro à alta fortuna! Honesta ama, adeus. Saem.","scenevi~scenevi~7":"Cena VI","enterfriarlaurenceandromeo~terfriarlaurenceandromeo~26":"Entram Frei Laurence e Romeo.","friarlaurencesosmiletheheavensuponthisho~ourswithsorrowchideusnot~79":"Friar Laurence — Assim sorriam os céus a este santo ato,\nQue as horas futuras não nos repreendam com pesar!","romeoamenamenbutcomewhatsorrowcanitcanno~enoughimaybutcallhermine~200":"Romeo — Amém, amém! Mas venha que pesar vier,\nNão pode contrabalançar a troca de alegria\nQue um só breve minuto me dá na vista dela:\nBasta que unas nossas mãos com palavras santas,\nE então a morte devoradora de amor faça o que ousar;\nBasta-me que eu possa chamá-la minha.","friarlaurencetheseviolentdelightshavevio~tarrivesastardyastooslow~256":"Friar Laurence — Estes deleites violentos têm fins violentos\nE em seu triunfo morrem, como fogo e pólvora,\nQue ao se beijarem se consomem: o mais doce mel\nÉ repugnante em sua própria delícia\nE no gosto confunde o apetite:\nPortanto, ama com moderação; o amor duradouro assim faz;\nChegar depressa demais é tão tardio quanto demasiado lento.","herecomestheladyosolightafootwillneerwea~etnotfallsolightisvanity~148":"Aí vem a dama: ó, pé tão leve\nNunca gastará a eterna pedra:\nUm amante pode cavalgar o fio de teia de aranha\nQue vagueia no travesso ar de verão,\nE contudo não cair; tão leve é a vaidade.","julietgoodeventomyghostlyconfessor~eventomyghostlyconfessor~34":"Juliet — Boa tarde a meu confessor espiritual.","friarlaurenceromeoshallthanktheedaughter~anktheedaughterforusboth~49":"Friar Laurence — Romeo te agradecerá, filha, por nós dois.","julietasmuchtohimelseishisthankstoomuch~imelseishisthankstoomuch~39":"Juliet — Outro tanto a ele, senão seus agradecimentos são demais.","romeoahjulietifthemeasureofthyjoybeheapd~itherbythisdearencounter~209":"Romeo — Ah, Juliet, se a medida de tua alegria\nEstá tão cheia quanto a minha, e se tens mais arte\nPara proclamá-la, adoça então com teu hálito\nEste ar vizinho, e deixa que a língua da rica música\nDesdobre a felicidade imaginada que ambos\nRecebemos um do outro neste caro encontro.","julietconceitmorerichinmatterthaninwords~otsumupsumofhalfmywealth~172":"Juliet — O pensamento, mais rico em matéria que em palavras,\nGaba-se de sua substância, não de ornamento:\nSó são mendigos os que podem contar seu valor;\nMas meu verdadeiro amor cresceu a tal excesso\nQue não posso somar a soma da metade de minha riqueza.","friarlaurencecomecomewithmeandwewillmake~ncorporatetwoinoneexeunt~123":"Friar Laurence — Vinde, vinde comigo, e faremos curto trabalho;\nPois, com vossa licença, não ficareis a sós\nAté que a santa igreja incorpore dois em um. Saem.","apublicplace~apublicplace~12":"Uma praça pública.","entermercutiobenvoliopageandservants~obenvoliopageandservants~36":"Entram Mercúcio, Benvólio, o Pajem e Criados.","benvolioipraytheegoodmercutioletsretiret~aysisthemadbloodstirring~138":"Benvólio — Peço-te, bom Mercúcio, vamos nos retirar:\nO dia está quente, os Capuletos andam soltos,\nE, se os encontrarmos, não escaparemos a uma briga;\nPois nestes dias de calor o sangue louco se agita.","mercutiothouartlikeoneofthosefellowsthat~rwhenindeedthereisnoneed~199":"Mercúcio — Tu és como aqueles sujeitos que, ao entrar nos limites de uma taverna, batem a espada na mesa e dizem “Deus me livre de precisar de ti!” e, pela ação do segundo copo, a sacam contra o taberneiro, quando na verdade não há necessidade alguma.","benvolioamilikesuchafellow~nvolioamilikesuchafellow~26":"Benvólio — Sou eu parecido com um sujeito desses?","mercutiocomecomethouartashotajackinthymo~yandassoonmoodytobemoved~100":"Mercutio — Ora, ora, és tão esquentado quanto qualquer valentão da Itália, e tão depressa te enfureces quanto depressa a fúria te move.","benvolioandwhatto~benvolioandwhatto~17":"Benvólio — E a quê?","mercutionayanthereweretwosuchweshouldhav~lttutormefromquarrelling~624":"Mercutio — Ora, se houvesse dois como tu, em breve não teríamos nenhum, pois um mataria o outro. Tu! Ora, tu brigarias com um homem que tivesse um fio a mais, ou um fio a menos, na barba do que tu tens; brigarias com um homem por quebrar nozes, sem outra razão senão a de teres olhos castanhos: que olho, a não ser um olho assim, farejaria uma briga dessas? Tua cabeça está tão cheia de brigas quanto um ovo está cheio de gema, e no entanto tua cabeça já foi batida até ficar podre como um ovo de tanto brigar: brigaste com um homem por tossir na rua, porque ele acordou teu cão que dormia ao sol; não foi contigo que um alfaiate se desentendeu por usar o gibão novo antes da Páscoa? e outro, por amarrar os sapatos novos com fita velha? e ainda assim queres me dar lições contra brigas!","benvolioaniweresoapttoquarrelasthouartan~lifeforanhourandaquarter~93":"Benvólio — Se eu fosse tão afeito a brigas como tu, qualquer um compraria a posse plena da minha vida por uma hora e um quarto.","mercutiothefeesimpleosimple~cutiothefeesimpleosimple~27":"Mercutio — A posse plena! Ó simplório!","benvoliobymyheadherecomethecapulets~yheadherecomethecapulets~35":"Benvólio — Por minha cabeça, aí vêm os Capuletos.","mercutiobymyheelicarenot~mercutiobymyheelicarenot~24":"Mercutio — Por meu calcanhar, não me importo.","entertybaltandothers~entertybaltandothers~20":"Entram Teobaldo e outros.","tybaltfollowmecloseforiwillspeaktothemge~gooddenawordwithoneofyou~71":"Teobaldo — Segui-me de perto, pois vou falar com eles. Senhores, boa tarde: uma palavra com um de vós.","mercutioandbutonewordwithoneofuscoupleit~thingmakeitawordandablow~72":"Mercutio — Apenas uma palavra com um de nós? Acrescentai-lhe algo; que seja uma palavra e um golpe.","tybaltyoushallfindmeaptenoughtothatsiran~ranyouwillgivemeoccasion~61":"Teobaldo — Achareis em mim disposição bastante para isso, senhor, se me derdes ocasião.","mercutiocouldyounottakesomeoccasionwitho~omeoccasionwithoutgiving~48":"Mercutio — Não podíeis tomar uma ocasião sem que ela vos seja dada?","tybaltmercutiothouconsortstwithromeo~iothouconsortstwithromeo~36":"Teobaldo — Mercúcio, tu te acompanhas de Romeu—","mercutioconsortwhatdostthoumakeusminstre~akeyoudancezoundsconsort~150":"Mercutio — Acompanhas! Ora, nos fazes menestréis? Se fizeres menestréis de nós, espera ouvir apenas dissonâncias: eis meu arco de rabeca; eis o que vai fazer-te dançar. Pelas chagas, acompanhas!","benvoliowetalkhereinthepublichauntofmene~epartherealleyesgazeonus~135":"Benvólio — Falamos aqui no ponto de encontro público dos homens:\nOu retirai-vos para algum lugar reservado,\nE discuti friamente vossas queixas,\nOu então ide embora; aqui todos os olhos nos fitam.","mercutiomenseyesweremadetolookandletthem~tbudgefornomanspleasurei~75":"Mercutio — Os olhos dos homens foram feitos para olhar, e que olhem;\nEu não saio do lugar por gosto de homem nenhum, eu não.","tybaltwellpeacebewithyousirherecomesmyma~withyousirherecomesmyman~41":"Teobaldo — Bem, a paz esteja convosco, senhor: eis que chega o meu homem.","mercutiobutillbehangdsirifhewearyourlive~inthatsensemaycallhimman~115":"Mercutio — Mas que me enforquem, senhor, se ele usar vossa libré:\nPor Nossa Senhora, ide na frente ao campo, e ele vos seguirá;\nNesse sentido vossa senhoria pode chamá-lo de “homem”.","tybaltromeothehateibeartheecanaffordnobe~mthanthisthouartavillain~71":"Teobaldo — Romeu, o ódio que te tenho não pode dar\nMelhor nome do que este: és um canalha.","romeotybaltthereasonthatihavetolovetheed~ewelliseethouknowstmenot~137":"Romeu — Teobaldo, a razão que tenho para te amar\nDesculpa em muito a ira própria\nA tal saudação: canalha não sou;\nPortanto, adeus; vejo que não me conheces.","tybaltboythisshallnotexcusetheinjuriesth~nemethereforeturnanddraw~76":"Teobaldo — Rapaz, isto não desculpará as ofensas\nQue me fizeste; portanto, vira-te e saca.","romeoidoprotestineverinjuredtheebutlovet~dearlyasmyownbesatisfied~160":"Romeu — Protesto que nunca te ofendi,\nMas te amo mais do que podes imaginar,\nAté que saibas a razão do meu amor:\nE assim, bom Capuleto — nome que estimo\nTanto quanto o meu —, dá-te por satisfeito.","mercutioocalmdishonourablevilesubmission~youratcatcherwillyouwalk~100":"Mercutio — Ó calma, desonrosa, vil submissão!\nO alla stoccata leva a melhor. Saca a espada.\nTeobaldo, caçador de ratos, queres vir passear?","tybaltwhatwouldstthouhavewithme~hatwouldstthouhavewithme~31":"Teobaldo — Que queres de mim?","mercutiogoodkingofcatsnothingbutoneofyou~eaboutyourearsereitbeout~213":"Mercutio — Bom rei dos gatos, nada além de uma das tuas nove vidas; pretendo tomá-la com ousadia e, conforme me tratares depois, surrar as outras oito. Quereis arrancar a espada da bainha pelas orelhas? Apressai-vos, para que a minha não vos zumbam nas orelhas antes que a vossa saia.","tybaltiamforyoudrawing~tybaltiamforyoudrawing~22":"Teobaldo — Estou a vosso dispor. Saca a espada.","romeogentlemercutioputthyrapierup~lemercutioputthyrapierup~33":"Romeu — Gentil Mercúcio, guarda a tua rapieira.","mercutiocomesiryourpassadotheyfight~esiryourpassadotheyfight~35":"Mercutio — Vamos, senhor, mostrai o vosso passado. Lutam.","romeodrawbenvoliobeatdowntheirweaponsgen~andflieswithhisfollowers~219":"Romeu — Saca, Benvólio; abatamos-lhes as armas.\nSenhores, vergonha, detende esta afronta!\nTeobaldo, Mercúcio, o príncipe expressamente\nProibiu as rixas nas ruas de Verona:\nParai, Teobaldo! Bom Mercúcio! Teobaldo, por baixo do braço de Romeu, fere Mercúcio e foge com seus seguidores.","mercutioiamhurtaplagueobothyourhousesiam~edishegoneandhathnothing~66":"Mercutio — Estou ferido.\nUma peste sobre as duas casas! Estou liquidado.\nEle se foi, e não leva nada?","benvoliowhatartthouhurt~benvoliowhatartthouhurt~23":"Benvólio — Quê, estás ferido?","mercutioayayascratchascratchmarrytisenou~ainfetchasurgeonexitpage~85":"Mercutio — Sim, sim, um arranhão, um arranhão; pois é, basta.\nOnde está meu pajem? Vai, patife, busca um cirurgião. Sai o Pajem.","romeocouragemanthehurtcannotbemuch~gemanthehurtcannotbemuch~34":"Romeu — Coragem, homem; o ferimento não pode ser grande.","mercutionotisnotsodeepasawellnorsowideas~enusiwashurtunderyourarm~313":"Mercutio — Não, não é fundo como um poço, nem largo como a porta de uma igreja; mas basta, vai servir: perguntai por mim amanhã e me achareis um homem grave. Estou pimentado, garanto, para este mundo. Uma peste sobre as duas casas! Pelas chagas, um cão, um rato, um camundongo, um gato, para arranhar um homem até a morte! Um fanfarrão, um biltre, um canalha, que luta pelo livro de aritmética! Que diabo vos fez meter entre nós? Fui ferido por baixo do teu braço.","romeoithoughtallforthebest~meoithoughtallforthebest~26":"Romeu — Pensei que era pelo melhor.","mercutiohelpmeintosomehousebenvolioorish~xeuntmercutioandbenvolio~150":"Mercutio — Ajuda-me a entrar em alguma casa, Benvólio,\nOu desmaiarei. Uma peste sobre as duas casas!\nFizeram de mim comida de vermes: já a tenho,\nE bem firme: vossas casas! Saem Mercúcio e Benvólio.","romeothisgentlemantheprincesnearallymyve~empersoftendvalourssteel~220":"Romeu — Este cavalheiro, parente próximo do príncipe,\nMeu verdadeiro amigo, recebeu seu ferimento mortal\nEm minha defesa; minha reputação manchada\nPela calúnia de Teobaldo — Teobaldo, que há uma hora\nÉ meu parente! Ó doce Julieta,\nTua beleza me tornou efeminado\nE em meu temperamento amoleceu o aço da bravura!","reenterbenvolio~reenterbenvolio~15":"Reentra Benvólio.","benvoliooromeoromeobravemercutiosdeadtha~melyheredidscorntheearth~110":"Benvólio — Ó Romeu, Romeu, o bravo Mercúcio está morto!\nAquele espírito galante subiu às nuvens,\nQue cedo demais desdenhou aqui a terra.","romeothisdaysblackfateonmoredaysdothdepe~eginsthewoeothersmustend~74":"Romeu — O negro destino deste dia pesa sobre outros dias;\nIsto apenas começa a desgraça que outros hão de terminar.","benvolioherecomesthefurioustybaltbackaga~hefurioustybaltbackagain~42":"Benvólio — Eis que volta o furioso Teobaldo.","romeoaliveintriumphandmercutioslainawayt~reeyedfurybemyconductnow~92":"Romeu — Vivo, em triunfo! E Mercúcio morto!\nIde para o céu, prudente clemência,\nE que a fúria de olhos de fogo seja agora minha guia!","reentertybalt~reentertybalt~13":"Reentra Teobaldo.","nowtybalttakethevillainbackagainthatlate~ouoriorbothmustgowithhim~159":"Agora, Teobaldo, toma de volta o nome de canalha\nQue há pouco me deste; pois a alma de Mercúcio\nEstá apenas um pouco acima de nossas cabeças,\nEsperando a tua para lhe fazer companhia:\nOu tu, ou eu, ou ambos, devemos ir com ele.","tybaltthouwretchedboythatdidstconsorthim~himhereshaltwithhimhence~61":"Teobaldo — Tu, miserável rapaz, que aqui o acompanhaste,\nIrás daqui com ele.","romeothisshalldeterminethattheyfighttyba~thattheyfighttybaltfalls~47":"Romeu — Isto decidirá a questão. Lutam; Teobaldo cai.","benvolioromeoawaybegonethecitizensareupa~uarttakenhencebegoneaway~122":"Benvólio — Romeu, vai-te, foge!\nOs cidadãos se levantaram, e Teobaldo está morto.\nNão fiques atônito: o príncipe te condenará à morte\nSe fores preso: foge, vai-te, some!","romeooiamfortunesfool~romeooiamfortunesfool~21":"Romeu — Ó, sou o bobo da fortuna!","benvoliowhydostthoustayexitromeo~whydostthoustayexitromeo~32":"Benvólio — Por que ficas? Sai Romeu.","entercitizensetc~entercitizensetc~16":"Entram Cidadãos etc.","firstcitizenwhichwayranhethatkilldmercut~hatmurdererwhichwayranhe~73":"Primeiro Cidadão — Por onde fugiu aquele que matou Mercúcio?\nTeobaldo, aquele assassino, por onde fugiu?","benvoliothereliesthattybalt~voliothereliesthattybalt~27":"Benvólio — Ali jaz esse Teobaldo.","firstcitizenupsirgowithmeichargetheeinth~theeintheprincesnameobey~56":"Primeiro Cidadão — De pé, senhor, vinde comigo;\nIntimo-vos em nome do príncipe, obedecei.","enterprinceattendedmontaguecapulettheirw~pulettheirwivesandothers~53":"Entram o Príncipe, acompanhado; Montéquio, Capuleto, suas Esposas e outros.","princewherearethevilebeginnersofthisfray~evilebeginnersofthisfray~40":"Príncipe — Onde estão os vis causadores desta contenda?","benvolioonobleprinceicandiscoveralltheun~wthykinsmanbravemercutio~130":"Benvólio — Ó nobre príncipe, posso revelar tudo\nSobre o infeliz desenrolar desta briga fatal:\nAli jaz o homem, morto pelo jovem Romeu,\nQue matou teu parente, o bravo Mercúcio.","ladycapulettybaltmycousinomybrotherschil~dofmontagueocousincousin~158":"Lady Capuleto — Teobaldo, meu sobrinho! Ó filho do meu irmão!\nÓ príncipe! Ó sobrinho! Marido! Ó, o sangue é derramado\nDo meu querido parente! Príncipe, se és justo,\nPelo sangue nosso, derrama sangue de Montéquio.\nÓ sobrinho, sobrinho!","princebenvoliowhobeganthisbloodyfray~iowhobeganthisbloodyfray~36":"Príncipe — Benvólio, quem começou esta sangrenta contenda?","benvoliotybalthereslainwhomromeoshanddid~thetruthorletbenvoliodie~820":"Benvólio — Teobaldo, aqui morto, a quem a mão de Romeu matou;\nRomeu, que lhe falou com cortesia, pediu-lhe que refletisse\nComo era fútil a querela, e lembrou-lhe ainda\nO vosso alto desagrado: tudo isso dito\nCom voz gentil, olhar sereno, joelhos humildemente dobrados,\nNão pôde trazer trégua ao ânimo indócil\nDe Teobaldo, surdo à paz, que investe\nCom aço penetrante contra o peito do audaz Mercúcio,\nQue, igualmente aceso, volta ponta mortal contra ponta,\nE, com marcial desdém, com uma das mãos afasta\nA morte fria e com a outra a devolve\nA Teobaldo, cuja destreza\nA rebate: Romeu grita em voz alta,\n“Parai, amigos! Amigos, separai!” e, mais veloz que a língua,\nSeu braço ágil abate as pontas fatais\nE se lança entre eles; sob cujo braço\nUma estocada invejosa de Teobaldo atingiu a vida\nDo forte Mercúcio, e então Teobaldo fugiu;\nMas logo volta a Romeu,\nQue acabava de acolher a vingança,\nE ao combate partem como um relâmpago, pois, antes que eu\nPudesse sacar para separá-los, o forte Teobaldo estava morto,\nE, quando ele caiu, Romeu se virou e fugiu.\nEsta é a verdade, ou que Benvólio morra.","ladycapuletheisakinsmantothemontagueaffe~ewtybaltromeomustnotlive~216":"Lady Capuleto — Ele é parente dos Montéquios;\nA afeição o faz falso; ele não diz a verdade:\nUns vinte deles lutaram nesta negra contenda,\nE todos esses vinte só puderam matar uma vida.\nPeço justiça, que tu, príncipe, deves dar;\nRomeu matou Teobaldo, Romeu não deve viver.","princeromeoslewhimheslewmercutiowhonowth~iceofhisdearblooddothowe~67":"Príncipe — Romeu o matou, ele matou Mercúcio;\nQuem agora deve o preço de seu precioso sangue?","montaguenotromeoprincehewasmercutiosfrie~shouldendthelifeoftybalt~96":"Montéquio — Não Romeu, príncipe, ele era amigo de Mercúcio;\nSua culpa apenas conclui o que a lei deveria encerrar,\nA vida de Teobaldo.","princeandforthatoffenceimmediatelywedoex~oningthosethatkillexeunt~409":"Príncipe — E por essa ofensa\nImediatamente o exilamos daqui:\nTenho interesse no andamento de vosso ódio,\nMeu sangue por vossas rudes brigas jaz a sangrar;\nMas vos imporei multa tão pesada\nQue todos vos arrependereis da perda do meu:\nSerei surdo a súplicas e desculpas;\nNem lágrimas nem preces comprarão a absolvição dos abusos:\nPortanto não as useis: que Romeu parta depressa,\nOu, quando for achado, aquela hora será a sua última.\nLevai este corpo e esperai nossa vontade:\nA clemência só assassina, ao perdoar os que matam. Saem.","julietgallopapaceyoufieryfootedsteedstow~espeaksheavenlyeloquence~1109":"Julieta — Galopai depressa, corcéis de pés de fogo,\nRumo à morada de Febo: um cocheiro como\nFaetonte vos chicotearia para o poente\nE traria de imediato a noite nublada.\nEstende tua cortina cerrada, noite que favoreces o amor,\nPara que os olhos dos fugitivos se fechem, e Romeu\nSalte a estes braços, sem ser comentado nem visto.\nOs amantes podem enxergar para cumprir seus ritos amorosos\nPela luz de suas próprias belezas; ou, se o amor é cego,\nCombina melhor com a noite. Vem, noite cortês,\nMatrona de traje sóbrio, toda de preto,\nE ensina-me a perder uma partida ganha,\nJogada por um par de virgindades imaculadas:\nCobre meu sangue indomado, que bate em minhas faces,\nCom teu manto negro; até que o amor estranho, tornado ousado,\nPense que o amor verdadeiro foi simples recato.\nVem, noite; vem, Romeu; vem, tu, dia na noite;\nPois repousarás sobre as asas da noite\nMais branco que neve nova nas costas de um corvo.\nVem, gentil noite, vem, amorosa noite de fronte escura,\nDá-me meu Romeu; e, quando ele morrer,\nToma-o e recorta-o em pequenas estrelas,\nE ele fará a face do céu tão bela\nQue o mundo inteiro se enamorará da noite\nE não prestará culto ao sol espalhafatoso.\nÓ, comprei a mansão de um amor,\nMas não a possuí, e, embora eu esteja vendida,\nAinda não fui desfrutada: tão tedioso é este dia\nQuanto a noite que precede uma festa\nPara uma criança impaciente que tem roupas novas\nE não pode vesti-las. Ó, eis que vem minha ama,\nE traz notícias; e toda língua que fala\nSó o nome de Romeu fala com eloquência celestial.","enternursewithcords~enternursewithcords~19":"Entra a Ama, com as cordas.","nownursewhatnewswhathastthoutherethecord~rdsthatromeobidtheefetch~62":"Agora, ama, que notícias? Que tens aí? As cordas\nQue Romeu mandou que buscasses?","nurseayaythecordsthrowsthemdown~aythecordsthrowsthemdown~31":"Ama — Sim, sim, as cordas. Joga-as ao chão.","julietaymewhatnewswhydostthouwringthyhan~whydostthouwringthyhands~42":"Julieta — Ai de mim! Que notícias? Por que torces as mãos?","nurseahwelladayhesdeadhesdeadhesdeadwear~ayhesgoneheskilldhesdead~95":"Ama — Ah, que dia! Ele está morto, está morto, está morto!\nEstamos perdidas, senhora, estamos perdidas!\nAi, que dia! Ele se foi, foi morto, está morto!","julietcanheavenbesoenvious~lietcanheavenbesoenvious~26":"Julieta — Pode o céu ser tão invejoso?","nurseromeocanthoughheavencannotoromeorom~rwouldhavethoughtitromeo~72":"Ama — Romeu pode,\nEmbora o céu não possa: ó Romeu, Romeu!\nQuem jamais teria pensado nisso? Romeu!","julietwhatdevilartthouthatdosttormentmet~dsdetermineofmywealorwoe~291":"Julieta — Que demônio és tu, que assim me atormentas?\nEsta tortura deveria ser rugida no sombrio inferno.\nRomeu se matou? Diz apenas “sim”,\nE essa simples vogal “sim” envenenará mais\nQue o olhar mortífero do basilisco:\nNão sou eu, se existir tal “eu”;\nOu se se fecharem os olhos que te fazem responder “sim”.\nSe ele foi morto, diz “sim”; se não, diz não:\nSons breves decidem meu bem ou meu mal.","nurseisawthewoundisawitwithmineeyesgodsa~bloodiswoundedatthesight~166":"Ama — Vi a ferida, vi-a com meus olhos —\nDeus guarde a marca! — aqui em seu peito viril:\nUm cadáver lastimável, um cadáver sangrento e lastimável;\nPálido, pálido como cinzas, todo lambuzado de sangue,\nTodo em sangue coagulado; desmaiei à vista.","julietobreakmyheartpoorbankruptbreakaton~ndromeopressoneheavybier~138":"Julieta — Ó, parte-te, meu coração! Pobre falido, parte-te de uma vez!\nPara a prisão, olhos, jamais olheis a liberdade!\nVil terra, à terra te entrega; acaba aqui o movimento;\nE tu e Romeu sustentai um só pesado esquife!","nurseotybalttybaltthebestfriendihadocour~ishouldlivetoseetheedead~98":"Ama — Ó Teobaldo, Teobaldo, o melhor amigo que eu tinha!\nÓ cortês Teobaldo! Honesto cavalheiro!\nQue eu vivesse para ver-te morto!","julietwhatstormisthisthatblowssocontrary~slivingifthosetwoaregone~173":"Julieta — Que tempestade é esta que sopra tão contrária?\nRomeu foi trucidado, e Teobaldo está morto?\nMeu querido primo, e meu mais querido senhor?\nEntão, trombeta terrível, soa o juízo final!\nPois quem vive, se aqueles dois se foram?","nursetybaltisgoneandromeobanishedromeoth~thatkilldhimheisbanished~62":"Ama — Teobaldo se foi, e Romeu foi banido;\nRomeu, que o matou, foi banido.","julietogoddidromeoshandshedtybaltsblood~meoshandshedtybaltsblood~39":"Julieta — Ó Deus! A mão de Romeu derramou o sangue de Teobaldo?","nurseitdiditdidalasthedayitdid~tdiditdidalasthedayitdid~30":"Ama — Derramou, derramou; ai, que dia, derramou!","julietoserpenthearthidwithafloweringface~ellinsuchagorgeouspalace~416":"Julieta — Ó coração de serpente, oculto sob um rosto florido!\nJamais um dragão guardou caverna tão bela?\nTirano formoso! Demônio angelical!\nCorvo de plumas de pomba! Cordeiro de voracidade lupina!\nSubstância desprezível de aparência divina!\nExato oposto do que justamente pareces,\nSanto danado, vilão honrado!\nÓ natureza, que tinhas a ver com o inferno,\nQuando alojaste o espírito de um demônio\nNo paraíso mortal de tão doce carne?\nJamais existiu livro com tal matéria vil\nTão belamente encadernado? Ó, que a fraude deva habitar\nNum palácio tão magnífico!","nursetheresnotrustnofaithnohonestyinmena~akemeoldshamecometoromeo~173":"Ama — Não há confiança,\nNem fé, nem honestidade nos homens; todos perjuros,\nTodos falsos, todos imprestáveis, todos dissimulados.\nAh, onde está meu criado? Dá-me um pouco de aguardente:\nEstas dores, estes males, estas tristezas me envelhecem.\nVergonha caia sobre Romeu!","julietblisterdbethytongueforsuchawishhew~atabeastwasitochideathim~178":"Julieta — Que tua língua se encha de bolhas\nPor tal desejo! Ele não nasceu para a vergonha:\nEm sua fronte a vergonha tem vergonha de sentar-se;\nPois é um trono onde a honra pode ser coroada\nMonarca único da terra universal.\nÓ, que animal fui eu ao repreendê-lo!","nursewillyouspeakwellofhimthatkilldyourc~ofhimthatkilldyourcousin~45":"Ama — Falareis bem daquele que matou vosso primo?","julietshallispeakillofhimthatismyhusband~myfatherandmymothernurse~1053":"Julieta — Falarei mal daquele que é meu marido?\nAh, pobre senhor meu, que língua suavizará teu nome,\nQuando eu, tua esposa de três horas, o dilacerei?\nMas por que, vilão, mataste meu primo?\nAquele primo vilão teria matado meu marido:\nVoltai, tolas lágrimas, voltai à fonte natal;\nVossas gotas tributárias pertencem à dor,\nE vós, enganadas, as oferecéis à alegria.\nMeu marido vive, que Teobaldo queria matar;\nE Teobaldo está morto, que queria matar meu marido:\nTudo isso é consolo; por que então choro?\nHouve uma palavra, pior que a morte de Teobaldo,\nQue me assassinou: eu a esqueceria de bom grado;\nMas, ó, ela se crava em minha memória,\nComo ações danadas e culpadas na mente dos pecadores:\n“Teobaldo está morto, e Romeu — banido”;\nEsse “banido”, essa única palavra “banido”,\nMatou dez mil Teobaldos. A morte de Teobaldo\nJá era dor bastante, se tivesse parado ali:\nOu, se a amarga dor se compraz em companhia\nE necessariamente quer se alinhar a outras mágoas,\nPor que não se seguiu, quando ela disse “Teobaldo está morto”,\n“Teu pai”, ou “tua mãe”, ou até ambos,\nO que lamentações comuns teriam comovido?\nMas, com uma retaguarda seguindo a morte de Teobaldo,\n“Romeu está banido”, pronunciar essa palavra\nÉ pai, mãe, Teobaldo, Romeu, Julieta,\nTodos mortos, todos finados. “Romeu está banido!”\nNão há fim, nem limite, medida, fronteira\nNa morte dessa palavra; nenhuma palavra pode sondar essa dor.\nOnde estão meu pai e minha mãe, ama?","nurseweepingandwailingovertybaltscorsewi~themiwillbringyouthither~73":"Ama — Chorando e gemendo sobre o cadáver de Teobaldo:\nQuereis ir até eles? Eu vos levo até lá.","julietwashtheyhiswoundswithtearsmineshal~notromeotakemymaidenhead~268":"Julieta — Que lavem as feridas dele com lágrimas: as minhas serão gastas\nQuando as deles secarem, pelo banimento de Romeu.\nRecolhe essas cordas: pobres cordas, fostes enganadas,\nVós e eu; pois Romeu está exilado:\nEle vos fez para ser uma estrada ao meu leito;\nMas eu, donzela, morro donzela e viúva.\nVinde, cordas, vem, ama; irei para o leito nupcial;\nE que a morte, não Romeu, tome a minha virgindade!","nursehietoyourchamberillfindromeotocomfo~himheishidatlaurencecell~123":"Ama — Correi ao vosso quarto: acharei Romeu\nPara vos consolar: sei bem onde ele está.\nEscutai, vosso Romeu virá aqui à noite:\nIrei até ele; está escondido na cela de Frei Lourenço.","julietofindhimgivethisringtomytrueknight~akehislastfarewellexeunt~80":"Julieta — Ó, encontra-o! Dá este anel ao meu fiel cavaleiro,\nE pede-lhe que venha dar o último adeus. Saem.","enterfriarlaurence~enterfriarlaurence~18":"Entra Frei Lourenço.","friarlaurenceromeocomeforthcomeforththou~dthouartweddedtocalamity~106":"Frei Lourenço — Romeu, sai; sai, homem temeroso:\nA aflição está enamorada de tuas qualidades,\nE tu estás casado com a calamidade.","romeofatherwhatnewswhatistheprincesdoomw~eatmyhandthatiyetknownot~90":"Romeu — Padre, que notícias? Qual é a sentença do príncipe?\nQue mágoa pede conhecimento de minha mão\nQue eu ainda não conheça?","friarlaurencetoofamiliarismydearsonwiths~etidingsoftheprincesdoom~87":"Frei Lourenço — Demasiado familiar\nÉ meu querido filho com tão amarga companhia:\nTraga-te notícias da sentença do príncipe.","romeowhatlessthandoomsdayistheprincesdoo~doomsdayistheprincesdoom~41":"Romeu — Que menos que o juízo final é a sentença do príncipe?","friarlaurenceagentlerjudgmentvanishdfrom~sdeathbutbodysbanishment~78":"Frei Lourenço — Um julgamento mais brando saiu de seus lábios,\nNão a morte do corpo, mas o banimento do corpo.","romeohabanishmentbemercifulsaydeathforex~ndeathdonotsaybanishment~101":"Romeu — Ah, banimento! Sê misericordioso, diz “morte”;\nPois o exílio tem mais terror no aspecto,\nMuito mais que a morte: não digas “banimento”.","friarlaurencehencefromveronaartthoubanis~ortheworldisbroadandwide~77":"Frei Lourenço — Daqui de Verona estás banido:\nTem paciência, pois o mundo é largo e vasto.","romeothereisnoworldwithoutveronawallsbut~onthestrokethatmurdersme~239":"Romeu — Não há mundo fora dos muros de Verona,\nSenão purgatório, tortura, o próprio inferno.\nBanido daqui é banido do mundo,\nE exílio do mundo é morte: portanto banimento\nÉ morte com nome trocado: chamando a morte de banimento,\nCortas minha cabeça com um machado de ouro\nE sorris ao golpe que me assassina.","friarlaurenceodeadlysinorudeunthankfulne~armercyandthouseestitnot~185":"Frei Lourenço — Ó pecado mortal! Ó rude ingratidão!\nTua falta nossa lei chama de morte; mas o bondoso príncipe,\nTomando teu partido, afastou a lei,\nE converteu aquela negra palavra morte em banimento:\nIsto é preciosa clemência, e não a vês.","romeotistortureandnotmercyheavenisherewh~lemewiththatwordbanished~745":"Romeu — É tortura, e não clemência: o céu está aqui,\nOnde vive Julieta; e todo gato e cão\nE pequeno camundongo, toda coisa indigna\nVive aqui no céu e pode olhar para ela;\nMas Romeu não pode: mais valor,\nMais honroso estado, mais galanteio vive\nNas moscas de carniça que em Romeu: elas podem tomar\nA branca maravilha da mão da querida Julieta\nE roubar bênção imortal de seus lábios,\nQue, mesmo em pura e virginal modéstia,\nSe ruborizam, como se vissem pecado nos próprios beijos;\nMas Romeu não pode; está banido:\nMoscas podem fazer isto, mas eu devo fugir disto:\nElas são homens livres, mas eu sou banido.\nE ainda dizes que o exílio não é morte?\nNão tinhas veneno misturado, nem faca bem afiada,\nNem meio súbito de morte, por mais baixo que fosse,\nSenão “banido” para me matar? “Banido”?\nÓ frade, os danados usam essa palavra no inferno;\nUivos a acompanham: como tens coragem,\nSendo um sacerdote, um confessor espiritual,\nUm absolvedor de pecados, e meu amigo declarado,\nDe me dilacerar com essa palavra “banido”?","friarlaurencethoufondmadmanhearmebutspea~admanhearmebutspeakaword~46":"Frei Lourenço — Tolo louco, ouve-me apenas dizer uma palavra.","romeoothouwiltspeakagainofbanishment~ltspeakagainofbanishment~36":"Romeu — Ó, tornarás a falar de banimento.","friarlaurenceillgivetheearmourtokeepofft~heethoughthouartbanished~110":"Frei Lourenço — Dar-te-ei armadura para afastar essa palavra;\nO doce leite da adversidade, a filosofia,\nPara te consolar, embora estejas banido.","romeoyetbanishedhangupphilosophyunlessph~titprevailsnottalknomore~127":"Romeu — Ainda “banido”? Pendura a filosofia!\nA não ser que a filosofia possa fazer uma Julieta,\nDeslocar uma cidade, reverter a sentença de um príncipe,\nNão ajuda, não vale: não fales mais.","friarlaurenceotheniseethatmadmenhavenoea~iseethatmadmenhavenoears~42":"Frei Lourenço — Ó, então vejo que os loucos não têm ouvidos.","romeohowshouldtheywhenthatwisemenhavenoe~henthatwisemenhavenoeyes~43":"Romeu — Como teriam, se os sábios não têm olhos?","friarlaurenceletmedisputewiththeeofthyes~sputewiththeeofthyestate~44":"Frei Lourenço — Deixa-me discutir contigo tua situação.","romeothoucanstnotspeakofthatthoudostnotf~nmadegraveknockingwithin~252":"Romeu — Não podes falar do que não sentes:\nFosses tão jovem quanto eu, Julieta teu amor,\nCasado havia uma hora, Teobaldo assassinado,\nEnlouquecido como eu e como eu banido,\nEntão poderias falar, então poderias arrancar os cabelos,\nE cair por terra, como faço agora,\nTirando a medida de uma sepultura ainda por abrir. Batem à porta.","friarlaurenceariseoneknocksgoodromeohide~ocksgoodromeohidethyself~47":"Frei Lourenço — Levanta-te; alguém bate; bom Romeu, esconde-te.","romeonotiunlessthebreathofheartsickgroan~mthesearchofeyesknocking~84":"Romeu — Eu não; a menos que o sopro de gemidos de um coração doente,\nComo névoa, me envolva e me esconda da busca dos olhos. Batem.","friarlaurenceharkhowtheyknockwhostherero~encecomeyouwhatsyourwill~194":"Frei Lourenço — Ouve como batem! Quem está aí? Romeu, levanta-te;\nSerás apanhado. Esperai um pouco! Levanta-te; Batem.\nCorre ao meu gabinete. Já vou! Pela vontade de Deus,\nQue tolice é esta! Já vou, já vou! Batem.\nQuem bate tão forte? De onde vindes? Que desejais?","nursewithinletmecomeinandyoushallknowmye~rrandicomefromladyjuliet~64":"Ama — Dentro. Deixai-me entrar, e sabereis o meu recado;\nVenho da parte de Lady Julieta.","friarlaurencewelcomethen~friarlaurencewelcomethen~24":"Frei Lourenço — Sede bem-vinda, então.","enternurse~enternurse~10":"Entra a Ama.","nurseoholyfriarotellmeholyfriarwhereismy~ismyladyslordwheresromeo~60":"Ama — Ó santo frade, ó, dizei-me, santo frade,\nOnde está o senhor de minha senhora, onde está Romeu?","friarlaurencethereonthegroundwithhisownt~withhisowntearsmadedrunk~53":"Frei Lourenço — Ali no chão, embriagado com suas próprias lágrimas.","nurseoheiseveninmymistresscasejustinherc~ouldyoufallintosodeepano~224":"Ama — Ó, ele está exatamente no estado de minha senhora,\nExatamente no estado dela! Ó dolorosa semelhança!\nSituação lastimável! Assim mesmo jaz ela,\nSoluçando e chorando, chorando e soluçando.\nLevantai-vos, levantai-vos; de pé, se sois homem:\nPor amor de Julieta, por amor dela, erguei-vos e ficai de pé;\nPor que cair num O tão profundo?","romeonurse~romeonurse~10":"Romeu — Ama!","nurseahsirahsirwelldeathstheendofall~sirwelldeathstheendofall~36":"Ama — Ah, senhor! Ah, senhor! Bem, a morte é o fim de tudo.","romeospakestthouofjuliethowisitwithherdo~aldladytoourcancelldlove~202":"Romeu — Falaste de Julieta? Como está ela?\nNão me julga um velho assassino,\nAgora que manchei a infância de nossa alegria\nCom sangue pouco distante do seu próprio?\nOnde está ela? E como vai? E que diz\nMinha escondida senhora de nosso amor cancelado?","nurseoshesaysnothingsirbutweepsandweepsa~iesandthendownfallsagain~127":"Ama — Ó, ela não diz nada, senhor, mas chora e chora;\nE agora cai na cama; e então se levanta num sobressalto,\nE chama Teobaldo; e depois grita por Romeu,\nE então torna a cair.","romeoasifthatnameshotfromthedeadlylevelo~ulmansiondrawinghissword~205":"Romeu — Como se aquele nome,\nDisparado da mira mortal de um canhão,\nA assassinasse; como a mão maldita desse nome\nAssassinou o parente dela. Ó, dize-me, frade, dize-me,\nEm que parte vil desta anatomia\nReside meu nome? Dize-me, para que eu saqueie\nA mansão odiosa. Saca a espada.","friarlaurenceholdthydesperatehandartthou~themaptuntoromeoiscoming~1699":"Frei Lourenço — Detém tua mão desesperada:\nÉs um homem? Tua forma grita que és:\nTuas lágrimas são de mulher; teus atos selvagens denotam\nA fúria irracional de uma fera:\nMulher indecorosa num homem aparente!\nOu fera mal-apessoada em ambos aparente!\nEspantaste-me: por minha ordem santa,\nPensei que teu temperamento fosse mais bem temperado.\nMataste Teobaldo? Queres matar-te a ti mesmo?\nE matar também tua senhora que vive em ti,\nFazendo ódio maldito contra ti mesmo?\nPor que injurias teu nascimento, o céu e a terra?\nJá que nascimento, céu e terra, os três se encontram\nEm ti de uma só vez; e tu de uma vez os queres perder.\nVergonha, vergonha, envergonhas tua forma, teu amor, teu juízo;\nTu que, como um usurário, abundas em tudo,\nE não usas nada com o verdadeiro uso\nQue deveria adornar tua forma, teu amor, teu juízo:\nTua nobre forma é apenas figura de cera,\nDesviando-se da bravura de um homem;\nTeu querido amor jurado é só perjúrio vazio,\nMatando o amor que juraste prezar;\nTeu juízo, ornamento da forma e do amor,\nDeformado na condução de ambos,\nComo pólvora na bolsa de um soldado inexperiente,\nÉ incendiado por tua própria ignorância,\nE tu és desmembrado por tua própria defesa.\nVamos, ergue-te, homem! Tua Julieta está viva,\nPor cujo querido amor estavas há pouco morto;\nNisso és feliz: Teobaldo te mataria,\nMas tu mataste Teobaldo; nisso és feliz também:\nA lei que ameaçava com a morte torna-se tua amiga\nE a converte em exílio; nisso és feliz:\nUm bando de bênçãos cai sobre tuas costas;\nA felicidade te corteja em seus melhores trajes;\nMas, como uma moça malcriada e emburrada,\nAmuas contra tua sorte e teu amor:\nCuidado, cuidado, pois esses morrem miseráveis.\nVai, vai ter com teu amor, como foi decidido,\nSobe a seu quarto, vai e consola-a:\nMas olha que não fiques até a guarda ser posta,\nPois então não poderás passar a Mântua;\nOnde viverás, até acharmos o momento\nDe proclamar vosso casamento, reconciliar vossos amigos,\nPedir perdão ao príncipe e chamar-te de volta\nCom vinte vezes cem mil vezes mais alegria\nDo que saíste em lamentação.\nVai na frente, ama: recomenda-me à tua senhora;\nE pede-lhe que apresse toda a casa a deitar,\nO que a pesada tristeza os torna dispostos a fazer:\nRomeu está a caminho.","nurseolordicouldhavestaydhereallthenight~illtellmyladyyouwillcome~102":"Ama — Ó Senhor, eu poderia ter ficado aqui a noite toda\nPara ouvir bons conselhos: ó, que coisa é a instrução!\nMeu senhor, direi à minha senhora que vindes.","romeodosoandbidmysweetpreparetochide~bidmysweetpreparetochide~36":"Romeu — Faz isso, e pede à minha doce que se prepare para me repreender.","nurseheresiraringshebidmegiveyousirhieyo~teforitgrowsverylateexit~72":"Ama — Aqui, senhor, um anel que ela mandou que vos desse, senhor:\nApressai-vos, andai depressa, pois está ficando muito tarde. Sai.","romeohowwellmycomfortisrevivedbythis~mycomfortisrevivedbythis~36":"Romeu — Como meu consolo é reavivado por isto!","friarlaurencegohencegoodnightandherestan~tislatefarewellgoodnight~252":"Frei Lourenço — Vai daqui; boa noite; e aqui está toda a tua sorte:\nOu parte antes de a guarda ser posta,\nOu ao romper do dia, disfarçado, daqui:\nHospeda-te em Mântua; encontrarei teu criado,\nE ele te informará de tempos em tempos\nToda boa sorte que aqui te suceda:\nDá-me a mão; é tarde: adeus; boa noite.","romeobutthatajoypastjoycallsoutonmeitwer~rtwiththeefarewellexeunt~82":"Romeu — Não fosse uma alegria acima da alegria a me chamar,\nSeria dor separar-me de ti tão depressa:\nAdeus. Saem.","entercapuletladycapuletandparis~puletladycapuletandparis~31":"Entram Capuleto, Lady Capuleto e Páris.","capuletthingshavefallnoutsirsounluckilyt~uldhavebeenabedanhourago~229":"Capuleto — As coisas se deram, senhor, tão infelizmente\nQue não tivemos tempo de persuadir nossa filha:\nVede, ela amava muito o primo Teobaldo,\nE eu também: bem, nascemos para morrer.\nÉ muito tarde, ela não descerá esta noite:\nPrometo-vos que, não fosse pela vossa companhia,\nEu estaria deitado há uma hora.","paristhesetimesofwoeaffordnotimetowoomad~tcommendmetoyourdaughter~74":"Páris — Estes tempos de dor não dão tempo para cortejar.\nSenhora, boa noite: recomendai-me à vossa filha.","ladycapuletiwillandknowhermindearlytomor~heismewduptoherheaviness~75":"Lady Capuleto — Assim farei, e saberei o seu ânimo bem cedo amanhã;\nEsta noite ela está enclausurada em sua tristeza.","capuletsirparisiwillmakeadesperatetender~nextbutsoftwhatdayisthis~220":"Capuleto — Senhor Páris, farei uma oferta ousada\nDo amor de minha filha: creio que ela se deixará guiar\nEm tudo por mim; mais, nem duvido.\nEsposa, ide a ela antes de deitar;\nInformai-a aqui do amor de meu filho Páris;\nE dizei-lhe, prestai atenção, que na próxima quarta-feira —\nMas, calma! Que dia é hoje?","parismondaymylord~parismondaymylord~17":"Páris — Segunda-feira, meu senhor,","capuletmondayhahawellwednesdayistoosoono~dbutwhatsayyoutothursday~332":"Capuleto — Segunda! Ah, ah! Bem, quarta é cedo demais,\nQue seja quinta: dizei-lhe que na quinta\nElá se casará com este nobre conde.\nEstareis pronto? Gostais desta pressa?\nNão faremos grande alarido — um amigo ou dois;\nPois, ouvi, com Teobaldo morto há tão pouco,\nPoderia parecer que o tínhamos em pouca conta,\nSendo nosso parente, se festejássemos muito:\nPortanto teremos uns seis amigos,\nE basta. Mas que dizeis de quinta?","parismylordiwouldthatthursdayweretomorro~thatthursdayweretomorrow~41":"Páris — Meu senhor, quisera que a quinta fosse amanhã.","capuletwellgetyougoneothursdaybeitthengo~lybyandbygoodnightexeunt~198":"Capuleto — Bem, ide: então seja na quinta.\nIde a Julieta antes de deitar,\nPreparai-a, esposa, para este dia de núpcias.\nAdeus, meu senhor. Luz ao meu quarto, ei!\nPor minha fé! É tão tarde, tão tarde,\nQue logo poderemos chamá-lo de cedo.\nBoa noite. Saem.","enterromeoandjulietaboveatthewindow~ndjulietaboveatthewindow~35":"Entram Romeu e Julieta, no alto, à janela.","julietwiltthoubegoneitisnotyetneardayitw~eloveitwasthenightingale~173":"Julieta — Queres ir? Ainda não está perto do dia:\nFoi o rouxinol, e não a cotovia,\nQue feriu o oco temeroso de teu ouvido;\nÀs noites ela canta naquela romãzeira:\nCrê-me, amor, foi o rouxinol.","romeoitwasthelarktheheraldofthemornnonig~egoneandliveorstayanddie~209":"Romeu — Foi a cotovia, a arauta da manhã,\nNão o rouxinol: olha, amor, que faixas invejosas\nRendilham as nuvens que se apartam lá no oriente:\nAs velas da noite estão consumidas, e o dia jovial\nPõe-se na ponta dos pés sobre os cumes enevoados.\nDevo partir e viver, ou ficar e morrer.","julietyonlightisnotdaylightiknowitiitiss~yetthouneedstnottobegone~162":"Julieta — Aquela luz não é luz do dia, eu sei, eu:\nÉ algum meteoro que o sol exala,\nPara ser para ti esta noite um tocheiro\nE iluminar teu caminho para Mântua:\nPortanto fica ainda; não precisas partir.","romeoletmebetaenletmebeputtodeathiamcont~mysoulletstalkitisnotday~290":"Romeu — Deixa que me prendam, deixa que me matem;\nEstou contente, se assim o queres.\nDirei que aquele cinza não é o olho da manhã,\nÉ apenas o pálido reflexo da fronte de Cíntia;\nNem aquela é a cotovia, cujas notas batem\nA abóbada do céu tão alto sobre nossas cabeças:\nTenho mais desejo de ficar que vontade de ir:\nVem, morte, e sê bem-vinda! Julieta assim o quer.\nComo vai, minha alma? Falemos; não é dia.","julietitisitishiehencebegoneawayitisthel~morelightandlightitgrows~341":"Julieta — É, é: vai-te daqui, foge, some!\nÉ a cotovia que canta tão desafinada,\nForçando ásperas dissonâncias e agudos desagradáveis.\nAlguns dizem que a cotovia faz doce variação;\nEsta não faz, pois nos divide:\nAlguns dizem que a cotovia e o odioso sapo trocaram de olhos;\nÓ, agora quisera que tivessem trocado também as vozes!\nJá que essa voz nos arranca braço de braço,\nCaçando-te daqui com o toque de alvorada ao dia.\nÓ, vai-te agora; cada vez mais luz se faz.","romeomorelightandlightmoredarkanddarkour~htmoredarkanddarkourwoes~44":"Romeu — Cada vez mais luz; cada vez mais escuras nossas dores!","enternursetothechamber~enternursetothechamber~22":"Entra a Ama, no quarto.","nursemadam~nursemadam~10":"Ama — Senhora!","julietnurse~julietnurse~11":"Julieta — Ama?","nurseyourladymotheriscomingtoyourchamber~brokebewarylookaboutexit~72":"Ama — Vossa mãe vem ao vosso quarto:\nO dia raiou; tende cuidado, olhai ao redor. Sai.","julietthenwindowletdayinandletlifeout~dowletdayinandletlifeout~37":"Julieta — Então, janela, deixa entrar o dia e sair a vida.","romeofarewellfarewellonekissandilldescen~andilldescendhegoethdown~52":"Romeu — Adeus, adeus! Um beijo, e descerei. Desce.","julietartthougonesolovelordayhusbandfrie~rsereiagainbeholdmyromeo~157":"Julieta — Foste assim? Amor, senhor, sim, marido, amigo!\nDevo ter notícias tuas todo dia, a toda hora,\nPois num minuto há muitos dias:\nÓ, por esta conta estarei bem avançada em anos\nAntes de tornar a ver meu Romeu!","romeofarewelliwillomitnoopportunitythatm~veymygreetingslovetothee~69":"Romeu — Adeus!\nNão perderei oportunidade alguma\nQue possa levar meus cumprimentos, amor, a ti.","julietothinkstthouweshallevermeetagain~thouweshallevermeetagain~38":"Julieta — Ó, pensas que nos encontraremos outra vez?","romeoidoubtitnotandallthesewoesshallserv~iscoursesinourtimetocome~74":"Romeu — Não duvido; e todas estas dores servirão\nPara doces conversas em nosso tempo por vir.","julietogodihaveanilldiviningsoulmethinks~ghtfailsorthoulookstpale~127":"Julieta — Ó Deus, tenho uma alma de maus presságios!\nParece-me ver-te, agora que estás lá embaixo,\nComo um morto no fundo de um túmulo:\nOu me falha a vista, ou estás pálido.","romeoandtrustmeloveinmyeyesodoyoudrysorr~ksourbloodadieuadieuexit~70":"Romeu — E crê-me, amor, aos meus olhos tu também:\nA dor seca bebe nosso sangue. Adeus, adeus! Sai.","julietofortunefortuneallmencalltheefickl~eephimlongbutsendhimback~159":"Julieta — Ó fortuna, fortuna! Todos te chamam volúvel:\nSe és volúvel, que fazes com aquele\nQue é célebre pela fidelidade? Sê volúvel, fortuna;\nPois então, espero, não o reterás por muito tempo,\nMas o enviarás de volta.","ladycapuletwithinhodaughterareyouup~withinhodaughterareyouup~35":"Lady Capuleto — Dentro. Ei, filha! Já estás de pé?","julietwhoistthatcallsisitmyladymotheriss~mdcauseprocuresherhither~103":"Julieta — Quem é que chama? É minha senhora mãe?\nEstá ela deitada tão tarde, ou de pé tão cedo?\nQue causa inusitada a traz aqui?","enterladycapulet~enterladycapulet~16":"Entra Lady Capuleto.","ladycapuletwhyhownowjuliet~dycapuletwhyhownowjuliet~26":"Lady Capuleto — Ora, que há, Julieta!","julietmadamiamnotwell~julietmadamiamnotwell~21":"Julieta — Senhora, não estou bem.","ladycapuletevermoreweepingforyourcousins~fshowsstillsomewantofwit~203":"Lady Capuleto — Sempre chorando a morte de teu primo?\nQuê, queres lavá-lo da sepultura com lágrimas?\nE se pudesses, não poderias fazê-lo viver;\nPortanto, basta: alguma dor mostra muito amor;\nMas muita dor mostra sempre alguma falta de juízo.","julietyetletmeweepforsuchafeelingloss~eweepforsuchafeelingloss~37":"Julieta — Deixai-me ainda chorar por tão sensível perda.","ladycapuletsoshallyoufeelthelossbutnotth~thefriendwhichyouweepfor~62":"Lady Capuleto — Assim sentirás a perda, mas não o amigo\nQue choras.","julietfeelingsothelossicannotchoosebutev~oosebuteverweepthefriend~55":"Julieta — Sentindo assim a perda,\nNão posso deixar de chorar sempre o amigo.","ladycapuletwellgirlthouweepstnotsomuchfo~nliveswhichslaughterdhim~88":"Lady Capuleto — Bem, menina, não choras tanto pela morte dele\nQuanto porque vive o vilão que o matou.","julietwhatvillainmadam~julietwhatvillainmadam~22":"Julieta — Que vilão, senhora?","ladycapuletthatsamevillainromeo~uletthatsamevillainromeo~31":"Lady Capuleto — Esse mesmo vilão, Romeu.","julietasidevillainandhebemanymilesasunde~nlikehedothgrievemyheart~104":"Julieta — À parte. Vilão e ele estão a muitas milhas de distância. —\nDeus o perdoe! Eu o perdoo, de todo o coração;\nE no entanto nenhum homem como ele aflige meu coração.","ladycapuletthatisbecausethetraitormurder~ethetraitormurdererlives~47":"Lady Capuleto — Isso é porque o traidor assassino vive.","julietaymadamfromthereachofthesemyhandsw~mightvengemycousinsdeath~76":"Julieta — Sim, senhora, longe do alcance destas minhas mãos:\nQuisera que ninguém além de mim vingasse a morte de meu primo!","ladycapuletwewillhavevengeanceforitfeart~ihopethouwiltbesatisfied~212":"Lady Capuleto — Teremos vingança por isso, não temas:\nPortanto não chores mais. Mandarei alguém a Mântua,\nOnde vive esse banido vagabundo,\nQue lhe dará uma dose tão incomum\nQue logo fará companhia a Teobaldo:\nE então, espero, ficarás satisfeita.","julietindeedinevershallbesatisfiedwithro~odythathathslaughterdhim~304":"Julieta — Na verdade, nunca ficarei satisfeita\nCom Romeu, até que o veja — morto —\nÉ assim que meu pobre coração se aflige por um parente:\nSenhora, se pudésseis achar só um homem\nPara levar um veneno, eu o prepararia;\nPara que Romeu, ao recebê-lo,\nDormisse logo em paz. Ó, como meu coração abomina\nOuvi-lo nomeado, e não poder ir até ele,\nPara descarregar o amor que dediquei a meu primo\nSobre o corpo daquele que o matou!","ladycapuletfindthouthemeansandillfindsuc~elltheejoyfultidingsgirl~79":"Lady Capuleto — Acha tu os meios, e eu acharei tal homem.\nMas agora te direi notícias alegres, menina.","julietandjoycomeswellinsuchaneedytimewha~theyibeseechyourladyship~68":"Julieta — E a alegria vem bem em tempo tão necessitado:\nQuais são elas, suplico a vossa senhoria?","ladycapuletwellwellthouhastacarefulfathe~pectstnotnorilookdnotfor~139":"Lady Capuleto — Bem, bem, tens um pai cuidadoso, filha;\nUm que, para te tirar da tristeza,\nArranjou um súbito dia de alegria,\nQue tu não esperas nem eu aguardava.","julietmadaminhappytimewhatdayisthat~inhappytimewhatdayisthat~35":"Julieta — Senhora, em boa hora, que dia é esse?","ladycapuletmarrymychildearlynextthursday~aketheethereajoyfulbride~146":"Lady Capuleto — Pois bem, minha filha, cedo, na próxima quinta-feira,\nO galante, jovem e nobre cavalheiro,\nO conde Páris, na igreja de São Pedro,\nFará de ti ali uma noiva feliz.","julietnowbysaintpeterschurchandpetertooh~nparisthesearenewsindeed~263":"Julieta — Agora, pela igreja de São Pedro e por Pedro também,\nEle não fará de mim ali uma noiva feliz.\nEspanto-me com esta pressa; que eu deva casar\nAntes que aquele que será meu marido venha cortejar.\nPeço-vos, dizei a meu senhor e pai, senhora,\nQue ainda não me casarei; e, quando o fizer, juro,\nSerá com Romeu, a quem sabeis que odeio,\nAntes que com Páris. Estas sim são notícias!","ladycapuletherecomesyourfathertellhimsoy~whewilltakeitatyourhands~79":"Lady Capuleto — Eis que vem teu pai; diz-lhe tu mesma,\nE vê como ele o receberá de tuas mãos.","entercapuletandnurse~entercapuletandnurse~20":"Entram Capuleto e a Ama.","capuletwhenthesunsetstheairdothdrizzlede~oudeliverdtoherourdecree~417":"Capuleto — Quando o sol se põe, o ar goteja orvalho;\nMas pelo ocaso do filho de meu irmão\nChove a cântaros.\nQue é isso! Uma bica, menina? Quê, ainda em lágrimas?\nSempre em chuva? Num pequeno corpo\nImitas um barco, um mar, um vento;\nPois teus olhos, que posso chamar de mar,\nVão e vêm com as lágrimas; o barco é teu corpo,\nNavegando neste dilúvio salgado; os ventos, teus suspiros;\nQue, furiosos com tuas lágrimas, e elas com eles,\nSe não vier súbita calmaria, virarão\nTeu corpo açoitado pela tempestade. Então, esposa!\nJá lhe transmitistes nosso decreto?","ladycapuletaysirbutshewillnoneshegivesyo~oolweremarriedtohergrave~81":"Lady Capulet — Sim, senhor; mas ela não quer, agradece-vos.\nQuisera que a tola estivesse casada com sua sepultura!","capuletsofttakemewithyoutakemewithyouwif~ntlemantobeherbridegroom~180":"Capulet — Calma! Explicai-vos melhor, explicai-vos melhor, esposa.\nComo! Ela não quer? Não nos agradece?\nNão está orgulhosa? Não se considera abençoada,\nIndigna como é, por termos arranjado\nTão digno cavalheiro para ser seu noivo?","julietnotproudyouhavebutthankfulthatyouh~enforhatethatismeantlove~107":"Juliet — Orgulhosa, não estou; mas agradecida por terdes feito isso:\nOrgulhosa jamais posso ser do que odeio;\nMas agradecida até pelo ódio que quis ser amor.","capulethownowhownowchoplogicwhatisthispr~tyoubaggageyoutallowface~293":"Capulet — Que é isso, que é isso, sofista! Que é isto?\n“Orgulhosa”, e “agradeço-vos”, e “não vos agradeço”;\nE no entanto “não orgulhosa”: senhorita dengosa,\nNão me agradeças agradecimentos, nem me orgulhes orgulhos,\nMas ajeita essas belas juntas para a próxima quinta-feira,\nPara ir com Paris à igreja de São Pedro,\nOu te arrastarei até lá numa padiola.\nFora, carniça de clorose! Fora, trapo! Cara de sebo!","ladycapuletfiefiewhatareyoumad~puletfiefiewhatareyoumad~30":"Lady Capulet — Vergonha, vergonha! Quê, estais louco?","julietgoodfatheribeseechyouonmykneeshear~hpatiencebuttospeakaword~69":"Juliet — Bom pai, suplico-vos de joelhos,\nOuvi-me com paciência dizer só uma palavra.","capulethangtheeyoungbaggagedisobedientwr~havingheroutonherhilding~282":"Capulet — Maldita sejas, moça atrevida! Desobediente miserável!\nDigo-te o que é: vai à igreja na quinta,\nOu nunca mais me olhes na cara:\nNão fales, não repliques, não me respondas;\nMeus dedos coçam. Esposa, mal nos achávamos abençoados\nPor Deus nos ter emprestado apenas esta filha;\nMas agora vejo que esta é uma demais,\nE que temos uma maldição por tê-la:\nFora com ela, mulher de nada!","nursegodinheavenblessheryouaretoblamemyl~toblamemylordtorateherso~54":"Ama — Deus do céu a abençoe!\nEstais errado, meu senhor, em repreendê-la assim.","capuletandwhymyladywisdomholdyourtongueg~smatterwithyourgossipsgo~75":"Capulet — E por quê, minha senhora sabedoria? Segurai a língua,\nBoa prudência; tagarelai com vossas comadres, ide.","nurseispeaknotreason~nurseispeaknotreason~20":"Ama — Não digo traição alguma.","capuletogodyegodden~capuletogodyegodden~19":"Capulet — Ó, Deus vos dê boa noite.","nursemaynotonespeak~nursemaynotonespeak~19":"Ama — Não se pode falar?","capuletpeaceyoumumblingfoolutteryourgrav~psbowlforhereweneeditnot~76":"Capulet — Paz, tola resmungona!\nProferi vossa gravidade sobre a tigela de uma comadre;\nPois aqui não precisamos dela.","ladycapuletyouaretoohot~ladycapuletyouaretoohot~23":"Lady Capulet — Estais muito exaltado.","capuletgodsbreaditmakesmemaddaynighthour~kyouillnotbeforswornexit~683":"Capulet — Pelo pão de Deus! Isto me deixa louco:\nDia, noite, hora, maré, tempo, trabalho, folga,\nSozinho, em companhia, sempre meu cuidado foi\nCasá-la bem: e tendo agora arranjado\nUm cavalheiro de nobre linhagem,\nDe belas terras, jovem e nobremente educado,\nRecheado, como se diz, de honrosas qualidades,\nProporcionado como o pensamento desejaria um homem;\nE depois ter uma tola miserável e chorona,\nUma boneca lamurienta, diante da oferta de sua sorte,\nA responder “Não me casarei; não posso amar,\nSou muito jovem; peço-vos, perdoai-me.”\nMas, se não vos casardes, eu vos perdoo:\nPastai onde quiserdes, não morareis comigo:\nPensai nisso, cuidai; não costumo gracejar.\nA quinta está perto; ponde a mão no coração, refleti:\nSe sois minha, entrego-vos a meu amigo;\nSe não sois, enforcai-vos, mendigai, passai fome, morrei nas ruas,\nPois, por minha alma, nunca vos reconhecerei,\nNem o que é meu jamais vos fará bem:\nConfiai nisso, pensai; não serei perjuro. Sai.","julietistherenopitysittinginthecloudstha~mmonumentwheretybaltlies~185":"Juliet — Não há piedade sentada nas nuvens,\nQue veja o fundo da minha dor?\nÓ, minha doce mãe, não me rejeiteis!\nAdiai este casamento por um mês, uma semana;\nOu, se não o fizerdes, preparai o leito nupcial\nNaquele sombrio mausoléu onde jaz Tybalt.","ladycapulettalknottomeforillnotspeakawor~forihavedonewiththeeexit~77":"Lady Capulet — Não me fales, pois não direi palavra:\nFaze o que quiseres, pois acabei contigo. Sai.","julietogodonursehowshallthisbepreventedm~ordofjoysomecomfortnurse~294":"Juliet — Ó Deus! — Ó ama, como isto será evitado?\nMeu marido está na terra, minha fé no céu;\nComo essa fé voltará à terra,\nA menos que esse marido ma envie do céu\nDeixando a terra? Consola-me, aconselha-me.\nAi, ai, que o céu pratique estratagemas\nContra um sujeito tão frágil como eu!\nQue dizes? Não tens uma palavra de alegria?\nAlgum consolo, ama.","nursefaithhereitisromeoisbanishdandallth~vinghereandyounouseofhim~434":"Ama — Pois bem, aqui está.\nRomeo está banido; e todo o mundo contra nada\nQue ele nunca ousará voltar para reclamar-vos;\nOu, se o fizer, terá de ser às ocultas.\nEntão, já que o caso está como agora está,\nParece-me melhor que vos caseis com o conde.\nÓ, é um encantador cavalheiro!\nRomeo é um pano de prato perto dele: uma águia, senhora,\nNão tem olho tão verde, tão vivo, tão belo\nComo Paris tem. Maldito seja meu coração,\nPenso que sereis feliz neste segundo casamento,\nPois ele excede o primeiro; ou, se não excedesse,\nO primeiro está morto; ou seria o mesmo que estivesse,\nVivendo aqui e sem proveito algum para vós.","julietspeakestthoufromthyheart~speakestthoufromthyheart~30":"Juliet — Falas do fundo do coração?","nurseandfrommysoultooorelsebeshrewthembo~tooorelsebeshrewthemboth~42":"Ama — E da alma também;\nOu então malditos sejam ambos.","julietamen~julietamen~10":"Juliet — Amém!","nursewhat~nursewhat~9":"Ama — Quê?","julietwellthouhastcomfortedmemarvellousm~onfessionandtobeabsolved~136":"Juliet — Bem, consolaste-me maravilhosamente.\nEntra; e diz a minha mãe que fui,\nTendo desagradado meu pai, à cela de Laurence,\nPara me confessar e ser absolvida.","nursemarryiwillandthisiswiselydoneexit~landthisiswiselydoneexit~38":"Ama — Pois sim, direi; e isto é sensatamente feito. Sai.","julietancientdamnationomostwickedfiendis~myselfhavepowertodieexit~276":"Juliet — Antiga danação! Ó mais perverso demônio!\nÉ maior pecado desejar-me assim perjura,\nOu desacreditar meu senhor com a mesma língua\nQue o louvou acima de qualquer comparação\nTantos milhares de vezes? Vai, conselheira;\nTu e meu peito doravante serão dois.\nIrei ao frade, saber seu remédio:\nSe tudo mais falhar, tenho eu mesma o poder de morrer. Sai."}$tr$::jsonb, 690)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_the-merchant-of-venice (461 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-merchant-of-venice', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","veniceastreet~veniceastreet~13":"Veneza. Uma rua.","enterantoniosalarinoandsalanio~ntoniosalarinoandsalanio~30":"Entram Antônio, Salarino e Salânio.","antonioinsoothiknownotwhyiamsosaditweari~ihavemuchadotoknowmyself~196":"Antônio — Em verdade, não sei por que estou tão triste:\nCansa-me; dizeis que vos cansa;\nMas como o apanhei, achei ou adquiri,\nDe que matéria é feito, de que nasce,\nIsso tenho de aprender;\nE tal tristeza sem juízo faz de mim\nQue mal consigo me reconhecer.","salarinoyourmindistossingontheoceanthere~ythemwiththeirwovenwings~231":"Salarino — Vossa mente balança no oceano;\nLá, onde vossos galeões de velas soberbas,\nComo senhores e ricos burgueses sobre as ondas,\nOu, por assim dizer, os cortejos do mar,\nDominam do alto os pequenos mercadores,\nQue lhes fazem reverências, lhes prestam homenagem,\nQuando voam por eles com suas asas tecidas.","salaniobelievemesirhadisuchventurefortht~outofdoubtwouldmakemesad~258":"Salânio — Crede-me, senhor, se eu tivesse tal empresa no mar,\nA melhor parte de minhas afeições estaria\nCom minhas esperanças no estrangeiro. Estaria sempre\nArrancando capim, para saber onde se assenta o vento,\nEspiando mapas atrás de portos, cais e ancoradouros;\nE todo objeto que me fizesse temer\nInfortúnio às minhas empresas, sem dúvida\nMe faria triste.","salarinomywindcoolingmybrothwouldblowmet~othinkuponhismerchandise~620":"Salarino — Meu vento, a esfriar-me o caldo,\nSoprar-me-ia uma febre, ao pensar\nQue dano um vento forte demais no mar poderia fazer.\nNão veria correr a areia da ampulheta\nSem pensar em baixios e bancos de areia,\nE ver meu rico Andrew encalhado na areia,\nBaixando a gávea mais que as costelas\nPara beijar o seu sepulcro. Se eu fosse à igreja\nE visse o santo edifício de pedra,\nE não me lembrasse logo de rochas perigosas,\nQue, tocando apenas o flanco de minha gentil embarcação,\nEspalhariam todas as suas especiarias na corrente,\nVestiriam as águas rugidoras com minhas sedas,\nE, numa palavra, valendo agora isto tanto,\nE logo nada? Terei eu o pensamento\nDe pensar nisto, e me faltará o pensamento\nDe que tal coisa, ocorrendo, me faria triste?\nMas não me digais; sei que Antônio\nEstá triste de pensar em suas mercadorias.","antoniobelievemenoithankmyfortuneforitmy~merchandisemakesmenotsad~169":"Antônio — Crede-me, não: agradeço à minha sorte,\nMinhas empresas não estão confiadas a um só casco,\nNem a um só lugar; nem toda a minha fortuna\nDepende da sorte do presente ano:\nPortanto minhas mercadorias não me fazem triste.","salarinowhythenyouareinlove~arinowhythenyouareinlove~27":"Salarino — Ora, então estais apaixonado.","antoniofiefie~antoniofiefie~13":"Antônio — Ora, ora!","salarinonotinloveneitherthenletussayyoua~rswearthejestbelaughable~365":"Salarino — Nem apaixonado? Então digamos que estais triste\nPorque não estais alegre: e seria tão fácil\nPara vós rir, saltar e dizer que estais alegre\nPorque não estais triste. Por Jano de duas cabeças,\nA natureza criou estranhos sujeitos em seu tempo:\nUns que sempre espiarão pelos olhos semicerrados\nE rirão como papagaios de um gaiteiro,\nE outros de aspecto tão avinagrado\nQue não mostrarão os dentes em sorriso,\nAinda que Nestor jure ser a graça risível.","enterbassaniolorenzoandgratiano~ssaniolorenzoandgratiano~31":"Entram Bassânio, Lourenço e Graciano.","salanioherecomesbassanioyourmostnoblekin~eyounowwithbettercompany~102":"Salânio — Aí vem Bassânio, vosso nobilíssimo parente,\nGraciano e Lourenço. Ficai bem:\nDeixamo-vos agora com melhor companhia.","salarinoiwouldhavestaydtillihadmadeyoume~friendshadnotpreventedme~77":"Salarino — Teria ficado até vos fazer alegre,\nSe amigos mais dignos não me tivessem antecipado.","antonioyourworthisverydearinmyregarditak~bracetheoccasiontodepart~100":"Antônio — Vosso valor me é muito caro.\nPenso que vossos próprios negócios vos chamam\nE aproveitais a ocasião para partir.","salarinogoodmorrowmygoodlords~inogoodmorrowmygoodlords~29":"Salarino — Bom dia, meus bons senhores.","bassaniogoodsigniorsbothwhenshallwelaugh~ceedingstrangemustitbeso~80":"Bassânio — Bons senhores ambos, quando riremos? dizei, quando?\nTornais-vos excessivamente esquivos: deve ser assim?","salarinowellmakeourleisurestoattendonyou~exeuntsalarinoandsalanio~66":"Salarino — Faremos que nossos lazeres sirvam aos vossos. Saem Salarino e Salânio.","lorenzomylordbassaniosinceyouhavefoundan~aveinmindwherewemustmeet~110":"Lourenço — Milorde Bassânio, já que encontrastes Antônio,\nNós dois vos deixaremos: mas na hora do jantar,\nRogo-vos, lembrai onde devemos nos encontrar.","bassanioiwillnotfailyou~bassanioiwillnotfailyou~23":"Bassânio — Não vos faltarei.","gratianoyoulooknotwellsigniorantonioyouh~ouaremarvellouslychanged~136":"Graciano — Não pareceis bem, Senhor Antônio;\nDais importância demais ao mundo:\nPerdem-no os que o compram com muito cuidado:\nCrede-me, estais maravilhosamente mudado.","antonioiholdtheworldbutastheworldgratian~tplayapartandmineasadone~87":"Antonio — Tenho o mundo apenas por mundo, Gratiano;\nUm palco onde todo homem deve representar um papel,\nE o meu é triste.","gratianoletmeplaythefoolwithmirthandlaug~myexhortationafterdinner~835":"Gratiano — Deixa-me representar o bobo:\nQue venham as velhas rugas com alegria e riso,\nE que meu fígado se aqueça antes com vinho\nDo que meu coração esfrie com gemidos mortificantes.\nPor que um homem, de sangue quente por dentro,\nSentaria como seu avô talhado em alabastro?\nDormir quando está desperto e cair na icterícia\nDe tanto mau humor? Digo-te o que é, Antonio —\nAmo-te, e é meu amor que fala —\nHá uma classe de homens cujos semblantes\nFormam nata e película como um lago parado,\nE cultivam um silêncio deliberado,\nCom o propósito de se vestirem de uma reputação\nDe sabedoria, gravidade, profundo entendimento,\nComo quem dissesse “Sou o Senhor Oráculo,\nE quando eu abrir os lábios, que nenhum cão ladre!”\nÓ meu Antonio, conheço desses\nQue só são tidos por sábios\nPor nada dizerem; quando, estou bem certo,\nSe falassem, quase condenariam os ouvidos\nQue, ao ouvi-los, chamariam seus irmãos de tolos.\nContar-te-ei mais disto em outra ocasião:\nMas não pesques, com esta isca melancólica,\nEste tolo gobião, a reputação.\nVem, bom Lorenzo. Passai bem por ora:\nAcabarei minha exortação depois do jantar.","lorenzowellwewillleaveyouthentilldinnert~gratianoneverletsmespeak~102":"Lorenzo — Bem, deixar-te-emos então até a hora do jantar:\nDevo ser um desses mudos sábios,\nPois Gratiano nunca me deixa falar.","gratianowellkeepmecompanybuttwoyearsmoet~thesoundofthineowntongue~79":"Gratiano — Bem, faze-me companhia só mais dois anos,\nE não reconhecerás o som da tua própria língua.","antoniofarewellillgrowatalkerforthisgear~llgrowatalkerforthisgear~40":"Antonio — Adeus: tornar-me-ei tagarela por causa dessa conversa.","gratianothanksifaithforsilenceisonlycomm~exeuntgratianoandlorenzo~109":"Gratiano — Obrigado, na verdade, pois o silêncio só é louvável\nNuma língua de boi seca e numa donzela invendável. Saem Gratiano e Lorenzo.","antonioisthatanythingnow~antonioisthatanythingnow~24":"Antonio — Isso foi alguma coisa?","bassaniogratianospeaksaninfinitedealofno~theyarenotworththesearch~197":"Bassanio — Gratiano fala uma infinidade de nada, mais que qualquer homem de toda Veneza. Suas razões são como dois grãos de trigo escondidos em dois alqueires de palha: procurareis o dia inteiro antes de achá-los, e quando os tiverdes, não valem a busca.","antoniowelltellmenowwhatladyisthesametow~utodaypromisedtotellmeof~98":"Antonio — Bem, dize-me agora que dama é aquela\nA quem juraste uma peregrinação secreta,\nDe quem hoje prometeste me falar?","bassaniotisnotunknowntoyouantoniohowmuch~etclearofallthedebtsiowe~407":"Bassanio — Não é desconhecido de ti, Antonio,\nQuanto reduzi o meu patrimônio,\nExibindo um porte um tanto mais pomposo\nDo que meus parcos meios permitiriam manter:\nNem lamento agora ser reduzido\nDesse nobre padrão; mas meu principal cuidado\nÉ sair honrosamente das grandes dívidas\nEm que minha mocidade, um tanto pródiga demais,\nMe deixou empenhado. A ti, Antonio,\nDevo o mais, em dinheiro e em afeto,\nE de teu afeto tenho a garantia\nPara descarregar todos os meus planos e propósitos\nSobre como me livrar de todas as dívidas que devo.","antonioiprayyougoodbassanioletmeknowitan~llunlockdtoyouroccasions~158":"Antonio — Peço-te, bom Bassanio, deixa-me sabê-lo;\nE se ele se mantém, como tu mesmo sempre te manténs,\nÀ vista da honra, fica seguro,\nMinha bolsa, minha pessoa, meus mais extremos recursos\nEstão todos abertos às tuas necessidades.","bassanioinmyschooldayswhenihadlostonesha~llyrestdebtorforthefirst~441":"Bassanio — Nos tempos de escola, quando eu perdia uma flecha,\nDisparava sua companheira, do mesmo alcance,\nPelo mesmo caminho, com olhar mais atento,\nPara achar a outra, e arriscando ambas\nMuitas vezes achei ambas: invoco esta prova de infância,\nPorque o que segue é pura inocência.\nDevo-te muito, e, como um jovem voluntarioso,\nO que devo está perdido; mas se te aprouver\nDisparar outra flecha pelo mesmo caminho\nPor onde disparaste a primeira, não duvido,\nPois vigiarei a pontaria, de achar ambas\nOu trazer de volta tua última aposta\nE ficar, grato, devedor apenas da primeira.","antonioyouknowmewellandhereinspendbuttim~restuntoitthereforespeak~258":"Antonio — Conheces-me bem, e aqui gastas apenas tempo\nEm rodear meu afeto com circunlóquios;\nE sem dúvida me fazes agora mais agravo\nPondo em questão o meu máximo\nDo que se tivesses dissipado tudo o que tenho:\nPortanto dize-me apenas o que devo fazer\nQue em teu saber por mim possa ser feito,\nE estou pronto para isso: portanto, fala.","bassanioinbelmontisaladyrichlyleftandshe~dquestionlessbefortunate~518":"Bassanio — Em Belmont há uma dama ricamente herdeira;\nE é bela, e, mais bela que essa palavra,\nDe maravilhosas virtudes: às vezes de seus olhos\nRecebi belas mensagens mudas:\nSeu nome é Portia, em nada inferior\nÀ filha de Catão, a Portia de Brutus:\nNem o vasto mundo ignora seu valor,\nPois os quatro ventos trazem de cada costa\nPretendentes famosos, e seus cabelos solares\nPendem-lhe das têmporas como um velocino de ouro;\nO que faz de sua morada de Belmont a praia da Cólquida,\nE muitos Jasões vêm em busca dela.\nÓ meu Antonio, tivesse eu os meios\nPara disputar um lugar ao lado de um deles,\nTenho um pressentimento que me augura tal fortuna\nQue eu seria sem dúvida bem-sucedido!","antoniothouknowstthatallmyfortunesareats~mytrustorformysakeexeunt~293":"Antonio — Sabes que todas as minhas fortunas estão no mar;\nNem tenho dinheiro nem mercadoria\nPara levantar uma soma presente: portanto vai;\nVê o que meu crédito pode fazer em Veneza:\nEle será esticado até o extremo\nPara te prover para Belmont, para a bela Portia.\nVai, informa-te já, e assim farei eu,\nOnde há dinheiro, e não tenho dúvida\nDe obtê-lo por minha confiança ou por minha causa. Saem.","sceneii~sceneii~7":"Cena II","belmontaroominportiashouse~lmontaroominportiashouse~26":"Belmont. Um aposento na casa de Portia.","enterportiaandnerissa~enterportiaandnerissa~21":"Entram Portia e Nerissa.","portiabymytrothnerissamylittlebodyisawea~isawearyofthisgreatworld~58":"Portia — Palavra, Nerissa, meu pequeno corpo está cansado deste grande mundo.","nerissayouwouldbesweetmadamifyourmiserie~butcompetencyliveslonger~269":"Nerissa — Estaríeis, doce senhora, se vossas misérias fossem tão abundantes quanto vossas boas fortunas: e no entanto, pelo que vejo, adoecem tanto os que se fartam de demais quanto os que passam fome por nada. Não é pequena felicidade, portanto, estar sentado no meio-termo: o excesso chega mais cedo aos cabelos brancos, mas a suficiência vive mais.","portiagoodsentencesandwellpronounced~ntencesandwellpronounced~36":"Portia — Boas sentenças e bem pronunciadas.","nerissatheywouldbebetterifwellfollowed~ldbebetterifwellfollowed~38":"Nerissa — Seriam melhores se bem seguidas.","portiaiftodowereaseasyastoknowwhatwerego~otchooseonenorrefusenone~582":"Portia — Se fazer fosse tão fácil quanto saber o que é bom fazer, capelas teriam sido igrejas e choupanas de pobres, palácios de príncipes. É bom pregador quem segue as próprias instruções: mais facilmente ensino vinte o que seria bom fazer do que sou uma dos vinte a seguir meu próprio ensinamento. O cérebro pode inventar leis para o sangue, mas um temperamento ardente salta sobre um decreto frio: tal lebre é a loucura da juventude, a saltar sobre as redes do bom conselho, esse aleijado. Mas este raciocínio não serve para escolher-me um marido. Ai de mim, a palavra “escolher”! Não posso nem escolher quem quero nem recusar quem desgosto; assim a vontade de uma filha viva é refreada pela vontade de um pai morto. Não é duro, Nerissa, que eu não possa escolher nenhum nem recusar nenhum?","nerissayourfatherwasevervirtuousandholym~uitorsthatarealreadycome~330":"Nerissa — Vosso pai foi sempre virtuoso; e os homens santos têm boas inspirações na hora da morte: portanto a loteria que ele concebeu nestes três cofres de ouro, prata e chumbo, em que quem escolher seu sentido escolhe a vós, não será, sem dúvida, jamais escolhida acertadamente senão por quem acertadamente vos amar. Mas que calor há em vossa afeição por algum desses príncipes pretendentes que já vieram?","portiaipraytheeovernamethemandasthouname~iptionlevelatmyaffection~108":"Portia — Peço-te, nomeia-os um a um; e à medida que os nomeares, eu os descreverei; e, conforme minha descrição, mirarei minha afeição.","nerissafirstthereistheneapolitanprince~ereistheneapolitanprince~38":"Nerissa — Primeiro, há o príncipe napolitano.","portiaaythatsacoltindeedforhedothnothing~herplayedfalsewithasmith~177":"Portia — Sim, esse é um potro de verdade, pois não faz senão falar de seu cavalo; e tem como grande mérito de suas próprias qualidades que ele mesmo sabe ferrá-lo. Receio muito que a senhora sua mãe tenha traído com um ferreiro.","nerissathenthereisthecountypalatine~thereisthecountypalatine~35":"Nerissa — Depois há o conde palatino.","portiahedothnothingbutfrownaswhoshouldsa~egoddefendmefromthesetwo~278":"Portia — Ele não faz senão franzir a testa, como quem dissesse “Se não me quiserdes, escolhei”: ouve histórias alegres e não sorri: temo que se revele o filósofo chorão quando envelhecer, sendo tão cheio de tristeza deselegante na juventude. Preferia me casar com uma caveira com um osso na boca a casar com qualquer um destes. Deus me defenda desses dois!","nerissahowsayyoubythefrenchlordmonsieurl~efrenchlordmonsieurlebon~44":"Nerissa — Que dizeis do senhor francês, Monsieur Le Bon?","portiagodmadehimandthereforelethimpassfo~essishallneverrequitehim~370":"Portia — Deus o fez, e portanto deixemo-lo passar por homem. Na verdade, sei que é pecado zombar: mas ele! Ora, ele tem um cavalo melhor que o do napolitano, um hábito de franzir a testa pior, e melhor, que o do conde palatino; é todos os homens e nenhum homem; se um tordo canta, põe-se logo a cabriolar: esgrimirá com a própria sombra: se me casasse com ele, casaria com vinte maridos. Se ele me desprezasse eu o perdoaria, pois, se me amar até a loucura, jamais o retribuirei.","nerissawhatsayyouthentofalconbridgetheyo~getheyoungbaronofengland~57":"Nerissa — Que dizeis, então, de Falconbridge, o jovem barão da Inglaterra?","portiayouknowisaynothingtohimforheunders~andhisbehavioreverywhere~328":"Portia — Sabeis que nada lhe digo, pois ele não me entende, nem eu a ele: não tem nem latim, nem francês, nem italiano, e podeis ir ao tribunal e jurar que tenho pouquíssimo domínio do inglês. É a imagem de um homem bem-apessoado, mas, ai, quem pode conversar com uma pantomima? Que esquisitamente está vestido! Creio que comprou o gibão na Itália, as calças redondas na França, o barrete na Alemanha e o comportamento em toda parte.","nerissawhatthinkyouofthescottishlordhisn~scottishlordhisneighbour~48":"Nerissa — Que pensais do lorde escocês, seu vizinho?","portiathathehathaneighbourlycharityinhim~andsealedunderforanother~176":"Portia — Que tem nele caridade de vizinho, pois tomou emprestado um tabefe do inglês e jurou que o pagaria de volta quando pudesse: creio que o francês foi seu fiador e selou por outro.","nerissahowlikeyoutheyounggermanthedukeof~anthedukeofsaxonysnephew~53":"Nerissa — Que tal vos parece o jovem alemão, sobrinho do duque da Saxônia?","portiaveryvilelyinthemorningwhenheissobe~lmakeshifttogowithouthim~220":"Portia — Muito vilmente pela manhã, quando está sóbrio, e mais vilmente à tarde, quando está bêbado: quando está no melhor, é um pouco pior que um homem, e quando está no pior, é pouco melhor que um animal: e na pior queda que jamais houve, espero dar um jeito de passar sem ele.","nerissaifheshouldoffertochooseandchooset~ushouldrefusetoaccepthim~120":"Nerissa — Se ele se oferecesse para escolher, e escolhesse o cofre certo, recusaríeis cumprir a vontade de vosso pai se recusásseis aceitá-lo.","portiathereforeforfearoftheworstipraythe~ereillbemarriedtoasponge~196":"Portia — Portanto, por medo do pior, peço-te, põe uma taça funda de vinho do Reno no cofre errado, pois, se o diabo estiver dentro e aquela tentação fora, sei que ele o escolherá. Farei qualquer coisa, Nerissa, antes de me casar com uma esponja.","nerissayouneednotfearladythehavinganyoft~iondependingonthecaskets~231":"Nerissa — Não precisais temer, senhora, ter algum desses lordes: deram-me a conhecer suas resoluções; que são, de fato, voltar para casa e não vos incomodar mais com pretensões, a menos que possais ser conquistada de outro modo que não a imposição de vosso pai dependente dos cofres.","portiaifilivetobeasoldassibyllaiwilldiea~dgrantthemafairdeparture~220":"Portia — Se eu viver até ser tão velha quanto a Sibila, morrerei tão casta quanto Diana, a menos que seja obtida segundo a vontade de meu pai. Fico contente que este lote de pretendentes seja tão sensato, pois não há um entre eles cuja própria ausência eu não adore, e rogo a Deus que lhes conceda uma boa partida.","nerissadoyounotrememberladyinyourfathers~ofthemarquisofmontferrat~119":"Nerissa — Não vos lembrais, senhora, no tempo de vosso pai, de um veneziano, erudito e soldado, que veio aqui em companhia do marquês de Montferrat?","portiayesyesitwasbassanioasithinkhewasso~nioasithinkhewassocalled~46":"Portia — Sim, sim, era Bassanio; creio que assim se chamava.","nerissatruemadamheofallthementhatevermyf~hebestdeservingafairlady~88":"Nerissa — É verdade, senhora: ele, de todos os homens que meus tolos olhos jamais fitaram, era o que mais merecia uma bela dama.","portiairememberhimwellandirememberhimwor~mberhimworthyofthypraise~54":"Portia — Lembro-me bem dele, e lembro-me dele digno do teu louvor.","enteraservingman~enteraservingman~16":"Entra um Criado.","hownowwhatnews~hownowwhatnews~14":"Então! Que notícias?","servantthefourstrangersseekforyoumadamto~smasterwillbeheretonight~155":"Criado — Os quatro forasteiros vos procuram, senhora, para se despedir: e chegou um mensageiro de um quinto, o príncipe de Marrocos, que traz notícia de que o príncipe seu senhor estará aqui esta noite.","portiaificouldbidthefifthwelcomewithsogo~herknocksatthedoorexeunt~276":"Portia — Se eu pudesse dar as boas-vindas ao quinto com tão bom coração quanto posso dizer adeus aos outros quatro, ficaria contente com sua chegada: se ele tiver a condição de um santo e a tez de um diabo, preferiria que me confessasse a que me desposasse. Vem, Nerissa. Moço, vai na frente. Enquanto fechamos os portões a um pretendente, outro bate à porta. Saem.","sceneiii~sceneiii~8":"Cena III","veniceapublicplace~veniceapublicplace~18":"Veneza. Uma praça pública.","enterbassanioandshylock~enterbassanioandshylock~23":"Entram Bassanio e Shylock.","shylockthreethousandducatswell~kthreethousandducatswell~30":"Shylock — Três mil ducados; bem.","bassanioaysirforthreemonths~sanioaysirforthreemonths~27":"Bassanio — Sim, senhor, por três meses.","shylockforthreemonthswell~hylockforthreemonthswell~25":"Shylock — Por três meses; bem.","bassanioforthewhichasitoldyouantonioshal~ldyouantonioshallbebound~48":"Bassanio — Para o que, como vos disse, Antonio ficará obrigado.","shylockantonioshallbecomeboundwell~onioshallbecomeboundwell~34":"Shylock — Antonio ficará obrigado; bem.","bassaniomayyousteadmewillyoupleasuremesh~remeshalliknowyouranswer~58":"Bassanio — Podeis ajudar-me? Quereis fazer-me o favor? Saberei vossa resposta?","shylockthreethousandducatsforthreemonths~reemonthsandantoniobound~55":"Shylock — Três mil ducados por três meses e Antonio obrigado.","bassanioyouranswertothat~bassanioyouranswertothat~24":"Bassanio — Vossa resposta a isso.","shylockantonioisagoodman~shylockantonioisagoodman~24":"Shylock — Antonio é um homem bom.","bassaniohaveyouheardanyimputationtotheco~yimputationtothecontrary~46":"Bassanio — Ouvistes alguma acusação em contrário?","shylockohnonononomymeaninginsayingheisag~atsithinkimaytakehisbond~482":"Shylock — Ó, não, não, não, não: meu sentido ao dizer que é um homem bom é fazer-vos entender que é solvente. Contudo seus recursos estão em suposição: tem uma nau mercante rumo a Trípoli, outra para as Índias; compreendo ademais, no Rialto, que tem uma terceira no México, uma quarta para a Inglaterra, e outros empreendimentos que tem espalhados pelo estrangeiro. Mas navios são apenas tábuas, marinheiros apenas homens: há ratos de terra e ratos de água, ladrões de água e ladrões de terra, quero dizer, piratas, e depois há o perigo das águas, ventos e rochedos. O homem é, não obstante, solvente. Três mil ducados; creio que posso aceitar seu título.","bassaniobeassuredyoumay~bassaniobeassuredyoumay~23":"Bassanio — Estai seguro de que podeis.","shylockiwillbeassuredimayandthatimaybeas~nkmemayispeakwithantonio~79":"Shylock — Estarei seguro de que posso; e, para estar seguro, refletirei. Posso falar com Antonio?","bassanioifitpleaseyoutodinewithus~fitpleaseyoutodinewithus~33":"Bassanio — Se vos aprouver jantar conosco.","shylockyestosmellporktoeatofthehabitatio~herialtowhoishecomeshere~232":"Shylock — Sim, para cheirar porco; para comer da habitação em que vosso profeta, o Nazareno, conjurou o diabo. Comprarei convosco, venderei convosco, falarei convosco, passearei convosco, e assim por diante, mas não comerei convosco, não beberei convosco, nem rezarei convosco. Que notícias no Rialto? Quem é este que vem aí?","enterantonio~enterantonio~12":"Entra Antonio.","bassaniothisissigniorantonio~aniothisissigniorantonio~28":"Bassanio — Este é o senhor Antonio.","shylockasidehowlikeafawningpublicanheloo~edbemytribeififorgivehim~378":"Shylock — À parte. Que aparência de publicano bajulador ele tem!\nOdeio-o porque é cristão,\nMas mais porque em baixa simplicidade\nEmpresta dinheiro de graça e faz baixar\nA taxa de usura aqui entre nós em Veneza.\nSe eu o apanhar uma vez desprevenido,\nEngordarei o antigo rancor que lhe guardo.\nEle odeia nossa sagrada nação, e esbraveja,\nAté ali onde os mercadores mais se congregam,\nContra mim, meus negócios e meu bem-ganho lucro,\nQue ele chama de juros. Maldita seja minha tribo,\nSe eu o perdoar!","bassanioshylockdoyouhear~bassanioshylockdoyouhear~24":"Bassanio — Shylock, ouvis?","shylockiamdebatingofmypresentstoreandbyt~wasthelastmaninourmouths~265":"Shylock — Estou calculando meu estoque presente,\nE, pela aproximada estimativa de minha memória,\nNão consigo de imediato levantar a soma\nDe três mil ducados inteiros. E daí?\nTubal, um rico hebreu de minha tribo,\nMe fornecerá. Mas calma! Quantos meses\nDesejais? A Antonio. Deus vos guarde, bom senhor;\nVossa senhoria foi o último homem em nossas bocas.","antonioshylockalthoughineitherlendnorbor~etpossessdhowmuchyewould~147":"Antonio — Shylock, embora eu nem empreste nem tome emprestado\nCobrando ou pagando excesso,\nContudo, para suprir as prementes necessidades de meu amigo,\nQuebrarei um costume. Ele já está informado\nDe quanto quereis?","shylockayaythreethousandducats~kayaythreethousandducats~30":"Shylock — Sim, sim, três mil ducados.","antonioandforthreemonths~antonioandforthreemonths~24":"Antonio — E por três meses.","shylockihadforgotthreemonthsyoutoldmesow~ndnorborrowuponadvantage~128":"Shylock — Tinha esquecido; três meses; assim me dissestes.\nBem então, vosso título; e deixai-me ver; mas ouvi;\nParecia-me que dissestes que nem emprestais nem tomais\nCom vantagem.","antonioidoneveruseit~antonioidoneveruseit~20":"Antonio — Nunca o pratico.","shylockwhenjacobgrazedhisunclelabansshee~possessorayhewasthethird~134":"Shylock — Quando Jacó apascentava as ovelhas de seu tio Labão —\nEste Jacó era, desde nosso santo Abraão,\nComo sua sábia mãe providenciou em seu favor,\nO terceiro possuidor; sim, era o terceiro —","antonioandwhatofhimdidhetakeinterest~atofhimdidhetakeinterest~36":"Antonio — E que há com ele? Cobrou juros?","shylocknonottakeinterestnotasyouwouldsay~sblessingifmenstealitnot~514":"Shylock — Não, não cobrou juros, não, como diríeis,\nJuros diretos: notai o que fez Jacó.\nQuando Labão e ele se acordaram\nQue todos os cordeiros que nascessem listrados e malhados\nCaberiam como salário de Jacó, as ovelhas, no cio,\nNo fim do outono voltaram-se para os carneiros,\nE, quando a obra da geração estava\nEm ato entre esses lanudos reprodutores,\nO hábil pastor descascou-me certas varas,\nE, no ato da obra da natureza,\nEnfiou-as diante das ovelhas lascivas,\nQue, então concebendo, na hora de parir\nDeram cordeiros de duas cores, e esses foram de Jacó.\nEsta foi uma forma de prosperar, e ele foi abençoado:\nE lucro é bênção, se os homens não o roubam.","antoniothiswasaventuresirthatjacobserved~goldandsilverewesandrams~176":"Antonio — Isto foi uma aventura, senhor, pela qual Jacó serviu;\nUma coisa que não estava em seu poder realizar,\nMas governada e moldada pela mão do céu.\nFoi isto inserido para justificar os juros?\nOu vosso ouro e prata são ovelhas e carneiros?","shylockicannottellimakeitbreedasfastbutn~edasfastbutnotemesignior~52":"Shylock — Não sei dizer; faço-o procriar tão depressa:\nMas notai-me, senhor.","antoniomarkyouthisbassaniothedevilcancit~odlyoutsidefalsehoodhath~184":"Antonio — Repara nisto, Bassanio,\nO diabo pode citar as Escrituras para seus fins.\nUma alma má que produz testemunho santo\nÉ como um vilão de face sorridente,\nUma bela maçã podre por dentro:\nÓ, que bela aparência tem a falsidade!","shylockthreethousandducatstisagoodrounds~welvethenletmeseetherate~82":"Shylock — Três mil ducados; é uma boa soma redonda.\nTrês meses de doze; então, deixai-me ver; a taxa —","antoniowellshylockshallwebebeholdingtoyo~kshallwebebeholdingtoyou~41":"Antonio — Bem, Shylock, ficaremos em dívida convosco?","shylocksigniorantoniomanyatimeandoftinth~illlendyouthusmuchmoneys~724":"Shylock — Senhor Antonio, muitas vezes e amiúde\nNo Rialto me censurastes\nSobre meu dinheiro e minhas usuras:\nSempre suportei com um encolher de ombros paciente,\nPois o sofrimento é a insígnia de toda a nossa tribo.\nChamais-me descrente, cão degolador,\nE cuspis em minha túnica judia,\nE tudo pelo uso do que é meu.\nBem então, agora parece que precisais de minha ajuda:\nAdiante, então; vindes a mim, e dizeis\n“Shylock, queremos dinheiro”: assim dizeis;\nVós, que despejastes vosso catarro em minha barba\nE me chutastes como se enxota um cão forasteiro\nDa soleira: dinheiro é vosso pedido.\nQue devo dizer-vos? Não devia dizer\n“Tem dinheiro um cão? É possível\nQue um vira-lata empreste três mil ducados?” Ou\nDevo curvar-me e em tom de servo,\nCom o fôlego contido e humildade sussurrante, dizer isto:\n“Belo senhor, cuspistes em mim na quarta-feira passada;\nChutastes-me tal dia; outra vez\nChamastes-me cão; e por estas cortesias\nEmprestar-vos-ei tanto dinheiro”?","antonioiamasliketocalltheesoagaintospito~etterfaceexactthepenalty~242":"Antonio — Estou tão disposto a chamar-te assim de novo,\nA cuspir em ti de novo, a chutar-te também.\nSe queres emprestar esse dinheiro, não o emprestes\nComo a teus amigos; pois quando a amizade cobrou\nCria por metal estéril de seu amigo?\nMas empresta-o antes a teu inimigo,\nQue, se faltar, poderás com mais cara\nExigir a penalidade.","shylockwhylookyouhowyoustormiwouldbefrie~othearmethisiskindioffer~190":"Shylock — Ora, vede como vos enfurecei!\nQueria ser vosso amigo e ter vosso afeto,\nEsquecer as vergonhas com que me manchastes,\nSuprir vossas necessidades presentes e não tomar um vintém\nDe usura por meu dinheiro, e não me quereis ouvir:\nEsta é a bondade que ofereço.","bassaniothiswerekindness~bassaniothiswerekindness~24":"Bassanio — Isto seria bondade.","shylockthiskindnesswillishowgowithmetoan~partofyourbodypleasethme~265":"Shylock — Esta bondade mostrarei.\nIde comigo a um tabelião, selai-me lá\nVosso título simples; e, em divertido jogo,\nSe não me pagardes em tal dia,\nEm tal lugar, tal soma ou somas conforme\nExpressas na condição, que a multa\nSeja fixada em uma libra justa\nDe vossa bela carne, a ser cortada e tomada\nDa parte de vosso corpo que me aprouver.","antoniocontentifaithillsealtosuchabondan~reismuchkindnessinthejew~71":"Antonio — Contente, palavra: selarei tal título\nE direi que há muita bondade no judeu.","bassanioyoushallnotsealtosuchabondformei~ratherdwellinmynecessity~66":"Bassanio — Não selareis tal título por mim:\nPrefiro permanecer em minha necessidade.","antoniowhyfearnotmaniwillnotforfeititwit~etimesthevalueofthisbond~140":"Antonio — Ora, não temas, homem; não o perderei:\nDentro destes dois meses, isto é, um mês antes\nQue este título expire, espero o retorno\nDe três vezes três o valor deste título.","shylockofatherabramwhatthesechristiansar~myloveiprayyouwrongmenot~365":"Shylock — Ó pai Abraão, que gente são estes cristãos,\nCujos próprios negócios duros lhes ensinam a suspeitar\nOs pensamentos dos outros! Peço-vos, dizei-me isto;\nSe ele faltar ao dia, que ganharei\nCom a exigência da penalidade?\nUma libra de carne de homem tirada de um homem\nNão é tão estimável, nem lucrativa,\nQuanto carne de carneiros, bois ou cabras. Digo,\nPara comprar seu favor, estendo esta amizade:\nSe ele a aceitar, assim seja; se não, adeus;\nE, em nome do meu afeto, peço-vos, não me façais injustiça.","antonioyesshylockiwillsealuntothisbond~ockiwillsealuntothisbond~38":"Antonio — Sim, Shylock, selarei este título.","shylockthenmeetmeforthwithatthenotarysgi~dpresentlyiwillbewithyou~182":"Shylock — Então encontrai-me já no tabelião;\nDai-lhe instrução para este alegre título,\nE eu irei embolsar os ducados logo,\nVer minha casa, deixada na guarda temerosa\nDe um criado perdulário, e imediatamente\nEstarei convosco.","antoniohietheegentlejewexitshylocktheheb~turnchristianhegrowskind~71":"Antonio — Apressa-te, gentil judeu. Sai Shylock.\nO hebreu vai virar cristão: está ficando bondoso.","bassanioilikenotfairtermsandavillainsmin~airtermsandavillainsmind~41":"Bassanio — Não gosto de belos termos e mente de vilão.","antoniocomeoninthistherecanbenodismaymys~amonthbeforethedayexeunt~76":"Antonio — Vem: nisto não pode haver desânimo;\nMeus navios chegam um mês antes do dia. Saem.","flourishofcornetsentertheprinceofmorocco~erissaandothersattending~82":"Toque de cornetas. Entram o Príncipe de Marrocos e seu séquito; Portia, Nerissa e outros em atendimento.","moroccomislikemenotformycomplexionthesha~ourthoughtsmygentlequeen~405":"Morocco — Não me desgostes pela minha tez,\nA libré sombria do sol polido,\nDe quem sou vizinho e perto criado.\nTraze-me a mais bela criatura nascida ao norte,\nOnde o fogo de Febo mal derrete os pingentes de gelo,\nE façamos uma incisão por vosso amor,\nPara provar de quem o sangue é mais rubro, dele ou meu.\nDigo-te, senhora, este meu aspecto\nAssustou os valentes: por meu amor juro\nAs virgens mais bem-vistas de nosso clima\nTambém o amaram: não trocaria esta cor,\nSalvo para roubar vossos pensamentos, minha gentil rainha.","portiaintermsofchoiceiamnotsolelyledbyni~lookdonyetformyaffection~297":"Portia — Na escolha não sou conduzida apenas\nPela delicada direção dos olhos de uma donzela;\nAlém disso, a loteria de meu destino\nMe tolhe o direito de escolher livremente:\nMas se meu pai não me houvesse limitado\nE cercado com seu engenho, a entregar-me\nComo esposa a quem me ganhar pelo meio que vos disse,\nVós mesmo, famoso príncipe, estaríeis tão bem\nQuanto qualquer pretendente que já vi\nPara a minha afeição.","moroccoevenforthatithankyouthereforeipra~attainanddiewithgrieving~532":"Morocco — Mesmo por isso vos agradeço:\nPortanto, rogo-vos, levai-me aos cofres\nPara tentar minha sorte. Por este alfanje\nQue matou o Sófi e um príncipe persa\nQue venceu três batalhas do sultão Solimão,\nEu encararia os olhos mais severos que olham,\nDesafiaria o coração mais ousado da terra,\nArrancaria os filhotes lactentes da ursa,\nSim, zombaria do leão quando ruge por presa,\nPara vos ganhar, senhora. Mas, ai de mim!\nSe Hércules e Licas jogam aos dados\nQuem é o melhor homem, o lance maior\nPode, por fortuna, sair da mão mais fraca:\nAssim é Alcides vencido por seu pajem;\nE assim posso eu, guiado pela fortuna cega,\nPerder o que um menos digno pode alcançar,\nE morrer de pesar.","portiayoumusttakeyourchanceandeithernota~rriagethereforebeadvised~157":"Portia — Deveis correr vosso risco,\nE ou não tentar escolher de modo algum\nOu jurar antes de escolher, se escolherdes errado,\nNunca mais falar a dama alguma\nEm intenção de casamento: portanto, ponderai.","morocconorwillnotcomebringmeuntomychance~tcomebringmeuntomychance~40":"Morocco — Nem o farei. Vamos, levai-me à minha sorte.","portiafirstforwardtothetempleafterdinner~neryourhazardshallbemade~61":"Portia — Primeiro, ao templo: depois do jantar\nSerá feita vossa aposta.","moroccogoodfortunethentomakemeblestorcur~amongmencornetsandexeunt~69":"Morocco — Boa fortuna então!\nPara me fazer o mais abençoado ou o mais maldito dos homens. Toque de cornetas, e saem.","enterlauncelot~enterlauncelot~14":"Entra Launcelot.","launcelotcertainlymyconsciencewillservem~areatyourcommandiwillrun~1139":"Launcelot — Certamente minha consciência me autorizará a fugir deste judeu, meu amo. O demônio está a meu cotovelo e me tenta dizendo-me “Gobbo, Launcelot Gobbo, bom Launcelot”, ou “bom Gobbo”, ou “bom Launcelot Gobbo, usa as pernas, toma a dianteira, foge.” Minha consciência diz “Não; toma cuidado, honesto Launcelot; toma cuidado, honesto Gobbo”, ou, como dito, “honesto Launcelot Gobbo; não fujas; despreza correr com os calcanhares.” Bem, o demônio mais corajoso me manda fazer as malas: “Via!”, diz o demônio; “embora!”, diz o demônio; “pelos céus, ergue um ânimo valente”, diz o demônio, “e corre.” Bem, minha consciência, pendurada no pescoço do meu coração, diz-me muito sabiamente “Meu honesto amigo Launcelot, sendo filho de um homem honesto”, ou melhor, filho de uma mulher honesta; pois, na verdade, meu pai tinha algo de sabor, algo de pendor, tinha uma espécie de gosto; bem, minha consciência diz “Launcelot, não te mexas.” “Mexe-te”, diz o demônio. “Não te mexas”, diz minha consciência. “Consciência”, digo eu, “aconselhas bem”; “Demônio”, digo eu, “aconselhas bem”: para ser governado por minha consciência, deveria ficar com o judeu, meu amo, que, Deus guarde a marca, é uma espécie de diabo; e, para fugir do judeu, deveria ser governado pelo demônio, que, com o devido respeito, é o próprio diabo. Certamente o judeu é o diabo em pessoa; e, em minha consciência, minha consciência não passa de uma consciência dura, ao se propor a aconselhar-me a ficar com o judeu. O demônio dá o conselho mais amigo: vou correr, demônio; meus calcanhares estão a vosso mando; vou correr.","enteroldgobbowithabasket~enteroldgobbowithabasket~24":"Entra o Velho Gobbo, com um cesto.","gobbomasteryoungmanyouiprayyouwhichisthe~hichisthewaytomasterjews~55":"Gobbo — Mestre jovem, vós, peço-vos, qual é o caminho para a casa do mestre judeu?","launcelotasideoheavensthisismytruebegott~willtryconfusionswithhim~123":"Launcelot — À parte. Ó céus, este é meu pai de verdade! que, mais que cego de areia, cego de cascalho graúdo, não me conhece: vou tentar confusões com ele.","gobbomasteryounggentlemaniprayyouwhichis~hichisthewaytomasterjews~58":"Gobbo — Mestre jovem cavalheiro, peço-vos, qual é o caminho para a casa do mestre judeu?","launcelotturnuponyourrighthandatthenextt~indirectlytothejewshouse~152":"Launcelot — Virai à mão direita na próxima esquina, mas, na esquina seguinte de todas, à esquerda; pois bem, na esquina mesmo seguinte, não virai a mão alguma, mas descei de través para a casa do judeu.","gobbobygodssontiestwillbeahardwaytohitca~swithhimdwellwithhimorno~102":"Gobbo — Por Deus e seus santinhos, será um caminho difícil de acertar. Podeis dizer-me se um tal Launcelot, que mora com ele, mora com ele ou não?","launcelottalkyouofyoungmasterlauncelotas~ouofyoungmasterlauncelot~103":"Launcelot — Falais do jovem Mestre Launcelot? À parte. Reparai agora; agora vou levantar as águas. Falais do jovem Mestre Launcelot?","gobbonomastersirbutapoormanssonhisfather~ndgodbethankedwelltolive~103":"Gobbo — Mestre não, senhor, mas filho de um pobre homem: seu pai, embora eu o diga, é um homem honesto e extremamente pobre e, graças a Deus, bem de saúde.","launcelotwelllethisfatherbewhatawillweta~lkofyoungmasterlauncelot~64":"Launcelot — Bem, seja o pai o que quiser, falamos do jovem Mestre Launcelot.","gobboyourworshipsfriendandlauncelotsir~ipsfriendandlauncelotsir~38":"Gobbo — Amigo de vossa mercê e Launcelot, senhor.","launcelotbutiprayyouergooldmanergoibesee~ouofyoungmasterlauncelot~74":"Launcelot — Mas peço-vos, ergo, velho, ergo, rogo-vos, falais do jovem Mestre Launcelot?","gobbooflauncelotantpleaseyourmastership~tantpleaseyourmastership~39":"Gobbo — De Launcelot, se apraz a vossa mestria.","launcelotergomasterlauncelottalknotofmas~inplaintermsgonetoheaven~218":"Launcelot — Ergo, Mestre Launcelot. Não faleis de Mestre Launcelot, pai; pois o jovem cavalheiro, segundo os Fados e Destinos e tais ditos esquisitos, as Três Irmãs e tais ramos do saber, está de fato falecido, ou, como diríeis em termos claros, foi para o céu.","gobbomarrygodforbidtheboywastheverystaff~rystaffofmyagemyveryprop~57":"Gobbo — Por Nossa Senhora, Deus não permita! o rapaz era o próprio bordão de minha velhice, meu próprio esteio.","launcelotdoilooklikeacudgelorahovelposta~orapropdoyouknowmefather~69":"Launcelot — Pareço-me com um cacete ou um poste de choupana, um bordão ou um esteio? Conheceis-me, pai?","gobboalackthedayiknowyounotyounggentlema~odresthissoulaliveordead~90":"Gobbo — Ai, que dia, não vos conheço, jovem cavalheiro: mas, peço-vos, dizei-me, meu rapaz, que Deus lhe guarde a alma, está vivo ou morto?","launcelotdoyounotknowmefather~elotdoyounotknowmefather~29":"Launcelot — Não me conheceis, pai?","gobboalacksiriamsandblindiknowyounot~riamsandblindiknowyounot~36":"Gobbo — Ai, senhor, estou cego de areia; não vos conheço.","launcelotnayindeedifyouhadyoureyesyoumig~tatthelengthtruthwillout~226":"Launcelot — Não, na verdade, se tivésseis os olhos, poderíeis falhar em me conhecer: é sábio o pai que conhece o próprio filho. Bem, velho, vou dar-vos notícias de vosso filho: dai-me vossa bênção: a verdade virá à luz; o assassinato não pode ficar muito tempo oculto; o filho de um homem pode, mas por fim a verdade se revela.","gobboprayyousirstandupiamsureyouarenotla~eyouarenotlauncelotmyboy~52":"Gobbo — Peço-vos, senhor, levantai-vos: tenho certeza de que não sois Launcelot, meu rapaz.","launcelotprayyouletshavenomorefoolingabo~atisyourchildthatshallbe~124":"Launcelot — Peço-vos, não façamos mais tolices, mas dai-me vossa bênção: sou Launcelot, vosso rapaz que foi, vosso filho que é, vosso filho que será.","gobboicannotthinkyouaremyson~oicannotthinkyouaremyson~28":"Gobbo — Não posso crer que sejais meu filho.","launcelotiknownotwhatishallthinkofthatbu~argeryyourwifeismymother~98":"Launcelot — Não sei o que devo pensar disso: mas sou Launcelot, o criado do judeu, e tenho certeza de que Margery, vossa esposa, é minha mãe.","gobbohernameismargeryindeedillbeswornift~nmyfillhorsehasonhistail~186":"Gobbo — Seu nome é Margery, de fato: juro que, se és Launcelot, és minha própria carne e sangue. Senhor seja louvado! Que barba tens! Tens mais pelo no queixo do que Dobbin, meu cavalo de brancal, tem na cauda.","launcelotitshouldseemthenthatdobbinstail~eofmyfacewhenilastsawhim~114":"Launcelot — Parece então que a cauda de Dobbin cresce para trás: tenho certeza de que ele tinha mais pelo na cauda do que eu tenho no rosto quando o vi pela última vez.","gobbolordhowartthouchangedhowdostthouand~himapresenthowgreeyounow~90":"Gobbo — Senhor, como estás mudado! Como te entendes com teu amo? Trouxe-lhe um presente. Como vos entendeis agora?","launcelotwellwellbutformineownpartasihav~wifiservethejewanylonger~405":"Launcelot — Bem, bem: mas, de minha parte, como já decidi fugir, não descansarei até ter corrido algum chão. Meu amo é um perfeito judeu: dar-lhe um presente! Dai-lhe uma corda: morro de fome a seu serviço; podeis contar cada dedo que tenho pelas minhas costelas. Pai, estou contente que viestes: dai vosso presente a um Mestre Bassanio, que, de fato, dá raras libres novas: se não o servir, correrei tão longe quanto Deus tiver chão. Ó rara fortuna! eis que vem o homem: a ele, pai; pois sou judeu, se servir ao judeu por mais tempo.","enterbassaniowithleonardoandotherfollowe~eonardoandotherfollowers~42":"Entra Bassanio, com Leonardo e outros seguidores.","bassanioyoumaydosobutletitbesohastedthat~ntomylodgingexitaservant~178":"Bassanio — Podeis fazê-lo; mas que seja tão depressa que a ceia esteja pronta, no máximo, às cinco horas. Vede que estas cartas sejam entregues; mandai fazer as libres, e pedi a Gratiano que venha logo a meus aposentos. Sai um Criado.","launcelottohimfather~launcelottohimfather~20":"Launcelot — A ele, pai.","gobbogodblessyourworship~gobbogodblessyourworship~24":"Gobbo — Deus abençoe vossa mercê!","bassaniogramercywouldstthouaughtwithme~cywouldstthouaughtwithme~38":"Bassanio — Muito obrigado! Queres algo comigo?","gobboheresmysonsirapoorboy~bboheresmysonsirapoorboy~26":"Gobbo — Eis meu filho, senhor, um pobre rapaz —","launcelotnotapoorboysirbuttherichjewsman~irasmyfathershallspecify~74":"Launcelot — Não um pobre rapaz, senhor, mas o criado do rico judeu; que quereria, senhor, como meu pai especificará —","gobbohehathagreatinfectionsirasonewoulds~nsirasonewouldsaytoserve~49":"Gobbo — Ele tem uma grande infecção, senhor, por assim dizer, de servir —","launcelotindeedtheshortandthelongisiserv~reasmyfathershallspecify~83":"Launcelot — De fato, o curto e o longo é que sirvo o judeu, e tenho um desejo, como meu pai especificará —","gobbohismasterandhesavingyourworshipsrev~ncearescarcecatercousins~67":"Gobbo — Seu amo e ele, com o respeito devido a vossa mercê, mal são primos-irmãos —","launcelottobebrieftheverytruthisthatthej~ldmanshallfrutifyuntoyou~117":"Launcelot — Para ser breve, a pura verdade é que o judeu, tendo-me feito mal, me leva, como meu pai, sendo, espero, um homem velho, frutificará a vós —","gobboihavehereadishofdovesthatiwouldbest~onyourworshipandmysuitis~68":"Gobbo — Tenho aqui um prato de pombos que gostaria de oferecer a vossa mercê, e meu pedido é —","launcelotinverybriefthesuitisimpertinent~oldmanyetpoormanmyfather~133":"Launcelot — Em brevíssimo, o pedido é impertinente para mim, como vossa mercê saberá por este honesto velho; e, embora eu o diga, embora velho, no entanto pobre, meu pai.","bassanioonespeakforbothwhatwouldyou~speakforbothwhatwouldyou~35":"Bassanio — Um fale por ambos. Que quereis?","launcelotserveyousir~launcelotserveyousir~20":"Launcelot — Servir-vos, senhor.","gobbothatistheverydefectofthemattersir~verydefectofthemattersir~38":"Gobbo — Esse é o próprio defeito da questão, senhor.","bassanioiknowtheewellthouhastobtaindthys~llowerofsopooragentleman~172":"Bassanio — Conheço-te bem; obtiveste teu pedido:\nShylock, teu amo, falou comigo hoje,\nE te recomendou, se for recomendação\nDeixar o serviço de um rico judeu para tornar-te\nO seguidor de um cavalheiro tão pobre.","launcelottheoldproverbisverywellpartedbe~eofgodsirandhehathenough~107":"Launcelot — O velho provérbio está muito bem repartido entre meu amo Shylock e vós, senhor: vós tendes a graça de Deus, senhor, e ele tem o bastante.","bassaniothouspeakstitwellgofatherwiththy~dthanhisfellowsseeitdone~136":"Bassanio — Falas bem. Vai, pai, com teu filho.\nDespede-te de teu velho amo e procura\nMeus aposentos. Dá-lhe uma libré\nMais agaloada que a de seus companheiros: vê que se faça.","launcelotfatherinicannotgetaservicenoiha~euntlauncelotandoldgobbo~490":"Launcelot — Pai, entra. Não consigo arranjar um emprego, não; não tenho língua na cabeça. Bem, se algum homem na Itália tiver uma palma mais bela, que ofereça jurar sobre um livro, terei boa fortuna. Vamos, eis uma simples linha da vida: eis um pequeno punhado de esposas: ai, quinze esposas não é nada! onze viúvas e nove donzelas é um ganho modesto para um homem só: e depois escapar três vezes de afogamento, e estar em perigo de vida pela beirada de uma cama de penas; eis escapadas modestas. Bem, se a Fortuna é mulher, é uma boa moça para esse negócio. Pai, vem; despedir-me-ei do judeu num piscar de olhos. Saem Launcelot e o Velho Gobbo.","bassanioipraytheegoodleonardothinkonthis~emdacquaintancehietheego~144":"Bassanio — Peço-te, bom Leonardo, pensa nisto:\nTendo estas coisas sido compradas e ordenadamente dispostas,\nVolta depressa, pois hoje à noite dou um banquete\nAos meus mais estimados conhecidos: apressa-te, vai.","leonardomybestendeavoursshallbedoneherei~eavoursshallbedoneherein~41":"Leonardo — Meus melhores esforços serão feitos nisso.","entergratiano~entergratiano~13":"Entra Gratiano.","gratianowhereisyourmaster~ratianowhereisyourmaster~25":"Gratiano — Onde está vosso amo?","leonardoyondersirhewalksexit~ardoyondersirhewalksexit~28":"Leonardo — Ali, senhor, ele passeia. Sai.","gratianosigniorbassanio~gratianosigniorbassanio~23":"Gratiano — Senhor Bassanio!","bassaniogratiano~bassaniogratiano~16":"Bassanio — Gratiano!","gratianoihaveasuittoyou~gratianoihaveasuittoyou~23":"Gratiano — Tenho um pedido a vos fazer.","bassanioyouhaveobtaindit~bassanioyouhaveobtaindit~24":"Bassanio — Já o obtiveste.","gratianoyoumustnotdenymeimustgowithyouto~eimustgowithyoutobelmont~47":"Gratiano — Não deveis me negar: devo ir convosco a Belmont.","bassaniowhythenyoumustbutheartheegratian~placeigotoandlosemyhopes~336":"Bassanio — Então deves. Mas ouve, Gratiano;\nÉs demasiado selvagem, demasiado rude e arrojado de voz;\nQualidades que te caem bastante bem\nE a olhos como os nossos não parecem defeitos;\nMas onde não és conhecido, ora, ali mostram\nAlgo demasiado licencioso. Peço-te, esforça-te\nPara temperar com algumas frias gotas de modéstia\nTeu espírito saltitante, para que por teu comportamento selvagem\nEu não seja mal interpretado no lugar a que vou,\nE perca minhas esperanças.","gratianosigniorbassaniohearmeifidonotput~sgrandamnevertrustmemore~286":"Gratiano — Senhor Bassanio, ouvi-me:\nSe eu não vestir um hábito sóbrio,\nFalar com respeito e jurar só de vez em quando,\nTrazer livros de oração no bolso, olhar com recato,\nMais ainda, enquanto se diz a graça, encapuzar meus olhos\nAssim com o chapéu, e suspirar e dizer “amém”,\nUsar toda a observância da civilidade,\nComo alguém bem versado em aparência grave\nPara agradar à avó, nunca mais confiai em mim.","bassaniowellweshallseeyourbearing~ellweshallseeyourbearing~33":"Bassanio — Bem, veremos teu comportamento.","gratianonaybutibartonightyoushallnotgaug~gaugemebywhatwedotonight~60":"Gratiano — Não, mas excetuo esta noite: não me julgareis\nPelo que fizermos esta noite.","bassanionothatwerepityiwouldentreatyoura~youwellihavesomebusiness~140":"Bassanio — Não, isso seria pena:\nAntes te rogaria que vestisses\nTeu mais ousado traje de alegria, pois temos amigos\nQue pretendem folia. Mas passa bem:\nTenho alguns negócios.","gratianoandimusttolorenzoandtherestbutwe~sityouatsuppertimeexeunt~70":"Gratiano — E eu devo ir a Lorenzo e aos demais:\nMas vos visitaremos na hora da ceia. Saem.","thesamearoominshylockshouse~samearoominshylockshouse~27":"O mesmo lugar. Um aposento na casa de Shylock.","enterjessicaandlauncelot~enterjessicaandlauncelot~24":"Entram Jessica e Launcelot.","jessicaiamsorrythouwiltleavemyfathersoou~atherseemeintalkwiththee~287":"Jessica — Lamento que deixes meu pai assim:\nNossa casa é o inferno, e tu, um diabo alegre,\nTirava-lhe algo do gosto do tédio.\nMas passa bem, eis um ducado para ti:\nE, Launcelot, logo na ceia verás\nLorenzo, que é convidado de teu novo amo:\nDá-lhe esta carta; faze-o em segredo;\nE assim adeus: não quero que meu pai\nMe veja em conversa contigo.","launcelotadieutearsexhibitmytonguemostbe~gdrownmymanlyspiritadieu~178":"Launcelot — Adeus! as lágrimas inibem minha língua. Belíssima pagã, doce judia! se um cristão não fizer o papel de patife e te levar, muito me engano. Mas adeus: estas tolas gotas afogam um pouco meu espírito viril: adeus.","jessicafarewellgoodlauncelotexitlauncelo~tianandthylovingwifeexit~226":"Jessica — Adeus, bom Launcelot. Sai Launcelot.\nAi, que pecado hediondo há em mim\nEm ter vergonha de ser filha de meu pai!\nMas embora seja filha de seu sangue,\nNão o sou de seus modos. Ó Lorenzo,\nSe cumprires a promessa, porei fim a esta luta,\nTornar-me-ei cristã e tua amorosa esposa. Sai.","sceneiv~sceneiv~7":"Cena IV","thesameastreet~thesameastreet~14":"O mesmo lugar. Uma rua.","entergratianolorenzosalarinoandsalanio~orenzosalarinoandsalanio~38":"Entram Gratiano, Lorenzo, Salarino e Salanio.","lorenzonaywewillslinkawayinsuppertimedis~gingandreturnallinanhour~78":"Lorenzo — Não, escapuliremos na hora da ceia,\nNos disfarçaremos em meus aposentos e voltaremos,\nTudo em uma hora.","gratianowehavenotmadegoodpreparation~venotmadegoodpreparation~36":"Gratiano — Não fizemos bons preparativos.","salarinowehavenotspokeusyetoftorchbearer~spokeusyetoftorchbearers~41":"Salarino — Ainda não falamos de porta-tochas.","salaniotisvileunlessitmaybequaintlyorder~tterinmymindnotundertook~70":"Salanio — É coisa vil, a menos que seja engenhosamente ordenada,\nE melhor, em minha opinião, não empreendida.","lorenzotisnowbutfouroclockwehavetwohours~ehavetwohourstofurnishus~51":"Lorenzo — São apenas quatro horas: temos duas horas\nPara nos aprestar.","enterlauncelotwithaletter~nterlauncelotwithaletter~25":"Entra Launcelot, com uma carta.","friendlauncelotwhatsthenews~endlauncelotwhatsthenews~27":"Amigo Launcelot, que notícias?","launcelotanitshallpleaseyoutobreakupthis~thisitshallseemtosignify~60":"Launcelot — Se vos aprouver abrir isto, parecerá significar.","lorenzoiknowthehandinfaithtisafairhandan~tonisthefairhandthatwrit~88":"Lorenzo — Conheço a letra: na verdade, é bela letra;\nE mais branca que o papel em que escreveu\nÉ a bela mão que escreveu.","gratianolovenewsinfaith~gratianolovenewsinfaith~23":"Gratiano — Notícias de amor, na verdade.","launcelotbyyourleavesir~launcelotbyyourleavesir~23":"Launcelot — Com vossa licença, senhor.","lorenzowhithergoestthou~lorenzowhithergoestthou~23":"Lorenzo — Para onde vais?","launcelotmarrysirtobidmyoldmasterthejewt~hmynewmasterthechristian~78":"Launcelot — Pois bem, senhor, convidar meu velho amo, o judeu, a cear esta noite com meu novo amo, o cristão.","lorenzoholdheretakethistellgentlejessica~amprovidedofatorchbearer~157":"Lorenzo — Espera, toma isto: dize à gentil Jessica\nQue não lhe falharei; dize-o em privado.\nIde, cavalheiros, Sai Launcelot.\nVos preparareis para esta mascarada de hoje à noite?\nTenho um porta-tocha providenciado.","salarinoaymarryillbegoneaboutitstraight~illbegoneaboutitstraight~39":"Salarino — Sim, na verdade, vou já cuidar disso.","salanioandsowilli~salanioandsowilli~17":"Salanio — E eu também.","lorenzomeetmeandgratianoatgratianoslodgi~anoslodgingsomehourhence~55":"Lorenzo — Encontrai-me, a mim e a Gratiano,\nNa casa de Gratiano daqui a uma hora.","salarinotisgoodwedosoexeuntsalarinoandsa~exeuntsalarinoandsalanio~45":"Salarino — É bom que assim façamos. Saem Salarino e Salanio.","gratianowasnotthatletterfromfairjessica~hatletterfromfairjessica~39":"Gratiano — Não era aquela carta da bela Jessica?","lorenzoimustneedstelltheeallshehathdirec~allbemytorchbearerexeunt~369":"Lorenzo — Devo te contar tudo. Ela indicou\nComo devo levá-la da casa do pai,\nQue ouro e joias ela traz consigo,\nQue traje de pajem ela tem pronto.\nSe algum dia o judeu, seu pai, chegar ao céu,\nSerá por causa de sua gentil filha:\nE nunca ouse o infortúnio cruzar-lhe o pé,\nA menos que o faça sob esta desculpa,\nDe que é filha de um judeu infiel.\nVem, vai comigo; lê isto enquanto andas:\nA bela Jessica será minha porta-tocha. Saem.","scenev~scenev~6":"Cena V","thesamebeforeshylockshouse~esamebeforeshylockshouse~26":"O mesmo lugar. Diante da casa de Shylock.","entershylockandlauncelot~entershylockandlauncelot~24":"Entram Shylock e Launcelot.","shylockwellthoushaltseethyeyesshallbethy~appareloutwhyjessicaisay~192":"Shylock — Bem, verás, teus olhos serão teu juiz,\nA diferença entre o velho Shylock e Bassanio: —\nQuê, Jessica! — não te empanturrarás,\nComo fizeste comigo: — Quê, Jessica! —\nE dormir e roncar, e rasgar roupas; —\nOra, Jessica, digo eu!","launcelotwhyjessica~launcelotwhyjessica~19":"Launcelot — Ora, Jessica!","shylockwhobidstheecallidonotbidtheecall~heecallidonotbidtheecall~39":"Shylock — Quem te manda chamar? Eu não te mando chamar.","launcelotyourworshipwaswonttotellmethati~ddonothingwithoutbidding~68":"Launcelot — Vossa mercê costumava me dizer que eu não podia fazer nada sem ser mandado.","enterjessica~enterjessica~12":"Entra Jessica.","jessicacallyouwhatisyourwill~icacallyouwhatisyourwill~28":"Jessica — Chamais-me? Qual é vossa vontade?","shylockiambidforthtosupperjessicatherear~ddreamofmoneybagstonight~252":"Shylock — Fui convidado a cear fora, Jessica:\nEis minhas chaves. Mas por que devo ir?\nNão fui convidado por afeto; eles me lisonjeiam:\nMas ainda assim irei por ódio, para banquetear-me\nCom o cristão pródigo. Jessica, minha menina,\nCuida de minha casa. Estou muito relutante em ir:\nHá algum mal fermentando contra meu repouso,\nPois sonhei com bolsas de dinheiro esta noite.","launcelotibeseechyousirgomyyoungmasterdo~erdothexpectyourreproach~60":"Launcelot — Suplico-vos, senhor, ide: meu jovem amo espera vossa censura.","shylocksodoihis~shylocksodoihis~15":"Shylock — Assim eu a dele.","launcelotantheyhaveconspiredtogetheriwil~asfouryearintheafternoon~216":"Launcelot — Se conspiraram juntos, não direi que vereis uma mascarada; mas se virdes, então não foi à toa que meu nariz sangrou na última Segunda-Feira Negra às seis horas da manhã, caindo naquele ano na Quarta-Feira de Cinzas, faz quatro anos, à tarde.","shylockwhataretheremasqueshearyoumejessi~foremesirrahsayiwillcome~395":"Shylock — Quê, há mascaradas? Ouve-me, Jessica:\nTranca minhas portas; e quando ouvires o tambor\nE o vil guincho do pífaro de pescoço torto,\nNão subas então às janelas,\nNem enfies a cabeça na rua pública\nPara olhar tolos cristãos de rostos envernizados,\nMas tapa os ouvidos de minha casa, quero dizer, as janelas:\nQue o som da frivolidade rasa não entre\nEm minha casa sóbria. Pelo cajado de Jacó, juro,\nNão tenho vontade de banquetear-me fora esta noite:\nMas irei. Vai na minha frente, moço;\nDize que irei.","launcelotiwillgobeforesirmistresslookout~illbeworthajewesseyeexit~108":"Launcelot — Irei na frente, senhor. Senhora, olhai pela janela, apesar de tudo;\nPassará um cristão por aqui\nQue valerá o olho de uma judia. Sai.","shylockwhatsaysthatfoolofhagarsoffspring~tfoolofhagarsoffspringha~42":"Shylock — Que diz aquele tolo, rebento de Agar, hã?","jessicahiswordswerefarewellmistressnothi~ewellmistressnothingelse~46":"Jessica — Suas palavras foram “Adeus, senhora”; nada mais.","shylockthepatchiskindenoughbutahugefeede~erstaleinthriftymindexit~316":"Shylock — O bobo é bondoso bastante, mas enorme comilão;\nLento como caracol no lucro, e dorme de dia\nMais que o gato selvagem: zangões não colmeiam comigo;\nPortanto me separo dele, e me separo dele\nPara alguém que o queira ajudando a gastar\nSua bolsa emprestada. Bem, Jessica, entra;\nTalvez eu volte logo:\nFaze como mandei; fecha as portas atrás de ti:\nBem trancado, bem achado;\nProvérbio nunca gasto em mente econômica. Sai.","jessicafarewellandifmyfortunebenotcrosti~theryouadaughterlostexit~71":"Jessica — Adeus; e se minha sorte não for contrariada,\nTenho um pai, vós uma filha, perdidos. Sai.","scenevi~scenevi~7":"Cena VI","thesame~thesame~7":"O mesmo lugar.","entergratianoandsalarinomasqued~atianoandsalarinomasqued~31":"Entram Gratiano e Salarino, mascarados.","gratianothisisthepenthouseunderwhichlore~enzodesiredustomakestand~63":"Gratiano — Este é o alpendre sob o qual Lorenzo\nPediu que esperássemos.","salarinohishourisalmostpast~arinohishourisalmostpast~27":"Salarino — Sua hora está quase passada.","gratianoanditismarvelheoutdwellshishourf~erseverrunbeforetheclock~69":"Gratiano — E é de admirar que ele ultrapasse sua hora,\nPois os amantes sempre correm adiante do relógio.","salarinootentimesfastervenuspigeonsflyto~pobligedfaithunforfeited~105":"Salarino — Ó, dez vezes mais veloz voam os pombos de Vênus\nPara selar os laços do amor recém-feitos do que costumam\nPara manter a fé empenhada sem quebra!","gratianothateverholdswhorisethfromafeast~beggardbythestrumpetwind~409":"Gratiano — Isso sempre vale: quem se ergue de um banquete\nCom o apetite aguçado com que se sentou?\nOnde está o cavalo que desfaz de novo\nSuas tediosas passadas com o fogo inabalado\nCom que as percorreu a primeira vez? Todas as coisas que são,\nSão perseguidas com mais ânimo que desfrutadas.\nComo um mocinho ou um pródigo\nO navio embandeirado deixa sua baía natal,\nAbraçado e estreitado pelo vento meretriz!\nComo o pródigo ele retorna,\nCom costados gastos pelo tempo e velas esfarrapadas,\nMagro, rasgado e empobrecido pelo vento meretriz!","salarinoherecomeslorenzomoreofthishereaf~renzomoreofthishereafter~43":"Salarino — Eis que vem Lorenzo: mais disto depois.","enterlorenzo~enterlorenzo~12":"Entra Lorenzo.","lorenzosweetfriendsyourpatienceformylong~smyfatherjewhowhoswithin~183":"Lorenzo — Doces amigos, vossa paciência pela minha longa demora;\nNão eu, mas meus negócios, vos fizeram esperar:\nQuando vos aprouver bancar os ladrões de esposas,\nVigiarei tanto por vós. Aproximai-vos;\nAqui mora meu pai judeu. Ei! Quem está dentro?","enterjessicaaboveinboysclothes~essicaaboveinboysclothes~30":"Entra Jessica, no alto, em roupas de rapaz.","jessicawhoareyoutellmeformorecertaintyal~earthatidoknowyourtongue~73":"Jessica — Quem sois? Dizei-me, para maior certeza,\nEmbora jure que conheço vossa língua.","lorenzolorenzoandthylove~lorenzolorenzoandthylove~24":"Lorenzo — Lorenzo, e teu amor.","jessicalorenzocertainandmyloveindeedforw~oulorenzowhetheriamyours~95":"Jessica — Lorenzo, certamente, e meu amor de fato,\nPois a quem amo tanto? E agora quem sabe\nSenão vós, Lorenzo, se sou vossa?","lorenzoheavenandthythoughtsarewitnesstha~htsarewitnessthatthouart~48":"Lorenzo — O céu e teus pensamentos são testemunhas de que és.","jessicaherecatchthiscasketitisworththepa~emethustransformedtoaboy~235":"Jessica — Aqui, apanha este cofrinho; vale o esforço.\nAlegra-me que seja noite, não me vedes,\nPois tenho muita vergonha da minha troca:\nMas o amor é cego e os amantes não veem\nAs lindas tolices que eles próprios cometem;\nPois se pudessem, o próprio Cupido coraria\nAo ver-me assim transformada em rapaz.","lorenzodescendforyoumustbemytorchbearer~oryoumustbemytorchbearer~39":"Lorenzo — Desce, pois deves ser minha porta-tocha.","jessicawhatmustiholdacandletomyshamesthe~loveandishouldbeobscured~125":"Jessica — Quê, devo segurar uma vela para minhas vergonhas?\nElas, em si, na verdade, já são leves demais.\nOra, é um ofício de revelação, amor;\nE eu deveria estar oculta.","lorenzosoareyousweeteveninthelovelygarni~staydforatbassaniosfeast~127":"Lorenzo — Assim estás, doce,\nMesmo no adorável adorno de um rapaz.\nMas vem de uma vez;\nPois a noite fechada faz-se fugitiva,\nE esperam-nos no banquete de Bassanio.","jessicaiwillmakefastthedoorsandgildmysel~withyoustraightexitabove~88":"Jessica — Fecharei bem as portas, e me dourarei\nCom mais alguns ducados, e estarei contigo já. Sai do alto.","gratianonowbymyhoodagentileandnojew~bymyhoodagentileandnojew~35":"Gratiano — Agora, por meu capuz, uma gentia e não judia.","lorenzobeshrewmebutiloveherheartilyforsh~beplacedinmyconstantsoul~199":"Lorenzo — Maldito eu seja se não a amo de coração;\nPois é sábia, se posso julgá-la,\nE bela é, se meus olhos são verdadeiros,\nE leal é, como se provou,\nE portanto, como ela mesma, sábia, bela e leal,\nSerá colocada em minha alma constante.","enterjessicabelow~enterjessicabelow~17":"Entra Jessica, embaixo.","whatartthoucomeongentlemenawayourmasquin~itwithjessicaandsalarino~91":"Quê, chegaste? Adiante, cavalheiros; vamos!\nNossos companheiros de mascarada a esta hora nos esperam. Sai com Jessica e Salarino.","antoniowhosthere~antoniowhosthere~16":"Antonio — Quem está aí?","gratianosigniorantonio~gratianosigniorantonio~22":"Gratiano — Senhor Antonio!","antoniofiefiegratianowherearealltherestt~enttwentyouttoseekforyou~167":"Antonio — Que vergonha, que vergonha, Gratiano! Onde estão todos os demais?\nSão nove horas: nossos amigos todos esperam por vós.\nNada de mascarada hoje: o vento mudou;\nBassanio vai embarcar logo:\nMandei vinte pessoas procurar-vos.","gratianoiamgladontidesirenomoredelightth~sailandgonetonightexeunt~75":"Gratiano — Fico contente: não desejo maior deleite\nDo que estar a vela e partido esta noite. Saem.","scenevii~scenevii~8":"Cena VII","flourishofcornetsenterportiawiththeprinc~eofmoroccoandtheirtrains~64":"Toque de cornetas. Entram Portia, com o Príncipe de Marrocos, e seus séquitos.","portiagodrawasidethecurtainsanddiscovert~eprincenowmakeyourchoice~90":"Portia — Ide, afastai as cortinas e descobri\nOs diversos cofres a este nobre príncipe.\nAgora fazei vossa escolha.","moroccothefirstofgoldwhothisinscriptionb~iknowifidochoosetheright~269":"Morocco — O primeiro, de ouro, que traz esta inscrição,\n“Quem me escolher ganhará o que muitos homens desejam”;\nO segundo, de prata, que traz esta promessa,\n“Quem me escolher obterá tanto quanto merece”;\nEste terceiro, de chumbo opaco, com aviso igualmente áspero,\n“Quem me escolher deve dar e arriscar tudo o que tem.”\nComo saberei se escolho o certo?","portiatheoneofthemcontainsmypictureprinc~sethattheniamyourswithal~74":"Portia — Um deles contém meu retrato, príncipe:\nSe escolherdes esse, então sou vossa também.","moroccosomegoddirectmyjudgmentletmeseeiw~oichooseandthriveiasimay~1590":"Morocco — Algum deus dirija meu juízo! Deixai-me ver;\nVou examinar de novo as inscrições.\nQue diz este cofre de chumbo?\n“Quem me escolher deve dar e arriscar tudo o que tem.”\nDeve dar: por quê? Por chumbo? Arriscar por chumbo?\nEste cofre ameaça. Homens que arriscam tudo\nFazem-no na esperança de belas vantagens:\nUma mente de ouro não se curva a aparências de escória;\nNão darei nem arriscarei, então, nada por chumbo.\nQue diz a prata com sua cor virginal?\n“Quem me escolher obterá tanto quanto merece.”\nTanto quanto merece! Pausa aí, Marrocos,\nE pesa teu valor com mão equânime:\nSe és avaliado por tua própria estima,\nMereces bastante; e contudo bastante\nPode não se estender tanto quanto à dama:\nE contudo temer meu merecimento\nSeria um fraco rebaixamento de mim mesmo.\nTanto quanto mereço! Ora, essa é a dama:\nMereço-a em nascimento, e em fortunas,\nEm graças e em qualidades de educação;\nMas mais que isto, em amor eu mereço.\nE se eu não me desviasse mais, mas escolhesse aqui?\nVejamos mais uma vez este dito gravado em ouro\n“Quem me escolher ganhará o que muitos homens desejam.”\nOra, essa é a dama; o mundo inteiro a deseja;\nDos quatro cantos da terra vêm,\nBeijar este santuário, esta santa de sopro mortal:\nOs desertos da Hircânia e as vastas selvas\nDa larga Arábia são agora como estradas\nPara príncipes virem ver a bela Portia:\nO reino aquoso, cuja cabeça ambiciosa\nCospe na face do céu, não é barreira\nPara deter os espíritos estrangeiros, que vêm,\nComo sobre um riacho, ver a bela Portia.\nUm destes três contém seu retrato celestial.\nÉ provável que o chumbo a contenha? Seria condenação\nPensar tão baixo pensamento: seria demasiado grosseiro\nCingir sua mortalha no escuro túmulo.\nOu pensarei que em prata ela está emparedada,\nSendo dez vezes menos valiosa que o ouro provado?\nÓ pensamento pecaminoso! Nunca tão rica joia\nFoi engastada em coisa pior que ouro. Têm na Inglaterra\nUma moeda que traz a figura de um anjo\nCunhada em ouro, mas é apenas gravada por cima;\nMas aqui um anjo num leito de ouro\nJaz todo por dentro. Entregai-me a chave:\nAqui escolho, e prospere eu como puder!","portiatheretakeitprinceandifmyformliethe~heunlocksthegoldencasket~78":"Portia — Tomai, príncipe; e se minha imagem jaz aí,\nEntão sou vossa. Ele abre o cofre de ouro.","moroccoohellwhathavewehereacarriondeathw~istrainflourishofcornets~470":"Morocco — Ó inferno! Que temos aqui?\nUma Morte carniça, em cuja órbita vazia\nHá um rolo escrito! Lerei o escrito. Lê. Nem tudo que reluz é ouro;\nAmiúde ouvistes isso contado:\nMuitos homens venderam a vida\nSó por ver minha aparência:\nTúmulos dourados encerram vermes.\nTivésseis sido sábio como ousado,\nJovem de membros, de juízo velho,\nVossa resposta não estaria enrolada:\nPassai bem; vosso pedido está frio. Frio, de fato; e trabalho perdido:\nEntão adeus, calor, e bem-vinda, geada! Portia, adeus. Tenho o coração muito aflito\nPara fazer uma despedida longa: assim partem os que perdem. Sai com seu séquito. Toque de cornetas.","portiaagentleriddancedrawthecurtainsgole~mplexionchoosemesoexeunt~75":"Portia — Bom livramento. Fechai as cortinas, ide.\nQue todos de sua tez me escolham assim. Saem.","sceneviii~sceneviii~9":"Cena VIII","entersalarinoandsalanio~entersalarinoandsalanio~23":"Entram Salarino e Salanio.","salarinowhymanisawbassanioundersailwithh~rshipiamsurelorenzoisnot~94":"Salarino — Ora, homem, vi Bassanio a vela:\nCom ele foi Gratiano;\nE em seu navio tenho certeza de que Lorenzo não está.","salaniothevillainjewwithoutcriesraisedth~himtosearchbassaniosship~80":"Salanio — O vilão judeu com gritos levantou o doge,\nQue foi com ele revistar o navio de Bassanio.","salarinohecametoolatetheshipwasundersail~notwithbassanioinhisship~194":"Salarino — Chegou tarde demais, o navio já estava a vela:\nMas ali o doge foi informado\nDe que numa gôndola foram vistos juntos\nLorenzo e sua amorosa Jessica:\nAlém disso, Antonio certificou ao doge\nQue não estavam com Bassanio em seu navio.","salanioineverheardapassionsoconfusedsost~tonesuponherandtheducats~381":"Salanio — Nunca ouvi paixão tão confusa,\nTão estranha, ultrajante e tão variável,\nComo a que o cão judeu proferiu nas ruas:\n“Minha filha! Ó meus ducados! Ó minha filha!\nFugiu com um cristão! Ó meus ducados cristãos!\nJustiça! A lei! Meus ducados, e minha filha!\nUm saco selado, dois sacos selados de ducados,\nDe ducados duplos, roubados de mim por minha filha!\nE joias, duas pedras, duas pedras ricas e preciosas,\nRoubadas por minha filha! Justiça! Achai a menina;\nEla tem as pedras consigo, e os ducados.”","salarinowhyalltheboysinvenicefollowhimcr~shisdaughterandhisducats~76":"Salarino — Ora, todos os meninos de Veneza o seguem,\nGritando, suas pedras, sua filha e seus ducados.","salanioletgoodantoniolookhekeephisdayorh~isdayorheshallpayforthis~56":"Salanio — Que o bom Antonio cuide de cumprir seu prazo,\nOu pagará por isto.","salarinomarrywellrememberdireasondwithaf~nsilencethatitwerenothis~219":"Salarino — Pois sim, bem lembrado.\nConversei com um francês ontem,\nQue me disse que nos mares estreitos que separam\nA França e a Inglaterra, ali naufragou\nUma embarcação de nosso país ricamente carregada:\nPensei em Antonio quando ele me disse;\nE desejei em silêncio que não fosse dele.","salanioyouwerebesttotellantoniowhatyouhe~uddenlyforitmaygrievehim~75":"Salanio — Seria melhor contares a Antonio o que ouves;\nContudo não de súbito, pois pode afligi-lo.","salarinoakindergentlemantreadsnottheeart~anioshandandsotheyparted~495":"Salarino — Um cavalheiro mais bondoso não pisa a terra.\nVi Bassanio e Antonio se despedirem:\nBassanio lhe disse que daria alguma pressa\nEm seu retorno: ele respondeu, “Não faças assim;\nNão atabalhoes negócios por mim, Bassanio,\nMas espera o completo amadurecimento do tempo;\nE quanto ao título do judeu que ele tem de mim,\nQue não entre em tua mente de amor:\nSê alegre, e emprega teus principais pensamentos\nNo galanteio e em tais belas demonstrações de amor\nQue convenientemente te caibam lá”:\nE mesmo então, com os olhos cheios de lágrimas,\nVirando o rosto, pôs a mão atrás de si,\nE com afeto maravilhosamente sensível\nApertou a mão de Bassanio; e assim se despediram.","salanioithinkheonlylovestheworldforhimip~sswithsomedelightorother~119":"Salanio — Creio que só ama o mundo por causa dele.\nPeço-te, vamos achá-lo\nE animar sua pesada tristeza abraçada\nCom algum deleite ou outro.","salarinodowesoexeunt~salarinodowesoexeunt~20":"Salarino — Façamos assim. Saem.","sceneix~sceneix~7":"Cena IX","enternerissawithaservitor~nternerissawithaservitor~25":"Entra Nerissa com um Servidor.","nerissaquickquickipraytheedrawthecurtain~estohiselectionpresently~111":"Nerissa — Depressa, depressa, peço-te; corre a cortina logo:\nO Príncipe de Aragão prestou seu juramento,\nE vem fazer sua escolha agora mesmo.","flourishofcornetsentertheprinceofarragon~agonportiaandtheirtrains~60":"Toque de cornetas. Entram o Príncipe de Aragão, Portia e seus séquitos.","portiabeholdtherestandthecasketsnoblepri~gonefromhenceimmediately~184":"Portia — Vede, ali estão os cofres, nobre príncipe:\nSe escolherdes aquele em que estou contida,\nLogo serão solenizados nossos ritos nupciais:\nMas se falhardes, sem mais palavras, meu senhor,\nDeveis partir daqui imediatamente.","arragoniamenjoindbyoathtoobservethreethi~atelytoleaveyouandbegone~219":"Arragon — Estou obrigado por juramento a observar três coisas:\nPrimeira, nunca revelar a ninguém\nQual cofre escolhi; segunda, se falhar\nno cofre certo, nunca em minha vida\nCortejar donzela com intenção de casamento: Por fim,\nSe eu falhar na sorte de minha escolha,\nDeixar-vos imediatamente e partir.","portiatotheseinjunctionseveryonedothswea~hazardformyworthlessself~76":"Portia — A essas obrigações todos juram\nQue vêm arriscar-se por minha indigna pessoa.","arragonandsohaveiaddressdmefortunenowtom~reheopensthesilvercasket~1201":"Arragon — E assim me preparei. Fortuna, agora\nÀ esperança de meu coração! Ouro; prata; e vil chumbo.\n“Quem me escolher deve dar e arriscar tudo o que tem.”\nTerás de parecer mais belo antes que eu dê ou arrisque.\nQue diz o cofre de ouro? Ah! deixai-me ver:\n“Quem me escolher ganhará o que muitos homens desejam.”\nO que muitos homens desejam! esse “muitos” talvez se refira\nÀ multidão tola, que escolhe pela aparência,\nNão aprendendo mais do que o olho néscio ensina;\nQue não penetra o interior, mas, como o andorinhão,\nConstrói ao tempo na parede externa,\nNa própria força e rota do acaso.\nNão escolherei o que muitos homens desejam,\nPorque não quero concordar com espíritos vulgares\nE alinhar-me com as multidões bárbaras.\nOra, então a ti, tu, tesouro de prata;\nDize-me mais uma vez que título trazes:\n“Quem me escolher obterá tanto quanto merece”:\nE bem dito também; pois quem tentará\nTrapacear a fortuna e ser honrado\nSem o selo do mérito? Que ninguém presuma\nUsar uma dignidade imerecida.\nÓ, que propriedades, graus e ofícios\nNão fossem derivados corruptamente, e que a honra límpida\nFosse adquirida pelo mérito de quem a porta!\nQuantos então se cobririam que estão de cabeça descoberta!\nQuantos seriam mandados que mandam!\nQuanta gente baixa seria então colhida\nDa verdadeira semente da honra! e quanta honra\nColhida da palha e da ruína dos tempos\nSeria novamente envernizada! Bem, mas à minha escolha:\n“Quem me escolher obterá tanto quanto merece.”\nAssumirei merecimento. Dai-me uma chave para este,\nE abri já minhas fortunas aqui. Abre o cofre de prata.","portiatoolongapauseforthatwhichyoufindth~forthatwhichyoufindthere~43":"Portia — Demasiado longa pausa para o que ali achais.","arragonwhatsheretheportraitofablinkingid~rizearemydesertsnobetter~242":"Arragon — Que é isto? O retrato de um idiota piscante,\nApresentando-me um rolo! Vou lê-lo.\nComo és diferente de Portia!\nComo és diferente de minhas esperanças e meus merecimentos!\n“Quem me escolher terá tanto quanto merece.”\nMereci eu não mais que uma cabeça de tolo?\nÉ esse o meu prêmio? Meus méritos não são melhores?","portiatooffendandjudgearedistinctoffices~ficesandofopposednatures~59":"Portia — Ofender e julgar são ofícios distintos\nE de naturezas opostas.","arragonwhatisherereadsthefireseventimest~othexeuntarragonandtrain~408":"Arragon — Que há aqui? Lê. O fogo sete vezes provou isto:\nSete vezes provado é aquele juízo\nQue nunca escolheu mal.\nHá alguns que beijam sombras;\nTais só têm a ventura de uma sombra:\nHá tolos vivos, bem sei,\nPratadas por fora; e assim era este.\nLevai qual esposa quiserdes ao leito,\nSerei sempre vossa cabeça:\nPortanto ide: estais despachado. Ainda mais tolo parecerei\nPelo tempo que aqui me demorar\nCom uma cabeça de tolo vim cortejar,\nMas parto com duas.\nDoce, adeus. Manterei meu juramento,\nSuportando com paciência meu tormento. Saem Arragon e séquito.","portiathushaththecandlesingedthemothothe~hewisdombytheirwittolose~106":"Portia — Assim a vela chamuscou a mariposa.\nÓ, estes tolos deliberados! Quando escolhem,\nTêm a sabedoria de, por seu engenho, perder.","nerissatheancientsayingisnoheresyhanging~ngandwivinggoesbydestiny~62":"Nerissa — O antigo ditado não é heresia,\nForca e casamento vêm por destino.","portiacomedrawthecurtainnerissa~omedrawthecurtainnerissa~31":"Portia — Vem, corre a cortina, Nerissa.","enteraservant~enteraservant~13":"Entra um Criado.","servantwhereismylady~servantwhereismylady~20":"Criado — Onde está minha senhora?","portiaherewhatwouldmylord~ortiaherewhatwouldmylord~25":"Portia — Aqui: que quer meu senhor?","servantmadamthereisalightedatyourgateayo~purrercomesbeforehislord~322":"Criado — Senhora, apeou à vossa porta\nUm jovem veneziano, que vem na frente\nPara anunciar a aproximação de seu senhor;\nDe quem traz saudações sensíveis,\nA saber, além de recomendações e palavras corteses,\nPresentes de rico valor. Contudo nunca vi\nTão digno embaixador do amor:\nUm dia de abril nunca veio tão doce,\nPara mostrar quão rico o verão estava próximo,\nComo este esporeador vem antes de seu senhor.","portianomoreipraytheeiamhalfafeardthouwi~spostthatcomessomannerly~166":"Portia — Basta, peço-te: temo meio\nQue digas logo que ele é teu parente,\nTão cheio de espírito de festa em louvá-lo.\nVem, vem, Nerissa; pois anseio por ver\nO mensageiro do ágil Cupido que vem tão cortês.","nerissabassaniolordloveifthywillitbeexeu~dloveifthywillitbeexeunt~42":"Nerissa — Bassanio, senhor Amor, se for tua vontade! Saem.","entersalanioandsalarino~entersalanioandsalarino~23":"Entram Salanio e Salarino.","salanionowwhatnewsontherialto~ionowwhatnewsontherialto~29":"Salanio — Então, que notícias no Rialto?","salarinowhyyetitlivesthereuncheckdthatan~beanhonestwomanofherword~237":"Salarino — Ora, ainda corre por lá, sem contestação, que Antonio teve um navio de rica carga naufragado nos mares estreitos; os Goodwins, creio que chamam o lugar; um baixio perigosíssimo e fatal, onde jazem sepultadas as carcaças de muitos altos navios, segundo dizem, se minha comadre Fama for mulher honesta de palavra.","salanioiwouldshewereaslyingagossipinthat~oughtokeephisnamecompany~265":"Salanio — Quisera que ela fosse tão mentirosa comadre nisto quanto qualquer uma que jamais mastigou gengibre ou fez seus vizinhos crerem que chorava a morte de um terceiro marido. Mas é verdade, sem rodeios de prolixidade nem sair da estrada real da conversa, que o bom Antonio, o honesto Antonio — ó, quisera ter um título bom o bastante para fazer companhia ao seu nome! —","salarinocomethefullstop~salarinocomethefullstop~23":"Salarino — Vamos, o ponto final.","salaniohawhatsayestthouwhytheendishehath~ytheendishehathlostaship~49":"Salanio — Ah! que dizes? Ora, o fim é que ele perdeu um navio.","salarinoiwoulditmightprovetheendofhislos~htprovetheendofhislosses~43":"Salarino — Quisera que fosse o fim de suas perdas.","salanioletmesayamenbetimeslestthedevilcr~comesinthelikenessofajew~84":"Salanio — Deixa-me dizer “amém” a tempo, para que o diabo não cruze minha prece, pois eis que ele vem na figura de um judeu.","entershylock~entershylock~12":"Entra Shylock.","hownowshylockwhatnewsamongthemerchants~hatnewsamongthemerchants~38":"Então, Shylock! Que notícias entre os mercadores?","shylockyouknownonesowellnonesowellasyouo~asyouofmydaughtersflight~58":"Shylock — Sabeis, ninguém tão bem, ninguém tão bem quanto vós, da fuga de minha filha.","salarinothatscertainiformypartknewthetai~adethewingssheflewwithal~72":"Salarino — Isso é certo: eu, de minha parte, conhecia o alfaiate que fez as asas com que ela voou.","salanioandshylockforhisownpartknewthebir~onofthemalltoleavethedam~97":"Salanio — E Shylock, de sua parte, sabia que a ave estava emplumada; e então é da natureza de todas elas deixar a mãe.","shylocksheisdamnedforit~shylocksheisdamnedforit~23":"Shylock — Ela está condenada por isso.","salaniothatscertainifthedevilmaybeherjud~nifthedevilmaybeherjudge~42":"Salanio — Isso é certo, se o diabo for seu juiz.","shylockmyownfleshandbloodtorebel~yownfleshandbloodtorebel~32":"Shylock — Minha própria carne e sangue a se rebelar!","salaniooutuponitoldcarrionrebelsitatthes~rionrebelsitattheseyears~46":"Salanio — Que vergonha, velha carniça! Rebela-se nessa idade?","shylockisaymydaughterismyfleshandblood~aughterismyfleshandblood~38":"Shylock — Digo, minha filha é minha carne e sangue.","salarinothereismoredifferencebetweenthyf~ohavehadanylossatseaorno~184":"Salarino — Há mais diferença entre tua carne e a dela do que entre azeviche e marfim; mais entre vossos sangues do que entre vinho tinto e vinho do Reno. Mas dize-nos, ouviste se Antonio teve alguma perda no mar ou não?","shylockthereihaveanotherbadmatchabankrup~rtesylethimlooktohisbond~247":"Shylock — Aí tenho outro mau negócio: um falido, um pródigo, que mal ousa mostrar a cabeça no Rialto; um mendigo, que costumava vir tão elegante ao mercado; que cuide de seu título: costumava me chamar de usurário; que cuide de seu título: costumava emprestar dinheiro por cortesia cristã; que cuide de seu título.","salarinowhyiamsureifheforfeitthouwiltnot~hisfleshwhatsthatgoodfor~68":"Salarino — Ora, tenho certeza de que, se ele falhar, não tomarás sua carne: para que serve?","shylocktobaitfishwithalifitwillfeednothi~willbettertheinstruction~781":"Shylock — Para isca de peixe: se não alimentar mais nada, alimentará minha vingança. Ele me desgraçou, e me impediu de ganhar meio milhão; riu de minhas perdas, zombou de meus ganhos, desprezou minha nação, frustrou meus negócios, esfriou meus amigos, aqueceu meus inimigos; e qual é sua razão? Sou judeu. Não tem olhos um judeu? Não tem mãos um judeu, órgãos, dimensões, sentidos, afeições, paixões? Alimentado com a mesma comida, ferido com as mesmas armas, sujeito às mesmas doenças, curado pelos mesmos meios, aquecido e esfriado pelo mesmo inverno e verão que um cristão? Se nos picais, não sangramos? Se nos fazeis cócegas, não rimos? Se nos envenenais, não morremos? E se nos ofendeis, não nos vingaremos? Se somos como vós no resto, pareceremos convosco nisso. Se um judeu ofende um cristão, qual é sua humildade? Vingança. Se um cristão ofende um judeu, qual deve ser sua tolerância pelo exemplo cristão? Ora, vingança. A vilania que me ensinais, executarei, e será difícil que eu não melhore a lição.","servantgentlemenmymasterantonioisathisho~esirestospeakwithyouboth~71":"Criado — Cavalheiros, meu amo Antonio está em casa e deseja falar convosco dois.","salarinowehavebeenupanddowntoseekhim~vebeenupanddowntoseekhim~36":"Salarino — Temos andado de um lado a outro para procurá-lo.","entertubal~entertubal~10":"Entra Tubal.","salanioherecomesanotherofthetribeathirdc~alaniosalarinoandservant~113":"Salanio — Aí vem outro da tribo: um terceiro não se pode igualar, a menos que o próprio diabo se faça judeu. Saem Salanio, Salarino e o Criado.","shylockhownowtubalwhatnewsfromgenoahastt~ahastthoufoundmydaughter~58":"Shylock — Então, Tubal! Que notícias de Gênova? Achaste minha filha?","tubalioftencamewhereididhearofherbutcann~earofherbutcannotfindher~49":"Tubal — Muitas vezes cheguei onde ouvi falar dela, mas não consigo achá-la.","shylockwhytheretheretherethereadiamondgo~ngnotearsbutofmyshedding~516":"Shylock — Ora, aí, aí, aí, aí! Um diamante perdido, que me custou dois mil ducados em Frankfurt! A maldição nunca caiu sobre nossa nação até agora; nunca a senti até agora: dois mil ducados nisso; e outras preciosas, preciosas joias. Quisera minha filha morta a meus pés, e as joias em sua orelha! Quisera-a no ataúde a meus pés, e os ducados em seu caixão! Nenhuma notícia deles? Ora, está bem: e não sei quanto se gasta na busca: ora, tu, perda sobre perda! O ladrão foi-se com tanto, e tanto a gastar para achar o ladrão; e nenhuma satisfação, nenhuma vingança: nem má sorte alguma se move senão a que cai sobre meus ombros; nenhum suspiro senão o do meu fôlego; nenhuma lágrima senão a que eu derramo.","tubalyesothermenhaveilllucktooantonioasi~ooantonioasiheardingenoa~52":"Tubal — Sim, outros homens também têm má sorte: Antonio, como ouvi em Gênova —","shylockwhatwhatwhatillluckillluck~atwhatwhatillluckillluck~33":"Shylock — Quê, quê, quê? Má sorte, má sorte?","tubalhathanargosycastawaycomingfromtripo~stawaycomingfromtripolis~43":"Tubal — Perdeu uma nau mercante, vinda de Trípoli.","shylockithankgodithankgodisttrueisttrue~dithankgodisttrueisttrue~39":"Shylock — Agradeço a Deus, agradeço a Deus. É verdade, é verdade?","tubalispokewithsomeofthesailorsthatescap~ilorsthatescapedthewreck~50":"Tubal — Falei com alguns dos marinheiros que escaparam do naufrágio.","shylockithanktheegoodtubalgoodnewsgoodne~goodnewshahawhereingenoa~58":"Shylock — Agradeço-te, bom Tubal: boas novas, boas novas! Ah, ah! Onde? Em Gênova?","tubalyourdaughterspentingenoaasiheardino~nonenightfourscoreducats~62":"Tubal — Tua filha gastou em Gênova, como ouvi, numa só noite oitenta ducados.","shylockthoustickestadaggerinmeishallneve~tasittingfourscoreducats~95":"Shylock — Cravas-me um punhal: nunca mais verei meu ouro: oitenta ducados de uma vez! Oitenta ducados!","tubaltherecamediversofantonioscreditorsi~arhecannotchoosebutbreak~89":"Tubal — Vieram vários dos credores de Antonio em minha companhia para Veneza, que juram que ele não pode deixar de quebrar.","shylockiamverygladofitillplaguehimilltor~illtorturehimiamgladofit~58":"Shylock — Fico muito contente: vou atormentá-lo; vou torturá-lo: fico contente.","tubaloneofthemshowedmearingthathehadofyo~ofyourdaughterforamonkey~60":"Tubal — Um deles me mostrou um anel que ele recebeu de tua filha por um macaco.","shylockoutuponherthoutorturestmetubalitw~tforawildernessofmonkeys~125":"Shylock — Maldita seja ela! Torturas-me, Tubal: era minha turquesa; recebi-a de Lea quando era solteiro: não a teria dado por uma floresta de macacos.","tubalbutantonioiscertainlyundone~antonioiscertainlyundone~32":"Tubal — Mas Antonio está certamente arruinado.","shylocknaythatstruethatsverytruegotubalf~toursynagoguetubalexeunt~228":"Shylock — Não, isso é verdade, é muito verdade. Vai, Tubal, contrata-me um oficial; combina com ele quinze dias antes. Terei o coração dele, se faltar; pois, estando ele fora de Veneza, posso fazer o comércio que quiser. Vai, vai, Tubal, e encontra-me em nossa sinagoga; vai, bom Tubal; em nossa sinagoga, Tubal. Saem.","enterbassanioportiagratianonerissaandatt~ianonerissaandattendants~47":"Entram Bassanio, Portia, Gratiano, Nerissa e Criados.","portiaiprayyoutarrypauseadayortwobeforey~gthtostayyoufromelection~777":"Portia — Peço-vos, demorai-vos: fazei uma pausa de um ou dois dias\nAntes de arriscar; pois, escolhendo errado,\nPerco vossa companhia: portanto, esperai um pouco.\nAlgo me diz, mas não é amor,\nQue não quereria perder-vos; e vós mesmo sabeis\nQue o ódio não aconselha em tal qualidade.\nMas para que não me entendais mal, —\nE no entanto uma donzela não tem língua senão pensamento, —\nQuereria deter-vos aqui um mês ou dois\nAntes que vos aventureis por mim. Eu poderia ensinar-vos\nComo escolher certo, mas então estaria perjura;\nAssim jamais serei: portanto podeis perder-me;\nMas se perderdes, fareis-me desejar um pecado,\nQue eu tivesse sido perjura. Maldigo vossos olhos,\nEles me examinaram e me dividiram;\nUma metade de mim é vossa, a outra metade vossa,\nMinha, quero dizer; mas se minha, então vossa,\nE assim toda vossa. Ó, estes tempos perversos\nPõem barreiras entre os donos e seus direitos!\nE assim, embora vossa, não vossa. Se assim se provar,\nQue a fortuna vá ao inferno por isso, não eu.\nFalo demais; mas é para dar peso ao tempo,\nAlongá-lo e esticá-lo em comprimento,\nPara reter-vos da escolha.","bassanioletmechooseforasiamiliveuponther~forasiamiliveupontherack~43":"Bassanio — Deixai-me escolher,\nPois como estou, vivo no suplício.","portiaupontherackbassaniothenconfesswhat~ereismingledwithyourlove~73":"Portia — No suplício, Bassanio! Então confessai\nQue traição está misturada ao vosso amor.","bassaniononebutthatuglytreasonofmistrust~ndfireastreasonandmylove~137":"Bassanio — Nenhuma senão aquela feia traição da desconfiança,\nQue me faz temer o gozo de meu amor:\nPoderia haver tanto amizade e vida\nEntre neve e fogo quanto traição e meu amor.","portiaaybutifearyouspeakupontherackwhere~nenforceddospeakanything~66":"Portia — Sim, mas temo que faleis no suplício,\nOnde os homens forçados dizem qualquer coisa.","bassaniopromisemelifeandillconfessthetru~ifeandillconfessthetruth~42":"Bassanio — Prometei-me a vida, e confessarei a verdade.","portiawellthenconfessandlive~iawellthenconfessandlive~28":"Portia — Bem então, confessai e vivei.","bassanioconfessandlovehadbeentheverysumo~tomyfortuneandthecaskets~144":"Bassanio — “Confesso” e “amo”\nTeriam sido a própria soma de minha confissão:\nÓ feliz tormento, quando meu torturador\nMe ensina respostas para libertação!\nMas deixai-me ir à minha sorte e aos cofres.","portiaawaytheniamlockdinoneofthemifyoudo~hanthouthatmakestthefray~758":"Portia — Ide, então! Estou trancada num deles:\nSe me amais, haveis de me achar.\nNerissa e os demais, ficai todos afastados.\nQue a música soe enquanto ele faz sua escolha;\nAssim, se perder, terá fim de cisne,\nDesvanecendo em música: para que a comparação\nSeja mais própria, meu olho será o rio\nE leito de morte aquoso para ele. Ele pode ganhar;\nE que é a música então? Então a música é\nComo o toque quando verdadeiros súditos se curvam\nA um monarca recém-coroado: tal é\nComo aqueles sons suaves ao romper do dia\nQue se insinuam no ouvido do noivo sonhando,\nE o convocam ao casamento. Agora ele vai,\nCom não menos presença, mas com muito mais amor,\nQue o jovem Alcides, quando resgatou\nO tributo virginal pago por Troia uivante\nAo monstro marinho: eu me ofereço em sacrifício;\nOs demais, afastados, são as esposas dardânias,\nCom rostos embaçados, que saíram para ver\nO desfecho do feito. Vai, Hércules!\nVivas tu, vivo eu: com muito, muito mais pavor\nVejo a luta do que tu que travas a peleja.","musicwhilstbassaniocommentsonthecasketst~ntsonthecasketstohimself~48":"Música, enquanto Bassanio comenta consigo os cofres.","song~song~4":"Canção.","tellmewhereisfancybredorintheheartorinth~llillbeginitdingdongbell~189":"Dizei onde nasce o afeto,\nNo coração ou no intelecto?\nComo gerado, como nutrido?\nRespondei, respondei.\nÉ engendrado nos olhos,\nCom o olhar alimentado; e morre o afeto\nNo berço onde está deitado.\nTodos dobremos o sino do afeto,\nEu começo: — Din, dom, don.","alldingdongbell~alldingdongbell~15":"Todos — Din, dom, don.","bassaniosomaytheoutwardshowsbeleastthems~ooseijoybetheconsequence~1194":"Bassanio — Assim as aparências podem ser o que menos são:\nO mundo é sempre enganado pelo ornamento.\nNa lei, que defesa tão manchada e corrupta,\nMas, temperada com uma voz graciosa,\nObscurece a aparência do mal? Na religião,\nQue erro maldito, que alguma fronte sóbria\nNão o abençoe e aprove com um texto,\nOcultando a grosseria com belo ornamento?\nNão há vício tão simples que não assuma\nAlguma marca de virtude em suas partes externas:\nQuantos covardes, cujos corações são todos tão falsos\nQuanto escadas de areia, trazem contudo no queixo\nAs barbas de Hércules e do carrancudo Marte;\nQue, examinados por dentro, têm fígados brancos como leite;\nE estes assumem apenas o excremento da bravura\nPara se fazerem temidos! Olhai a beleza,\nE vereis que é comprada a peso;\nO que nisso opera um milagre na natureza,\nFazendo mais leves os que mais a usam:\nAssim são aqueles anelados cachos dourados serpentinos\nQue brincam tão lascivos com o vento,\nSobre uma suposta beleza, muitas vezes sabidos\nSer o dote de uma segunda cabeça,\nO crânio que os criou no sepulcro.\nAssim o ornamento é apenas a praia enganosa\nDe um mar perigosíssimo; a bela echarpe\nQue vela uma beleza indiana; numa palavra,\nA verdade aparente que os tempos astutos vestem\nPara apanhar os mais sábios. Portanto, tu, ouro berrante,\nDura comida para Midas, não quero nada de ti;\nNem de ti, tu, pálida e comum serviçal\nEntre homem e homem: mas tu, tu, chumbo magro,\nQue ameaças mais do que prometes algo,\nTua palidez me move mais que eloquência;\nE aqui escolho; que a alegria seja a consequência!","portiaasidehowalltheotherpassionsfleetto~akeitlessforfearisurfeit~232":"Portia — À parte. Como todas as outras paixões se esvaem no ar,\nComo pensamentos duvidosos, e desespero abraçado com precipitação,\nE medo trêmulo, e ciúme de olhos verdes! Ó amor,\nSê moderado; abranda teu êxtase,\nComedidamente refreia tua alegria; reduz este excesso.\nSinto demais tua bênção: faze-a menor,\nPara que eu não me sacie.","bassaniowhatfindihereopeningtheleadencas~nfirmdsigndratifiedbyyou~1132":"Bassanio — Que encontro aqui? Abrindo o cofre de chumbo.\nO retrato da bela Portia! Que semideus\nChegou tão perto da criação? Movem-se estes olhos?\nOu, cavalgando sobre as bolas dos meus,\nParecem em movimento? Eis lábios separados,\nEntreabertos por sopro de açúcar: tão doce barreira\nDeveria separar tão doces amigos. Aqui em seus cabelos\nO pintor faz de aranha e teceu\nUma malha dourada para prender os corações dos homens,\nMais firmes que mosquitos em teias; mas seus olhos, —\nComo pôde ver para pintá-los? Tendo feito um,\nParece-me que teria poder para roubar ambos os seus\nE deixar-se desprovido. Contudo, vede quanto\nA substância do meu louvor agrava esta sombra\nSubestimando-a, tanto esta sombra\nManqueja atrás da substância. Eis o rolo,\nO conteúdo e resumo da minha sorte. Lê. Vós que não escolheis pela vista,\nTende sorte tão boa e escolhei tão certo!\nJá que esta fortuna a vós cabe,\nContentai-vos e não busqueis nova,\nSe estais bem satisfeito com esta\nE tendes vossa sorte por vossa ventura,\nVoltai-vos para onde está vossa dama\nE reclamai-a com um beijo amoroso. Um rolo gentil. Bela dama, com vossa licença;\nVenho por escrito, para dar e receber.\nComo um de dois que disputam um prêmio,\nQue pensa ter-se saído bem aos olhos do povo,\nOuvindo aplauso e grito universal,\nTonto de espírito, ainda a olhar em dúvida\nSe estas pérolas de louvor são suas ou não;\nAssim, três vezes bela dama, estou eu, assim mesmo;\nTão duvidoso se o que vejo é verdade,\nAté ser confirmado, assinado, ratificado por vós.","portiayouseemelordbassaniowhereistandsuc~emyvantagetoexclaimonyou~850":"Portia — Vedes-me, senhor Bassanio, onde estou,\nTal qual sou: embora por mim apenas\nNão fosse ambiciosa em meu desejo,\nDe desejar-me muito melhor; contudo, por vós\nQuereria ser vinte vezes triplicada;\nMil vezes mais bela, dez mil vezes mais rica;\nPara que, só por estar em alta conta convosco,\nEu pudesse em virtude, belezas, posses, amigos,\nExceder a conta; mas a soma total de mim\nÉ soma de algo que, para nomear em bruto,\nÉ uma menina sem lições, sem escola, sem prática;\nFeliz nisto, ela ainda não é tão velha\nQue não possa aprender; mais feliz que isto,\nNão foi criada tão obtusa que não possa aprender;\nFelicíssima de tudo é que seu gentil espírito\nSe entrega a vós para ser dirigido,\nComo de seu senhor, seu governante, seu rei.\nEu mesma e o que é meu a vós e aos vossos\nÉ agora convertido: ainda há pouco eu era a senhora\nDesta bela mansão, mestra de meus servos,\nRainha sobre mim mesma: e agora mesmo, só agora,\nEsta casa, estes servos e esta mesma eu\nSão vossos, meu senhor: dou-os com este anel;\nQuando dele vos separardes, o perderdes ou o derdes,\nQue isso pressagie a ruína de vosso amor\nE me dê vantagem para vos acusar.","bassaniomadamyouhavebereftmeofallwordson~beboldtosaybassaniosdead~367":"Bassanio — Senhora, privastes-me de todas as palavras,\nSó meu sangue vos fala em minhas veias;\nE há tamanha confusão em minhas faculdades\nComo após alguma oração bem proferida\nPor um príncipe amado, aparece\nEntre a multidão zumbidora e satisfeita;\nOnde cada coisa, misturada junta,\nSe torna uma selva de nada, salvo de alegria,\nExpressa e não expressa. Mas quando este anel\nSe separar deste dedo, então se separará a vida daqui:\nÓ, então ousai dizer que Bassanio está morto!","nerissamylordandladyitisnowourtimethatha~djoygoodjoymylordandlady~104":"Nerissa — Meu senhor e senhora, é agora nossa hora,\nDe nós que ficamos ao lado e vimos nossos desejos prosperar,\nDe gritar, muita alegria: muita alegria, meu senhor e senhora!","gratianomylordbassanioandmygentleladyiwi~thattimeimaybemarriedtoo~195":"Gratiano — Meu senhor Bassanio e minha gentil senhora,\nDesejo-vos toda a alegria que podeis desejar;\nPois estou certo de que nenhuma podeis desejar de mim:\nE quando vossas honras pretenderem solenizar\nO contrato de vossa fé, suplico-vos,\nQue nessa mesma ocasião eu possa casar-me também.","bassaniowithallmyheartsothoucanstgetawif~heartsothoucanstgetawife~41":"Bassanio — De todo o coração, contanto que consigas uma esposa.","gratianoithankyourlordshipyouhavegotmeon~rtuneachievedhermistress~409":"Gratiano — Agradeço a vossa senhoria, conseguistes-me uma.\nMeus olhos, meu senhor, podem olhar tão ligeiro quanto os vossos:\nVós vistes a senhora, eu contemplei a donzela;\nVós amastes, eu amei por interrupção.\nNão mais me cabe, meu senhor, do que a vós.\nVossa sorte dependia do cofre ali,\nE a minha também, como as coisas se dão;\nPois cortejando aqui até suar de novo,\nE suando até o próprio céu da boca secar\nCom juramentos de amor, por fim, se promessa dura,\nObtive uma promessa desta bela aqui\nDe ter seu amor, contanto que vossa sorte\nConquistasse sua senhora.","portiaisthistruenerissa~portiaisthistruenerissa~23":"Portia — É verdade, Nerissa?","nerissamadamitissoyoustandpleasedwithal~ssoyoustandpleasedwithal~39":"Nerissa — Senhora, é, se estais de acordo com isso.","bassanioanddoyougratianomeangoodfaith~yougratianomeangoodfaith~37":"Bassanio — E tu, Gratiano, falas com boa-fé?","gratianoyesfaithmylord~gratianoyesfaithmylord~22":"Gratiano — Sim, na fé, meu senhor.","bassanioourfeastshallbemuchhonourdinyour~uchhonourdinyourmarriage~48":"Bassanio — Nossa festa será muito honrada com vosso casamento.","gratianowellplaywiththemthefirstboyforat~rstboyforathousandducats~53":"Gratiano — Apostaremos com eles o primeiro menino por mil ducados.","nerissawhatandstakedown~nerissawhatandstakedown~23":"Nerissa — Quê, e com a aposta posta?","gratianonoweshallneerwinatthatsportandst~oldvenetianfriendsalerio~115":"Gratiano — Não; nunca ganharemos nesse jogo, e com a aposta posta.\nMas quem vem aqui? Lorenzo e sua infiel?\nQuê, e meu velho amigo veneziano Salerio?","enterlorenzojessicaandsalerioamessengerf~erioamessengerfromvenice~49":"Entram Lorenzo, Jessica e Salerio, um Mensageiro de Veneza.","bassaniolorenzoandsaleriowelcomehitherif~trymensweetportiawelcome~154":"Bassanio — Lorenzo e Salerio, bem-vindos aqui;\nSe a juventude de meu novo interesse aqui\nTem poder para dar-vos boas-vindas. Com vossa licença,\nDou aos meus verdadeiros amigos e compatriotas,\nDoce Portia, as boas-vindas.","portiasodoimylordtheyareentirelywelcome~rdtheyareentirelywelcome~39":"Portia — Assim faço eu, meu senhor:\nSão inteiramente bem-vindos.","lorenzoithankyourhonourformypartmylordmy~ingnaytocomewithhimalong~147":"Lorenzo — Agradeço a vossa honra. De minha parte, meu senhor,\nMeu propósito não era ver-vos aqui;\nMas encontrando Salerio pelo caminho,\nEle me rogou, a ponto de não se poder dizer não,\nQue viesse com ele.","salerioididmylordandihavereasonforitsign~oyougivesbassanioaletter~86":"Salerio — Roguei, meu senhor;\nE tenho razão para isso. O senhor Antonio\nRecomenda-se a vós. Entrega uma carta a Bassanio.","bassanioereiopehisletteriprayyoutellmeho~ellmehowmygoodfrienddoth~57":"Bassanio — Antes de abrir sua carta,\nPeço-vos, dizei-me como vai meu bom amigo.","salerionotsickmylordunlessitbeinmindnorw~herewillshowyouhisestate~89":"Salerio — Não doente, meu senhor, a não ser de ânimo;\nNem bem, a não ser de ânimo: sua carta ali\nVos mostrará seu estado.","gratianonerissacheeryonstrangerbidherwel~jasonswehavewonthefleece~177":"Gratiano — Nerissa, anima aquela forasteira; dá-lhe as boas-vindas.\nTua mão, Salerio: que notícias de Veneza?\nComo vai aquele régio mercador, o bom Antonio?\nSei que ficará contente com nosso êxito;\nSomos os Jasões, ganhamos o velocino.","salerioiwouldyouhadwonthefleecethathehat~nthefleecethathehathlost~45":"Salerio — Quisera que tivésseis ganho o velocino que ele perdeu.","portiatherearesomeshrewdcontentsinyonsam~atthissamepaperbringsyou~278":"Portia — Há algum conteúdo funesto naquele papel,\nQue rouba a cor da face de Bassanio:\nAlgum caro amigo morto; senão, nada no mundo\nPoderia mudar tanto a constituição\nDe um homem constante. Quê, pior e pior!\nCom licença, Bassanio: sou metade de vós,\nE devo ter livremente a metade de qualquer coisa\nQue este papel vos traga.","bassanioosweetportiahereareafewoftheunpl~chofmerchantmarringrocks~668":"Bassanio — Ó doce Portia,\nEis algumas das mais desagradáveis palavras\nQue jamais borraram papel! Gentil senhora,\nQuando primeiro vos confiei meu amor,\nDisse-vos francamente que toda a riqueza que eu tinha\nCorria em minhas veias, que era um cavalheiro;\nE então disse-vos a verdade: e contudo, cara senhora,\nAvaliando-me em nada, vereis\nQuanto eu fui fanfarrão. Quando vos disse\nQue meu estado era nada, deveria então ter-vos dito\nQue eu era pior que nada; pois, de fato,\nComprometi-me com um caro amigo,\nComprometi meu amigo com seu mero inimigo,\nPara alimentar meus meios. Eis uma carta, senhora;\nO papel como o corpo de meu amigo,\nE cada palavra nela uma ferida aberta,\nJorrando sangue vital. Mas é verdade, Salerio?\nTodos os seus empreendimentos falharam? Quê, nem um acertou?\nDe Trípoli, do México e da Inglaterra,\nDe Lisboa, da Barbária e da Índia?\nE nenhuma embarcação escapou ao terrível toque\nDos rochedos que arruínam mercadores?","salerionotonemylordbesidesitshouldappear~itureofjusticeandhisbond~411":"Salerio — Nenhuma, meu senhor.\nAlém disso, parece que, se ele tivesse\nO dinheiro à vista para quitar o judeu,\nEste não o aceitaria. Nunca conheci\nCriatura que trouxesse a forma de homem\nTão ávida e ansiosa por destruir um homem:\nPressiona o doge de manhã e de noite,\nE acusa a liberdade do Estado\nSe lhe negam justiça: vinte mercadores,\nO próprio doge e os magnatas\nDe maior porte, todos o persuadiram;\nMas ninguém pode afastá-lo do invejoso pleito\nDe confisco, de justiça e de seu título.","jessicawheniwaswithhimihaveheardhimswear~illgohardwithpoorantonio~219":"Jessica — Quando estava com ele, ouvi-o jurar\nA Tubal e a Chus, seus compatriotas,\nQue preferia ter a carne de Antonio\nA vinte vezes o valor da soma\nQue este lhe devia: e sei, meu senhor,\nSe a lei, a autoridade e o poder não negarem,\nSerá duro para o pobre Antonio.","portiaisityourdearfriendthatisthusintrou~riendthatisthusintrouble~43":"Portia — É vosso caro amigo que está assim em apuros?","bassaniothedearestfriendtomethekindestma~nythatdrawsbreathinitaly~166":"Bassanio — O mais caro amigo para mim, o homem mais bondoso,\nO espírito de melhor condição e incansável\nEm fazer cortesias, e um em quem\nA antiga honra romana mais aparece\nDo que em qualquer um que respire na Itália.","portiawhatsumoweshethejew~ortiawhatsumoweshethejew~25":"Portia — Que soma deve ele ao judeu?","bassanioformethreethousandducats~formethreethousandducats~32":"Bassanio — Por mim, três mil ducados.","portiawhatnomorepayhimsixthousandanddefa~eartheletterofyourfriend~548":"Portia — Quê, não mais?\nPagai-lhe seis mil, e rasgai o título;\nDobrai seis mil, e depois triplicai isso,\nAntes que um amigo desta descrição\nPerca um fio de cabelo por culpa de Bassanio.\nPrimeiro ide comigo à igreja e chamai-me esposa,\nE depois partí para Veneza, ao vosso amigo;\nPois nunca jazereis ao lado de Portia\nCom a alma inquieta. Tereis ouro\nPara pagar a ninharia da dívida vinte vezes:\nQuando estiver paga, trazei vosso verdadeiro amigo.\nMinha criada Nerissa e eu entretanto\nViveremos como donzelas e viúvas. Vamos, ide!\nPois partireis daqui no dia de vosso casamento:\nDai boas-vindas a vossos amigos, mostrai semblante alegre:\nJá que fostes comprado caro, amar-vos-ei caro.\nMas deixai-me ouvir a carta de vosso amigo.","bassanioreadssweetbassaniomyshipshaveall~eyoutocomeletnotmyletter~287":"Bassanio — Lê. Doce Bassanio, meus navios todos naufragaram, meus credores tornam-se cruéis, meu estado está muito baixo, meu título ao judeu está confiscado; e como, ao pagá-lo, é impossível que eu viva, todas as dívidas entre vós e mim estão quitadas, se eu puder apenas ver-vos na minha morte. Não obstante, fazei como vos aprouver: se vosso amor não vos persuadir a vir, que não o faça minha carta.","portiaolovedispatchallbusinessandbegone~atchallbusinessandbegone~39":"Portia — Ó amor, despacha todos os negócios, e vai!","bassaniosinceihaveyourgoodleavetogoawayi~rposertwixtustwainexeunt~135":"Bassanio — Já que tenho vossa boa licença para partir,\nApressar-me-ei: mas, até que eu volte,\nNenhuma cama será culpada de minha demora,\nNenhum descanso se interporá entre nós dois. Saem.","entershylocksalarinoantonioandgaoler~salarinoantonioandgaoler~36":"Entram Shylock, Salarino, Antonio e o Carcereiro.","shylockgaolerlooktohimtellnotmeofmercyth~neygratisgaolerlooktohim~88":"Shylock — Carcereiro, vigia-o: não me fales de misericórdia;\nEste é o tolo que emprestava dinheiro de graça:\nCarcereiro, vigia-o.","antoniohearmeyetgoodshylock~oniohearmeyetgoodshylock~27":"Antonio — Ouve-me ainda, bom Shylock.","shylockillhavemybondspeaknotagainstmybon~broadwithhimathisrequest~241":"Shylock — Terei meu título; não fales contra meu título:\nJurei que terei meu título.\nChamaste-me cão antes de teres motivo;\nMas, já que sou cão, cuidado com minhas presas:\nO doge me concederá justiça. Admiro-me,\nTu, carcereiro malvado, de seres tão tolo\nQue saias com ele a seu pedido.","antonioipraytheehearmespeak~onioipraytheehearmespeak~27":"Antonio — Peço-te, ouve-me falar.","shylockillhavemybondiwillnotheartheespea~akingiwillhavemybondexit~212":"Shylock — Terei meu título; não te ouvirei falar:\nTerei meu título; e portanto não fales mais.\nNão serei feito um tolo mole e de olhos embaçados,\nPara balançar a cabeça, ceder, suspirar e render-me\nA intercessores cristãos. Não me sigais;\nNão quero conversa: terei meu título. Sai.","salarinoitisthemostimpenetrablecurthatev~lecurthateverkeptwithmen~53":"Salarino — É o cão mais impenetrável\nQue jamais conviveu com homens.","antoniolethimaloneillfollowhimnomorewith~antomethereforehehatesme~165":"Antonio — Deixai-o em paz:\nNão o seguirei mais com preces inúteis.\nBusca minha vida; sua razão conheço bem:\nMuitas vezes livrei de seus confiscos\nMuitos que por vezes se lamentaram a mim;\nPor isso ele me odeia.","salarinoiamsurethedukewillnevergrantthis~rantthisforfeituretohold~56":"Salarino — Estou certo de que o doge\nNunca permitirá que este confisco se mantenha.","antoniothedukecannotdenythecourseoflawfo~ebtandthenicarenotexeunt~361":"Antonio — O doge não pode negar o curso da lei:\nPois a comodidade que os estrangeiros têm\nConosco em Veneza, se for negada,\nMuito prejudicará a justiça de seu Estado;\nJá que o comércio e o lucro da cidade\nConsistem de todas as nações. Portanto, ide:\nEstas dores e perdas me emagreceram tanto\nQue mal poderei poupar uma libra de carne\nAmanhã a meu sanguinário credor.\nBem, carcereiro, adiante. Queira Deus que Bassanio venha\nVer-me pagar sua dívida, e então nada me importa! Saem.","enterportianerissalorenzojessicaandbalth~renzojessicaandbalthasar~44":"Entram Portia, Nerissa, Lorenzo, Jessica e Balthasar.","lorenzomadamalthoughispeakitinyourpresen~omarybountycanenforceyou~301":"Lorenzo — Senhora, embora o diga em vossa presença,\nTendes um nobre e verdadeiro conceito\nDa amizade divina; o que aparece mais fortemente\nEm suportar assim a ausência de vosso senhor.\nMas se soubésseis a quem mostrais esta honra,\nQue verdadeiro cavalheiro socorreis,\nQue caro amigo de meu senhor vosso marido,\nSei que estaríeis mais orgulhosa da obra\nDo que a generosidade habitual vos pode forçar.","portiaineverdidrepentfordoinggoodnorshal~enecessitynowlaysuponyou~779":"Portia — Nunca me arrependi de fazer o bem,\nNem me arrependerei agora: pois entre companheiros\nQue conversam e passam o tempo juntos,\nCujas almas levam um igual jugo de amor,\nDeve haver necessariamente semelhante proporção\nDe traços, de modos e de espírito;\nO que me faz pensar que este Antonio,\nSendo o amigo do peito de meu senhor,\nDeve ser necessariamente como meu senhor. Se assim for,\nQuão pequeno é o custo que dispendi\nEm comprar a semelhança de minha alma\nDo estado de miséria infernal!\nIsto chega perto demais de louvar a mim mesma;\nPortanto, chega disso: ouvi outras coisas.\nLorenzo, confio a vossas mãos\nA administração e o governo de minha casa\nAté o retorno de meu senhor: de minha parte,\nFiz ao céu um voto secreto\nDe viver em prece e contemplação,\nAcompanhada só de Nerissa aqui,\nAté o retorno do marido dela e de meu senhor:\nHá um mosteiro a duas milhas daqui;\nE ali permaneceremos. Peço-vos\nNão negar esta imposição;\nQue meu amor e alguma necessidade\nAgora vos impõem.","lorenzomadamwithallmyheartishallobeyyoui~obeyyouinallfaircommands~56":"Lorenzo — Senhora, de todo o coração;\nObedecer-vos-ei em todas as belas ordens.","portiamypeopledoalreadyknowmymindandwill~welltillweshallmeetagain~127":"Portia — Meu povo já conhece meu desejo,\nE vos reconhecerá, a vós e a Jessica,\nNo lugar de lorde Bassanio e de mim.\nE assim adeus, até que nos encontremos de novo.","lorenzofairthoughtsandhappyhoursattendon~andhappyhoursattendonyou~43":"Lorenzo — Belos pensamentos e horas felizes vos acompanhem!","jessicaiwishyourladyshipallheartscontent~ladyshipallheartscontent~40":"Jessica — Desejo a vossa senhoria todo o contentamento do coração.","portiaithankyouforyourwishandamwellpleas~eishallbetherebeforethee~453":"Portia — Agradeço-vos o desejo, e fico bem contente\nEm desejá-lo de volta a vós: passai bem, Jessica. Saem Jessica e Lorenzo.\nAgora, Balthasar,\nComo sempre te achei honesto e leal,\nAssim deixa-me achar-te ainda. Toma esta carta,\nE emprega todo o empenho de um homem\nEm rapidez para Pádua: vê que a entregues\nNas mãos de meu primo, doutor Bellario;\nE, olha, as notas e vestes que ele te der,\nTraze-as, peço-te, com velocidade imaginada\nAté o tranecto, à balsa comum\nQue faz o trajeto para Veneza. Não percas tempo em palavras,\nMas vai: estarei lá antes de ti.","balthasarmadamigowithallconvenientspeede~thallconvenientspeedexit~43":"Balthasar — Senhora, vou com toda a conveniente rapidez. Sai.","portiacomeonnerissaihaveworkinhandthatyo~bandsbeforetheythinkofus~90":"Portia — Vem, Nerissa; tenho um trabalho em mãos\nDo qual ainda não sabes: veremos nossos maridos\nAntes que pensem em nós.","nerissashalltheyseeus~nerissashalltheyseeus~21":"Nerissa — Eles nos verão?","portiatheyshallnerissabutinsuchahabittha~gjackswhichiwillpractise~638":"Portia — Verão, Nerissa; mas em tal traje\nQue pensarão que estamos dotadas\nDo que nos falta. Aposto contigo qualquer coisa,\nQuando ambas estivermos trajadas como rapazes,\nEu provarei ser o mais bonito dos dois,\nE usarei meu punhal com mais garbo,\nE falarei entre a mudança de homem e menino\nCom voz de caniço, e converterei dois passos miúdos\nNuma passada viril, e falarei de rixas\nComo um belo jovem fanfarrão, e contarei mentiras curiosas,\nComo damas honradas buscaram meu amor,\nE eu recusando, adoeceram e morreram;\nNão pude evitar; então me arrependerei,\nE desejarei, apesar de tudo, não as ter matado;\nE vinte destas mentirinhas contarei,\nQue os homens jurarão que deixei a escola\nHá mais de um ano. Tenho na mente\nMil truques crus desses valentões,\nQue praticarei.","nerissawhyshallweturntomen~rissawhyshallweturntomen~26":"Nerissa — Ora, nos tornaremos homens?","portiafiewhataquestionsthatifthouwertnea~retwentymilestodayexeunt~194":"Portia — Que vergonha, que pergunta é essa,\nSe estivesses perto de um intérprete obsceno!\nMas vem, contarei todo o meu plano\nQuando estiver em minha carruagem, que nos espera\nNo portão do parque; e portanto depressa,\nPois devemos percorrer vinte milhas hoje. Saem.","thesameagarden~thesameagarden~14":"O mesmo lugar. Um jardim.","enterlauncelotandjessica~enterlauncelotandjessica~24":"Entram Launcelot e Jessica.","launcelotyestrulyforlookyouthesinsofthef~kindofbastardhopeneither~281":"Launcelot — Sim, verdadeiramente; pois, vede, os pecados do pai devem ser lançados sobre os filhos: portanto, prometo-vos, eu vos temo. Sempre fui franco convosco, e assim agora digo minha agitação sobre o assunto: portanto, animai-vos, pois verdadeiramente creio que estais condenada. Há apenas uma esperança nisso que vos pode fazer algum bem; e essa é apenas uma espécie de esperança bastarda também.","jessicaandwhathopeisthatipraythee~dwhathopeisthatipraythee~33":"Jessica — E que esperança é essa, peço-te?","launcelotmarryyoumaypartlyhopethatyourfa~youarenotthejewsdaughter~81":"Launcelot — Pois bem, podeis em parte esperar que vosso pai não vos gerou, que não sois filha do judeu.","jessicathatwereakindofbastardhopeindeeds~hershouldbevisiteduponme~79":"Jessica — Isso seria uma espécie de esperança bastarda, de fato: assim os pecados de minha mãe seriam visitados sobre mim.","launcelottrulythenifearyouaredamnedbothb~erwellyouaregonebothways~135":"Launcelot — Verdadeiramente então temo que estejais condenada tanto por pai quanto por mãe: assim, quando evito Cila, vosso pai, caio em Caríbdis, vossa mãe: bem, estais perdida pelos dois lados.","jessicaishallbesavedbymyhusbandhehathmad~ndhehathmademeachristian~53":"Jessica — Serei salva por meu marido; ele me fez cristã.","launcelottrulythemoretoblamehewewerechri~rasheronthecoalsformoney~206":"Launcelot — Verdadeiramente, mais culpa a dele: éramos cristãos o bastante antes; justamente tantos quantos podiam viver bem, uns com os outros. Este fazer cristãos vai subir o preço dos porcos: se todos nos tornarmos comedores de porco, em breve não teremos uma fatia nas brasas por dinheiro.","jessicailltellmyhusbandlauncelotwhatyous~lotwhatyousayherehecomes~53":"Jessica — Contarei a meu marido, Launcelot, o que dizes: eis que ele vem.","lorenzoishallgrowjealousofyoushortlylaun~thusgetmywifeintocorners~74":"Lorenzo — Ficarei com ciúme de ti em breve, Launcelot, se levares assim minha esposa para os cantos.","jessicanayyouneednotfearuslorenzolauncel~nsyouraisethepriceofpork~214":"Jessica — Não, não precisais nos temer, Lorenzo: Launcelot e eu estamos brigados. Diz-me sem rodeios que não há misericórdia para mim no céu, porque sou filha de judeu: e diz que não sois bom membro da comunidade, pois ao converter judeus em cristãos, subis o preço do porco.","lorenzoishallanswerthatbettertothecommon~swithchildbyyoulauncelot~116":"Lorenzo — Responderei isso melhor à comunidade do que tu poderás responder pelo inchaço do ventre da negra: a mourisca está grávida de ti, Launcelot.","launcelotitismuchthatthemoorshouldbemore~ndeedmorethanitookherfor~111":"Launcelot — É demais que a mourisca esteja mais do que razoável: mas se ela é menos que mulher honesta, é de fato mais do que eu pensava.","lorenzohoweveryfoolcanplayuponthewordith~hbidthempreparefordinner~166":"Lorenzo — Como qualquer tolo sabe brincar com palavras! Creio que a melhor graça do espírito em breve se converterá em silêncio, e a conversa só será louvável nos papagaios. Entra, moço; manda prepararem o jantar.","launcelotthatisdonesirtheyhaveallstomach~nesirtheyhaveallstomachs~41":"Launcelot — Isso está feito, senhor; todos têm estômago.","lorenzogoodlylordwhatawitsnapperareyouth~thenbidthempreparedinner~62":"Lorenzo — Bom Senhor, que quebra-espírito és tu! Então manda prepararem o jantar.","launcelotthatisdonetoosironlycoveristhew~toosironlycoveristheword~43":"Launcelot — Isso também está feito, senhor; só falta “cobrir”.","lorenzowillyoucoverthensir~renzowillyoucoverthensir~26":"Lorenzo — Quereis cobrir-vos então, senhor?","launcelotnotsosirneitheriknowmyduty~tsosirneitheriknowmyduty~35":"Launcelot — Também não, senhor; conheço meu dever.","lorenzoyetmorequarrellingwithoccasionwil~tandwewillcomeintodinner~198":"Lorenzo — Ainda mais brigas com a ocasião! Queres mostrar toda a riqueza de teu espírito num instante? Peço-te, entende um homem simples em seu sentido simples: vai a teus companheiros; manda cobrirem a mesa, servirem a carne, e entraremos para o jantar.","launcelotforthetablesiritshallbeservedin~dconceitsshallgovernexit~140":"Launcelot — Quanto à mesa, senhor, será servida; quanto à carne, senhor, será coberta; quanto a vossa entrada para o jantar, senhor, ora, que seja como os humores e fantasias governarem. Sai.","lorenzoodeardiscretionhowhiswordsaresuit~likethelordbassanioswife~262":"Lorenzo — Ó cara discrição, como suas palavras estão bem vestidas!\nO tolo plantou em sua memória\nUm exército de boas palavras; e conheço\nMuitos tolos que ocupam melhor posição,\nGuarnecidos como ele, que por uma palavra engenhosa\nDesafiam o sentido. Como te sentes, Jessica?\nE agora, doce bem, dize tua opinião,\nComo gostas da esposa do lorde Bassanio?","jessicapastallexpressingitisverymeetthel~udeworldhathnotherfellow~352":"Jessica — Acima de toda expressão. É muito justo\nQue lorde Bassanio viva vida reta;\nPois, tendo tal bênção em sua dama,\nAcha as alegrias do céu aqui na terra;\nE se na terra não as tiver em conta, então\nPor razão jamais deveria chegar ao céu.\nOra, se dois deuses jogassem alguma partida celeste\nE apostassem duas mulheres terrenas,\nE Portia fosse uma, deveria haver algo mais\nEmpenhado com a outra, pois o pobre e rude mundo\nNão tem sua igual.","lorenzoevensuchahusbandhastthouofmeasshe~tthouofmeassheisforawife~50":"Lorenzo — Tal marido como ela é esposa\nTens em mim.","jessicanaybutaskmyopiniontooofthat~butaskmyopiniontooofthat~34":"Jessica — Não, mas pede também minha opinião sobre isso.","lorenzoiwillanonfirstletusgotodinner~anonfirstletusgotodinner~36":"Lorenzo — Pedirei logo: primeiro, vamos jantar.","jessicanayletmepraiseyouwhileihaveastoma~iseyouwhileihaveastomach~42":"Jessica — Não, deixa-me louvar-te enquanto tenho apetite.","lorenzonopraytheeletitservefortabletalkt~therthingsishalldigestit~90":"Lorenzo — Não, peço-te, que sirva de conversa de mesa;\nEntão, como quer que fales, entre outras coisas\nA digerirei.","jessicawellillsetyouforthexeunt~wellillsetyouforthexeunt~31":"Jessica — Bem, eu te exaltarei. Saem."}$tr$::jsonb, 461)
