-- william-shakespeare_the-taming-of-the-shrew (396 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-taming-of-the-shrew', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"induction":"Indução","acti":"Ato I","actii":"Ato II"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","beforeanalehouseonaheath~beforeanalehouseonaheath~24":"Diante de uma taverna numa charneca.","enterhostessandsly~enterhostessandsly~18":"Entram a Taverneira e Sly.","slyillpheezeyouinfaith~slyillpheezeyouinfaith~22":"Sly — Vou te dar uma sova, juro.","hostessapairofstocksyourogue~essapairofstocksyourogue~28":"Taverneira — Um par de grilhões, seu patife!","slyyeareabaggagetheslysarenorogueslookin~rislettheworldslidesessa~126":"Sly — Você é uma rameira: os Sly não são patifes; olhe nas crônicas; viemos com Ricardo, o Conquistador. Portanto, paucas pallabris; deixe o mundo rolar: sessa!","hostessyouwillnotpayfortheglassesyouhave~ortheglassesyouhaveburst~45":"Taverneira — Não vai pagar pelos copos que quebrou?","slynonotadeniergobyjeronimygotothycoldbe~otothycoldbedandwarmthee~52":"Sly — Não, nem um centavo. Passe de largo, Jerônimo: vá para a sua cama fria e se aqueça.","hostessiknowmyremedyimustgofetchthethird~fetchthethirdboroughexit~51":"Taverneira — Sei qual é o meu remédio; vou chamar o guarda-mor. Sai.","slythirdorfourthorfifthboroughillanswerh~comeandkindlyfallsasleep~97":"Sly — Guarda-mor, ou segundo, ou terceiro, responderei a ele conforme a lei: não saio daqui um palmo, rapaz: que venha, e com boas maneiras. Adormece.","hornswindedenteralordfromhuntingwithhist~dfromhuntingwithhistrain~44":"Soam trompas. Entra um Lorde, voltando da caça, com seu séquito.","lordhuntsmanichargetheetenderwellmyhound~losethedogfortwentypound~211":"Lorde — Caçador, mando-te tratar bem dos meus cães:\nA cadela Merriman, coitada, está esfalfada;\nE emparelha Clowder com a cadela de voz grave.\nNão viste, rapaz, como Silver acertou a pista\nNo canto da sebe, no rastro mais frio?\nNão perderia esse cão por vinte libras.","firsthuntsmanwhybelmanisasgoodashemylord~eitakehimforthebetterdog~134":"Primeiro Caçador — Ora, Belman é tão bom quanto ele, senhor;\nLatiu ao achar o rastro na mais completa perda\nE duas vezes hoje descobriu o faro mais fraco:\nCreia-me, tenho-o por melhor cão.","lordthouartafoolifechowereasfleetiwoulde~morrowiintendtohuntagain~121":"Lorde — És um tolo: se Echo fosse tão veloz,\nEu o julgaria digno de uma dúzia de tais.\nMas dá-lhes bem de comer e cuida de todos:\nAmanhã pretendo caçar de novo.","firsthuntsmaniwillmylord~firsthuntsmaniwillmylord~24":"Primeiro Caçador — Assim farei, senhor.","lordwhatshereonedeadordrunkseedothhebrea~dordrunkseedothhebreathe~43":"Lorde — Que é isto? um morto, ou um bêbado? Vede, respira?","secondhuntsmanhebreathesmylordwerehenotw~dbutcoldtosleepsosoundly~86":"Segundo Caçador — Respira, senhor. Se não estivesse aquecido de cerveja,\nEsta seria uma cama bem fria para dormir tão a fundo.","lordomonstrousbeasthowlikeaswineheliesgr~ebeggarthenforgethimself~284":"Lorde — Ó monstruosa besta! como jaz feito um porco!\nMorte horrenda, quão vil e repugnante é tua imagem!\nSenhores, vou pregar uma peça a este bêbado.\nQue pensais, se ele fosse levado para a cama,\nEnvolto em roupas perfumadas, anéis postos nos dedos,\nUm banquete deliciosíssimo junto ao leito,\nE bravos criados ao redor quando despertasse,\nNão esqueceria o mendigo de si mesmo?","firsthuntsmanbelievemelordithinkhecannot~lordithinkhecannotchoose~46":"Primeiro Caçador — Creia-me, senhor, penso que não poderia deixar de esquecer.","secondhuntsmanitwouldseemstrangeuntohimw~trangeuntohimwhenhewaked~50":"Segundo Caçador — Pareceria estranho a ele quando acordasse.","lordevenasaflatteringdreamorworthlessfan~itbehusbandedwithmodesty~819":"Lorde — Tal qual um sonho lisonjeiro ou fantasia sem valor.\nEntão levantai-o e conduzi bem a brincadeira:\nCarregai-o com cuidado para o meu mais belo aposento\nE guarnecei-o com todos os meus quadros licenciosos:\nBanhai-lhe a cabeça imunda em águas destiladas mornas\nE queimai lenha perfumada para adocicar o aposento:\nProvidenciai-me música pronta quando despertar,\nPara fazer um som doce e celestial;\nE se por acaso ele falar, estai logo preparados\nE com baixa e submissa reverência\nDizei: “Que ordena vossa honra?”\nQue um o sirva com uma bacia de prata\nCheia de água de rosas e coberta de flores;\nOutro traga o jarro, o terceiro uma toalha,\nE diga: “Apraz a vossa senhoria refrescar as mãos?”\nAlguém esteja pronto com uma roupa custosa\nE lhe pergunte que traje há de vestir;\nOutro lhe fale de seus cães e cavalo,\nE de que sua dama lamenta o seu mal:\nPersuadi-o de que esteve lunático;\nE quando ele disser que está, dizei que sonha,\nPois ele nada é senão um poderoso lorde.\nFazei isso e fazei-o com boa graça, gentis senhores:\nSerá passatempo sobremodo excelente,\nSe for conduzido com discrição.","firsthuntsmanmylordiwarrantyouwewillplay~snolessthanwhatwesayheis~106":"Primeiro Caçador — Senhor, garanto que faremos o nosso papel,\nDe modo que ele pense, por nossa verdadeira diligência,\nQue não é menos do que dizemos que é.","lordtakehimupgentlyandtobedwithhimandeac~mejourneytoreposehimhere~212":"Lorde — Levantai-o com suavidade e para a cama com ele;\nE cada um ao seu ofício quando despertar. Alguns levam Sly. Soa uma trombeta.\nMeu rapaz, vai ver que trombeta é essa que soa: Sai um Criado.\nTalvez algum nobre cavalheiro que pretenda,\nem viagem, repousar aqui.","reenterservingman~reenterservingman~17":"Reentra o Criado.","hownowwhoisit~hownowwhoisit~13":"Então! Quem é?","servantantpleaseyourhonourplayersthatoff~ferservicetoyourlordship~63":"Criado — Com a vossa licença, senhor, são uns atores \n Que oferecem seus serviços a Vossa Senhoria.","lordbidthemcomenear~lordbidthemcomenear~19":"Lorde — Mandai-os entrar.","enterplayers~enterplayers~12":"Entram os Atores.","nowfellowsyouarewelcome~nowfellowsyouarewelcome~23":"Agora, companheiros, sede bem-vindos.","playerswethankyourhonour~playerswethankyourhonour~24":"Atores — Agradecemos a Vossa Senhoria.","lorddoyouintendtostaywithmetonight~ntendtostaywithmetonight~34":"Lorde — Pretendeis ficar comigo esta noite?","aplayersopleaseyourlordshiptoacceptourdu~rlordshiptoacceptourduty~42":"Um Ator — Se aprouver a Vossa Senhoria aceitar o nosso serviço.","lordwithallmyheartthisfellowiremembersin~ttedandnaturallyperformd~174":"Lorde — De todo o coração. Lembro-me deste homem, \n Pois certa vez fez o filho mais velho de um lavrador: \n Foi quando cortejastes tão bem a donzela: \n Esqueci vosso nome; mas, por certo, esse papel \n Vos assentava bem e foi representado com naturalidade.","aplayerithinktwassotothatyourhonourmeans~ssotothatyourhonourmeans~40":"Um Ator — Creio que Vossa Senhoria se refere a Soto.","lordtisverytruethoudidstitexcellentwelly~uldsmilehegrowsimpatient~342":"Lorde — É verdade: fizeste-o com perfeição. \n Pois bem, chegais a mim em boa hora; \n Tanto mais que tenho em mãos um divertimento \n Em que a vossa arte me pode ajudar muito. \n Há um lorde que ouvirá vossa peça esta noite: \n Mas duvido da vossa compostura; \n Pois, ao observar-lhe o estranho comportamento — \n Já que Sua Senhoria nunca viu uma peça — \n Podeis desatar em alguma risada alegre \n E assim ofendê-lo; porque vos digo, senhores, \n Se sorrirdes, ele se impacienta.","aplayerfearnotmylordwecancontainourselve~heveriestanticintheworld~72":"Um Ator — Nada temais, meu senhor: sabemos conter-nos, \n Fosse ele o mais extravagante bufão do mundo.","lordgosirrahtakethemtothebutteryandgivet~ldgrowintoextremesexeunt~1265":"Lorde — Vai, rapaz, leva-os à despensa \n E dá a cada um deles boas-vindas amigas: \n Que nada lhes falte do que minha casa oferece. Sai um com os Atores. \n Tu, rapaz, vai ter com Bartolomeu, meu pajem, \n E vê que o vistam todo como uma dama: \n Feito isso, conduze-o ao quarto do bêbado; \n Chama-o de “senhora” e faze-lhe reverência. \n Diz-lhe de minha parte que, se quiser ganhar meu afeto, \n Comporte-se com ação honrada, \n Tal como observou nas nobres damas \n Para com seus senhores, e por elas praticada: \n Que tal dever mostre ao bêbado, \n Com voz doce e baixa e humilde cortesia, \n E diga: “Que ordena Vossa Senhoria, \n Em que vossa dama e humilde esposa \n Possa mostrar seu dever e dar a conhecer seu amor?” \n E então, com afetuosos abraços, beijos tentadores, \n E com a cabeça inclinada sobre o seu peito, \n Mande-o derramar lágrimas, como quem se sobrepuja de alegria \n Por ver seu nobre senhor restituído à saúde, \n Ele que por sete anos se julgou \n Não melhor que um pobre e repugnante mendigo: \n E se o rapaz não tiver o dom feminino \n De fazer chover lágrimas por encomenda, \n Uma cebola servirá bem a tal fim, \n E, escondida num guardanapo, \n Há de forçar, mau grado seu, um olho molhado. \n Despacha isto com toda a pressa que puderes: \n Logo te darei mais instruções. Sai um Criado. \n Sei que o rapaz usurpará bem a graça, \n A voz, o andar e os gestos de uma dama: \n Anseio por ouvi-lo chamar o bêbado de marido, \n E ver como meus homens se conterão do riso \n Ao prestarem homenagem a esse simples camponês. \n Vou entrar para aconselhá-los; talvez minha presença \n Possa abrandar o humor folgazão em demasia \n Que de outro modo cresceria até os extremos. Saem.","sceneii~sceneii~7":"Cena II","abedchamberinthelordshouse~edchamberinthelordshouse~26":"Um quarto na casa do Lorde.","enteraloftslywithattendantssomewithappar~therappurtenancesandlord~92":"Entram no alto Sly, com Criados; alguns trazem roupas, outros bacia, jarro e outros apetrechos; e o Lorde.","slyforgodssakeapotofsmallale~orgodssakeapotofsmallale~28":"Sly — Pelo amor de Deus, um caneco de cerveja fraca.","firstservantwilltpleaseyourlordshipdrink~rlordshipdrinkacupofsack~50":"Primeiro Criado — Apraz a Vossa Senhoria beber uma taça de vinho seco?","secondservantwilltpleaseyourhonourtasteo~ourtasteoftheseconserves~55":"Segundo Criado — Apraz a Vossa Senhoria provar destas conservas?","thirdservantwhatraimentwillyourhonourwea~twillyourhonourweartoday~46":"Terceiro Criado — Que traje vestirá Vossa Senhoria hoje?","slyiamchristopheroslycallnotmehonournorl~ookthroughtheoverleather~292":"Sly — Sou Christophero Sly; não me chameis de “senhoria” nem de “honra”: nunca na vida bebi vinho seco; e se me derdes conservas, dai-me conservas de carne; não me pergunteis que traje vestirei; pois não tenho mais gibões que costas, nem mais meias que pernas, nem mais sapatos que pés; e até, às vezes, mais pés que sapatos, ou sapatos tais que meus dedos espiam pelo couro de cima.","lordheavenceasethisidlehumourinyourhonou~infusedwithsofoulaspirit~133":"Lorde — Que o Céu faça cessar este humor desvairado em Vossa Senhoria! \n Oh, que um homem poderoso, de tal linhagem, \n De tais posses e tão alta estima, \n Seja tomado por tão vil espírito!","slywhatwouldyoumakememadamnotichristophe~hatiamnotbestraughtheres~322":"Sly — O quê, quereis me enlouquecer? Não sou eu Christopher Sly, filho do velho Sly de Burton-heath, de nascimento mascate, de educação cardador, por transmutação domador de ursos e, por profissão atual, funileiro? Perguntai a Marian Hacket, a gorda taverneira de Wincot, se ela não me conhece: se disser que não lhe devo catorze pence de cerveja pura, anotai-me na conta como o maior mentiroso da cristandade. Ora! Não estou fora de mim: eis que—","thirdservantothisitisthatmakesyourladymo~isthatmakesyourladymourn~43":"Terceiro Criado — Oh, é isto que faz vossa dama lamentar-se!","secondservantothisisitthatmakesyourserva~atmakesyourservantsdroop~48":"Segundo Criado — Oh, é isto que abate os vossos criados!","lordhencecomesitthatyourkindredshunsyour~echoesfromthehollowearth~670":"Lorde — Daí vem que vossos parentes evitem vossa casa, \n Como que expulsos pela vossa estranha loucura. \n Oh, nobre senhor, lembrai-vos de vosso berço, \n Chamai de volta do exílio os vossos antigos pensamentos \n E banis para longe esses sonhos vis e rasteiros. \n Vede como vossos criados vos assistem, \n Cada qual em seu ofício, pronto a um aceno vosso. \n Quereis música? Ouvi! Apolo toca. Música. \n E vinte rouxinóis engaiolados cantam: \n Ou quereis dormir? Teremos para vós um leito \n Mais macio e doce que o leito lascivo \n Preparado de propósito para Semíramis. \n Dizei que quereis passear; juncaremos o chão: \n Ou quereis cavalgar? Vossos cavalos serão ajaezados, \n Os arreios cravejados de ouro e pérolas. \n Gostais da caça com falcão? Tendes falcões que se elevam \n Acima da cotovia da manhã: ou quereis caçar? \n Vossos cães farão o firmamento responder-lhes \n E trarão ecos estridentes da terra oca.","firstservantsaythouwiltcoursethygreyhoun~stagsayfleeterthantheroe~86":"Primeiro Criado — Dizei que quereis a caça de lebres; vossos galgos são velozes \n Como cervos esbaforidos, sim, mais ligeiros que a corça.","secondservantdostthoulovepictureswewillf~wavingsedgesplaywithwind~179":"Segundo Criado — Gostais de pinturas? Traremos logo \n Adônis pintado junto a um regato, \n E Citereia toda escondida entre os juncos, \n Que parecem mover-se e brincar ao seu sopro, \n Tal como os juncos ondulantes brincam com o vento.","lordwellshowtheeioasshewasamaidandhowshe~ypaintedasthedeedwasdone~94":"Lorde — Mostraremos Io quando era donzela, \n E como foi enganada e surpreendida, \n Tão vivamente pintada quanto o fato foi cometido.","thirdservantordaphneroamingthroughathorn~thebloodandtearsaredrawn~155":"Terceiro Criado — Ou Dafne vagando por um bosque espinhoso, \n Arranhando as pernas, de modo que se jura que sangra, \n E a tal vista o triste Apolo chorará, \n Tão primorosamente o sangue e as lágrimas estão traçados.","lordthouartalordandnothingbutalordthouha~nanywomaninthiswaningage~90":"Lorde — Tu és um lorde e nada senão um lorde: \n Tens uma dama bem mais bela \n Que qualquer mulher nesta era declinante.","firstservantandtillthetearsthatshehathsh~ndyetsheisinferiortonone~144":"Primeiro Criado — E até que as lágrimas que ela derramou por vós, \n Como enciumadas torrentes, lhe inundassem o belo rosto, \n Era a criatura mais formosa do mundo; \n E mesmo assim não é inferior a nenhuma.","slyamialordandhaveisuchaladyordoidreamor~againapotothesmallestale~238":"Sly — Sou um lorde? E tenho tal dama? \n Ou sonho? Ou tenho sonhado até agora? \n Não durmo: vejo, ouço, falo; \n Sinto cheiros suaves e toco coisas macias: \n Pela minha vida, sou mesmo um lorde \n E não um funileiro nem Christophero Sly. \n Pois bem, trazei nossa dama à nossa vista; \n E mais uma vez, um caneco da cerveja mais fraca.","secondservantwilltpleaseyourmightinessto~wakedsowakedasifyouslept~184":"Segundo Criado — Apraz a Vossa Majestade lavar as mãos? \n Oh, como nos alegramos de ver restaurado o vosso juízo! \n Oh, se soubésseis de novo o que sois! \n Estes quinze anos estivestes num sonho; \n Ou, quando acordáveis, acordáveis como se dormísseis.","slythesefifteenyearsbymyfayagoodlynapbut~ineverspeakofallthattime~67":"Sly — Estes quinze anos! Pela minha fé, um bom cochilo. \n Mas nunca falei durante todo esse tempo?","firstservantoyesmylordbutveryidlewordsfo~ldcalloutforcicelyhacket~256":"Primeiro Criado — Oh, sim, meu senhor, mas palavras muito vãs: \n Pois, embora jazêsseis neste belo aposento, \n Dizíeis que fôreis expulso porta afora; \n E injuriáveis a dona da casa; \n E dizíeis que a denunciaríeis no tribunal, \n Porque trazia jarros de barro e não quartilhos selados: \n Às vezes chamáveis por Cicely Hacket.","slyaythewomansmaidofthehouse~ythewomansmaidofthehouse~28":"Sly — Sim, a criada da mulher da casa.","thirdservantwhysiryouknownohousenornosuc~neverwerenornomaneversaw~204":"Terceiro Criado — Ora, senhor, não conheceis casa nem tal criada, \n Nem tais homens como os que enumerastes, \n Como Stephen Sly e o velho John Naps da Grécia \n E Peter Turph e Henry Pimpernell \n E mais vinte nomes e homens como estes \n Que nunca existiram nem homem algum viu.","slynowlordbethankedformygoodamends~bethankedformygoodamends~34":"Sly — Agora, graças ao Senhor pela minha boa cura!","allamen~allamen~7":"Todos — Amém.","slyithanktheethoushaltnotlosebyit~theethoushaltnotlosebyit~33":"Sly — Agradeço-te: não perderás com isso.","enterthepageasaladywithattendants~ageasaladywithattendants~33":"Entra o Pajem vestido de dama, com criados.","pagehowfaresmynoblelord~pagehowfaresmynoblelord~23":"Pajem — Como passa meu nobre senhor?","slymarryifarewellforhereischeerenoughwhe~cheerenoughwhereismywife~50":"Sly — Ora, passo bem; pois aqui há regalo bastante. \n Onde está minha esposa?","pageherenoblelordwhatisthywillwithher~lordwhatisthywillwithher~37":"Pajem — Aqui, nobre senhor: que desejais dela?","slyareyoumywifeandwillnotcallmehusbandmy~callmelordiamyourgoodman~73":"Sly — Sois minha esposa e não me chamais de marido? \n Meus homens devem me chamar de “senhor”: eu sou vosso bom homem.","pagemyhusbandandmylordmylordandhusbandia~amyourwifeinallobedience~63":"Pajem — Meu marido e meu senhor, meu senhor e marido; \n Sou vossa esposa em toda obediência.","slyiknowitwellwhatmusticallher~owitwellwhatmusticallher~30":"Sly — Bem o sei. Como devo chamá-la?","lordmadam~lordmadam~9":"Lorde — Madame.","slyalcemadamorjoanmadam~slyalcemadamorjoanmadam~23":"Sly — Madame Alice, ou madame Joana?","lordmadamandnothingelsesolordscallladies~ingelsesolordscallladies~40":"Lorde — “Madame”, e nada mais: assim os lordes chamam as damas.","slymadamwifetheysaythatihavedreamdandsle~ovesomefifteenyearormore~68":"Sly — Madame esposa, dizem que sonhei \n E dormi mais de quinze anos.","pageayandthetimeseemsthirtyuntomebeingal~stimeabandondfromyourbed~68":"Pajem — Sim, e o tempo me parece trinta, \n Por todo esse tempo ter sido afastada do vosso leito.","slytismuchservantsleavemeandheralonemada~ndressyouandcomenowtobed~66":"Sly — É muito. Criados, deixai-me a sós com ela. \n Madame, despi-vos e vinde já para a cama.","pagethricenoblelordletmeentreatofyoutopa~sreasonstandsformyexcuse~220":"Pajem — Três vezes nobre senhor, deixai-me rogar-vos \n Que me perdoeis ainda por uma noite ou duas, \n Ou, se não, até que o sol se ponha: \n Pois vossos médicos ordenaram expressamente, \n Sob pena de incorrerdes na vossa antiga enfermidade, \n Que eu ainda me ausente do vosso leito: \n Espero que esta razão sirva de minha escusa.","slyayitstandssothatimayhardlytarrysolong~iteofthefleshandtheblood~128":"Sly — Sim, serve de tal modo que mal posso esperar tanto. Mas eu teria horror de recair nos meus sonhos: portanto esperarei, a despeito da carne e do sangue.","enteramessenger~enteramessenger~15":"Entra um Mensageiro.","messengeryourhonoursplayersheatingyouram~andharmsandlengthenslife~289":"Mensageiro — Os atores de Vossa Senhoria, ouvindo de vosso restabelecimento, \n Vieram representar uma agradável comédia; \n Pois assim vossos médicos julgam muito conveniente, \n Visto que demasiada tristeza coagulou vosso sangue, \n E a melancolia é a ama da frenesi: \n Por isso acharam bom que ouvísseis uma peça \n E dispusésseis o ânimo à alegria e ao regozijo, \n Que afasta mil males e prolonga a vida.","slymarryiwillletthemplayitisnotacomontya~sgamboldoratumblingtrick~72":"Sly — Ora, quero sim, que a representem. Não é uma comonty um folguedo de Natal ou uma pirueta de saltimbanco?","pagenomygoodlorditismorepleasingstuff~orditismorepleasingstuff~37":"Pajem — Não, meu bom senhor; é matéria mais agradável.","slywhathouseholdstuff~slywhathouseholdstuff~21":"Sly — O quê, trastes de casa?","pageitisakindofhistory~pageitisakindofhistory~22":"Pajem — É uma espécie de história.","slywellwellseetcomemadamwifesitbymysidea~allneerbeyoungerflourish~85":"Sly — Pois bem, vê-la-emos. Vinde, madame esposa, sentai-vos ao meu lado e deixai o mundo correr: nunca seremos mais jovens. Fanfarra.","paduaapublicplace~paduaapublicplace~17":"Pádua. Um lugar público.","enterlucentioandhismantranio~rlucentioandhismantranio~28":"Entram Lucentio e seu criado Tranio.","lucentiotraniosinceforthegreatdesireihad~tyseekstoquenchhisthirst~765":"Lucentio — Tranio, pois pelo grande desejo que tinha \n De ver a bela Pádua, berço das artes, \n Cheguei à fértil Lombardia, \n O aprazível jardim da grande Itália; \n E pelo amor e licença de meu pai estou munido \n De sua boa vontade e da tua boa companhia, \n Meu fiel servo, provado em tudo, \n Aqui respiremos e talvez instituamos \n Um curso de aprendizado e engenhosos estudos. \n Pisa, famosa por seus graves cidadãos, \n Deu-me o ser e a meu pai primeiro, \n Mercador de grande tráfico pelo mundo, \n Vincentio, da casa dos Bentivoli. \n Ao filho de Vincentio, criado em Florença, \n Cabe servir a todas as esperanças concebidas, \n Adornar sua fortuna com feitos virtuosos: \n E portanto, Tranio, durante o tempo em que estudo, \n A virtude e aquela parte da filosofia \n Que trata da felicidade, a ser alcançada \n Especialmente pela virtude, eis o que aplicarei. \n Dize-me o que pensas; pois deixei Pisa \n E vim a Pádua, como quem deixa \n Um raso charco para mergulhar no fundo \n E com fartura procura saciar a sede.","traniomiperdonatogentlemastermineiaminal~irstudywhatyoumostaffect~508":"Tranio — Mi perdonato, gentil senhor meu, \n Em tudo sinto como vós; \n Alegro-me que persistais assim em vosso intento \n De sorver as doçuras da doce filosofia. \n Apenas, bom senhor, enquanto admiramos \n Esta virtude e esta disciplina moral, \n Não sejamos estoicos nem estacas, peço-vos; \n Nem tão devotos das censuras de Aristóteles \n Que Ovídio seja de todo banido e abjurado: \n Deixai a lógica de lado com os conhecidos que tendes \n E praticai a retórica em vossa conversa comum; \n Usai a música e a poesia para vos avivar; \n A matemática e a metafísica, \n Entregai-vos a elas conforme vosso estômago o permitir; \n Nenhum proveito cresce onde não há prazer: \n Em suma, senhor, estudai o que mais vos apraz.","lucentiogramerciestraniowelldostthouadvi~yawhilewhatcompanyisthis~193":"Lucentio — Mil graças, Tranio, bem aconselhas. \n Se, Biondello, tivesses desembarcado, \n Poderíamos logo nos aprontar \n E tomar alojamento próprio para receber \n Os amigos que o tempo em Pádua nos der. \n Mas esperai um pouco: que companhia é esta?","traniomastersomeshowtowelcomeustotown~omeshowtowelcomeustotown~37":"Tranio — Senhor, algum espetáculo para nos dar boas-vindas à cidade.","enterbaptistakatharinabiancagremioandhor~lucentioandtraniostandby~70":"Entram Baptista, Katharina, Bianca, Gremio e Hortensio. Lucentio e Tranio ficam à parte.","baptistagentlemenimportunemenofartherfor~tocourtheratyourpleasure~234":"Baptista — Senhores, não me importuneis mais, \n Pois sabeis quão firmemente estou resolvido; \n A saber, não dar a minha filha mais moça \n Antes de ter marido para a mais velha: \n Se algum de vós ama Katharina, \n Porque vos conheço bem e vos estimo bem, \n Tereis licença de cortejá-la a vosso gosto.","gremioasidetocartherrathershestooroughfo~ehortensiowillyouanywife~76":"Gremio — À parte. Antes, de a levar à carroça: é áspera demais para mim. \n Vamos, vamos, Hortensio, quereis uma esposa?","katharinaiprayyousirisityourwilltomakeas~aleofmeamongstthesemates~65":"Katharina — Peço-vos, senhor, é vossa vontade \n Fazer de mim um chamariz entre esses camaradas?","hortensiomatesmaidhowmeanyouthatnomatesf~wereofgentlermildermould~78":"Hortensio — Camaradas, donzela! Que quereis dizer? Não há camaradas para vós, \n A menos que fôsseis de molde mais gentil e brando.","katharinaifaithsiryoushallneverneedtofea~urfaceanduseyoulikeafool~173":"Katharina — Por minha fé, senhor, nunca precisareis temer: \n Bem sei que isso não está a meio caminho de seu coração; \n Mas se estivesse, não duvideis que seu cuidado seria \n Pentear-vos o cocuruto com um banco de três pés \n E pintar-vos o rosto e tratar-vos como a um tolo.","hortensiafromallsuchdevilsgoodlorddelive~hdevilsgoodlorddeliverus~43":"Hortensio — De todos esses demônios, bom Senhor, livrai-nos!","gremioandmetoogoodlord~gremioandmetoogoodlord~22":"Gremio — E a mim também, bom Senhor!","traniohushmasterheressomegoodpastimetowa~arkmadorwonderfulfroward~79":"Tranio — Quieto, senhor! Eis um bom passatempo a caminho: \n Aquela moça é completamente louca ou prodigiosamente rebelde.","lucentiobutintheotherssilencedoiseemaids~urandsobrietypeacetranio~75":"Lucentio — Mas no silêncio da outra vejo \n O comportamento brando e a sobriedade de uma donzela. \n Paz, Tranio!","traniowellsaidmastermumandgazeyourfill~mastermumandgazeyourfill~38":"Tranio — Bem dito, senhor; calado! E contemplai à vontade.","baptistagentlementhatimaysoonmakegoodwha~ovetheeneerthelessmygirl~131":"Baptista — Senhores, para que eu logo cumpra \n O que disse, Bianca, entra: \n E não te desagrade, boa Bianca, \n Pois nem por isso te amarei menos, minha menina.","katharinaaprettypeatitisbestputfingerint~ngerintheeyeansheknewwhy~57":"Katharina — Uma lindinha mimada! Seria melhor \n Pôr o dedo no olho, se ela soubesse por quê.","biancasistercontentyouinmydiscontentsirt~otookandpractisebymyself~137":"Bianca — Irmã, contentai-vos com o meu descontentamento. \n Senhor, ao vosso gosto humildemente me submeto: \n Meus livros e instrumentos serão minha companhia, \n Neles olharei e me exercitarei sozinha.","lucentioharktraniothoumaysthearminervasp~houmaysthearminervaspeak~43":"Lucentio — Ouve, Tranio! Podes ouvir Minerva falar.","hortensiosigniorbaptistawillyoubesostran~dwilleffectsbiancasgrief~84":"Hortensio — Senhor Baptista, sereis assim tão estranho? \n Lamento que nossa boa vontade cause \n a mágoa de Bianca.","gremiowhywillyoumewherupsigniorbaptistaf~earthepenanceofhertongue~92":"Gremio — Por que a encerrais assim, \n Senhor Baptista, por causa deste demônio do inferno, \n E a fazeis arcar com a penitência da língua dela?","baptistagentlemencontentyeiamresolvedgoi~etocommunewithbiancaexit~370":"Baptista — Senhores, contentai-vos; estou resolvido: \n Entra, Bianca: Sai Bianca. \n E porque sei que ela tem o maior deleite \n Em música, instrumentos e poesia, \n Manterei mestres-escolas em minha casa, \n Aptos a instruir-lhe a juventude. Se vós, Hortensio, \n Ou vós, Senhor Gremio, conhecerdes algum, \n Recomendai-os aqui; pois a homens de saber \n Serei muito afável, e liberal \n Na boa educação de meus próprios filhos: \n E assim, adeus. Katharina, podeis ficar; \n Pois tenho mais a conversar com Bianca. Sai.","katharinawhyanditrustimaygotoomayinotwha~takeandwhattoleavehaexit~115":"Katharina — Ora, e creio que posso ir também, não posso? O quê, hei de ter horários marcados; como se, quiçá, eu não soubesse o que tomar e o que deixar, ah? Sai.","gremioyoumaygotothedevilsdamyourgiftsare~siwillwishhimtoherfather~290":"Gremio — Podeis ir para a avó do diabo: vossos dotes são tão bons que aqui ninguém vos reterá. O amor deles não é tão grande, Hortensio, que não possamos soprar juntos nos dedos e jejuar como se deve: nosso bolo está cru dos dois lados. Adeus: contudo, pelo amor que tenho à minha doce Bianca, se eu puder de algum modo achar um homem apto a ensinar-lhe aquilo em que ela se deleita, hei de recomendá-lo ao pai.","hortensiosowillisigniorgremiobutawordipr~deffectonethingspecially~229":"Hortensio — Também eu, Senhor Gremio: mas uma palavra, peço-vos. Embora a natureza de nossa querela nunca tenha admitido parlamento, sabei agora, após reflexão, que toca a nós dois, para que possamos de novo ter acesso a nossa bela senhora e ser felizes rivais no amor de Bianca, e trabalhar e realizar uma coisa em especial.","gremiowhatsthatipray~gremiowhatsthatipray~20":"Gremio — Qual é, peço-vos?","hortensiomarrysirtogetahusbandforhersist~ogetahusbandforhersister~42":"Hortensio — Ora, senhor, arranjar um marido para a irmã dela.","gremioahusbandadevil~gremioahusbandadevil~20":"Gremio — Um marido! Um diabo.","hortensioisayahusband~hortensioisayahusband~21":"Hortensio — Digo, um marido.","gremioisayadevilthinkestthouhortensiotho~ryafooltobemarriedtohell~98":"Gremio — Digo, um diabo. Pensais, Hortensio, que, embora o pai seja muito rico, haja homem tão rematado tolo que se case com o inferno?","hortensiotushgremiothoughitpassyourpatie~hallfaultsandmoneyenough~167":"Hortensio — Bah, Gremio, embora ultrapasse vossa paciência e a minha suportar seus altos alarmes, ora, homem, há bons sujeitos no mundo, se um homem pudesse encontrá-los, que a tomariam com todos os defeitos, e dinheiro bastante.","gremioicannottellbutihadaslieftakeherdow~thehighcrosseverymorning~96":"Gremio — Não sei dizer; mas eu preferiria tomar-lhe o dote com a condição de ser açoitado todas as manhãs na cruz da praça.","hortensiofaithasyousaytheressmallchoicei~nghowsayyousigniorgremio~302":"Hortensio — Na verdade, como dizeis, há pouca escolha entre maçãs podres. Mas vinde; já que este impedimento legal nos faz amigos, que seja amigavelmente mantido até que, ajudando a filha mais velha de Baptista a achar marido, libertemos a mais moça para um marido, e então voltemos à disputa. Doce Bianca! Feliz seja o homem que a conquistar! Quem corre mais depressa leva o anel. Que dizeis, Senhor Gremio?","gremioiamagreedandwouldihadgivenhimthebe~exeuntgremioandhortensio~159":"Gremio — Estou de acordo; e quisera eu ter dado o melhor cavalo de Pádua àquele que começasse a cortejar de verdade, desposar e levar para a cama essa mulher, e livrar a casa dela! Vamos. Saem Gremio e Hortensio.","tranioipraysirtellmeisitpossiblethatlove~uldofasuddentakesuchhold~67":"Tranio — Peço-vos, senhor, dizei-me, é possível \n Que o amor de repente tome tamanho domínio?","lucentiootraniotillifoundittobetrueineve~metranioforiknowthouwilt~339":"Lucentio — Oh, Tranio, até que o achei verdadeiro, \n Nunca pensei que fosse possível ou provável; \n Mas vê, enquanto ocioso ficava a olhar, \n Descobri o efeito do amor na ociosidade: \n E agora, com franqueza, confesso-te, \n A ti que me és tão secreto e tão caro \n Quanto Ana era para a rainha de Cartago, \n Tranio, ardo, definho, pereço, Tranio, \n Se não alcançar esta jovem e modesta donzela. \n Aconselha-me, Tranio, pois sei que podes; \n Ajuda-me, Tranio, pois sei que o farás.","traniomasteritisnotimetochideyounowaffec~etecaptumquamqueasminimo~132":"Tranio — Senhor, não é hora de repreender-vos agora; \n A afeição não se expulsa do coração com censuras: \n Se o amor vos tocou, nada resta senão isto: \n “Redime te captum quam queas minimo.”","lucentiogramerciesladgoforwardthisconten~mfortforthycounselssound~79":"Lucentio — Mil graças, rapaz, prossegue; isto me contenta: \n O resto me confortará, pois teu conselho é sólido.","traniomasteryoulookdsolonglyonthemaidper~arkdnotwhatsthepithofall~72":"Tranio — Senhor, olhastes tão longamente para a donzela, \n Que talvez não notastes o essencial de tudo.","lucentiooyesisawsweetbeautyinherfacesuch~eshekissdthecretanstrand~139":"Lucentio — Oh, sim, vi doce beleza em seu rosto, \n Qual a que tinha a filha de Agenor, \n Que fez o grande Júpiter humilhar-se a sua mão, \n Quando de joelhos beijou a praia de Creta.","traniosawyounomoremarkdyounothowhersiste~smighthardlyendurethedin~110":"Tranio — Não vistes mais? Não notastes como a irmã dela \n Começou a ralhar e a levantar tal tempestade \n Que ouvidos mortais mal suportariam o estrépito?","lucentiotranioisawhercorallipstomoveandw~dandsweetwasallisawinher~100":"Lucentio — Tranio, vi os lábios de coral dela mover-se \n E com seu hálito ela perfumava o ar: \n Sagrado e doce era tudo o que vi nela.","tranionaythentistimetostirhimfromhistran~llnotbeannoydwithsuitors~282":"Tranio — Ora, então é hora de tirá-lo do êxtase. \n Peço-vos, despertai, senhor: se amais a donzela, \n Dirigi pensamentos e engenho a conquistá-la. Eis como está: \n A irmã mais velha é tão perversa e arisca \n Que, até que o pai se livre dela, \n Senhor, vosso amor deve viver donzela em casa; \n E por isso ele a tem fechada a sete chaves, \n Para que não seja incomodada por pretendentes.","lucentioahtraniowhatacruelfathershebutar~hoolmasterstoinstructher~110":"Lucentio — Ah, Tranio, que pai cruel é ele! \n Mas não reparaste que ele teve o cuidado \n De lhe arranjar mestres-escolas hábeis para instruí-la?","tranioaymarryamisirandnowtisplotted~ryamisirandnowtisplotted~35":"Tranio — Sim, por certo, senhor; e agora está tramado.","lucentioihaveittranio~lucentioihaveittranio~21":"Lucentio — Já tenho, Tranio.","traniomasterformyhandbothourinventionsme~ventionsmeetandjumpinone~54":"Tranio — Senhor, por minha mão, \n Nossos dois engenhos se encontram e coincidem em um.","lucentiotellmethinefirst~lucentiotellmethinefirst~24":"Lucentio — Dize-me o teu primeiro.","tranioyouwillbeschoolmasterandundertaket~ofthemaidthatsyourdevice~74":"Tranio — Vós sereis o mestre-escola \n E tomareis a si o ensino da donzela: \n É esse o vosso plano.","lucentioitismayitbedone~lucentioitismayitbedone~23":"Lucentio — É: pode-se fazer?","tranionotpossibleforwhoshallbearyourpart~countrymenandbanquetthem~140":"Tranio — Impossível; pois quem fará o vosso papel, \n E será aqui em Pádua o filho de Vincentio, \n Manterá casa e aplicará-se aos livros, receberá os amigos, \n Visitará os conterrâneos e os banqueteará?","lucentiobastacontenttheeforihaveitfullwe~mhimfirsttokeephistongue~394":"Lucentio — Basta; sossega, que tenho tudo pronto. \n Ainda não fomos vistos em casa alguma, \n Nem podemos ser distinguidos pelo rosto \n Como criado ou senhor; segue-se, pois, o seguinte: \n Tu serás o senhor, Tranio, em meu lugar, \n Manterás casa, porte e criados, como eu deveria: \n Eu serei outro qualquer, algum florentino, \n Algum napolitano, ou homem humilde de Pisa. \n Está chocado e assim será: Tranio, de imediato \n Despe-te; toma meu chapéu colorido e capa: \n Quando Biondello vier, ele servirá a ti; \n Mas primeiro o convencerei a guardar a língua.","traniosohadyouneedinbriefsirsithityourpl~causesowellilovelucentio~213":"Tranio — Bem precisais. \n Em suma, senhor, pois tal é vosso gosto, \n E estou obrigado a obedecer; \n Pois assim vosso pai me recomendou na partida: \n “Sê prestimoso a meu filho”, disse ele, \n Embora eu pense que foi em outro sentido; \n Contento-me em ser Lucentio, \n Porque amo tanto Lucentio.","lucentiotraniobesobecauselucentiolovesan~ndedeyeherecomestherogue~127":"Lucentio — Tranio, sê-o, porque Lucentio ama: \n E que eu seja escravo, para conquistar aquela donzela \n Cuja súbita visão cativou meu olho ferido. \n Eis que vem o malandro.","enterbiondello~enterbiondello~14":"Entra Biondello.","sirrahwherehaveyoubeen~sirrahwherehaveyoubeen~22":"Rapaz, onde estiveste?","biondellowherehaveibeennayhownowwhereare~isorbothpraywhatsthenews~119":"Biondello — Onde estive! Ora essa! Onde estais vós? Senhor, meu companheiro Tranio roubou vossas roupas? Ou vós as dele? Ou ambos? Por favor, quais são as novas?","lucentiosirrahcomehithertisnotimetojesta~avemylifeyouunderstandme~304":"Lucentio — Rapaz, vem cá: não é hora de gracejos, \n E por isso ajusta tuas maneiras ao momento. \n Teu companheiro Tranio aqui, para salvar-me a vida, \n Veste meus trajes e assume meu semblante, \n E eu, para minha fuga, vesti os dele; \n Pois numa briga, desde que desembarquei, \n Matei um homem e temo ter sido reconhecido: \n Serve-o, ordeno-te, como convém, \n Enquanto abro caminho daqui para salvar a vida: \n Entendes-me?","biondelloisirneerawhit~biondelloisirneerawhit~22":"Biondello — Eu, senhor! Nem um pouco.","lucentioandnotajotoftranioinyourmouthtra~nioischangedintolucentio~64":"Lucentio — E nem uma palavra de Tranio na tua boca: \n Tranio foi mudado em Lucentio.","biondellothebetterforhimwouldiweresotoo~terforhimwouldiweresotoo~39":"Biondello — Melhor para ele: quisera eu ser assim também!","traniosocouldifaithboytohavethenextwisha~eselseyourmasterlucentio~243":"Tranio — Eu também, na verdade, rapaz, para ter o desejo seguinte, \n Que Lucentio de fato tivesse a filha mais moça de Baptista. \n Mas, rapaz, não por mim, mas por teu amo, aconselho-te \n A usar tuas maneiras com discrição em toda sorte de companhia: \n Quando estou só, ora, então sou Tranio; \n Mas em todos os outros lugares, teu amo Lucentio.","lucentiotranioletsgoonethingmorereststha~bothgoodandweightyexeunt~139":"Lucentio — Tranio, vamos: resta uma coisa, que tu mesmo cumpras, que é ser um dentre esses pretendentes: se perguntas por quê, basta que minhas razões são boas e de peso. Saem.","thepresentersabovespeak~thepresentersabovespeak~23":"Os apresentadores no alto falam.","firstservantmylordyounodyoudonotmindthep~ounodyoudonotmindtheplay~43":"Primeiro Criado — Meu senhor, cabeceais; não prestais atenção à peça.","slyyesbysaintannedoiagoodmattersurelycom~elycomesthereanymoreofit~58":"Sly — Sim, por Santa Ana, presto. Boa matéria, por certo: vem mais alguma coisa?","pagemylordtisbutbegun~pagemylordtisbutbegun~21":"Pajem — Meu senhor, só começou.","slytisaveryexcellentpieceofworkmadamlady~dtweredonetheysitandmark~68":"Sly — É uma obra excelentíssima, madame senhora: quisera que já estivesse acabada! Sentam-se e observam.","paduabeforehortensioshouse~duabeforehortensioshouse~26":"Pádua. Diante da casa de Hortensio.","enterpetruchioandhismangrumio~petruchioandhismangrumio~29":"Entram Petruchio e seu criado Grumio.","petruchioveronaforawhileitakemyleavetose~eresirrahgrumioknockisay~151":"Petruchio — Verona, por um tempo despeço-me de ti, \n Para ver meus amigos em Pádua, mas de todos \n O mais amado e provado amigo, \n Hortensio; e creio que esta é a casa dele. \n Aqui, rapaz Grumio; bate, digo.","grumioknocksirwhomshouldiknockisthereman~manhasrebusedyourworship~61":"Grumio — Bater, senhor! A quem devo bater? Algum homem repreendeu Vossa Mercê?","petruchiovillainisayknockmeheresoundly~inisayknockmeheresoundly~38":"Petruchio — Vilão, digo, bate-me aqui com força.","grumioknockyouheresirwhysirwhatamisirtha~atishouldknockyouheresir~63":"Grumio — Bater-vos aqui, senhor! Ora, senhor, que sou eu, senhor, para vos bater aqui, senhor?","petruchiovillainisayknockmeatthisgateand~orillknockyourknavespate~73":"Petruchio — Vilão, digo, bate-me neste portão \n E golpeia-o bem, ou baterei no teu crânio de patife.","grumiomymasterisgrownquarrelsomeishouldk~wafterwhocomesbytheworst~87":"Grumio — Meu amo tornou-se briguento. Eu devia bater-vos primeiro, \n E depois sei quem leva a pior.","petruchiowillitnotbefaithsirrahanyoullno~ngithewringshimbytheears~104":"Petruchio — Não queres? \n Na verdade, rapaz, se não bateres, eu tocarei; \n Vou ver como sabes dó, ré, e cantá-lo. Torce-lhe as orelhas.","grumiohelpmastershelpmymasterismad~mastershelpmymasterismad~34":"Grumio — Socorro, senhores, socorro! Meu amo enlouqueceu.","petruchionowknockwhenibidyousirrahvillai~whenibidyousirrahvillain~41":"Petruchio — Agora bate quando eu mandar, rapaz vilão!","enterhortensio~enterhortensio~14":"Entra Hortensio.","hortensiohownowwhatsthemattermyoldfriend~uchiohowdoyouallatverona~89":"Hortensio — Então! Que se passa? Meu velho amigo Grumio! E meu bom amigo Petruchio! Como estais todos em Verona?","petruchiosigniorhortensiocomeyoutopartth~ilcuorebentrovatomayisay~77":"Petruchio — Senhor Hortensio, vindes apartar a briga? \n “Con tutto il cuore, ben trovato”, posso dizer.","hortensioallanostracasabenvenutomoltohon~ewillcompoundthisquarrel~102":"Hortensio — “Alla nostra casa ben venuto, molto honorato signor mio Petruchio.” Levanta, Grumio, levanta: nós acertaremos esta querela.","grumionaytisnomattersirwhathelegesinlati~dnotgrumiocomebytheworst~276":"Grumio — Não, não importa, senhor, o que ele alega em latim. Se este não é um caso legítimo para eu deixar o serviço dele, vede, senhor, ele me mandou bater nele e golpeá-lo com força, senhor: ora, era decente um criado tratar assim seu amo, que talvez, pelo que vejo, tenha trinta e dois, um ponto a menos? Quisera a Deus eu tivesse batido bem no início, \n Então Grumio não teria levado a pior.","petruchioasenselessvillaingoodhortensioi~otgethimformyhearttodoit~103":"Petruchio — Um vilão sem juízo! Bom Hortensio, \n Mandei o patife bater em vosso portão \n E não consegui, por nada deste mundo, que o fizesse.","grumioknockatthegateoheavensspakeyounott~nowwithknockingatthegate~142":"Grumio — Bater no portão! Oh, céus! Não dissestes estas palavras claramente: “Rapaz, bate-me aqui, golpeia-me aqui, bate-me bem e bate-me com força”? E vindes agora com “bater no portão”?","petruchiosirrahbegoneortalknotiadviseyou~egoneortalknotiadviseyou~40":"Petruchio — Rapaz, some, ou não fales, aconselho-te.","hortensiopetruchiopatienceiamgrumiospled~topaduaherefromoldverona~182":"Hortensio — Petruchio, paciência; sou fiador de Grumio: \n Ora, é um triste incidente entre ele e vós, \n Vosso antigo, fiel e agradável criado Grumio. \n E dizei-me agora, doce amigo, que feliz brisa \n Vos sopra aqui a Pádua desde a velha Verona?","petruchiosuchwindasscattersyoungmenthrou~mcomeabroadtoseetheworld~305":"Petruchio — O vento que espalha os jovens pelo mundo \n A buscar fortuna mais longe que em casa, \n Onde pouca experiência cresce. Mas em poucas palavras, \n Senhor Hortensio, assim estou: \n Antonio, meu pai, morreu; \n E lancei-me neste labirinto, \n Talvez para casar e prosperar o melhor que puder: \n Tenho coroas na bolsa e bens em casa, \n E assim saí a ver o mundo.","hortensiopetruchioshallithencomeroundlyt~ndandillnotwishtheetoher~207":"Hortensio — Petruchio, devo então falar-te às claras \n E desejar-te uma esposa megera e feia? \n Pouco me agradecerias o conselho: \n E no entanto prometo-te que seria rica, \n E muito rica: mas és meu amigo demais, \n E não te desejarei tal mulher.","petruchiosigniorhortensiotwixtsuchfriend~lthilythenhappilyinpadua~382":"Petruchio — Senhor Hortensio, entre amigos como nós \n Poucas palavras bastam; e portanto, se conheces \n Uma bastante rica para ser esposa de Petruchio, \n Pois a riqueza é o refrão de minha dança de corte, \n Seja ela tão feia quanto o amor de Florentius, \n Tão velha quanto a Sibila e tão perversa e arisca \n Quanto Xantipa, a de Sócrates, ou pior, \n Não me move, ou não tira, ao menos, \n O fio da afeição em mim, fosse ela tão áspera \n Quanto os mares inchados do Adriático: \n Vim casar riquemente em Pádua; \n Se riquemente, então felizmente em Pádua.","grumionaylookyousirhetellsyouflatlywhath~samisssomoneycomeswithal~219":"Grumio — Pois vede, senhor, ele vos diz às claras o que pensa: ora, dai-lhe ouro bastante e casai-o com um boneco ou uma figurinha de berloque; ou com uma velha rameira sem um dente na cabeça, ainda que tenha tantas doenças quanto cinquenta e dois cavalos: ora, nada lhe vem mal, contanto que venha dinheiro junto.","hortensiopetruchiosincewearesteppdthusfa~dnotwedherforamineofgold~330":"Hortensio — Petruchio, já que avançamos tanto, \n Continuarei o que iniciei por gracejo. \n Posso, Petruchio, arranjar-te uma esposa \n Com riqueza bastante, jovem e formosa, \n Criada como melhor convém a uma dama: \n Seu único defeito, e que defeito basta, \n É ser insuportavelmente perversa, \n Arisca e rebelde, tão além de toda medida \n Que, ainda que meu estado fosse bem pior do que é, \n Não a desposaria por uma mina de ouro.","petruchiohortensiopeacethouknowstnotgold~enthecloudsinautumncrack~150":"Petruchio — Hortensio, paz! Não conheces o efeito do ouro: \n Dize-me o nome do pai dela e basta; \n Pois a abordarei, ainda que ralhe tão alto \n Quanto o trovão quando as nuvens estalam no outono.","hortensioherfatherisbaptistaminolaanaffa~aduaforherscoldingtongue~122":"Hortensio — O pai é Baptista Minola, \n Cavalheiro afável e cortês: \n O nome dela é Katharina Minola, \n Famosa em Pádua por sua língua ralhadora.","petruchioiknowherfatherthoughiknownother~ouwillaccompanymethither~200":"Petruchio — Conheço o pai, embora não a conheça; \n E ele conheceu bem meu pai defunto. \n Não dormirei, Hortensio, até vê-la; \n E portanto permiti-me a ousadia \n De deixar-vos já neste primeiro encontro, \n A menos que me acompanheis até lá.","grumioiprayyousirlethimgowhilethehumourl~thanacatyouknowhimnotsir~361":"Grumio — Peço-vos, senhor, deixai-o ir enquanto dura o humor. Palavra minha, se ela o conhecesse tão bem quanto eu, pensaria que ralhar pouco adiantaria com ele: talvez o chame de meia dúzia de patifes ou por aí: ora, isso não é nada; se ele começar uma vez, vai injuriar em figuras de retórica de forca. Digo-vos, senhor, se ela o enfrentar só um pouco, ele lhe jogará uma figura no rosto e a desfigurará de tal modo que ela não terá mais olhos para ver do que um gato. Não o conheceis, senhor.","hortensiotarrypetruchioimustgowiththeefo~ethecursthavegotahusband~384":"Hortensio — Espera, Petruchio, devo ir contigo, \n Pois na fortaleza de Baptista está meu tesouro: \n Ele tem sob guarda a joia da minha vida, \n Sua filha mais moça, a formosa Bianca, \n E a retém de mim e de outros mais, \n Pretendentes dela e rivais no meu amor, \n Supondo ser coisa impossível, \n Pelos defeitos que antes enumerei, \n Que Katharina algum dia seja cortejada; \n Por isso Baptista tomou esta ordem: \n Que ninguém tenha acesso a Bianca \n Até que Katharina, a perversa, tenha marido.","grumiokatharinethecurstatitleforamaidofa~amaidofalltitlestheworst~56":"Grumio — Katharina, a perversa! \n Título para donzela, o pior de todos os títulos.","hortensionowshallmyfriendpetruchiodomegr~spectedcourtherbyherself~227":"Hortensio — Agora meu amigo Petruchio me fará o favor \n De apresentar-me, disfarçado em sóbrias vestes, \n Ao velho Baptista como mestre-escola \n Versado em música, para instruir Bianca; \n Para que assim, por este artifício, eu tenha ao menos \n Licença e vagar para lhe fazer a corte \n E cortejá-la a sós, sem suspeita.","grumioheresnoknaveryseetobeguiletheoldfo~lkslaytheirheadstogether~80":"Grumio — Aí não há patifaria! Vede, para enganar os velhos, como os jovens juntam as cabeças!","entergremioandlucentiodisguised~emioandlucentiodisguised~31":"Entram Gremio e Lucentio disfarçado.","mastermasterlookaboutyouwhogoesthereha~okaboutyouwhogoesthereha~38":"Senhor, senhor, olhai à vossa volta: quem vem ali, hein?","hortensiopeacegrumioitistherivalofmylove~vepetruchiostandbyawhile~62":"Hortensio — Paz, Grumio! É o rival do meu amor. \n Petruchio, ficai de lado um instante.","grumioaproperstriplingandanamorous~perstriplingandanamorous~34":"Grumio — Um belo rapazote e enamorado!","gremiooverywellihaveperusedthenoteharkyo~gotowhatwillyoureadtoher~322":"Gremio — Oh, muito bem; examinei a lista. \n Ouvi, senhor; quero-os muito bem encadernados: \n Todos livros de amor, cuidai disso a todo custo; \n E vede que não lhe leiais outras lições: \n Entendeis-me: além e acima \n Da liberalidade do Senhor Baptista, \n Eu a completarei com uma generosa quantia. Tomai também vosso papel, \n E mandai-os bem perfumados: \n Pois ela é mais doce que o próprio perfume \n A quem eles se destinam. Que lhe lereis?","lucentiowhateerireadtoherillpleadforyoua~unlessyouwereascholarsir~170":"Lucentio — Seja o que for que eu lhe ler, pleitearei por vós \n Como por meu patrono, ficai assim seguro, \n Tão firmemente como se vós mesmo estivésseis presente: \n Sim, e talvez com palavras mais bem-sucedidas \n Que as vossas, a menos que fôsseis um letrado, senhor.","gremioothislearningwhatathingitis~islearningwhatathingitis~33":"Gremio — Oh, este saber, que coisa é!","grumioothiswoodcockwhatanassitis~hiswoodcockwhatanassitis~32":"Grumio — Oh, este tolo, que asno é!","petruchiopeacesirrah~petruchiopeacesirrah~20":"Petruchio — Paz, rapaz!","hortensiogrumiomumgodsaveyousigniorgremi~mgodsaveyousigniorgremio~41":"Hortensio — Grumio, calado! Deus vos guarde, Senhor Gremio.","gremioandyouarewellmetsigniorhortensiotr~rbooksgoodonesiwarrantye~266":"Gremio — E bem encontrado, Senhor Hortensio. \n Sabeis aonde vou? A Baptista Minola. \n Prometi indagar com cuidado \n Acerca de um mestre-escola para a bela Bianca: \n E por boa fortuna achei muito bem \n Este jovem, em saber e comportamento \n Apto a seu fim, bem lido em poesia \n E outros livros, bons, garanto-vos.","hortensiotiswellandihavemetagentlemanhat~ofairbiancasobelovedofme~155":"Hortensio — Está bem; e encontrei um cavalheiro \n Que me prometeu ajudar-me a achar outro, \n Um fino músico para instruir nossa senhora; \n Assim não ficarei em nada atrás no dever \n Para com a bela Bianca, por mim tão amada.","gremiobelovedofmeandthatmydeedsshallprov~andthatmydeedsshallprove~41":"Gremio — Amada por mim; e isso provarão meus atos.","grumioandthathisbagsshallprove~andthathisbagsshallprove~30":"Grumio — E isso provarão suas bolsas.","hortensiogremiotisnownotimetoventourlove~marryherifherdowryplease~233":"Hortensio — Gremio, não é hora de expandir nosso amor: \n Ouvi-me, e se me falardes com cortesia, \n Contar-vos-ei novas razoavelmente boas para ambos. \n Eis um cavalheiro que por acaso encontrei, \n Que, mediante acordo de nossa parte a seu gosto, \n Empreenderá cortejar a perversa Katharina, \n Sim, e casar com ela, se o dote lhe agradar.","gremiososaidsodoneiswellhortensiohaveyou~veyoutoldhimallherfaults~59":"Gremio — Dito e feito, está bem. \n Hortensio, contastes-lhe todos os defeitos dela?","petruchioiknowsheisanirksomebrawlingscol~tbeallmastersihearnoharm~70":"Petruchio — Sei que é uma megera briguenta e enfadonha: \n Se isso é tudo, senhores, não vejo mal algum.","gremionosaystmesofriendwhatcountryman~mesofriendwhatcountryman~37":"Gremio — Não, dizeis-me isso, amigo? De que terra sois?","petruchioborninveronaoldantoniossonmyfat~hopegooddaysandlongtosee~96":"Petruchio — Nascido em Verona, filho do velho Antonio: \n Morto meu pai, minha fortuna vive por mim; \n E espero ver dias bons e longos.","gremioosirsuchalifewithsuchawifewerestra~butwillyouwoothiswildcat~130":"Gremio — Oh, senhor, tal vida, com tal esposa, seria estranha! \n Mas se tendes estômago, a ela em nome de Deus: \n Tereis meu auxílio em tudo. \n Mas cortejareis esta gata-selvagem?","petruchiowillilive~petruchiowillilive~18":"Petruchio — Se vou viver?","grumiowillhewooherayorillhangher~llhewooherayorillhangher~32":"Grumio — Se a cortejará? Sim, ou eu a enforco.","petruchiowhycameihitherbuttothatintentth~tushtushfearboyswithbugs~428":"Petruchio — Por que vim aqui senão com esse intento? \n Pensais que um pequeno alarido possa intimidar meus ouvidos? \n Não ouvi eu, em meu tempo, leões rugir? \n Não ouvi o mar, empolado pelos ventos, \n Rugir como javali furioso, ensopado de suor? \n Não ouvi grande artilharia no campo, \n E a artilharia do céu trovejar nos ares? \n Não ouvi, em batalha campal, \n Altos alarmes, relinchos de corcéis e clangor de trombetas? \n E me falais da língua de uma mulher, \n Que nem metade de tão grande golpe dá ao ouvido \n Quanto uma castanha no fogo de um lavrador? \n Bah, bah! Assustai meninos com bichos-papões.","grumioforhefearsnone~grumioforhefearsnone~20":"Grumio — Pois ele nada teme.","gremiohortensioharkthisgentlemanishappil~umesforhisowngoodandours~82":"Gremio — Hortensio, ouvi: \n Este cavalheiro chegou felizmente, \n Presume meu espírito, para seu bem e o nosso.","hortensioipromisedwewouldbecontributorsa~hargingofwooingwhatsoeer~74":"Hortensio — Prometi que seríamos contribuintes \n E arcaríamos com seus gastos de corte, quaisquer que fossem.","gremioandsowewillprovidedthathewinher~willprovidedthathewinher~37":"Gremio — E assim faremos, contanto que ele a conquiste.","grumioiwouldiwereassureofagooddinner~iwereassureofagooddinner~36":"Grumio — Quisera eu estar tão certo de um bom jantar.","entertraniobraveandbiondello~rtraniobraveandbiondello~28":"Entram Tranio, ricamente trajado, e Biondello.","traniogentlemengodsaveyouifimaybeboldtel~eofsigniorbaptistaminola~108":"Tranio — Senhores, Deus vos guarde. Se me permitis a ousadia, \n Dizei-me, rogo-vos, qual é o caminho mais curto \n Para a casa do Senhor Baptista Minola?","biondellohethathasthetwofairdaughtersist~airdaughtersistheyoumean~49":"Biondello — Aquele que tem as duas belas filhas: é ele que dizeis?","tranioevenhebiondello~tranioevenhebiondello~21":"Tranio — Ele mesmo, Biondello.","gremioharkyousiryoumeannotherto~arkyousiryoumeannotherto~31":"Gremio — Ouvi, senhor; não pretendeis ela para—","tranioperhapshimandhersirwhathaveyoutodo~andhersirwhathaveyoutodo~40":"Tranio — Talvez ele e ela, senhor: que tendes com isso?","petruchionotherthatchidessiratanyhandipr~tchidessiratanyhandipray~42":"Petruchio — Não a que ralha, senhor, em caso algum, peço.","tranioilovenochiderssirbiondelloletsaway~derssirbiondelloletsaway~40":"Tranio — Não amo ralhadoras, senhor. Biondello, vamos.","lucentiowellbeguntranio~lucentiowellbeguntranio~23":"Lucentio — Bem começado, Tranio.","hortensiosirawordereyougoareyouasuitorto~othemaidyoutalkofyeaorno~63":"Hortensio — Senhor, uma palavra antes de ir; \n Sois pretendente da donzela de que falais, sim ou não?","tranioandifibesirisitanyoffence~ndifibesirisitanyoffence~31":"Tranio — E se for, senhor, é alguma ofensa?","gremionoifwithoutmorewordsyouwillgetyouh~ewordsyouwillgetyouhence~44":"Gremio — Não; se sem mais palavras daqui vos retirardes.","traniowhysiriprayarenotthestreetsasfreef~reetsasfreeformeasforyou~52":"Tranio — Ora, senhor, peço, não são as ruas tão livres \n Para mim como para vós?","gremiobutsoisnotshe~gremiobutsoisnotshe~19":"Gremio — Mas ela não é.","tranioforwhatreasonibeseechyou~forwhatreasonibeseechyou~30":"Tranio — Por que razão, rogo-vos?","gremioforthisreasonifyoullknowthatshesth~hoiceloveofsigniorgremio~66":"Gremio — Por esta razão, se quereis saber, \n Que ela é o amor escolhido do Senhor Gremio.","hortensiothatshesthechosenofsigniorhorte~chosenofsigniorhortensio~44":"Hortensio — Que ela é a eleita do Senhor Hortensio.","traniosoftlymymastersifyoubegentlemendom~iscameinhopetospeedalone~320":"Tranio — Devagar, meus senhores! Se sois cavalheiros, \n Fazei-me esta justiça; ouvi-me com paciência. \n Baptista é um nobre cavalheiro, \n A quem meu pai não é de todo desconhecido; \n E fosse a filha mais bela do que é, \n Pode ter mais pretendentes, e a mim por um. \n A filha da bela Leda teve mil pretendentes; \n Pode, pois, bem ter mais um a bela Bianca: \n E assim terá; Lucentio será um deles, \n Ainda que Páris viesse esperando vencer sozinho.","gremiowhatthisgentlemanwillouttalkusall~entlemanwillouttalkusall~39":"Gremio — O quê! Este cavalheiro nos superará a todos em falar.","lucentiosirgivehimheadiknowhellproveajad~mheadiknowhellproveajade~41":"Lucentio — Senhor, dai-lhe rédea: sei que acabará um sendeiro.","petruchiohortensiotowhatendareallthesewo~owhatendareallthesewords~43":"Petruchio — Hortensio, a que fim todas essas palavras?","hortensiosirletmebesoboldasaskyoudidyouy~everseebaptistasdaughter~66":"Hortensio — Senhor, permiti-me a ousadia de perguntar-vos, \n Já vistes alguma vez a filha de Baptista?","tranionosirbuthearidothathehathtwotheone~otherforbeauteousmodesty~97":"Tranio — Não, senhor; mas ouço dizer que ele tem duas, \n Uma tão famosa pela língua ralhadora \n Quanto a outra pela beleza e modéstia.","petruchiosirsirthefirstsformelethergoby~thefirstsformelethergoby~39":"Petruchio — Senhor, senhor, a primeira é para mim; deixai-a para mim.","gremioyealeavethatlabourtogreatherculesa~tbemorethanalcidestwelve~70":"Gremio — Sim, deixai esse labor ao grande Hércules; \n E que seja mais que os doze de Alcides.","petruchiosirunderstandyouthisofmeinsooth~erthenisfreeandnotbefore~201":"Petruchio — Senhor, entendei isto de mim em verdade: \n A filha mais moça por quem suspirais \n O pai a guarda de todo acesso de pretendentes, \n E não a prometerá a homem algum \n Até que a irmã mais velha se case primeiro: \n A mais moça então fica livre, e não antes.","tranioifitbesosirthatyouarethemanmustste~sogracelessbetobeingrate~197":"Tranio — Se assim é, senhor, e sois o homem \n Que nos servirá a todos, e a mim entre os demais, \n E se quebrardes o gelo e fizerdes esta proeza, \n Conquistando a mais velha, libertando a mais moça \n Para nosso acesso, aquele a quem couber a sorte de tê-la \n Não será tão desgracioso a ponto de ser ingrato.","hortensiosiryousaywellandwellyoudoconcei~llrestgenerallybeholding~139":"Hortensio — Senhor, falais bem e bem concebeis; \n E já que professais ser pretendente, \n Deveis, como nós, gratificar este cavalheiro, \n A quem todos ficamos em geral devendo.","traniosirishallnotbeslackinsignwhereofpl~ybuteatanddrinkasfriends~169":"Tranio — Senhor, não serei negligente: em sinal do que, \n Se vos apraz, podemos combinar esta tarde \n E beber brindes à saúde de nossa senhora, \n E fazer como os adversários na lei, \n Pelejar com vigor, mas comer e beber como amigos.","grumiobiondellooexcellentmotionfellowsle~tmotionfellowsletsbegone~48":"Grumio\n Biondello — Oh, excelente moção! Companheiros, vamos.","hortensiothemotionsgoodindeedandbeitsope~allbeyourbenvenutoexeunt~74":"Hortensio — A moção é boa de fato, e seja assim, \n Petruchio, serei vosso ben venuto. Saem.","paduaaroominbaptistashouse~duaaroominbaptistashouse~26":"Pádua. Uma sala na casa de Baptista.","enterkatharinaandbianca~enterkatharinaandbianca~23":"Entram Katharina e Bianca.","biancagoodsisterwrongmenotnorwrongyourse~elliknowmydutytomyelders~220":"Bianca — Boa irmã, não me firas, nem a ti mesma, \n Fazendo de mim serva e escrava; \n Isso desdenho: mas quanto a estes outros enfeites, \n Desata-me as mãos, eu mesma os tirarei, \n Sim, todas as minhas roupas, até a anágua; \n Ou o que quiseres mandar-me, farei, \n Tão bem conheço meu dever para com meus mais velhos.","katharinaofallthysuitorshereichargetheet~tbestseethoudissemblenot~80":"Katharina — De todos os teus pretendentes, aqui te ordeno, dize \n A quem amas mais: vê que não dissimules.","biancabelievemesisterofallthemenaliveine~uldfancymorethananyother~99":"Bianca — Crê-me, irmã, de todos os homens vivos \n Nunca vi ainda aquele rosto especial \n Que eu preferisse a qualquer outro.","katharinaminionthouliestistnothortensio~thouliestistnothortensio~39":"Katharina — Faceira, mentes. Não é Hortensio?","biancaifyouaffecthimsisterhereiswearillp~myselfbutyoushallhavehim~74":"Bianca — Se o estimas, irmã, aqui juro \n Que eu mesma pleitearei por ti, e o terás.","katharinaothenbelikeyoufancyrichesmoreyo~lhavegremiotokeepyoufair~68":"Katharina — Oh, então, ao que parece, preferes a riqueza: \n Queres Gremio para te manter elegante.","biancaisitforhimyoudoenvymesonaythenyouj~eesisterkateuntiemyhands~126":"Bianca — É por ele que me tens tanta inveja? \n Ora, então gracejas, e agora bem percebo \n Que só gracejaste comigo todo este tempo: \n Rogo-te, irmã Kate, desata-me as mãos.","katharinaifthatbejestthenalltherestwasso~lltherestwassostrikesher~50":"Katharina — Se isso é gracejo, então o resto também foi. Bate nela.","enterbaptista~enterbaptista~13":"Entra Baptista.","baptistawhyhownowdamewhencegrowsthisinso~crosstheewithabitterword~216":"Baptista — Ora, que é isso, senhora! De onde vem tal insolência? \n Bianca, afasta-te. Pobre menina! Ela chora. \n Vai ao teu bordado; não te metas com ela. \n Vergonha, ordinária de espírito endiabrado, \n Por que ofendes quem nunca te ofendeu? \n Quando ela te contrariou com uma palavra amarga?","katharinahersilencefloutsmeandillbereven~revengedfliesafterbianca~59":"Katharina — O silêncio dela me zomba, e serei vingada. Corre atrás de Bianca.","baptistawhatinmysightbiancagettheeinexit~iancagettheeinexitbianca~46":"Baptista — O quê, diante dos meus olhos? Bianca, entra. Sai Bianca.","katharinawhatwillyounotsuffermenaynowise~indoccasionofrevengeexit~204":"Katharina — O quê, não me permitireis? Ora, agora vejo \n Que ela é vosso tesouro, ela deve ter marido; \n Eu devo dançar descalça no dia de seu casamento \n E, por vosso amor a ela, levar macacos ao inferno. \n Não me faleis: irei sentar-me e chorar \n Até que ache ocasião de vingança. Sai.","baptistawasevergentlemanthusgrievedasibu~rievedasibutwhocomeshere~53":"Baptista — Houve jamais cavalheiro tão aflito como eu? \n Mas quem vem aí?","entergremiolucentiointhehabitofameanmanp~ellobearingaluteandbooks~114":"Entram Gremio; Lucentio, em trajes de homem humilde; Petruchio, com Hortensio como músico; e Tranio, com Biondello, que traz um alaúde e livros.","gremiogoodmorrowneighbourbaptista~dmorrowneighbourbaptista~33":"Gremio — Bom dia, vizinho Baptista.","baptistagoodmorrowneighbourgremiogodsave~remiogodsaveyougentlemen~52":"Baptista — Bom dia, vizinho Gremio. \n Deus vos guarde, senhores!","petruchioandyougoodsirprayhaveyounotadau~katharinafairandvirtuous~74":"Petruchio — E a vós, bom senhor! Peço, não tendes uma filha \n Chamada Katharina, bela e virtuosa?","baptistaihaveadaughtersircalledkatharina~ughtersircalledkatharina~40":"Baptista — Tenho uma filha, senhor, chamada Katharina.","gremioyouaretoobluntgotoitorderly~aretoobluntgotoitorderly~33":"Gremio — Sois por demais brusco: ide a isso com ordem.","petruchioyouwrongmesigniorgremiogivemele~snameislicioborninmantua~491":"Petruchio — Ofendeis-me, Senhor Gremio: dai-me licença. \n Sou um cavalheiro de Verona, senhor, \n Que, ouvindo de sua beleza e seu espírito, \n Sua afabilidade e tímida modéstia, \n Suas maravilhosas qualidades e brando comportamento, \n Atrevo-me a mostrar-me hóspede afoito \n Em vossa casa, para que meus olhos sejam testemunhas \n Daquilo que tantas vezes ouvi dizer. \n E, como entrada em minha recepção, \n Apresento-vos um homem meu, Apresentando Hortensio. \n Hábil em música e matemática, \n Para instruí-la plenamente nessas ciências, \n Das quais sei que ela não é ignorante: \n Aceitai-o, ou me ofendereis: \n Seu nome é Licio, nascido em Mântua.","baptistayourewelcomesirandheforyourgoods~oryourturnthemoremygrief~110":"Baptista — Sois bem-vindo, senhor; e ele, por vossa causa. \n Mas quanto a minha filha Katharina, isto sei, \n Ela não serve a vosso fim, para meu maior pesar.","petruchioiseeyoudonotmeantopartwithheror~lseyoulikenotofmycompany~65":"Petruchio — Vejo que não pretendeis separar-vos dela, \n Ou então não gostais de minha companhia.","baptistamistakemenotispeakbutasifindwhen~usirwhatmayicallyourname~71":"Baptista — Não me entendais mal; falo apenas como acho. \n De onde sois, senhor? Como devo chamar vosso nome?","petruchiopetruchioismynameantoniossonama~lknownthroughoutallitaly~68":"Petruchio — Petruchio é meu nome; filho de Antonio, \n Homem bem conhecido por toda a Itália.","baptistaiknowhimwellyouarewelcomeforhiss~lyouarewelcomeforhissake~43":"Baptista — Conheço-o bem: sois bem-vindo por causa dele.","gremiosavingyourtalepetruchioiprayletust~eyouaremarvellousforward~99":"Gremio — Com vossa licença, Petruchio, peço, \n Deixai-nos, pobres peticionários, falar também: \n Baccare! Estais maravilhosamente afoito.","petruchioopardonmesigniorgremioiwouldfai~rgremioiwouldfainbedoing~48":"Petruchio — Oh, perdão, Senhor Gremio; eu gostaria de agir.","gremioidoubtitnotsirbutyouwillcurseyourw~mbioprayaccepthisservice~348":"Gremio — Não duvido, senhor; mas ireis amaldiçoar vossa corte. Vizinho, este é um presente muito grato, estou certo. Para exprimir igual bondade, eu mesmo, que vos devo mais cordialmente que qualquer um, dou-vos livremente este jovem letrado, apresentando Lucentio, que há muito estuda em Reims; tão hábil em grego, latim e outras línguas quanto o outro em música e matemática: seu nome é Cambio; peço, aceitai seu serviço.","baptistaathousandthankssigniorgremiowelc~knowthecauseofyourcoming~139":"Baptista — Mil agradecimentos, Senhor Gremio. Bem-vindo, bom Cambio. A Tranio. Mas, gentil senhor, parece-me que andais como estrangeiro: posso ter a ousadia de saber a causa de vossa vinda?","traniopardonmesirtheboldnessismineowntha~hemthentheirworthisgreat~452":"Tranio — Perdão, senhor, a ousadia é toda minha, \n Que, sendo estrangeiro nesta cidade, \n Me faço pretendente de vossa filha, \n De Bianca, bela e virtuosa. \n Nem me é desconhecida vossa firme resolução \n Quanto à precedência da irmã mais velha. \n Esta liberdade é tudo o que peço: \n Que, conhecida minha linhagem, \n Eu seja bem recebido entre os demais que cortejam, \n E tenha livre acesso e favor como os outros: \n E, para a educação de vossas filhas, \n Aqui ofereço um simples instrumento, \n E este pequeno pacote de livros gregos e latinos: \n Se os aceitardes, grande será o seu valor.","baptistalucentioisyournameofwhenceipray~oisyournameofwhenceipray~39":"Baptista — Lucentio é vosso nome; de onde, peço?","tranioofpisasirsontovincentio~oofpisasirsontovincentio~29":"Tranio — De Pisa, senhor; filho de Vincentio.","baptistaamightymanofpisabyreportiknowhim~pilspresentlyhollawithin~140":"Baptista — Poderoso homem de Pisa; por fama \n Conheço-o bem: sois muito bem-vindo, senhor, \n Tomai vós o alaúde, e vós o conjunto de livros; \n Ireis ver vossas discípulas agora mesmo. \n Olá, de dentro!","enteraservant~enteraservant~13":"Entra um Criado.","sirrahleadthesegentlementomydaughtersand~yyoualltothinkyourselves~241":"Rapaz, conduze estes cavalheiros \n Às minhas filhas; e dize a ambas \n Que são seus preceptores: manda que os tratem bem. Sai o Criado, com Lucentio e Hortensio, seguidos por Biondello. \n Iremos passear um pouco no pomar, \n E depois ao jantar. Sois mais que bem-vindos, \n E assim vos peço que vos considereis todos.","petruchiosigniorbaptistamybusinessasketh~yshallihavewithhertowife~237":"Petruchio — Senhor Baptista, meu negócio pede pressa, \n E não posso vir todos os dias a cortejar. \n Conhecestes bem meu pai, e nele a mim, \n Deixado único herdeiro de todas as suas terras e bens, \n Que melhorei mais do que diminuí: \n Dizei-me então, se eu ganhar o amor de vossa filha, \n Que dote terei com ela por esposa?","baptistaaftermydeaththeonehalfofmylandsa~siontwentythousandcrowns~74":"Baptista — Depois de minha morte, metade de minhas terras, \n E em posse imediata vinte mil coroas.","petruchioandforthatdowryillassureherofhe~ntsmaybekeptoneitherhand~174":"Petruchio — E, por esse dote, eu lhe assegurarei \n Seu direito de viúva, caso me sobreviva, \n Sobre todas as minhas terras e arrendamentos quaisquer: \n Que se redijam, pois, contratos entre nós, \n Para que os pactos sejam cumpridos de ambos os lados.","baptistaaywhenthespecialthingiswellobtai~herloveforthatisallinall~72":"Baptista — Sim, quando a coisa principal estiver bem obtida, \n A saber, o amor dela; pois isso é tudo em tudo.","petruchiowhythatisnothingforitellyoufath~mroughandwoonotlikeababe~277":"Petruchio — Ora, isso não é nada; pois vos digo, pai, \n Sou tão peremptório quanto ela é altiva; \n E onde dois fogos furiosos se encontram \n Consomem o que alimenta a sua fúria: \n Embora pequeno fogo cresça com pouco vento, \n Rajadas extremas apagam fogo e tudo: \n Assim eu a ela e assim ela se rende a mim; \n Pois sou rude e não cortejo como criança.","baptistawellmaystthouwooandhappybethyspe~uarmdforsomeunhappywords~74":"Baptista — Que cortejes bem, e feliz seja teu êxito! \n Mas arma-te para algumas palavras infelizes.","petruchioaytotheproofasmountainsareforwi~houghtheyblowperpetually~80":"Petruchio — Sim, à prova; como as montanhas aos ventos, \n Que não se abalam, ainda que soprem perpetuamente.","reenterhortensiowithhisheadbroke~ortensiowithhisheadbroke~32":"Reentra Hortensio, com a cabeça quebrada.","baptistahownowmyfriendwhydostthoulooksop~endwhydostthoulooksopale~43":"Baptista — Ora, meu amigo! Por que estás tão pálido?","hortensioforfearipromiseyouifilookpale~aripromiseyouifilookpale~38":"Hortensio — De medo, garanto-vos, se estou pálido.","baptistawhatwillmydaughterproveagoodmusi~ughterproveagoodmusician~44":"Baptista — O quê, minha filha será boa música?","hortensioithinkshellsoonerproveasoldieri~holdwithherbutneverlutes~70":"Hortensio — Creio que será antes soldado: \n O ferro pode aguentar com ela, mas nunca os alaúdes.","baptistawhythenthoucanstnotbreakhertothe~anstnotbreakhertothelute~44":"Baptista — Ora, então não podes domá-la ao alaúde?","hortensiowhynoforshehathbrokethelutetome~adshestudiedtomisusemeso~410":"Hortensio — Ora, não; pois ela quebrou o alaúde em mim. \n Apenas lhe disse que errava os trastes, \n E curvei-lhe a mão para ensinar a dedilhar; \n Quando, com espírito impaciente e endiabrado, \n “Trastes, chamais a isto?”, disse; “vou ferver com eles”: \n E, com essa palavra, bateu-me na cabeça, \n E através do instrumento passou o meu crânio; \n E ali fiquei atônito por um tempo, \n Como num pelourinho, olhando pelo alaúde: \n Enquanto ela me chamava de rabequista patife \n E Joãozinho dedilhador; com vinte outros termos vis, \n Como se tivesse estudado para me maltratar assim.","petruchionowbytheworlditisalustywenchilo~ongtohavesomechatwithher~98":"Petruchio — Agora, pelo mundo, é uma moça vigorosa; \n Amo-a dez vezes mais do que jamais amei: \n Oh, como anseio por trocar algumas palavras com ela!","baptistawellgowithmeandbenotsodiscomfite~isendmydaughterkatetoyou~178":"Baptista — Bem, vem comigo e não estejas tão desconcertado: \n Prossegue na prática com minha filha mais moça; \n Ela é apta a aprender e grata por bons serviços. \n Senhor Petruchio, vireis conosco, \n Ou devo enviar-vos minha filha Kate?","petruchioiprayyoudoexeuntallbutpetruchio~omesandnowpetruchiospeak~482":"Petruchio — Peço-vos que a envieis. Saem todos, exceto Petruchio. Aqui a aguardarei, \n E a cortejarei com ânimo quando vier. \n Suponhamos que ralhe; ora, direi-lhe com franqueza \n Que canta tão docemente quanto um rouxinol: \n Suponhamos que franza o cenho; direi que parece tão clara \n Quanto rosas da manhã recém-lavadas de orvalho: \n Suponhamos que seja muda e não diga palavra: \n Então louvarei sua loquacidade, \n E direi que profere penetrante eloquência: \n Se me mandar embora, agradecer-lhe-ei, \n Como se me mandasse ficar com ela uma semana: \n Se recusar casar, pedirei o dia \n Em que devo pedir os proclamas e quando casar. \n Mas aí vem ela; e agora, Petruchio, fala.","enterkatharina~enterkatharina~14":"Entra Katharina.","goodmorrowkateforthatsyournameihear~ateforthatsyournameihear~35":"Bom dia, Kate; pois é esse o vosso nome, ouvi dizer.","katharinawellhaveyouheardbutsomethinghar~ekatharinethatdotalkofme~83":"Katharina — Ouvistes bem, mas algo duro de ouvido: \n Chamam-me Katharina os que falam de mim.","petruchioyoulieinfaithforyouarecalldplai~mmovedtowootheeformywife~349":"Petruchio — Mentis, em verdade; pois sois chamada simplesmente Kate, \n E bela Kate e às vezes Kate, a perversa; \n Mas Kate, a mais bonita Kate da cristandade, \n Kate do Castelo Kate, minha super-delicada Kate, \n Pois delícias são todas as Kates, e portanto, Kate, \n Toma isto de mim, Kate de meu consolo; \n Ouvindo tua brandura louvada em cada cidade, \n Tuas virtudes comentadas e tua beleza proclamada, \n Mas não tão profundamente quanto te cabe, \n Eu mesmo sou movido a cortejar-te por esposa.","katharinamovedingoodtimelethimthatmovedy~thefirstyouwereamoveable~96":"Katharina — Movido! Em boa hora: que quem vos moveu para cá \n Vos remova daqui: conheci-vos de início \n Por um móvel.","petruchiowhywhatsamoveable~truchiowhywhatsamoveable~26":"Petruchio — Ora, que é um móvel?","katharinaajoindstool~katharinaajoindstool~20":"Katharina — Um banco de junta.","petruchiothouhasthititcomesitonme~thouhasthititcomesitonme~33":"Petruchio — Acertaste: vem, senta-te em mim.","katharinaassesaremadetobearandsoareyou~aremadetobearandsoareyou~38":"Katharina — Asnos são feitos para carregar, e vós também.","petruchiowomenaremadetobearandsoareyou~aremadetobearandsoareyou~38":"Petruchio — Mulheres são feitas para carregar, e tu também.","katharinanosuchjadeasyouifmeyoumean~suchjadeasyouifmeyoumean~35":"Katharina — Nenhuma sendeira como vós, se é a mim que dizeis.","petruchioalasgoodkateiwillnotburdentheef~theetobebutyoungandlight~73":"Petruchio — Ai! Boa Kate, não te sobrecarregarei; \n Pois, sabendo que és jovem e leve—","katharinatoolightforsuchaswainasyoutocat~sheavyasmyweightshouldbe~73":"Katharina — Leve demais para um rústico como vós apanhar; \n E no entanto tão pesada quanto meu peso deve ser.","petruchioshouldbeshouldbuzz~ruchioshouldbeshouldbuzz~27":"Petruchio — Deve ser! Deve—zum!","katharinawelltaenandlikeabuzzard~awelltaenandlikeabuzzard~32":"Katharina — Bem pego, e como um gavião-ratoeiro.","petruchiooslowwingdturtleshallabuzzardta~tleshallabuzzardtakethee~46":"Petruchio — Oh, rola de asas lentas! Poderá um gavião pegar-te?","katharinaayforaturtleashetakesabuzzard~aturtleashetakesabuzzard~38":"Katharina — Sim, por uma rola, como ele pega um gavião.","petruchiocomecomeyouwaspifaithyouaretooa~waspifaithyouaretooangry~44":"Petruchio — Vamos, vamos, vespa; por minha fé, estás irada demais.","katharinaifibewaspishbestbewaremysting~waspishbestbewaremysting~38":"Katharina — Se sou vespa, melhor temer meu ferrão.","petruchiomyremedyisthentopluckitout~remedyisthentopluckitout~35":"Petruchio — Meu remédio é então arrancá-lo.","katharinaayifthefoolcouldfinditwhereitli~olcouldfinditwhereitlies~42":"Katharina — Sim, se o tolo soubesse achá-lo onde está.","petruchiowhoknowsnotwhereawaspdoeswearhi~oeswearhisstinginhistail~55":"Petruchio — Quem não sabe onde a vespa carrega o ferrão? Na cauda.","katharinainhistongue~katharinainhistongue~20":"Katharina — Na língua.","petruchiowhosetongue~petruchiowhosetongue~20":"Petruchio — De quem a língua?","katharinayoursifyoutalkoftailsandsofarew~talkoftailsandsofarewell~43":"Katharina — A vossa, se falais de caudas: e assim, adeus.","petruchiowhatwithmytongueinyourtailnayco~aingoodkateiamagentleman~68":"Petruchio — O quê, com minha língua na vossa cauda? Não, volta, \n Boa Kate; sou um cavalheiro.","katharinathatilltryshestrikeshim~athatilltryshestrikeshim~32":"Katharina — Isso vou provar. Bate nele.","petruchioiswearillcuffyouifyoustrikeagai~lcuffyouifyoustrikeagain~41":"Petruchio — Juro que te darei um tabefe, se bateres de novo.","katharinasomayyouloseyourarmsifyoustrike~nogentlemanwhythennoarms~88":"Katharina — Assim podeis perder vossas armas: \n Se me bateis, não sois cavalheiro; \n E se não sois cavalheiro, ora, então sem brasão.","petruchioaheraldkateoputmeinthybooks~raldkateoputmeinthybooks~36":"Petruchio — Uma arauta, Kate? Oh, põe-me em teus livros!","katharinawhatisyourcrestacoxcomb~awhatisyourcrestacoxcomb~32":"Katharina — Qual é vosso timbre? Uma crista de bobo?","petruchioacomblesscocksokatewillbemyhen~esscocksokatewillbemyhen~39":"Petruchio — Um galo sem crista, se Kate quiser ser minha galinha.","katharinanocockofmineyoucrowtoolikeacrav~ineyoucrowtoolikeacraven~42":"Katharina — Nenhum galo meu; cantais como um covarde.","petruchionaycomekatecomeyoumustnotlookso~comeyoumustnotlooksosour~44":"Petruchio — Vamos, Kate, vamos; não deves olhar tão azeda.","katharinaitismyfashionwheniseeacrab~ismyfashionwheniseeacrab~35":"Katharina — É meu feitio, quando vejo uma maçã-brava.","petruchiowhyheresnocrabandthereforelookn~bandthereforelooknotsour~46":"Petruchio — Ora, aqui não há maçã-brava; portanto não olhes azeda.","katharinathereisthereis~katharinathereisthereis~23":"Katharina — Há, há.","petruchiothenshowitme~petruchiothenshowitme~21":"Petruchio — Então mostra-ma.","katharinahadiaglassiwould~atharinahadiaglassiwould~25":"Katharina — Tivesse eu um espelho, mostraria.","petruchiowhatyoumeanmyface~truchiowhatyoumeanmyface~26":"Petruchio — O quê, falas do meu rosto?","katharinawellaimdofsuchayoungone~awellaimdofsuchayoungone~32":"Katharina — Bem mirado para um tão jovem.","petruchionowbysaintgeorgeiamtooyoungfory~tgeorgeiamtooyoungforyou~42":"Petruchio — Pois por São Jorge, sou jovem demais para ti.","katharinayetyouarewitherd~atharinayetyouarewitherd~25":"Katharina — Contudo estais murcho.","petruchiotiswithcares~petruchiotiswithcares~21":"Petruchio — É de cuidados.","katharinaicarenot~katharinaicarenot~17":"Katharina — Não me importo.","petruchionayhearyoukateinsoothyouscapeno~kateinsoothyouscapenotso~43":"Petruchio — Não, ouve, Kate: em verdade não escapas assim.","katharinaichafeyouifitarryletmego~ichafeyouifitarryletmego~33":"Katharina — Irrito-vos, se me demoro: deixai-me ir.","petruchiononotawhitifindyoupassinggentle~etheewalkthoudostnothalt~540":"Petruchio — Não, nem um pouco: acho-te extremamente gentil. \n Disseram-me que eras rude, esquiva e rabugenta, \n E agora vejo que a fama é uma grande mentirosa; \n Pois és agradável, brincalhona, extremamente cortês, \n Mas lenta na fala, e doce como flores de primavera: \n Não sabes franzir o cenho, não sabes olhar de soslaio, \n Nem morder o lábio, como fazem as moças zangadas, \n Nem tens prazer em ser áspera na conversa, \n Mas com brandura recebes teus pretendentes, \n Com gentil conversa, suave e afável. \n Por que o mundo diz que Kate manca? \n Oh, mundo caluniador! Kate, como o ramo de aveleira, \n É reta e esbelta e de cor tão morena \n Quanto as avelãs e mais doce que as amêndoas. \n Oh, deixa-me ver-te andar: tu não coxeias.","katharinagofoolandwhomthoukeepstcommand~andwhomthoukeepstcommand~39":"Katharina — Vai, tolo, e manda em quem sustentas.","petruchiodideverdiansobecomeagroveaskate~ebechasteanddiansportful~133":"Petruchio — Jamais Diana adornou tanto um bosque \n Quanto Kate esta sala com seu porte principesco? \n Oh, sê tu Diana, e seja ela Kate; \n E então que Kate seja casta e Diana brincalhona!","katharinawheredidyoustudyallthisgoodlysp~studyallthisgoodlyspeech~44":"Katharina — Onde estudastes todo esse belo discurso?","petruchioitisextemporefrommymotherwit~extemporefrommymotherwit~37":"Petruchio — É improviso, do espírito de minha mãe.","katharinaawittymotherwitlesselseherson~ymotherwitlesselseherson~38":"Katharina — Uma mãe espirituosa! Sem espírito, o filho.","petruchioaminotwise~petruchioaminotwise~19":"Petruchio — Não sou sábio?","katharinayeskeepyouwarm~katharinayeskeepyouwarm~23":"Katharina — Sim; mantende-vos aquecido.","petruchiomarrysoimeansweetkatharineinthy~illhavekatharinatomywife~467":"Petruchio — Pois é o que pretendo, doce Katharina, em teu leito: \n E portanto, deixando de lado toda esta conversa, \n Digo em termos claros: teu pai consentiu \n Que sejas minha esposa; teu dote está acordado; \n E, queiras ou não queiras, casarei contigo. \n Agora, Kate, sou um marido ao teu jeito; \n Pois, por esta luz, com a qual vejo tua beleza, \n Tua beleza, que me faz gostar bem de ti, \n Não deves casar com homem algum senão comigo; \n Pois sou aquele nascido para te domar, Kate, \n E trazer-te de uma Kate selvagem a uma Kate \n Conforme como as outras Kates domésticas. \n Eis que vem teu pai: nunca negues; \n Devo e hei de ter Katharina por esposa.","reenterbaptistagremioandtranio~rbaptistagremioandtranio~30":"Reentram Baptista, Gremio e Tranio.","baptistanowsigniorpetruchiohowspeedyouwi~owspeedyouwithmydaughter~52":"Baptista — Então, Senhor Petruchio, como vos saís com minha filha?","petruchiohowbutwellsirhowbutwellitwereim~ossibleishouldspeedamiss~65":"Petruchio — Como senão bem, senhor? Como senão bem? \n Seria impossível que me saísse mal.","baptistawhyhownowdaughterkatharineinyour~hterkatharineinyourdumps~45":"Baptista — Ora, que é isso, filha Katharina! Abatida?","katharinacallyoumedaughternowipromiseyou~hoathstofacethematterout~167":"Katharina — Chamais-me de filha? Agora, garanto-vos \n Mostrastes terno cuidado de pai, \n Em desejar-me casada com um meio lunático; \n Um rufião de taverna e Joãozinho jurador, \n Que pensa enfrentar o assunto com palavrões.","petruchiofathertisthusyourselfandallthew~ponsundayistheweddingday~302":"Petruchio — Pai, é assim: vós mesmo e todo o mundo, \n Que falaram dela, falaram mal dela: \n Se é perversa, é por astúcia, \n Pois não é rebelde, mas modesta como a pomba; \n Não é fogosa, mas temperada como a manhã; \n Em paciência provará ser uma segunda Griselda, \n E uma Lucrécia romana em castidade: \n E para concluir, combinamos tão bem juntos \n Que no domingo é o dia do casamento.","katharinaillseetheehangdonsundayfirst~eetheehangdonsundayfirst~37":"Katharina — Antes te verei enforcado no domingo.","gremioharkpetruchioshesaysshellseetheeha~ysshellseetheehangdfirst~48":"Gremio — Ouvi, Petruchio; ela diz que vos verá enforcado primeiro.","tranioisthisyourspeedingnaythengoodnight~gnaythengoodnightourpart~47":"Tranio — Este é vosso êxito? Ora, então, boa noite à nossa parte!","petruchiobepatientgentlemenichooseherfor~remykatharineshallbefine~526":"Petruchio — Tende paciência, senhores; escolho-a para mim: \n Se ela e eu estamos contentes, que tendes vós com isso? \n Está combinado entre nós dois, a sós, \n Que ela continuará perversa em companhia. \n Digo-vos, é incrível de acreditar \n O quanto ela me ama: oh, a mais carinhosa Kate! \n Pendurou-se ao meu pescoço; e beijo sobre beijo \n Disputava tão depressa, protestando juramento sobre juramento, \n Que num piscar me conquistou para seu amor. \n Oh, sois noviços! É um mundo ver \n Como, quando homens e mulheres estão a sós, \n Um coitado covarde pode amansar a mais perversa megera. \n Dá-me a mão, Kate: irei a Veneza \n Comprar trajes para o dia do casamento. \n Preparai a festa, pai, e convidai os hóspedes; \n Cuidarei de que minha Katharina esteja elegante.","baptistaiknownotwhattosaybutgivemeyourha~youjoypetruchiotisamatch~74":"Baptista — Não sei o que dizer: mas dai-me as mãos; \n Deus vos envie alegria, Petruchio! É um par.","gremiotranioamensaywewewillbewitnesses~ensaywewewillbewitnesses~38":"Gremio\n Tranio — Amém, dizemos nós: seremos testemunhas.","petruchiofatherandwifeandgentlemenadieui~hioandkatharinaseverally~175":"Petruchio — Pai, e esposa, e senhores, adeus; \n Vou a Veneza; o domingo vem depressa: \n Teremos anéis e coisas e belos trajes; \n E beija-me, Kate, casaremos no domingo. Saem Petruchio e Katharina por lados diversos.","gremiowasevermatchclappdupsosuddenly~rmatchclappdupsosuddenly~36":"Gremio — Houve jamais casamento ajustado tão de repente?","baptistafaithgentlemennowiplayamerchants~uremadlyonadesperatemart~75":"Baptista — Na verdade, senhores, agora faço papel de mercador, \n E me aventuro loucamente num mercado desesperado.","traniotwasacommoditylayfrettingbyyoutwil~yougainorperishontheseas~70":"Tranio — Era uma mercadoria que jazia a vos roer: \n Dará lucro, ou perecerá nos mares.","baptistathegainiseekisquietinthematch~iniseekisquietinthematch~37":"Baptista — O lucro que busco é paz neste casamento.","gremionodoubtbuthehathgotaquietcatchbutn~ighbourandwassuitorfirst~134":"Gremio — Sem dúvida ele fez uma pesca sossegada. \n Mas agora, Baptista, à vossa filha mais moça: \n Eis o dia que há muito esperamos: \n Sou vosso vizinho, e fui pretendente primeiro.","tranioandiamonethatlovebiancamorethanwor~ssoryourthoughtscanguess~74":"Tranio — E sou eu quem ama Bianca mais \n Do que palavras podem testemunhar, ou vossos pensamentos adivinhar.","gremioyounglingthoucanstnotlovesodearasi~houcanstnotlovesodearasi~40":"Gremio — Mocinho, não podes amar tão caro como eu.","traniograybeardthylovedothfreeze~aybeardthylovedothfreeze~32":"Tranio — Barbacinza, teu amor congela.","gremiobutthinedothfryskipperstandbacktis~backtisagethatnourisheth~57":"Gremio — Mas o teu frita. \n Moleque, para trás: é a idade que nutre.","traniobutyouthinladieseyesthatflourishet~adieseyesthatflourisheth~41":"Tranio — Mas é a juventude que floresce nos olhos das damas.","baptistacontentyougentlemeniwillcompound~remiowhatcanyouassureher~177":"Baptista — Contentai-vos, senhores: resolverei esta contenda: \n São os feitos que devem ganhar o prêmio; e aquele dos dois \n Que puder assegurar a minha filha o maior dote \n Terá o amor de minha Bianca. \n Dizei, Senhor Gremio, que podeis assegurar-lhe?","gremiofirstasyouknowmyhousewithinthecity~stiliveshewillbeonlymine~559":"Gremio — Primeiro, como sabeis, minha casa dentro da cidade \n Está ricamente provida de prata e ouro; \n Bacias e jarros para lavar-lhe as delicadas mãos; \n Meus panos todos de tapeçaria de Tiro; \n Em cofres de marfim guardei minhas coroas; \n Em arcas de cipreste minhas colchas de arrás, \n Trajes custosos, tendas e dosséis, \n Linho fino, almofadas turcas cravejadas de pérolas, \n Franjas de ouro de Veneza em bordado, \n Estanho e latão e tudo o que pertence \n À casa ou ao governo da casa: depois, em minha fazenda \n Tenho cem vacas leiteiras para o balde, \n Cento e vinte bois gordos em meus estábulos, \n E tudo que corresponda a esta porção. \n Eu mesmo sou avançado em anos, devo confessar; \n E se eu morrer amanhã, isto é dela, \n Se enquanto eu viver ela for somente minha.","traniothatonlycamewellinsirlisttomeiammy~eipinchdyousigniorgremio~282":"Tranio — Esse “somente” veio a propósito. Senhor, ouvi-me: \n Sou herdeiro e filho único de meu pai: \n Se eu puder ter vossa filha por esposa, \n Deixar-lhe-ei três ou quatro casas tão boas, \n Dentro dos muros da rica Pisa, quanto qualquer \n Que o velho Senhor Gremio tem em Pádua; \n Além de dois mil ducados por ano \n De terra fértil, tudo o que será seu dote de viuvez. \n O quê, belisquei-vos, Senhor Gremio?","gremiotwothousandducatsbytheyearoflandmy~veichokedyouwithanargosy~158":"Gremio — Dois mil ducados por ano de terra! \n Minha terra não monta a tanto, toda ela: \n Isso ela terá; além de um galeão \n Que agora jaz na enseada de Marselha. \n O quê, sufoquei-vos com um galeão?","traniogremiotisknownmyfatherhathnolessth~chwhateerthouofferstnext~155":"Tranio — Gremio, é sabido que meu pai não tem menos \n Que três grandes galeões; além de duas galeaças, \n E doze galeras bem calafetadas: estas lhe asseguro, \n E o dobro, seja o que for que ofereceres depois.","gremionayihaveofferdallihavenomoreandshe~emesheshallhavemeandmine~97":"Gremio — Não, ofereci tudo, não tenho mais; \n E ela não pode ter mais do que tudo o que tenho: \n Se me aceitais, ela terá a mim e o que é meu.","traniowhythenthemaidisminefromalltheworl~rmpromisegremioisoutvied~73":"Tranio — Ora, então a donzela é minha perante todo o mundo, \n Por vossa firme promessa: Gremio foi superado.","baptistaimustconfessyourofferisthebestan~ebeforehimwheresherdower~141":"Baptista — Devo confessar que vossa oferta é a melhor; \n E, se vosso pai lhe fizer a garantia, \n Ela é vossa; senão, deveis perdoar-me, \n Se morrerdes antes dele, onde está o dote dela?","traniothatsbutacavilheisoldiyoung~tsbutacavilheisoldiyoung~33":"Tranio — Isso é mera chicana: ele é velho, eu jovem.","gremioandmaynotyoungmendieaswellasold~otyoungmendieaswellasold~37":"Gremio — E os jovens não podem morrer, tanto quanto os velhos?","baptistawellgentlemeniamthusresolvedonsu~kemyleaveandthankyouboth~203":"Baptista — Bem, senhores, \n Resolvi assim: no domingo próximo, sabeis, \n Minha filha Katharina será casada: \n Agora, no domingo seguinte, Bianca \n Será vossa noiva, se derdes esta garantia; \n Se não, do Senhor Gremio: \n E assim despeço-me e agradeço a ambos.","gremioadieugoodneighbourexitbaptistanowi~nfoxisnotsokindmyboyexit~181":"Gremio — Adeus, bom vizinho. Sai Baptista. Agora não vos temo: \n Rapaz jovem jogador, vosso pai seria tolo \n De dar-vos tudo, e em sua idade declinante \n Pôr os pés sob vossa mesa: bah, uma bobagem! \n Uma velha raposa italiana não é tão bondosa, meu rapaz. Sai.","tranioavengeanceonyourcraftywitherdhidey~fifailnotofmycunningexit~275":"Tranio — Uma praga sobre vosso couro astuto e murcho! \n Contudo enfrentei-o com um dez de cartas. \n Tenho na cabeça fazer bem a meu amo: \n Não vejo razão para que o suposto Lucentio \n Não ganhe um pai, chamado “suposto Vincentio”; \n E isso é uma maravilha: pais comumente \n Geram seus filhos; mas neste caso de cortejo, \n Um filho gerará um pai, se não me falhar a astúcia. Sai."}$tr$::jsonb, 396)
